INSERT INTO `block_content_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('basic', 0, 1, 1, 'en', 0, '<h2 class=\"mission-title\">About <span class=\"accent-text\">Us</span></h2><p class=\"mission-text\">Capacity Building Commission (CBC), is the custodian of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.<br>&nbsp;</p>', '', 'full_html'),
('basic', 0, 1, 1, 'hi', 0, '<h2 class=\"mission-title\"><span class=\"accent-text\">हमारे बारे में</span></h2><p class=\"mission-text\">क्षमता विकास आयोग (सीबीसी), मिशन कर्मयोगी फ्रेमवर्क का अभिरक्षक है, जो क्षमता निर्माण और सक्षमता आधारित अधिगम के माध्यम से लोक सेवा सुधारों को संचालित करता है। यह व्यक्तिगत और संस्थागत क्षमताओं को विकसित करने, नागरिक-केंद्रित सुशासन को बढ़ावा देने, भविष्य के लिए तत्पर रहने और लोक प्रशासन के सभी स्तरों पर आजीवन सीखने की संस्कृति को बढ़ावा देने पर फोकस करके सरकार के मानव संसाधन के आधार को मजबूत करने का काम करता है। यह आयोग फ्रेमवर्क डिजाइन करता है, मानक तय करता है और सुशासन को अधिकाधिक पारदर्शी, जवाबदेह, नागरिक-केंद्रित और भविष्योन्मुखी बनाने के लिए सहयोग को बढ़ावा देता है।</p>', '', 'full_html'),
('basic', 0, 2, 2, 'en', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img src=\"/sites/default/files/inline-images/image0028FRL_0.jpg\" data-entity-uuid=\"bd5c5bc6-931a-4493-a668-fa5290fd26cf\" data-entity-type=\"file\" width=\"602\" height=\"401\" alt=\"Narendra Damodardas Modi\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">\"National Program for Civil Services Capacity Building will radically improve the Human Resource Management practices in the Government through state of the art infrastructure to augment the capacity of Civil Servants.\"</p><p class=\"modi-message-attribution\">- Hon\'ble Prime Minister</p></div></div>', '', 'full_html'),
('basic', 0, 2, 2, 'hi', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img class=\"modi-image\" src=\"/themes/cbc/img/pm_modi.jpg\" alt=\"Prime Minister Narendra Modi\" width=\"934\" height=\"452\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">“राष्ट्रीय सिविल सेवा क्षमता निर्माण कार्यक्रम से आधुनिकतम अवसंरचना के जरिए सरकार में मानव संसाधन प्रबंधन संबंधी कार्यों में व्यापक उन्नयन होगा, ताकि सिविल सेवकों का क्षमता संवर्धन किया जा सके।”</p><p class=\"modi-message-attribution\">-माननीय प्रधान मंत्री</p></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'en', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">\"National Standards for Civil Service Training Institutes 2.0 is not just a compliance tool—it is a transformative step toward institutional excellence.\"</p><div class=\"jitender-name-badge\"><p>Dr. Jitendra Singh</p><p class=\"f-6\">Hon\'ble Minister of State</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'hi', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">“राष्ट्रीय सिविल सेवा प्रशिक्षण संस्थान मानक 2.0 न केवल एक अनुपालन साधन मात्र है- अपितु यह सांस्थानिक उत्कृष्टता की दिशा में एक परिवर्तनकारी कदम भी है।”</p><div class=\"jitender-name-badge\"><p>-&nbsp;&nbsp;&nbsp;&nbsp;डॉ. जितेंद्र सिंह</p><p class=\"f-6\">माननीय राज्य मंत्री</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 4, 4, 'en', 0, '<p><i class=\"fas fa-map-marker-alt\"></i> Capacity Building Commission,&nbsp;<br>&nbsp;19th, 20th &amp; 21st Floor,&nbsp;<br>Jawahar Vyapar Bhavan,&nbsp;<br>Tolstoy Road,&nbsp;New Delhi – 110001</p><p><i class=\"fas fa-phone-alt\"></i> <span>+91 11 23701126</span></p><p><i class=\"fas fa-envelope\"></i> info[at]cbc[dot]gov[dot]in</p>', '', 'full_html'),
('basic', 0, 5, 5, 'en', 0, '<h4>Capacity Building Commission</h4><p>Strengthening governance and empowering civil services through innovation, training, and collaborative leadership under Mission Karmayogi.</p><div class=\"social-icons\"><a href=\"https://x.com/CBC_MK\"><i class=\"fab fa-x-twitter\"></i></a> <a href=\"https://www.linkedin.com/company/capacity-building-commission/\"><i class=\"fab fa-linkedin\"></i></a> <a href=\"https://www.instagram.com/capacitybuildingcommission/\"><i class=\"fab fa-instagram\"></i></a> <a href=\"https://www.facebook.com/share/1AQvydowQ9/\"><i class=\"fab fa-facebook\"></i></a></div>', '', 'full_html'),
('basic', 0, 7, 7, 'en', 0, '<div class=\"section-body\"><div class=\"social-grid\"><!-- Twitter/X --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"twitter-widget-container\"><div style=\"margin:0;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://twitter.com/CBC_MK\"><strong style=\"font-size:12px;\">@CBC_MK</strong>&nbsp;</a></div><div style=\"margin:0;text-align:center;\"><a style=\"font-size:11px;text-decoration:none;\" href=\"https://twitter.com/CBC_MK\">Visit our Twitter/X&nbsp;</a></div><div style=\"background-color:white;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://twitter.com/CBC_MK\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-x-twitter\"></i> Twitter/X</div></div><!-- LinkedIn --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"linkedin-widget-container\"><p><a style=\"align-items:center;background-color:#e8e6e1;border-radius:6px;color:#0077b5;display:flex;flex-direction:column;justify-content:center;padding:6px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><i class=\"fab fa-linkedin\" style=\"font-size:18px;\"></i>&nbsp;</a></p><div style=\"text-align:center;\"><a style=\"color:#0077b5;font-size:11px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><strong>Capacity Building Commission</strong>&nbsp;</a></div><div style=\"text-align:center;\"><a style=\"color:#0077b5;font-size:10px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\">Visit our LinkedIn&nbsp;</a></div><div style=\"background-color:#ffffff;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"color:#0077b5;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-linkedin-in\"></i> LinkedIn</div></div><!-- Instagram --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"instagram-widget-container\"><p><a style=\"align-items:center;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><i class=\"fab fa-instagram\" style=\"font-size:18px;\"></i>&nbsp;</a></p><div style=\"text-align:center;\"><a style=\"font-size:11px;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><strong>@capacitybuildingcommission</strong>&nbsp;</a></div><div style=\"text-align:center;\"><a style=\"font-size:10px;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\">Visit our Instagram&nbsp;</a></div><div style=\"background-color:#0077b5;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-instagram\"></i> Instagram</div></div><!-- Facebook --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"facebook-widget-container\"><p><a style=\"align-items:center;background-color:#cce7ff;border-radius:6px;color:#1877f2;display:flex;flex-direction:column;justify-content:center;padding:6px;text-decoration:none;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\"><i class=\"fab fa-facebook\" style=\"font-size:18px;\"></i>&nbsp;</a></p><div style=\"text-align:center;\"><a style=\"color:#1877f2;font-size:11px;text-decoration:none;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\"><strong>Capacity Building Commission</strong>&nbsp;</a></div><div style=\"text-align:center;\"><a style=\"color:#1877f2;font-size:10px;text-decoration:none;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\">Visit our Facebook&nbsp;</a></div><div style=\"background-color:#1877f2;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"color:white;text-decoration:none;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-facebook\"></i> Facebook</div></div></div></div>', '', 'full_html'),
('basic', 0, 8, 8, 'en', 0, '<section class=\"stats-section\"><div class=\"stat\"><h3 class=\"count\" data-target=\"&#13;14883297\">0</h3><p>Total Karmayogis Onboarded</p></div><div class=\"stat\"><div style=\"display:flex;justify-content:center;\"><h3 class=\"count\" data-target=\"100\">0</h3><p style=\"margin-bottom:0px;\"><strong>+</strong></p></div><p>Ministries and Depts. Engaged</p></div><div class=\"stat\"><h3 class=\"count\" data-target=\"200\">0</h3><p>Training Institutes Accredited</p></div><div class=\"stat\"><h3 class=\"count\" data-target=\"30\">0</h3><p>MoUs (States/UTs)</p></div><div class=\"stat\"><h3 class=\"count\" data-target=\"4312\">0</h3><p>Total Courses</p></div></section>', '', 'full_html'),
('basic', 0, 9, 9, 'en', 0, '<div class=\"message-preview-letter\"><div class=\"preview-letter-header-new\"><div class=\"preview-letter-title-wrapper\"><h4 class=\"preview-letter-title-new\">FROM THE&nbsp;<br>CHAIRPERSON\'S DESK<span class=\"preview-pencil-icon\">✏️</span></h4></div><div class=\"preview-chairperson-photo\"><img class=\"preview-chairperson-img\" src=\"/sites/default/files/2025-12/cbc%20chairman_1.png\" alt=\"Ms. S. Radha Chauhan\" width=\"511\" height=\"361\"></div></div><div class=\"preview-letter-content\"><div class=\"preview-letter-text\"><p class=\"preview-letter-intro\">Let us join hands for continuously empowering our learning eco-system.</p><p class=\"preview-letter-paragraph\">Mission Karmayogi is a path-breaking and a first of its kind initiative envisioned by Hon\'ble Prime Minister Shri Narendra Modi, in the year 2020. Since its inception, Mission Karmayogi team has functioned with dedication towards developing an eco-system which strives to enable lifelong learning for the Civil Servants, who are an important link for citizen-centric delivery of services. The Capacity Building Commission, established on 1st April, 2021, functions at the core of Mission Karmayogi, through policy frameworks laying foundation of capacity building initiatives.</p><p class=\"preview-letter-paragraph\">It gives me immense pride to lead the efforts of Capacity Building Commission. We together need to take this journey ahead.</p><p class=\"preview-letter-paragraph\">As we are aware, civil servants perform in a ever-growing and sometimes uncertain environment. The emerging and new technologies are not only providing unseen opportunities, but at the same time posing challenges never imagined before. As civil servants, our duty is to deliver in any given situation and upkeep the trust of the citizens. Continuous capacity building is the key to strive through any challenge that might come and to optimally utilise the opportunities that might go unutilised if we are not well-equipped to handle them.</p><p class=\"preview-letter-paragraph\">It is pertinent to mention here that we all need to come together to continuously build a learning eco-system which enables our manpower to be ready to face and utilise any given situation to the best advantage of the citizens. Our civil servants across the Central and State Governments need to be a part of this learning process. The wider the chain, the greater the impact will be.</p><p class=\"preview-letter-paragraph\">We at the Commission are continuously functioning to arrive at the frameworks and policies that emphasise upon innovation, foresight and research. We wish to build an eco-system where we learn from the capacity building best practices of each other and institutionalise them as part of our eco-system.</p><p class=\"preview-letter-paragraph\">We emphasise on the capacity enhancement and upgrading of our Training Institute in all aspects while acknowledging that they are the backbone of our learning framework.</p><p class=\"preview-letter-paragraph\">I feel that excellence should not only be institutionalised but also celebrated by all of us. I wish to acknowledge the efforts put by you, which has set an example for other to strive towards excellence.</p><p class=\"preview-letter-paragraph\">I consider all my stakeholder an important part of my team &amp; journey and we are open to any feedback, suggestions that might help us grow together.</p></div></div><div class=\"preview-letter-signature\"><div class=\"preview-signature-wishes\">Best Wishes,</div><div class=\"preview-signature-name\">Ms. S. Radha Chauhan</div><div class=\"preview-signature-title\">Chairperson</div></div></div>', '', 'full_html'),
('basic', 0, 9, 9, 'hi', 0, '<div class=\"message-preview-letter\"><div class=\"preview-letter-header-new\"><div class=\"preview-letter-title-wrapper\"><h4 class=\"preview-letter-title-new\"><span class=\"preview-pencil-icon\">अध्यक्ष की कलम से✏️</span></h4></div><div class=\"preview-chairperson-photo\"><img class=\"preview-chairperson-img\" src=\"/sites/default/files/2025-12/cbc%20chairman_1.png\" alt=\"Ms. S. Radha Chauhan\" width=\"511\" height=\"361\"></div></div><div class=\"preview-letter-content\"><div class=\"preview-letter-text\"><p class=\"preview-letter-intro\">आईए हम सब अपने क्षमता विकास पारितंत्र को लगातार सशक्त बनाने के लिए सहयोग करें।</p><p class=\"preview-letter-paragraph\">मिशन कर्मयोगी एक पथ प्रवर्तक और अपने आप में एक ऐसी अनूठी पहल है जिसकी संकल्पना वर्ष 2020 में माननीय प्रधानमंत्री श्री नरेंद्र मोदी द्वारा की गई थी। अपनी शुरुआत से ही, मिशन कर्मयोगी की टीम ने एक ऐसे पारितंत्र को विकसित करने के लिए समर्पण की भावना से कार्य किया है, जो सिविल सेवकों को जीवनपर्यंत सीखने को सक्षम बनाने में मदद करता है। ये सिविल सेवक नागरिक केंद्रित सेवा प्रदानगी के लिए एक महत्वपूर्ण कड़ी है। 1 अप्रैल 2021 को स्थापित क्षमता विकास आयोग, नीतिगत ढांचों के माध्यम से क्षमता विकास संबंधी पहलों की आधारशिला रखते हुए मिशन कर्मयोगी के महत्वपूर्ण भाग के रूप में कार्य करता है।</p><p>क्षमता विकास आयोग के प्रयासों का नेतृत्‍व करना, मेरे लिए अत्यंत गर्व की बात है। हम सबको मिलकर इस सफर को आगे बढ़ाना है।</p><p>जैसा कि हम सब जानते हैं, कि सिविल सेवक निरंतर प्रगतिशील तथा कभी-कभी अनिश्चित महौल में कार्य करते हैं। उभरती हुई और नई प्रौद्योगिकियां न केवल ऐसे अनदेखे अवसर प्रदान कर रही है, बल्कि साथ ही ऐसी चुनौतियां भी खड़ी कर रह रही हैं जिनकी पहले कभी कल्‍पना नहीं की गई थी। सिविल सेवक के रूप में हमारा दायित्व किसी भी स्थिति में सेवा प्रदान करना और नागरिकों का विश्वास बनाए रखना है। लगातार क्षमता निर्माण, हमारे समक्ष आने वाले किसी भी चुनौती का सामना करने और उन अवसरों का इष्टतम उपयोग करने की कुंजी है, जिन्हें हम पूरी तरह से तैयार नहीं होने पर खो सकते हैं।&nbsp;</p><p class=\"preview-letter-paragraph\">यहां यह उल्लेख करना प्रासंगिक है कि एक शिक्षण पारितंत्र के निरंतर विकास हेतु हम सबको एक साथ आने की आवश्यकता है, ताकि हमारी जनशक्ति किसी भी परिस्थिति का सामना करने और नागरिकों की भलाई के लिए उसी परिस्थिति का उपयोग करने में समर्थ बन सके। केंद्र और राज्य सरकार के हमारे सिविल सेवकों को इस शिक्षण प्रक्रिया का भाग होना आवश्यक है। जितना व्‍यापक इसका दायरा होगा, उतना ही गहरा उसका प्रभाव भी होगा।&nbsp;</p><p class=\"preview-letter-paragraph\">आयोग में हम सब मिलकर ऐसे फ्रेमवर्क और नीति निर्माण पर निरंतर कार्य कर रहे हैं जो नवाचार, दूर दृष्टि और अनुसंधान पर बल देती हैं। हम एक ऐसा पारितंत्र बनाना चाहते है, जहां हम एक-दूसरे की क्षमता विकास की बेहतरीन पद्धतियों से सीख सकें और अपने पारितंत्र के भाग रूप में उसे स्थापित कर सकें।&nbsp;</p><p class=\"preview-letter-paragraph\">हम अपने प्रशिक्षण संस्थान के क्षमता संवर्धन और उसके उन्नयन के सभी पहलुओं पर जोर देते हैं, क्‍योंकि हम मानते हैं कि वह हमारे शिक्षण फ्रेमवर्क की रीढ़ है।</p><p class=\"preview-letter-paragraph\">मैं महसूस करती हूं कि उत्कृष्टता को न केवल स्थापित किया जाना चाहिए परंतु हमारे द्वारा इसे उत्सव के रूप में मनाया भी जाना चाहिए। मैं आपके द्वारा किए जा रहे प्रयासों के प्रति आभार व्यक्त करती हूं जिसने उत्कृष्टता के प्रति उन्मुख रहने हेतु अन्यों के लिए एक उदाहरण स्थापित किया है।</p><p class=\"preview-letter-paragraph\">मैं अपने सभी हितधारकों को अपनी टीम और सफर का एक महत्वपूर्ण हिस्सा मानती हूं और हम ऐसे किसी भी फीडबैक, सुझावों का स्वागत करते हैं, जो हमें साथ मिलकर आगे बढ़ने में मदद करें।&nbsp;</p></div></div><div class=\"preview-letter-signature\"><p>शुभकामनाओं सहित,<br>सुश्री एस. राधा चौहान<br><span class=\"preview-pencil-icon\">अध्यक्ष</span></p></div></div>', '', 'full_html'),
('basic', 0, 10, 10, 'en', 0, '<div class=\"social-section-enhanced py-5\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row\"><div class=\"col-12\"><h2 class=\"social-section-title mb-4\">Follow Us</h2><div class=\"social-icons-enhanced\"><a class=\"social-icon-btn\" href=\"https://twitter.com/CBC_MK\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-x-twitter\"></i> <span>Twitter</span> </a><a class=\"social-icon-btn\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-linkedin\"></i> <span>LinkedIn</span> </a><a class=\"social-icon-btn\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-instagram\"></i> <span>Instagram</span> </a><a class=\"social-icon-btn\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-facebook\"></i> <span>Facebook</span>&nbsp;</a></div></div></div></div></div></div>', '', 'full_html');
INSERT INTO `block_content__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('basic', 0, 1, 1, 'en', 0, '<h2 class=\"mission-title\">About <span class=\"accent-text\">Us</span></h2><p class=\"mission-text\">Capacity Building Commission (CBC), is the custodian of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.<br>&nbsp;</p>', '', 'full_html'),
('basic', 0, 1, 1, 'hi', 0, '<h2 class=\"mission-title\"><span class=\"accent-text\">हमारे बारे में</span></h2><p class=\"mission-text\">क्षमता विकास आयोग (सीबीसी), मिशन कर्मयोगी फ्रेमवर्क का अभिरक्षक है, जो क्षमता निर्माण और सक्षमता आधारित अधिगम के माध्यम से लोक सेवा सुधारों को संचालित करता है। यह व्यक्तिगत और संस्थागत क्षमताओं को विकसित करने, नागरिक-केंद्रित सुशासन को बढ़ावा देने, भविष्य के लिए तत्पर रहने और लोक प्रशासन के सभी स्तरों पर आजीवन सीखने की संस्कृति को बढ़ावा देने पर फोकस करके सरकार के मानव संसाधन के आधार को मजबूत करने का काम करता है। यह आयोग फ्रेमवर्क डिजाइन करता है, मानक तय करता है और सुशासन को अधिकाधिक पारदर्शी, जवाबदेह, नागरिक-केंद्रित और भविष्योन्मुखी बनाने के लिए सहयोग को बढ़ावा देता है।</p>', '', 'full_html'),
('basic', 0, 2, 2, 'en', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img src=\"/sites/default/files/inline-images/image0028FRL_0.jpg\" data-entity-uuid=\"bd5c5bc6-931a-4493-a668-fa5290fd26cf\" data-entity-type=\"file\" width=\"602\" height=\"401\" alt=\"Narendra Damodardas Modi\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">\"National Program for Civil Services Capacity Building will radically improve the Human Resource Management practices in the Government through state of the art infrastructure to augment the capacity of Civil Servants.\"</p><p class=\"modi-message-attribution\">- Hon\'ble Prime Minister</p></div></div>', '', 'full_html'),
('basic', 0, 2, 2, 'hi', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img class=\"modi-image\" src=\"/themes/cbc/img/pm_modi.jpg\" alt=\"Prime Minister Narendra Modi\" width=\"934\" height=\"452\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">“राष्ट्रीय सिविल सेवा क्षमता निर्माण कार्यक्रम से आधुनिकतम अवसंरचना के जरिए सरकार में मानव संसाधन प्रबंधन संबंधी कार्यों में व्यापक उन्नयन होगा, ताकि सिविल सेवकों का क्षमता संवर्धन किया जा सके।”</p><p class=\"modi-message-attribution\">-माननीय प्रधान मंत्री</p></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'en', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">\"National Standards for Civil Service Training Institutes 2.0 is not just a compliance tool—it is a transformative step toward institutional excellence.\"</p><div class=\"jitender-name-badge\"><p>Dr. Jitendra Singh</p><p class=\"f-6\">Hon\'ble Minister of State</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'hi', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">“राष्ट्रीय सिविल सेवा प्रशिक्षण संस्थान मानक 2.0 न केवल एक अनुपालन साधन मात्र है- अपितु यह सांस्थानिक उत्कृष्टता की दिशा में एक परिवर्तनकारी कदम भी है।”</p><div class=\"jitender-name-badge\"><p>-&nbsp;&nbsp;&nbsp;&nbsp;डॉ. जितेंद्र सिंह</p><p class=\"f-6\">माननीय राज्य मंत्री</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 4, 4, 'en', 0, '<p><i class=\"fas fa-map-marker-alt\"></i> Capacity Building Commission,&nbsp;<br>&nbsp;19th, 20th &amp; 21st Floor,&nbsp;<br>Jawahar Vyapar Bhavan,&nbsp;<br>Tolstoy Road,&nbsp;New Delhi – 110001</p><p><i class=\"fas fa-phone-alt\"></i> <span>+91 11 23701126</span></p><p><i class=\"fas fa-envelope\"></i> info[at]cbc[dot]gov[dot]in</p>', '', 'full_html'),
('basic', 0, 5, 5, 'en', 0, '<h4>Capacity Building Commission</h4><p>Strengthening governance and empowering civil services through innovation, training, and collaborative leadership under Mission Karmayogi.</p><div class=\"social-icons\"><a href=\"https://x.com/CBC_MK\"><i class=\"fab fa-x-twitter\"></i></a> <a href=\"https://www.linkedin.com/company/capacity-building-commission/\"><i class=\"fab fa-linkedin\"></i></a> <a href=\"https://www.instagram.com/capacitybuildingcommission/\"><i class=\"fab fa-instagram\"></i></a> <a href=\"https://www.facebook.com/share/1AQvydowQ9/\"><i class=\"fab fa-facebook\"></i></a></div>', '', 'full_html'),
('basic', 0, 7, 7, 'en', 0, '<div class=\"section-body\"><div class=\"social-grid\"><!-- Twitter/X --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"twitter-widget-container\"><div style=\"margin:0;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://twitter.com/CBC_MK\"><strong style=\"font-size:12px;\">@CBC_MK</strong>&nbsp;</a></div><div style=\"margin:0;text-align:center;\"><a style=\"font-size:11px;text-decoration:none;\" href=\"https://twitter.com/CBC_MK\">Visit our Twitter/X&nbsp;</a></div><div style=\"background-color:white;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://twitter.com/CBC_MK\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-x-twitter\"></i> Twitter/X</div></div><!-- LinkedIn --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"linkedin-widget-container\"><p><a style=\"align-items:center;background-color:#e8e6e1;border-radius:6px;color:#0077b5;display:flex;flex-direction:column;justify-content:center;padding:6px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><i class=\"fab fa-linkedin\" style=\"font-size:18px;\"></i>&nbsp;</a></p><div style=\"text-align:center;\"><a style=\"color:#0077b5;font-size:11px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><strong>Capacity Building Commission</strong>&nbsp;</a></div><div style=\"text-align:center;\"><a style=\"color:#0077b5;font-size:10px;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\">Visit our LinkedIn&nbsp;</a></div><div style=\"background-color:#ffffff;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"color:#0077b5;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-linkedin-in\"></i> LinkedIn</div></div><!-- Instagram --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"instagram-widget-container\"><p><a style=\"align-items:center;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><i class=\"fab fa-instagram\" style=\"font-size:18px;\"></i>&nbsp;</a></p><div style=\"text-align:center;\"><a style=\"font-size:11px;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><strong>@capacitybuildingcommission</strong>&nbsp;</a></div><div style=\"text-align:center;\"><a style=\"font-size:10px;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\">Visit our Instagram&nbsp;</a></div><div style=\"background-color:#0077b5;border-radius:12px;font-size:11px;margin-top:4px;text-align:center;\"><a style=\"text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\"><strong>Follow Us</strong>&nbsp;</a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-instagram\"></i> Instagram</div></div><!-- Facebook --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" style=\"display:flex;flex-direction:column;gap:4px;justify-content:center;\" id=\"facebook-widget-container\"><p><a style=\"align-items:center;background-color:#cce7ff;border-