('page', 0, 49, 85, 'en', 0, '<section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><!-- Mission Karmyogi Header --><div class=\"mission-karmayogi-header mb-4 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">Mission Karmyogi</h2></div><div class=\"intro-content mb-3\"><p class=\"text-muted\"><strong>National Programme for Civil Services Capacity Building (NPCSCB) – Mission Karmayogi</strong> was launched in September 2020.</p></div><!-- Mission Karmayogi Section --><div class=\"mission-karmayogi-highlight mb-5 p-4 rounded\"><div class=\"row align-items-center\"><div class=\"col-md-12\" mb-4=\"\"><!-- <h3 class=\"text-gradient mb-3\">Mission Karmayogi</h3> --><p class=\"mb-2\"><strong>\"Mission Karmayogi\"</strong> – aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonization for effective and efficient public service delivery.</p><p class=\"mb-0\">Envisioned as one of the largest capacity building initiatives in Government anywhere in the world, Mission Karmayogi aims to transform approximately <strong>1.5 crore government officials</strong> across the Centre, the States, and the local bodies.</p></div><div class=\"col-md-12 text-center mb-3 mb-md-0 mt-4\"><!-- Mission Karmayogi Institutional Framework Flowchart --><div class=\"institutional-framework-flowchart\"><div class=\"framework-header\"><h4 class=\"framework-title\">Mission Karmayogi – Institutional Framework</h4></div><div class=\"framework-content\"><div class=\"row g-3\"><!-- Capacity Building Commission Box --><div class=\"col-6\"><div class=\"framework-box high-contrast-border cbc-box\"><div class=\"framework-logo cbc-logo\"><img class=\"framework-logo-img\" src=\"img/cbc_logo.png\" alt=\"CBC Logo\"></div><h5 class=\"framework-box-title\">Capacity Building Commission</h5></div></div><!-- Karmayogi Bharat Box --><div class=\"col-6\"><div class=\"framework-box high-contrast-border karmayogi-box\"><div class=\"framework-logo karmayogi-logo\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\"><img class=\"framework-logo-img\" src=\"img/igot_karmyogi_logo.png\" alt=\"iGOT Karmayogi Logo\"></a></div><h5 class=\"framework-box-title\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\">Karmayogi Bharat</a></h5><p class=\"framework-box-subtitle\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\">(SPV - 100% govt. owned online learning platform - iGOT Karmayogi)</a></p></div></div></div></div></div></div></div></div><!-- About CBC Section --><div class=\"about-cbc-core mb-5\"><h2 class=\"mb-4 fw-bold\">About Capacity Building Commission</h2><div class=\"row\"><div class=\"col-lg-12\"><div class=\"cbc-intro-card p-4 mb-4 rounded\"><div class=\"row align-items-center\"><div class=\"col-md-12\"><!-- <h4 class=\"fw-bold mb-3\">The Capacity Building Commission (CBC)</h4> --><p class=\"mb-3\">Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.</p></div><!-- <div class=\"intro-content\">\r\n                      <p class=\"lead text-muted\">\r\n                        Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.\r\n                      </p>\r\n                    </div> --></div></div></div></div></div><!-- Vision & Mission Section --><div class=\"vision-mission-section\"><div class=\"row g-4\"><!-- Vision Card --><div class=\"col-lg-6\"><div class=\"vision-mission-card high-contrast-border vision-card h-100 p-4 rounded\"><div class=\"text-center mb-3\"><div class=\"vision-icon-wrapper mb-2\"><i class=\"fas fa-eye fa-3x text-primary\"></i></div><h3 class=\"fw-bold mb-2\">Our Vision</h3></div><div class=\"vision-content\"><h4 class=\"fw-bold text-center mb-0\">Enable Lifelong Learning For Civil Servants</h4></div></div></div><!-- Mission Card --><div class=\"col-lg-6\"><div class=\"vision-mission-card high-contrast-border mission-card h-100 p-4 rounded\"><div class=\"text-center mb-3\"><div class=\"mission-icon-wrapper mb-2\"><i class=\"fas fa-bullseye fa-3x text-warning\"></i></div><h3 class=\"fw-bold mb-2\">Our Mission</h3></div><div class=\"mission-content\"><h4 class=\"fw-bold text-center mb-0\">Enable Creating optimal learning opportunities for each civil servant with the objective to build an agile and future ready public service learning for all</h4></div></div></div></div></div><!-- Mandate Section --><div class=\"mandate-section mb-5\"><div class=\"text-center mb-5\"><h2 class=\"fw-bold mb-3\">Mandate of the Commission</h2><div class=\"title-underline mx-auto mb-4\">&nbsp;</div><p class=\"text-muted\">The key responsibilities that drive our mission</p></div><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-clipboard-list fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Capacity Building Plans</h5><p class=\"text-muted mb-0\">Facilitate preparation of Capacity Building Plans of ministries, departments, organizations and states/UTs</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-university fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Training Institutions</h5><p class=\"text-muted mb-0\">Functional supervision over all training Institutions involved in capacity building of civil servants</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-file-alt fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Annual Report</h5><p class=\"text-muted mb-0\">Prepare and present CBC\'s Annual Report to the Prime Minister\'s HR Council</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-lightbulb fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Policy Recommendations</h5><p class=\"text-muted mb-0\">Make Policy recommendations to DoPT on personnel/ HR and Capacity Building</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-chart-bar fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">HR Audit</h5><p class=\"text-muted mb-0\">Audit of Human Resources in Government and outcomes of the Capacity Building efforts</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-users fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Knowledge Partners</h5><p class=\"text-muted mb-0\">Approve Knowledge Partners and Content Validation mechanism for training of civil servants</p></div></div></div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 50, 86, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Paanch Pran Sankalpas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 50, 995, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Paanch Pran Sankalpas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 50, 1006, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Paanch Pran Sankalpas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-quote\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 50, 1273, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Paanch Pran Sankalpas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-quote\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 50, 1286, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">CHAR SANKALPAS</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-quote\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 50, 1291, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><p>The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister.</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">CHAR SANKALPAS</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-quote\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 50, 1313, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmyogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmyogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmyogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmyogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><p>The Karmyogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister.</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">CHAR SANKALPAS</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmyogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmyogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmyogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmyogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmyogi Competency Model during the inaugural \'Karmyogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-quote\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 51, 87, 'en', 0, '<section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">LARGE SCALE INTERVENTIONS</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">Introduction: Large Scale Interventions (LSI) are an approach for organising sustainable behavioural changes within the Public servants with active involvement of stakeholders throughout the whole system. The purpose of these programs is to sensitize the Public servants to the ideal of a Karmayogi, the value of living this ideal, and how to practice this ideal.</p></div></div></section><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">OBJECTIVES OF LSI</h2><div class=\"karmayogi-content-wrapper\"><ul class=\"karmayogi-text-large\" style=\"list-style-type:disc;padding-left:2rem;\"><li>Improving interactions with citizens for better Citizen experience (Citizen-centricity)</li><li>Re-awakening aspiration to serve (Seva Bhav)</li></ul></div></div></section><section class=\"karmayogi-section-fullwidth karmayogi-concept-note-section\"><div class=\"container\"><h2 class=\"karmayogi-concept-note-title\" style=\"margin-bottom:2rem;text-decoration:underline;\">RASHTRIYA KARMAYOGI JAN SEVA PROGRAM</h2><!-- Rail Karmayogi Programme --><div class=\"lsi-program-section\" style=\"margin-bottom:3rem;\"><h3 class=\"lsi-program-title\" style=\"color:#002b5b;font-size:1.5rem;margin-bottom:1.5rem;text-decoration:underline;\"><strong>RAIL KARMAYOGI PROGRAMME</strong></h3><div class=\"lsi-program-buttons\" style=\"display:flex;flex-wrap:wrap;gap:1rem;\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill me-2\"></i>VIDEO </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill me-2\"></i>EVALUATION REPORT&nbsp;</a></div></div><!-- Police Karmayogi Programme --><div class=\"lsi-program-section\" style=\"margin-bottom:3rem;\"><h3 class=\"lsi-program-title\" style=\"color:#002b5b;font-size:1.5rem;margin-bottom:1.5rem;text-decoration:underline;\"><strong>POLICE KARMAYOGI PROGRAMME</strong></h3><div class=\"lsi-program-buttons\" style=\"display:flex;flex-wrap:wrap;gap:1rem;\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill me-2\"></i>VIDEO </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill me-2\"></i>EVALUATION REPORT J&amp;K <i class=\"bi bi-file-earmark-pdf-fill me-2\"></i>EVALUATION REPORT PUDUCHERRY&nbsp;</a></div></div><!-- Dakshata Karmayogi Programme --><div class=\"lsi-program-section\" style=\"margin-bottom:3rem;\"><h3 class=\"lsi-program-title\" style=\"color:#002b5b;font-size:1.5rem;margin-bottom:1.5rem;text-decoration:underline;\"><strong>DAKSHATA KARMAYOGI PROGRAMME</strong></h3><div class=\"lsi-program-buttons\" style=\"display:flex;flex-wrap:wrap;gap:1rem;\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill me-2\"></i>VIDEO </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill me-2\"></i>EVALUATION REPORT&nbsp;</a></div></div><!-- Dak Karmayogi Programme --><div class=\"lsi-program-section\" style=\"margin-bottom:3rem;\"><h3 class=\"lsi-program-title\" style=\"color:#002b5b;font-size:1.5rem;margin-bottom:1.5rem;text-decoration:underline;\"><strong>DAK KARMAYOGI PROGRAMME</strong></h3><div class=\"lsi-program-buttons\" style=\"display:flex;flex-wrap:wrap;gap:1rem;\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill me-2\"></i>VIDEO&nbsp;</a></div></div></div></section><!-- Photo Gallery Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title text-center\"><i class=\"bi bi-images me-3\" style=\"color:#0063ae;\"></i>Photo Gallery</h2><div class=\"gallery-carousel-wrapper position-relative\" style=\"margin:30px 0;padding:0 50px;\"><p><button class=\"gallery-nav-btn gallery-nav-prev\" style=\"align-items:center;background-color:#00569A;border-radius:50%;border-style:none;box-shadow:0 2px 8px rgba(0, 0, 0, 0.2);color:white;cursor:pointer;display:flex;height:40px;justify-content:center;left:0;position:absolute;top:50%;transform:translateY(-50%);transition:all 0.3s ease;width:40px;z-index:10;\" aria-label=\"Previous\">\r\n          <i class=\"bi bi-chevron-left\"></i>\r\n        </button></p><div class=\"gallery-carousel-container\" style=\"overflow:hidden;padding:10px 0;position:relative;width:100%;\"><div class=\"gallery-carousel-track\" style=\"display:flex;gap:20px;transition:transform 0.5s ease;will-change:transform;\"><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/event1.jpg\" alt=\"Large Scale Intervention Event\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>Intervention Launch</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Capacity Building</p></div></div></div><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/event2.jpeg\" alt=\"Departmental Program\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>Departmental Program</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Training Session</p></div></div></div><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/event3.jpeg\" alt=\"State Level Initiative\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>State Level Initiative</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Governance Program</p></div></div></div><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/event4.jpeg\" alt=\"Multi-Level Program\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>Multi-Level Program</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Systemic Change</p></div></div></div><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/event5.jpeg\" alt=\"Cross-Cutting Theme\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>Cross-Cutting Theme</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Knowledge Exchange</p></div></div></div><div class=\"gallery-carousel-item\" style=\"flex:0 0 calc(33.333% - 14px);min-width:0;padding-top:10px;width:calc(33.333% - 14px);\"><div class=\"card high-contrast-border\" style=\"border-radius:10px;border-style:none;box-shadow:0 4px 15px rgba(0, 0, 0, 0.1);height:100%;overflow:hidden;transition:all 0.3s ease;\"><img class=\"card-img-top\" style=\"object-fit:cover;transition:transform 0.3s ease;\" src=\"img/collaboration_matter_01.jpeg\" alt=\"Partnership Event\" width=\"100%\" height=\"250\"><div class=\"card-body\" style=\"padding:15px;\"><h5 class=\"card-title\" style=\"color:#002b5b;font-size:1rem;margin:0 0 8px 0;\"><strong>Partnership</strong></h5><p class=\"card-text\" style=\"color:#6c757d;font-size:0.9rem;margin:0;\">Collaboration Event</p></div></div></div></div></div><p><button class=\"gallery-nav-btn gallery-nav-next\" style=\"align-items:center;background-color:#00569A;border-radius:50%;border-style:none;box-shadow:0 2px 8px rgba(0, 0, 0, 0.2);color:white;cursor:pointer;display:flex;height:40px;justify-content:center;position:absolute;right:0;top:50%;transform:translateY(-50%);transition:all 0.3s ease;width:40px;z-index:10;\" aria-label=\"Next\">\r\n          <i class=\"bi bi-chevron-right\"></i>\r\n        </button></p></div></div></section>', '', 'full_html'),
('page', 0, 51, 88, 'en', 0, '<section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">LARGE SCALE INTERVENTIONS</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">Introduction: Large Scale Interventions (LSI) are an approach for organising sustainable behavioural changes within the Public servants with active involvement of stakeholders throughout the whole system. The purpose of these programs is to sensitize the Public servants to the ideal of a Karmayogi, the value of living this ideal, and how to practice this ideal.</p></div></div></section><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">OBJECTIVES OF LSI</h2><div class=\"karmayogi-content-wrapper\"><ul class=\"karmayogi-text-large\" style=\"list-style-type:disc;padding-left:2rem;\"><li>Improving interactions with citizens for better Citizen experience (Citizen-centricity)</li><li>Re-awakening aspiration to serve (Seva Bhav)</li></ul></div></div></section><section class=\"karmayogi-section-fullwidth karmayogi-concept-note-section\"><div class=\"container\"><h2 class=\"karmayogi-concept-note-title\" style=\"margin-bottom:2rem;text-decoration:underline;\">RASHTRIYA KARMAYOGI JAN SEVA PROGRAM</h2><!-- Rail Karmayogi Programme --><div class=\"lsi-program-section\" style=\"margin-bottom:3rem;\"><h3 class=\"lsi-program-title\" style=\"color:#002b5b;font-size:1.5rem;margin-bottom:1.5rem;text-decoration:underline;\"><strong>RAIL KARMAYOGI PROGRAMME</strong></h3><div class=\"lsi-program-buttons\" style=\"display:flex;flex-wrap:wrap;gap:1rem;\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill me-2\"></i>VIDEO </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill me-2\"></i>EVALUATION REPORT&nbsp;</a></div></div><!-- Police Karmayogi Programme --><div 