ns\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill\"></i> <span>Watch Video</span> </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill\"></i> <span>Evaluation Report</span>&nbsp;</a></div></div></div></div><!-- Dak Karmayogi Programme --><div class=\"col-lg-6\"><div class=\"lsi-program-card\"><div class=\"lsi-program-header\"><div class=\"lsi-program-icon dak-icon\"><i class=\"bi bi-envelope-paper-fill\"></i></div><h3 class=\"lsi-program-title\">Dak Karmayogi Programme</h3></div><div class=\"lsi-program-body\"><p class=\"lsi-program-description\">Transforming postal services with citizen-centric approaches and behavioral excellence.</p><div class=\"lsi-program-actions\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill\"></i> <span>Watch Video</span>&nbsp;</a></div></div></div></div></div></div></div></section>', '', 'full_html');
