('page', 0, 51, 1299, 'en', 0, '<!-- LARGE SCALE INTERVENTIONS --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-section-header text-center\"><h2 class=\"karmayogi-section-title\">LARGE SCALE INTERVENTIONS</h2></div><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">Introduction: Large Scale Interventions (LSI) are an approach for organising sustainable behavioral changes within the Public servants with active involvement of stakeholders throughout the whole system. The purpose of these programs is to sensitize the Public servants to the ideal of a Karmayogi, the value of living this ideal, and how to practice this ideal.</p></div></div></section><!-- OBJECTIVES OF LSI --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-section-header text-center\"><h2 class=\"karmayogi-section-title\">OBJECTIVES OF LSI</h2></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"lsi-objective-card\"><div class=\"lsi-objective-icon\"><i class=\"bi bi-people-fill\"></i></div><h4 class=\"lsi-objective-title\">Citizen-Centricity</h4><p class=\"lsi-objective-text\">Improving interactions with citizens for better citizen experience.</p></div></div><div class=\"col-md-6\"><div class=\"lsi-objective-card\"><div class=\"lsi-objective-icon\"><i class=\"bi bi-heart-fill\"></i></div><h4 class=\"lsi-objective-title\">Seva Bhav</h4><p class=\"lsi-objective-text\">Re-awakening aspiration to serve (Seva Bhav).</p></div></div></div></div></section><!-- RASHTRIYA KARMAYOGI JAN SEVA PROGRAM --><section class=\"karmayogi-section-fullwidth karmayogi-programs-section\"><div class=\"container\"><!-- SECTION HEADING (MATCHES ABOVE DESIGN) --><div class=\"karmayogi-section-header text-center\"><h2 class=\"karmayogi-section-title\">RASHTRIYA KARMAYOGI JAN SEVA PROGRAM</h2><p class=\"karmayogi-section-subtitle\">Comprehensive programs designed to transform public service delivery through behavioral change and citizen-centric approaches.</p></div><!-- PROGRAM CARDS --><div class=\"row g-4\"><!-- Rail --><div class=\"col-lg-6\"><div class=\"lsi-program-card\"><div class=\"lsi-program-header\"><div class=\"lsi-program-icon rail-icon\"><i class=\"bi bi-train-front-fill\"></i></div><h3 class=\"lsi-program-title\">Rail Karmayogi Programme</h3></div><p class=\"lsi-program-description\">Transforming railway services through citizen-centric behavioral change initiatives.</p><div class=\"lsi-program-actions\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill\"></i> Watch Video </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill\"></i> Evaluation Report&nbsp;</a></div></div></div><!-- Police --><div class=\"col-lg-6\"><div class=\"lsi-program-card\"><div class=\"lsi-program-header\"><div class=\"lsi-program-icon police-icon\"><i class=\"bi bi-shield-check-fill\"></i></div><h3 class=\"lsi-program-title\">Police Karmayogi Programme</h3></div><p class=\"lsi-program-description\">Enhancing police-citizen interactions through behavioral transformation programs.</p><div class=\"lsi-program-actions\"><a class=\"lsi-action-btn lsi-video-btn\" href=\"#\"><i class=\"bi bi-play-circle-fill\"></i> Watch Video </a><a class=\"lsi-action-btn lsi-report-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill\"></i> Report J&amp;K <i class=\"bi bi-file-earmark-pdf-fill\"></i> Report Puducherry&nbsp;</a></div></div></div><!-- Dakshata --><div class=\"col-lg-6\"><div class=\"lsi-program-card\"><div class=\"lsi-program-header\"><div class=\"lsi-program-icon dakshata-icon\"><i class=\"bi bi-award-fill\"></i></div><h3 class=\"lsi-program-title\">Dakshata Karmayogi Programme</h3></div><p class=\"lsi-program-description\">Building excellence in public service delivery through capacity building.</p></div></div><!-- Dak --><div class=\"col-lg-6\"><div class=\"lsi-program-card\"><div class=\"lsi-program-header\"><div class=\"lsi-program-icon dak-icon\"><i class=\"bi bi-envelope-paper-fill\"></i></div><h3 class=\"lsi-program-title\">Dak Karmayogi Programme</h3></div><p class=\"lsi-program-description\">Transforming postal services with citizen-centric approaches.</p></div></div></div></div></section>', '', 'full_html'),
