('page', 0, 51, 1332, 'en', 0, '<section class=\"karmayogi-section\"><div class=\"karmayogi-card\"><!-- HEADER (ORANGE) --><div class=\"karmayogi-card-header\"><div class=\"karmayogi-icon\"><i class=\"bi bi-award-fill\"></i></div><h3 class=\"karmayogi-title\">Rastriya Karmayogi Jan Seva Program</h3></div><!-- BODY --><div class=\"karmayogi-card-body\"><p class=\"karmayogi-description\">Comprehensive programs designed to transform public service delivery through behavioral change and citizen-centric approaches.</p><p><a class=\"karmayogi-btn\" href=\"#\"><i class=\"bi bi-file-earmark-pdf-fill\"></i> Evaluation Report&nbsp;</a></p></div></div></section><p>/* PAGE BACKGROUND */ body { margin: 0; padding: 40px; background: #f4f7fb; font-family: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif; } /* SECTION */ .karmayogi-section { display: flex; justify-content: center; } /* CARD */ .karmayogi-card { width: 100%; max-width: 820px; background: #ffffff; border-radius: 18px; overflow: hidden; box-shadow: 0 20px 45px rgba(0, 0, 0, 0.12); } /* HEADER – ORANGE */ .karmayogi-card-header { background: linear-gradient(135deg, #ff8c00, #ff6a00); padding: 28px 32px; display: flex; align-items: center; gap: 18px; } /* ICON BOX */ .karmayogi-icon { width: 54px; height: 54px; background: rgba(255, 255, 255, 0.25); border-radius: 12px; display: flex; align-items: center; justify-content: center; color: #ffffff; font-size: 26px; } /* TITLE */ .karmayogi-title { margin: 0; color: #ffffff; font-size: 22px; font-weight: 600; } /* BODY */ .karmayogi-card-body { padding: 32px; } /* DESCRIPTION */ .karmayogi-description { font-size: 18px; line-height: 1.6; color: #4a4a4a; margin-bottom: 28px; } /* BUTTON */ .karmayogi-btn { display: inline-flex; align-items: center; gap: 10px; padding: 14px 24px; background: linear-gradient(135deg, #ff8c00, #ff6a00); color: #ffffff; font-size: 16px; font-weight: 600; border-radius: 10px; text-decoration: none; box-shadow: 0 10px 22px rgb