('page', 0, 74, 1446, 'en', 0, '<!-- ========================================\r\n     STATES AND UNION TERRITORIES PAGE\r\n     Updated with latest data as of 23rd Jan 2026\r\n     Theme Colors Only: Orange (#FF9800) and Blue (#0063ae)\r\n     ======================================== --><section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><h2 style=\"background-color:#FF9800;border-radius:8px;color:white;margin-bottom:20px;padding:15px 20px;text-align:center;\"><strong>For Accreditation &amp; QIP</strong></h2><!-- Overview Section --><div class=\"mb-5\" style=\"background-color:#003b73;border-radius:8px;color:white;padding:30px;\"><h2 style=\"color:white;margin-bottom:15px;\"><strong>Engagement with States/UTs</strong></h2><p style=\"color:white;font-size:1.1rem;line-height:1.6;margin:0;\"><strong>Overview:</strong> The Capacity Building Commission engages closely with States and Union Territories to support implementation of capacity-building initiatives. Dedicated team under Mission Karmayogi have been assigned to facilitate coordination and implementation at the State/UT level.</p></div><!-- At-a-Glance Summary --><div class=\"mb-5\"><h2 style=\"background-color:#FF9800;border-radius:8px;color:white;margin-bottom:20px;padding:15px 20px;text-align:center;\"><strong>At-a-Glance Summary</strong></h2><div class=\"table-responsive\"><table class=\"table\" style=\"border:2px solid #FF9800;\"><thead style=\"background-color:#ffe3ab;\"><tr><th style=\"border-color:#ddd;padding:15px;text-align:center;\">Total States/UTs engaged</th><th style=\"border-color:#ddd;padding:15px;text-align:center;\">Number of MoUs signed</th><th style=\"border-color:#ddd;padding:15px;text-align:center;\">No. of Workshops conducted in States/UTs (Online + Offline)</th></tr></thead><tbody><tr style=\"background-color:#fff9f0;\"><td style=\"border-color:#ddd;color:#0063ae;font-size:1.5rem;padding:15px;text-align:center;\"><strong>36</strong></td><td style=\"border-color:#ddd;color:#FF9800;font-size:1.5rem;padding:15px;text-align:center;\"><strong>28</strong></td><td style=\"border-color:#ddd;color:#666;font-size:1.2rem;padding:15px;text-align:center;\"><h2><strong>-</strong></h2></td></tr></tbody></table></div></div><!-- Important Documents Section --><div class=\"mb-5\"><h2 style=\"background-color:#FF9800;border-radius:8px;color:white;margin-bottom:20px;padding:15px 20px;text-align:center;\"><strong>Important Documents</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table\"><thead><tr><th style=\"white-space:nowrap;width:5%;\">Sr. No.</th><th style=\"width:70%;\">Important Documents</th><th style=\"width:25%;\">Document/Download</th></tr></thead><tbody><tr><td>1</td><td>Standard Operating Procedure for AI-iGOT Driven Capacity Building Plans for Administrative Training Institutes (ATIs)</td><td><a style=\"background-color:#FF9800;border-radius:5px;color:white;display:inline-block;padding:8px 20px;text-decoration:none;\" href=\"/sites/default/files/2026-01/SOP_Mission%20Karmayogi%20for%20ATIs.pdf\" target=\"_blank\"><strong><i class=\"fas fa-file-pdf\" style=\"margin-right:8px;\"></i>View&nbsp;</strong></a></td></tr></tbody></table></div></div><!-- Roles at a Glance --><div class=\"mb-5\"><h2 style=\"background-color:#0063ae;border-radius:8px;color:white;margin-bottom:20px;padding:15px 20px;text-align:center;\"><strong>Roles at a Glance</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table\"><thead><tr><th style=\"white-space:nowrap;width:5%;\">Sr. No.</th><th style=\"width:45%;\">Role</th><th style=\"width:50%;\">Responsibility</th></tr></thead><tbody><tr><td>1</td><td>Central Team</td><td>Guidance and Support</td></tr><tr><td>2</td><td>Program Coordinator (State)</td><td>Primary point of contact for State/UT coordination</td></tr><tr><td>3</td><td>Assistant Manager</td><td>Technical Queries and Resolution</td></tr></tbody></table></div></div><