INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 74, 1569, 'en', 0, '<!-- ========================================\r\n     STATES AND UNION TERRITORIES PAGE\r\n     Updated with latest data as of 23rd Jan 2026\r\n     Theme Colors Only: Orange (#FF9800) and Blue (#0063ae)\r\n     ======================================== --><section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><h2 class=\"states-header-orange mb-5\"><a class=\"text-white text-decoration-none\" href=\"/sites/default/files/2026-02/SOP_Mission%20Karmayogi%20for%20ATIs%20%281%29.pdf\"><i class=\"fas fa-file-pdf me-2\"></i> Standard Operating Procedure (SOP) for States &amp; UTs</a></h2><!-- Overview Section --><div class=\"states-overview-box\"><h2 class=\"text-white mb-3\"><strong>Engagement with States/UTs</strong></h2><p class=\"mb-0 fs-5 lh-base\"><strong>Overview:</strong> The Capacity Building Commission engages closely with States and Union Territories to support implementation of capacity-building initiatives. Dedicated team under Mission Karmayogi have been assigned to facilitate coordination and implementation at the State/UT level.</p></div><!-- At-a-Glance Summary --><div class=\"mb-5\"><h2 class=\"states-header-orange\"><strong>At-a-Glance Summary</strong></h2><div class=\"table-responsive\"><table class=\"table states-table-summary\"><thead><tr><th>Total States/UTs engaged</th><th>Number of MoUs signed</th><th>No. of Workshops conducted in States/UTs (Online + Offline)</th></tr></thead><tbody><tr><td><strong class=\"states-summary-val-blue\">36</strong></td><td><strong class=\"states-summary-val-orange\">28</strong></td><td><h2 class=\"mb-0\"><strong class=\"states-summary-val-gray\">-</strong></h2></td></tr></tbody></table></div></div><!-- Important Documents Section --><div class=\"mb-5\"><h2 class=\"states-header-orange\"><strong>Important Documents</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table states-ut-table important-docs-table\"><thead><tr><th>Sr. No.</th><th>Important Documents</th><th>Document/Download</th></tr></thead><tbody><tr><td>1</td><td>Standard Operating Procedure for AI-iGOT Driven Capacity Building Plans for Administrative Training Institutes (ATIs)</td><td><a class=\"btn btn-warning text-white rounded-pill px-4 py-2 fw-bold\" href=\"/sites/default/files/2026-01/SOP_Mission%20Karmayogi%20for%20ATIs.pdf\" target=\"_blank\"><i class=\"fas fa-file-pdf me-2\"></i>View</a></td></tr></tbody></table></div></div><!-- Roles at a Glance --><div class=\"mb-5\"><h2 class=\"states-header-blue\"><strong>Roles at a Glance</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table states-ut-table roles-table\"><thead><tr><th>Sr. No.</th><th>Role</th><th>Responsibility</th></tr></thead><tbody><tr><td>1</td><td>Central Team</td><td>Guidance and Support</td></tr><tr><td>2</td><td>Program Coordinator (State)</td><td>Primary point of contact for State/UT coordination</td></tr><tr><td>3</td><td>Assistant Manager</td><td>Technical Queries and Resolution</td></tr></tbody></table></div></div><!-- State/UT Central Team --><div class=\"mb-5\"><h2 class=\"states-header-orange\"><strong>State/UT Central Team</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table states-ut-table central-team-table\"><thead><tr><th>Sr. No.</th><th>Designation</th><th>Name</th><th>Contact</th><th>Email ID</th></tr></thead><tbody><tr><td>1</td><td>Principal Advisor</td><td>Chandralekha Mukherjee</td><td>9891340077</td><td>prinsadv.states-cbc@gov.in</td></tr><tr><td>2</td><td>Advisor</td><td>Ranu Mookerjee</td><td>8860040337</td><td>advisor.states-cbc@gov.in</td></tr></tbody></table></div></div><!-- State/UT Team --><div class=\"mb-5\"><h2 class=\"states-header-blue\"><strong>State/UT Team</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table states-ut-table team-table\"><thead><tr><th>Sr. No.</th><th>States/UTs</th><th>MoU Status</th><th>Program Co