('page', 0, 75, 120, 'en', 0, '<section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><!-- Mission Karmyogi Header --><div class=\"mission-karmayogi-header mb-4 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">Mission Karmyogi</h2></div><div class=\"intro-content mb-3\"><p class=\"text-muted\"><strong>National Programme for Civil Services Capacity Building (NPCSCB) – Mission Karmayogi</strong> was launched in September 2020.</p></div><!-- Mission Karmayogi Section --><div class=\"mission-karmayogi-highlight mb-5 p-4 rounded\"><div class=\"row align-items-center\"><div class=\"col-md-12\" mb-4=\"\"><!-- <h3 class=\"text-gradient mb-3\">Mission Karmayogi</h3> --><p class=\"mb-2\"><strong>\"Mission Karmayogi\"</strong> – aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonization for effective and efficient public service delivery.</p><p class=\"mb-0\">Envisioned as one of the largest capacity building initiatives in Government anywhere in the world, Mission Karmayogi aims to transform approximately <strong>1.5 crore government officials</strong> across the Centre, the States, and the local bodies.</p></div><div class=\"col-md-12 text-center mb-3 mb-md-0 mt-4\"><!-- Mission Karmayogi Institutional Framework Flowchart --><div class=\"institutional-framework-flowchart\"><div class=\"framework-header\"><h4 class=\"framework-title\">Mission Karmayogi – Institutional Framework</h4></div><div class=\"framework-content\"><div class=\"row g-3\"><!-- Capacity Building Commission Box --><div class=\"col-6\"><div class=\"framework-box high-contrast-border cbc-box\"><div class=\"framework-logo cbc-logo\"><img class=\"framework-logo-img\" src=\"img/cbc_logo.png\" alt=\"CBC Logo\"></div><h5 class=\"framework-box-title\">Capacity Building Commission</h5></div></div><!-- Karmayogi Bharat Box --><div class=\"col-6\"><div class=\"framework-box high-contrast-border karmayogi-box\"><div class=\"framework-logo karmayogi-logo\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\"><img class=\"framework-logo-img\" src=\"img/igot_karmyogi_logo.png\" alt=\"iGOT Karmayogi Logo\"></a></div><h5 class=\"framework-box-title\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\">Karmayogi Bharat</a></h5><p class=\"framework-box-subtitle\"><a class=\"framework-box-link\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\">(SPV - 100% govt. owned online learning platform - iGOT Karmayogi)</a></p></div></div></div></div></div></div></div></div><!-- About CBC Section --><div class=\"about-cbc-core mb-5\"><h2 class=\"mb-4 fw-bold\">About Capacity Building Commission</h2><div class=\"row\"><div class=\"col-lg-12\"><div class=\"cbc-intro-card p-4 mb-4 rounded\"><div class=\"row align-items-center\"><div class=\"col-md-12\"><!-- <h4 class=\"fw-bold mb-3\">The Capacity Building Commission (CBC)</h4> --><p class=\"mb-3\">Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.</p></div><!-- <div class=\"intro-content\">\r\n                      <p class=\"lead text-muted\">\r\n                        Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.\r\n                      </p>\r\n                    </div> --></div></div></div></div></div><!-- Vision & Mission Section --><div class=\"vision-mission-section\"><div class=\"row g-4\"><!-- Vision Card --><div class=\"col-lg-6\"><div class=\"vision-mission-card high-contrast-border vision-card h-100 p-4 rounded\"><div class=\"text-center mb-3\"><div class=\"vision-icon-wrapper mb-2\"><i class=\"fas fa-eye fa-3x text-primary\"></i></div><h3 class=\"fw-bold mb-2\">Our Vision</h3></div><div class=\"vision-content\"><h4 class=\"fw-bold text-center mb-0\">Enable Lifelong Learning For Civil Servants</h4></div></div></div><!-- Mission Card --><div class=\"col-lg-6\"><div class=\"vision-mission-card high-contrast-border mission-card h-100 p-4 rounded\"><div class=\"text-center mb-3\"><div class=\"mission-icon-wrapper mb-2\"><i class=\"fas fa-bullseye fa-3x text-warning\"></i></div><h3 class=\"fw-bold mb-2\">Our Mission</h3></div><div class=\"mission-content\"><h4 class=\"fw-bold text-center mb-0\">Enable Creating optimal learning opportunities for each civil servant with the objective to build an agile and future ready public service learning for all</h4></div></div></div></div></div><!-- Mandate Section --><div class=\"mandate-section mb-5\"><div class=\"text-center mb-5\"><h2 class=\"fw-bold mb-3\">Mandate of the Commission</h2><div class=\"title-underline mx-auto mb-4\">&nbsp;</div><p class=\"text-muted\">The key responsibilities that drive our mission</p></div><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-clipboard-list fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Capacity Building Plans</h5><p class=\"text-muted mb-0\">Facilitate preparation of Capacity Building Plans of ministries, departments, organizations and states/UTs</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-university fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Training Institutions</h5><p class=\"text-muted mb-0\">Functional supervision over all training Institutions involved in capacity building of civil servants</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-file-alt fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Annual Report</h5><p class=\"text-muted mb-0\">Prepare and present CBC\'s Annual Report to the Prime Minister\'s HR Council</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-lightbulb fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Policy Recommendations</h5><p class=\"text-muted mb-0\">Make Policy recommendations to DoPT on personnel/ HR and Capacity Building</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-chart-bar fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">HR Audit</h5><p class=\"text-muted mb-0\">Audit of Human Resources in Government and outcomes of the Capacity Building efforts</p></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"mandate-card h-100 p-4 rounded\"><div class=\"mandate-icon mb-3\"><i class=\"fas fa-users fa-2x text-primary\"></i></div><h5 class=\"fw-bold mb-3\">Knowledge Partners</h5><p class=\"text-muted mb-0\">Approve Knowledge Partners and Content Validation mechanism for training of civil servants</p></div></div></div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 75, 121, 'en', 0, '<section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><!-- Mission Karmyogi Header --><div class=\"mission-karmayogi-header mb-4 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">Mission Karmyogi</h2></div><div class=\"intro-content mb-3\"><p class=\"text-muted\"><strong>National Programme for Civil Services Capacity Building (NPCSCB) – Mission Karmayogi</strong> was launched in September 2020.</p></div><!-- Mission Karmayogi Section --><div class=\"mission-karmayogi-highlight mb-5 p-4 rounded\"><div class=\"row align-items-center\"><div class=\"col-md-12\" mb-4=\"\"><!-- <h3 class=\"text-gradient mb-3\">Mission Karmayogi</h3> --><p class=\"mb-2\"><strong>\"Mission Karmayogi\"</strong> – aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonization for effective and efficient public service delivery.</p><p class=\"mb-0\">Envisioned as one of the largest capacity building initiatives in Government anywhere in the world, Mission Karmayogi aims to transform approximately <strong>1.5 crore government officials</strong> across the Centre, the States, and the local bodies.</p></div><div class=\"col-md-12 text-center mb-3 mb-md-0 mt-4\"><!-- Mission Karmayogi Institutional Framework Flowchart --><div class=\"institutional-framework-flowchart\"><div class=\"framework-header\"><h4 class=\"framework-title\">Mission Karmayogi – Institutional Framework</h4></div><div class=\"framework-content\"><div class=\"row g-3\"><!-- Capacity Building Commission Box --><div class=\"col-6\"><div class=\"framework-box high-contrast-border cbc-box\"><div class=\"framework-logo cbc-logo\"><img class=\"framework-logo-img\" src=\"img/cbc_logo.png\" alt=\"CBC Logo\"></div><h5 class=\"framework-box-title\">Capacity Building Commission</h5></div></div><!-- Karmayogi Bharat Box --><div class=\"col-6\"><div class=\"framework-box