('page', 0, 76, 1388, 'en', 0, '<!-- ========================================\r\n     AMRIT GYAAN KOSH (AGK) SECTIONS\r\n     Ready to paste into Drupal views\r\n     With alternating orange/white backgrounds\r\n     ======================================== --><!-- Section 1: What is Amrit Gyaan Kosh? (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3\"></i> What is Amrit Gyaan Kosh?</h2><p class=\"karmayogi-text-large\">Amrit Gyaan Kosh is a dynamic repository of knowledge resources that captures and curates best practices in governance in form of case studies. This initiative is designed to reinforce the principles of Atmanirbharta, support the objectives of Mission Karmayogi, and contribute to the Hon\'ble Prime Minister\'s vision of a citizen-centric, transparent, and accountable governance framework. Focusing on India-centric ideas, exemplary best practices, and scalable governance models, these resources serve as a guide for Group A, B, and C officials across Central and State Governments, Municipalities, and Panchayats.</p><p class=\"karmayogi-text-large\">Each case study is designed with precise learning objectives to enhance problem-solving capabilities and encourage evidence-based decision-making. Beyond government training institutes, this repository extends its reach to global academic institutions, enabling the exchange of India\'s governance experiences with the world.</p></div></section><!-- Section 2: Strategic Objectives of Amrit Gyaan Kosh (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-ideation-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\"></i> Strategic Objectives of Amrit Gyaan Kosh</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-database-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Digital Knowledge Hub</h3><p class=\"karmayogi-learning-text\">Establish a structured, digital knowledge hub for case studies and best practices.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-mortarboard-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Case-Based Learning</h3><p class=\"karmayogi-learning-text\">Promote adoption of case-based learning within India\'s public administration training ecosystem.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-award-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Enhanced Training Programs</h3><p class=\"karmayogi-learning-text\">Enhance civil services training programs with engaging, real-world learning materials.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Faculty Capability Building</h3><p class=\"karmayogi-learning-text\">Strengthen case writing and teaching capabilities among faculty at CTIs and ATIs.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-globe-asia-australia\"></i></div><h3 class=\"karmayogi-learning-title\">Global Platform</h3><p class=\"karmayogi-learning-text\">Facilitate the use of India-centric case studies on national and international platforms.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\"><i class=\"bi bi-share-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Peer Learning</h3><p class=\"karmayogi-learning-text\">Encourage government officials to document and share innovations, fostering peer learning.</p></div></div></div></div></section><!-- Section 3: Core Principles of the Case Studies (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-intervention-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-gear-fill me-3\"></i> Core Principles of the Case Studies</h2><p class=\"karmayogi-text-large text-center mb-4\">Each case study is developed based on the following key principles:</p><div class=\"row g-4 mt-3\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center mb-3\"><i class=\"bi bi-calendar-check-fill\" style=\"color:#0063ae;font-size:3rem;\"></i></div><h3 class=\"karmayogi-phase-title\" style=\"justify-content:center;\">Relevant</h3><p class=\"karmayogi-phase-description\">The case should be current and contemporary, ideally not older than three years.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center mb-3\"><i class=\"bi bi-person-check-fill\" style=\"color:#28a745;font-size:3rem;\"></i></div><h3 class=\"karmayogi-phase-title\" style=\"justify-content:center;\">Relatable</h3><p class=\"karmayogi-phase-description\">The learnings should connect to the learner\'s daily life and experiences.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center mb-3\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;font-size:3rem;\"></i></div><h3 class=\"karmayogi-phase-title\" style=\"justify-content:center;\">Applicable</h3><p class=\"karmayogi-phase-description\">The insights gained should be practical and actionable for the learner.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center mb-3\"><i class=\"bi bi-arrow-repeat\" style=\"color:#28a745;font-size:3rem;\"></i></div><h3 class=\"karmayogi-phase-title\" style=\"justify-content:center;\">Scalable</h3><p class=\"karmayogi-phase-description\">The solution presented should be a replicable model.</p></div></div></div></div></section><!-- Section 4: Access to Amrit Gyaan Kosh Case Studies (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-link-45deg me-3\"></i> Access to Amrit Gyaan Kosh Case Studies</h2><p class=\"karmayogi-text-large text-center\">All published case studies under Amrit Gyaan Kosh are available on the iGOT platform in the Amrit Gyaan section. Registered and even non-registered users of IGOT can access these case studies directly from the iGOT homepage using the link below:</p><div class=\"text-center mt-4\"><a class=\"lsi-report-btn-orange\" style=\"border-radius:8px;display:inline-block;font-size:1.1rem;padding:15px 40px;text-decoration:none;\" href=\"https://www.igotkarmayogi.gov.in/#/show-all?type=case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> Access Case Studies on iGOT&nbsp;</strong></a></div></div></section><!-- Section 5: Capacity Building through Advanced Case Writing and Teaching Workshops (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-elements-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event-fill me-3\"></i> Capacity Building through Advanced Case Writing and Teaching Workshops</h2><div class=\"karmayogi-feature-block mt-4\" style=\"background-color:rgba(0, 99, 174, 0.05);border-left:5px solid #0063ae;\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> April 2023</h3><p class=\"karmayogi-text-large\">Organised a 3-day <strong>Case Teaching Workshop</strong> in collaboration with <strong>Harvard Business School</strong> for 30 faculty members from Central Training Institutes (CTIs) and Administrative Training Institutes (ATIs).</p></div><div class=\"karmayogi-feature-block mt-4\" style=\"background-color:rgba(40, 167, 69, 0.05);border-left:5px solid #28a745;\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> December 2024</h3><p class=\"karmayogi-text-large\">Conducted a 5-day <strong>Advanced Case Writing and Teaching Workshop</strong> in partnership with <strong>Stanford LAD, Asian Development Bank (ADB), and Asian Development Bank Institute (ADBI)</strong> for 60 faculty members from CTIs/ATIs. Over 50 case studies were developed by participants and 7 faculty mentors from top institutions like IITs guided participants through the writing process.</p></div><div class=\"karmayogi-feature-block mt-4\" style=\"background-color:rgba(255, 153, 51, 0.05);border-left:5px solid #ff9933;\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> September 2025</h3><p class=\"karmayogi-text-large\">In September 2025, the <strong>Second Edition of the Advanced Case Writing Workshop</strong> was conducted for 75 new faculty members from CTIs and ATIs, organised across three cohorts in different cities of India. The program was led by instructors from <strong>Stanford LAD and IIT Delhi</strong> with support from ADB and ADBI, while 10 mentors from the December 2024 batch returned as Faculty Mentors to guide and support participants in their case writing journey.</p></div><div class=\"karmayogi-requirements-card mt-4\"><h3 class=\"karmayogi-requirements-title\"><i class=\"bi bi-trophy-fill me-2\"></i> Building a Cadre of Master Trainers</h3><p class=\"karmayogi-requirements-text\">One of the central achievements of the program has been the development of an emerging pool of Master Trainers in the Government training ecosystem drawn from workshop alumni. 10 participants were selected from December 2024 workshop to mentor participants from September 2025 workshop. These trainers:</p><ul class=\"karmayogi-feature-list mt-3\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Mentor new participants across India</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Co-facilitated the September 2025 cohorts</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Support institutes in embedding case-based teaching into curricula</span></li></ul></div><div class=\"karmayogi-topics-card mt-4\"><h3 class=\"karmayogi-topics-title\"><i class=\"bi bi-star-fill me-2\"></i> Participants\' Experience and Feedback</h3><div class=\"row g-3 mt-2\"><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\" style=\"border-left-color:#28a745;\"><i class=\"bi bi-hand-thumbs-up-fill\" style=\"color:#28a745;\"></i> <span><strong>100%</strong> of respondents said they would recommend the workshop to colleagues</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\" style=\"border-left-color:#ffc107;\"><i class=\"bi bi-star-fill\" style=\"color:#ffc107;\"></i> <span><strong>4.8/5</strong> overall rating - The program received excellent ratings from participants</span></div></div></div></div></div></section><!-- Section 6: Statistics to be Highlighted (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\"></i> Key Statistics &amp; Achievements</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-file-earmark-check-fill\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#28a745;font-size:2.5rem;\">70</h3><p class=\"karmayogi-learning-text\">Cases currently live on IGOT</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-hourglass-split\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#ff9933;font-size:2.5rem;\">70</h3><p class=\"karmayogi-learning-text\">Cases in the pipeline</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#00a8e8;\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#0063ae;font-size:2.5rem;\">150+</h3><p class=\"karmayogi-learning-text\">Faculty from CTIs and ATIs trained in Case Writing</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#e83e8c;\"><i class=\"bi bi-globe2\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#dc3545;font-size:2.5rem;\">10</h3><p class=\"karmayogi-learning-text\">Cases co-published with ADBI, Tokyo</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-flag-fill\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#17a2b8;font-size:2.5rem;\">17</h3><p class=\"karmayogi-learning-text\">Features case studies aligned with all 17 Sustainable Development Goals (SDGs)</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon\" style=\"background-color:#e83e8c;\"><i class=\"bi bi-map-fill\"></i></div><h3 class=\"karmayogi-learning-title\" style=\"color:#6f42c1;font-size:2.5rem;\">20+</h3><p class=\"karmayogi-learning-text\">Cases published cover more than 20 states and represent diverse themes</p></div></div></div><div class=\"text-center mt-5\"><a class=\"lsi-report-btn-orange\" style=\"border-radius:8px;display:inline-block;font-size:1.1rem;padding:15px 40px;text-decoration:none;\" href=\"https://www.adb.org/adbi/publications/case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> View ADBI Published Cases&nbsp;</strong></a></div></div></section>', '', 'full_html'),
('page', 0, 76, 1548, 'en', 0, '<!-- Section 1: What is Amrit Gyaan Kosh? (Orange Gradient) --><!-- ========================================\r\n     AMRIT GYAAN KOSH (AGK) SECTIONS\r\n     Refactored to use external CSS classes\r\n     ======================================== --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3\"></i> What is Amrit Gyaan Kosh?</h2><p class=\"karmayogi-text-large\">Amrit Gyaan Kosh is a dynamic repository of knowledge resources that captures and curates best practices in governance in form of case studies. This initiative is designed to reinforce the principles of Atmanirbharta, support the objectives of Mission Karmayogi, and contribute to the Hon\'ble Prime Minister\'s vision of a citizen-centric, transparent, and accountable governance framework. Focusing on India-centric ideas, exemplary best practices, and scalable governance models, these resources serve as a guide for Group A, B, and C officials across Central and State Governments, Municipalities, and Panchayats.</p><p class=\"karmayogi-text-large\">Each case study is designed with precise learning objectives to enhance problem-solving capabilities and encourage evidence-based decision-making. Beyond government training institutes, this repository extends its reach to global academic institutions, enabling the exchange of India\'s governance experiences with the world.</p></div></section><!-- Section 2: Strategic Objectives of Amrit Gyaan Kosh (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-ideation-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\"></i> Strategic Objectives of Amrit Gyaan Kosh</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-database-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Digital Knowledge Hub</h3><p class=\"karmayogi-learning-text\">Establish a structured, digital knowledge hub for case studies and best practices.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-mortarboard-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Case-Based Learning</h3><p class=\"karmayogi-learning-text\">Promote adoption of case-based learning within India\'s public administration training ecosystem.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-yellow\"><i class=\"bi bi-award-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Enhanced Training Programs</h3><p class=\"karmayogi-learning-text\">Enhance civil services training programs with engaging, real-world learning materials.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Faculty Capability Building</h3><p class=\"karmayogi-learning-text\">Strengthen case writing and teaching capabilities among faculty at CTIs and ATIs.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-cyan\"><i class=\"bi bi-globe-asia-australia\"></i></div><h3 class=\"karmayogi-learning-title\">Global Platform</h3><p class=\"karmayogi-learning-text\">Facilitate the use of India-centric case studies on national and international platforms.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-share-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Peer Learning</h3><p class=\"karmayogi-learning-text\">Encourage government officials to document and share innovations, fostering peer learning.</p></div></div></div></div></section><!-- Section 3: Core Principles of the Case Studies (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-intervention-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-gear-fill me-3\"></i> Core Principles of the Case Studies</h2><p class=\"karmayogi-text-large text-center mb-4\">Each case study is developed based on the following key principles:</p><div class=\"row g-4 mt-3\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center\"><i class=\"bi bi-calendar-check-fill text-primary phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Relevant</h3><p class=\"karmayogi-phase-description\">The case should be current and contemporary, ideally not older than three years.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center\"><i class=\"bi bi-person-check-fill text-success phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Relatable</h3><p class=\"karmayogi-phase-description\">The learnings should connect to the learner\'s daily life and experiences.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center\"><i class=\"bi bi-check-circle-fill text-primary phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Applicable</h3><p class=\"karmayogi-phase-description\">The insights gained should be practical and actionable for the learner.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center\"><i class=\"bi bi-arrow-repeat text-success phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Scalable</h3><p class=\"karmayogi-phase-description\">The solution presented should be a replicable model.</p></div></div></div></div></section><!-- Section 4: Access to Amrit Gyaan Kosh Case Studies (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-link-45deg me-3\"></i> Access to Amrit Gyaan Kosh Case Studies</h2><p class=\"karmayogi-text-large text-center\">All published case studies under Amrit Gyaan Kosh are available on the iGOT platform in the Amrit Gyaan section. Registered and even non-registered users of IGOT can access these case studies directly from the iGOT homepage using the link below:</p><div class=\"text-center mt-4\"><a class=\"btn-karmayogi-orange\" href=\"https://www.igotkarmayogi.gov.in/#/show-all?type=case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> Access Case Studies on iGOT&nbsp;</strong>&nbsp;</a></div></div></section><!-- Section 5: Capacity Building through Advanced Case Writing and Teaching Workshops (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-elements-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event-fill me-3\"></i> Capacity Building through Advanced Case Writing and Teaching Workshops</h2><div class=\"karmayogi-feature-block mt-4 bg-alice-blue border-left-blue\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> April 2023</h3><p class=\"karmayogi-text-large\">Organised a 3-day <strong>Case Teaching Workshop</strong> in collaboration with <strong>Harvard Business School</strong> for 30 faculty members from Central Training Institutes (CTIs) and Administrative Training Institutes (ATIs).</p></div><div class=\"karmayogi-feature-block mt-4 bg-light-green border-left-green\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> December 2024</h3><p class=\"karmayogi-text-large\">Conducted a 5-day <strong>Advanced Case Writing and Teaching Workshop</strong> in partnership with <strong>Stanford LAD, Asian Development Bank (ADB), and Asian Development Bank Institute (ADBI)</strong> for 60 faculty members from CTIs/ATIs. Over 50 case studies were developed by participants and 7 faculty mentors from top institutions like IITs guided participants through the writing process.</p></div><div class=\"karmayogi-feature-block mt-4 bg-light-orange border-left-orange\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> September 2025</h3><p class=\"karmayogi-text-large\">In September 2025, the <strong>Second Edition of the Advanced Case Writing Workshop</strong> was conducted for 75 new faculty members from CTIs and ATIs, organised across three cohorts in different cities of India. The program was led by instructors from <strong>Stanford LAD and IIT Delhi</strong> with support from ADB and ADBI, while 10 mentors from the December 2024 batch returned as Faculty Mentors to guide and support participants in their case writing journey.</p></div><div class=\"karmayogi-requirements-card mt-4\"><h3 class=\"karmayogi-requirements-title\"><i class=\"bi bi-trophy-fill me-2\"></i> Building a Cadre of Master Trainers</h3><p class=\"karmayogi-requirements-text\">One of the central achievements of the program has been the development of an emerging pool of Master Trainers in the Government training ecosystem drawn from workshop alumni. 10 participants were selected from December 2024 workshop to mentor participants from September 2025 workshop. These trainers:</p><ul class=\"karmayogi-feature-list mt-3\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Mentor new participants across India</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Co-facilitated the September 2025 cohorts</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Support institutes in embedding case-based teaching into curricula</span></li></ul></div><div class=\"karmayogi-topics-card mt-4\"><h3 class=\"karmayogi-topics-title\"><i class=\"bi bi-star-fill me-2\"></i> Participants\' Experience and Feedback</h3><div class=\"row g-3 mt-2\"><div class=\"col-md-6\"><div class=\"karmayogi-topic-item karmayogi-list-green\"><i class=\"bi bi-hand-thumbs-up-fill text-green\"></i> <span><strong>100%</strong> of respondents said they would recommend the workshop to colleagues</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item karmayogi-list-orange\"><i class=\"bi bi-star-fill text-orange\"></i> <span><strong>4.8/5</strong> overall rating - The program received excellent ratings from participants</span></div></div></div></div></div></section><!-- Section 6: Statistics to be Highlighted (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\"></i> Key Statistics &amp; Achievements</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-file-earmark-check-fill\"></i></div><h3 class=\"karmayogi-learning-title text-green agk-stat-number\">70</h3><p class=\"karmayogi-learning-text\">Cases currently live on IGOT</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-yellow\"><i class=\"bi bi-hourglass-split\"></i></div><h3 class=\"karmayogi-learning-title text-orange agk-stat-number\">70</h3><p class=\"karmayogi-learning-text\">Cases in the pipeline</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-cyan\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title text-primary agk-stat-number\">150+</h3><p class=\"karmayogi-learning-text\">Faculty from CTIs and ATIs trained in Case Writing</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-pink\"><i class=\"bi bi-globe2\"></i></div><h3 class=\"karmayogi-learning-title text-red agk-stat-number\">10</h3><p class=\"karmayogi-learning-text\">Cases co-published with ADBI, Tokyo</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-flag-fill\"></i></div><h3 class=\"karmayogi-learning-title text-info agk-stat-number\">17</h3><p class=\"karmayogi-learning-text\">Features case studies aligned with all 17 Sustainable Development Goals (SDGs)</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-pink\"><i class=\"bi bi-map-fill\"></i></div><h3 class=\"karmayogi-learning-title text-purple agk-stat-number\">20+</h3><p class=\"karmayogi-learning-text\">Cases published cover more than 20 states and represent diverse themes</p></div></div></div><div class=\"text-center mt-5\"><a class=\"btn-karmayogi-orange\" href=\"https://www.adb.org/adbi/publications/case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> View ADBI Published Cases&nbsp;</strong>&nbsp;</a></div></div></section>', '', 'full_html'),
('page', 0, 76, 1559, 'en', 0, '<!-- Section 1: What is Amrit Gyaan Kosh? (Orange Gradient) --><!-- ========================================\r\n     AMRIT GYAAN KOSH (AGK) SECTIONS\r\n     Refactored to use external CSS classes\r\n     ======================================== --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3\"></i> What is Amrit Gyaan Kosh?</h2><p class=\"karmayogi-text-large\">Amrit Gyaan Kosh is a dynamic repository of knowledge resources that captures and curates best practices in governance in form of case studies. This initiative is designed to reinforce the principles of Atmanirbharta, support the objectives of Mission Karmayogi, and contribute to the Hon\'ble Prime Minister\'s vision of a citizen-centric, transparent, and accountable governance framework. Focusing on India-centric ideas, exemplary best practices, and scalable governance models, these resources serve as a guide for Group A, B, and C officials across Central and State Governments, Municipalities, and Panchayats.</p><p class=\"karmayogi-text-large\">Each case study is designed with precise learning objectives to enhance problem-solving capabilities and encourage evidence-based decision-making. Beyond government training institutes, this repository extends its reach to global academic institutions, enabling the exchange of India\'s governance experiences with the world.</p></div></section><!-- Section 2: Strategic Objectives of Amrit Gyaan Kosh (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-ideation-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\"></i> Strategic Objectives of Amrit Gyaan Kosh</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-database-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Digital Knowledge Hub</h3><p class=\"karmayogi-learning-text\">Establish a structured, digital knowledge hub for case studies and best practices.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-mortarboard-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Case-Based Learning</h3><p class=\"karmayogi-learning-text\">Promote adoption of case-based learning within India\'s public administration training ecosystem.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-yellow\"><i class=\"bi bi-award-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Enhanced Training Programs</h3><p class=\"karmayogi-learning-text\">Enhance civil services training programs with engaging, real-world learning materials.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Faculty Capability Building</h3><p class=\"karmayogi-learning-text\">Strengthen case writing and teaching capabilities among faculty at CTIs and ATIs.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-cyan\"><i class=\"bi bi-globe-asia-australia\"></i></div><h3 class=\"karmayogi-learning-title\">Global Platform</h3><p class=\"karmayogi-learning-text\">Facilitate the use of India-centric case studies on national and international platforms.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-share-fill\"></i></div><h3 class=\"karmayogi-learning-title\">Peer Learning</h3><p class=\"karmayogi-learning-text\">Encourage government officials to document and share innovations, fostering peer learning.</p></div></div></div></div></section><!-- Section 3: Core Principles of the Case Studies (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-intervention-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-gear-fill me-3\"></i> Core Principles of the Case Studies</h2><p class=\"karmayogi-text-large text-center mb-4\">Each case study is developed based on the following key principles:</p><div class=\"row g-4 mt-3\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center\"><i class=\"bi bi-calendar-check-fill text-primary phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Relevant</h3><p class=\"karmayogi-phase-description\">The case should be current and contemporary, ideally not older than three years.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center\"><i class=\"bi bi-person-check-fill text-success phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Relatable</h3><p class=\"karmayogi-phase-description\">The learnings should connect to the learner\'s daily life and experiences.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-primary\"><div class=\"text-center\"><i class=\"bi bi-check-circle-fill text-primary phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Applicable</h3><p class=\"karmayogi-phase-description\">The insights gained should be practical and actionable for the learner.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-phase-card karmayogi-phase-card-success\"><div class=\"text-center\"><i class=\"bi bi-arrow-repeat text-success phase-card-icon-lg\"></i></div><h3 class=\"karmayogi-phase-title text-center\">Scalable</h3><p class=\"karmayogi-phase-description\">The solution presented should be a replicable model.</p></div></div></div></div></section><!-- Section 4: Access to Amrit Gyaan Kosh Case Studies (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-link-45deg me-3\"></i> Access to Amrit Gyaan Kosh Case Studies</h2><p class=\"karmayogi-text-large text-center\">All published case studies under Amrit Gyaan Kosh are available on the iGOT platform in the Amrit Gyaan section. Registered and even non-registered users of IGOT can access these case studies directly from the iGOT homepage using the link below:</p><div class=\"text-center mt-4\"><a class=\"btn-karmayogi-orange\" href=\"https://www.igotkarmayogi.gov.in/#/show-all?type=case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> Access Case Studies on iGOT&nbsp;</strong>&nbsp;</a></div></div></section><!-- Section 5: Capacity Building through Advanced Case Writing and Teaching Workshops (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-elements-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event-fill me-3\"></i> Capacity Building through Advanced Case Writing and Teaching Workshops</h2><div class=\"karmayogi-feature-block mt-4 bg-alice-blue border-left-blue\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> April 2023</h3><p class=\"karmayogi-text-large\">Organised a 3-day <strong>Case Teaching Workshop</strong> in collaboration with <strong>Harvard Business School</strong> for 30 faculty members from Central Training Institutes (CTIs) and Administrative Training Institutes (ATIs).</p></div><div class=\"karmayogi-feature-block mt-4 bg-light-green border-left-green\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> December 2024</h3><p class=\"karmayogi-text-large\">Conducted a 5-day <strong>Advanced Case Writing and Teaching Workshop</strong> in partnership with <strong>Stanford LAD, Asian Development Bank (ADB), and Asian Development Bank Institute (ADBI)</strong> for 60 faculty members from CTIs/ATIs. Over 50 case studies were developed by participants and 7 faculty mentors from top institutions like IITs guided participants through the writing process.</p></div><div class=\"karmayogi-feature-block mt-4 bg-light-orange border-left-orange\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-calendar3 me-2\"></i> September 2025</h3><p class=\"karmayogi-text-large\">In September 2025, the <strong>Second Edition of the Advanced Case Writing Workshop</strong> was conducted for 75 new faculty members from CTIs and ATIs, organised across three cohorts in different cities of India. The program was led by instructors from <strong>Stanford LAD and IIT Delhi</strong> with support from ADB and ADBI, while 10 mentors from the December 2024 batch returned as Faculty Mentors to guide and support participants in their case writing journey.</p></div><div class=\"karmayogi-requirements-card mt-4\"><h3 class=\"karmayogi-requirements-title\"><i class=\"bi bi-trophy-fill me-2\"></i> Building a Cadre of Master Trainers</h3><p class=\"karmayogi-requirements-text\">One of the central achievements of the program has been the development of an emerging pool of Master Trainers in the Government training ecosystem drawn from workshop alumni. 10 participants were selected from December 2024 workshop to mentor participants from September 2025 workshop. These trainers:</p><ul class=\"karmayogi-feature-list mt-3\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Mentor new participants across India</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Co-facilitated the September 2025 cohorts</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Support institutes in embedding case-based teaching into curricula</span></li></ul></div><div class=\"karmayogi-topics-card mt-4\"><h3 class=\"karmayogi-topics-title\"><i class=\"bi bi-star-fill me-2\"></i> Participants\' Experience and Feedback</h3><div class=\"row g-3 mt-2\"><div class=\"col-md-6\"><div class=\"karmayogi-topic-item karmayogi-list-green\"><i class=\"bi bi-hand-thumbs-up-fill text-green\"></i> <span><strong>100%</strong> of respondents said they would recommend the workshop to colleagues</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item karmayogi-list-orange\"><i class=\"bi bi-star-fill text-orange\"></i> <span><strong>4.8/5</strong> overall rating - The program received excellent ratings from participants</span></div></div></div></div></div></section><!-- Section 6: Statistics to be Highlighted (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\"></i> Key Statistics &amp; Achievements</h2><div class=\"row g-4 mt-3\"><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-file-earmark-check-fill\"></i></div><h3 class=\"karmayogi-learning-title text-green agk-stat-number\">70</h3><p class=\"karmayogi-learning-text\">Cases currently live on IGOT</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-yellow\"><i class=\"bi bi-hourglass-split\"></i></div><h3 class=\"karmayogi-learning-title text-orange agk-stat-number\">70</h3><p class=\"karmayogi-learning-text\">Cases in the pipeline</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-cyan\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title text-primary agk-stat-number\">150+</h3><p class=\"karmayogi-learning-text\">Faculty from CTIs and ATIs trained in Case Writing</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-pink\"><i class=\"bi bi-globe2\"></i></div><h3 class=\"karmayogi-learning-title text-red agk-stat-number\">10</h3><p class=\"karmayogi-learning-text\">Cases co-published with ADBI, Tokyo</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-flag-fill\"></i></div><h3 class=\"karmayogi-learning-title text-info agk-stat-number\">17</h3><p class=\"karmayogi-learning-text\">Features case studies aligned with all 17 Sustainable Development Goals (SDGs)</p></div></div><div class=\"col-md-4 col-lg-3\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-pink\"><i class=\"bi bi-map-fill\"></i></div><h3 class=\"karmayogi-learning-title text-purple agk-stat-number\">20+</h3><p class=\"karmayogi-learning-text\">Cases published cover more than 20 states and represent diverse themes</p></div></div></div><div class=\"text-center mt-5\"><a class=\"btn-karmayogi-orange\" href=\"https://www.adb.org/adbi/publications/case-studies\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right me-2\"></i> View ADBI Published Cases&nbsp;</strong>&nbsp;</a></div></div></section>', '', 'full_html');
