('page', 0, 81, 171, 'en', 0, '<section class=\"join-mission-section\"><div class=\"container\"><div class=\"row justify-content-center mb-5\"><div class=\"col-lg-12\"><div class=\"mission-karmayogi-header mb-2 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">We welcome passionate individuals and organizations to join us in this transformative journey...</h2></div></div></div><!-- Opportunity Cards Section --><div class=\"row justify-content-center g-4 mb-5 join-opportunity-cards-row\"><!-- For Organisations / SMEs Card --><div class=\"col-lg-6 col-md-6\"><div class=\"join-opportunity-card high-contrast-border\"><div class=\"opportunity-card-header\"><div class=\"opportunity-icon-wrapper\"><i class=\"fas fa-users\"></i></div><h3 class=\"opportunity-title\">For Organisations</h3></div><div class=\"opportunity-card-body\"><p class=\"opportunity-description\">Collaborate with us to strengthen capacity building eco-system and support our initiatives. We welcome partnerships with organizations and subject matter experts who can contribute to our mission.</p><div class=\"opportunity-features\"><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Knowledge Partnerships</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Technology Solutions</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Training Support</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Resource Sharing</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Expert Support</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Content Development</span></div></div></div><div class=\"opportunity-card-footer\"><a class=\"opportunity-btn\" href=\"/cbc/form/organisations-form\" onclick=\"openOrganizationModal(); return false;\">Submit Here <i class=\"fas fa-arrow-right\"></i>&nbsp;</a></div></div></div><!-- Career Opportunities Card --><div class=\"col-lg-6 col-md-6\"><div class=\"join-opportunity-card career-opportunity-card high-contrast-border\"><div class=\"opportunity-card-header\"><div class=\"opportunity-icon-wrapper\"><i class=\"fas fa-briefcase\"></i></div><h3 class=\"opportunity-title\">For Individuals</h3></div><div class=\"opportunity-card-body\"><p class=\"opportunity-description\">Join our team and work on meaningful projects that impact governance and public service delivery. Be part of a dynamic organization committed to transforming civil service capacity building.</p><div class=\"opportunity-features\"><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Subject Matter Expert</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Advisor Role</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Consultant Role</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Internship Program</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Karmayogi Saarthis</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Research&nbsp;</span></div></div></div><div class=\"opportunity-card-footer\"><a class=\"webform-dialog webform-dialog-normal button\" href=\"/cbc/form/feedback\">Test Normal <i class=\"fas fa-arrow-right\"></i></a></div></div></div></div><!-- Call to Action Section --><div class=\"row justify-content-center\"><div class=\"col-lg-6\"><div class=\"join-cta-section\"><h3 class=\"cta-title\">Ready to Make a Difference?</h3><p class=\"cta-text\">Join us in building a competent civil service rooted in Indian ethos. Together, we can transform public service delivery across India.</p><div class=\"cta-buttons\"><a class=\"cta-btn-primary\" href=\"#/contact\"><i class=\"fas fa-envelope\"></i> Contact Us </a><a class=\"cta-btn-secondary\" href=\"#/about/about-cbc\"><i class=\"fas fa-info-circle\"></i> Learn Mor