('page', 0, 84, 164, 'en', 0, '<section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-earmark-text-fill me-3\" style=\"color:#0063ae;\"></i>Overview</h2><!-- Action Buttons --><div class=\"mb-4\" style=\"display:flex;flex-wrap:wrap;gap:15px;\"><a class=\"btn\" style=\"align-items:center;background-color:#0099ff;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;transition:all 0.3s ease;\" href=\"documents/Innovations_report_13March.pdf\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Open PDF in New Tab </strong></a><a class=\"btn\" style=\"align-items:center;background-color:#28a745;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;transition:all 0.3s ease;\" href=\"documents/Innovations_report_13March.pdf\" download=\"\"><strong><i class=\"bi bi-download\"></i> Download PDF&nbsp;</strong></a></div><!-- PDF Preview --><div class=\"document-viewer-wrapper\" style=\"background-color:#fff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);margin-top:20px;padding:20px;\"><p><iframe style=\"border-radius:8px;border:1px solid #e9ecef;height:800px;width:100%;\" id=\"innovationsReportViewer\" src=\"/cbc/sites/default/files/2025-12/Innovations_report_13March%20%281%29.pdf\" frameborder=\"0\">\r\n                              </iframe></p><div class=\"document-fallback\" style=\"background-color:#f8f9fa;border-radius:8px;display:none;margin-top:20px;padding:40px;text-align:center;\"><p class=\"mb-3\" style=\"color:#6c757d;font-size:1.1rem;\">PDF preview is not available in your browser. Please use the buttons above to open or download the document.</p><p><a class=\"btn\" style=\"align-items:center;background-color:#0099ff;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;\" href=\"/cbc/sites/default/files/2025-12/Innovations_report_13March%20%281%29.pdf\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Open PDF&nbsp;</strong></a></p></div></div></div></div></section><script>\r\n// Handle PDF viewer fallback\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n  const viewer = document.getElementById(\'innovationsReportViewer\');\r\n  const fallback = document.querySelector(\'.document-fallback\');\r\n  \r\n  // Check if iframe loads successfully\r\n  viewer.onerror = function() {\r\n    viewer.style.display = \'none\';\r\n    if (fallback) {\r\n      fallback.style.display = \'block\';\r\n    }\r\n  };\r\n  \r\n  // Check if PDF viewer is supported\r\n  setTimeout(function() {\r\n    try {\r\n      if (viewer.contentDocument === null || viewer.contentWindow.length === 0) {\r\n        // PDF may not be viewable in iframe, show fallback\r\n        if (fallback && viewer.src) {\r\n          viewer.style.display = \'none\';\r\n          fallback.style.display = \'block\';\r\n        }\r\n      }\r\n    } catch (e) {\r\n      // Cross-origin or other error, show fallback\r\n      if (fallback) {\r\n        viewer.style.display = \'none\';\r\n        fallback.style.display = \'block\';\r\n      }\r\n    }\r\n  }, 2000);\r\n});\r\n</script>', '', 'full_html');
