;\r\n}\r\n\r\n.acbp-table td:nth-child(2) {\r\n  text-align: left;\r\n}\r\n\r\n.acbp-table tbody tr:hover {\r\n  background: #f8f9fa;\r\n}\r\n\r\n.document-link {\r\n  color: #0063ae;\r\n  text-decoration: underline;\r\n  font-weight: 600;\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.document-link:hover {\r\n  color: #004b88;\r\n  text-decoration: underline;\r\n}\r\n\r\n.document-info {\r\n  display: block;\r\n  color: #6c757d;\r\n  font-size: 0.9rem;\r\n  margin-top: 4px;\r\n  font-weight: normal;\r\n}\r\n\r\n.table-pagination {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding: 16px 20px;\r\n  background: #ffffff;\r\n  border-top: 1px solid #e9ecef;\r\n}\r\n\r\n.pagination-info {\r\n  font-size: 0.95rem;\r\n  color: #6c757d;\r\n}\r\n\r\n.pagination-controls {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n}\r\n\r\n.pagination-btn {\r\n  padding: 8px 16px;\r\n  border: 1px solid #ddd;\r\n  background: #fff;\r\n  color: #333;\r\n  border-radius: 6px;\r\n  cursor: pointer;\r\n  font-size: 0.9rem;\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.pagination-btn:hover:not(:disabled) {\r\n  background: #f8f9fa;\r\n  border-color: #ff9800;\r\n  color: #ff9800;\r\n}\r\n\r\n.pagination-btn:disabled {\r\n  opacity: 0.5;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.pagination-numbers {\r\n  display: flex;\r\n  gap: 4px;\r\n  align-items: center;\r\n}\r\n\r\n.pagination-number {\r\n  min-width: 36px;\r\n  height: 36px;\r\n  padding: 0;\r\n  border: 1px solid #ddd;\r\n  background: #fff;\r\n  color: #333;\r\n  border-radius: 50%;\r\n  cursor: pointer;\r\n  font-size: 0.9rem;\r\n  transition: all 0.3s ease;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.pagination-number:hover {\r\n  background: #f8f9fa;\r\n  border-color: #ff9800;\r\n  color: #ff9800;\r\n}\r\n\r\n.pagination-number.active {\r\n  background: #ff9800;\r\n  border-color: #ff9800;\r\n  color: #fff;\r\n  font-weight: 700;\r\n}\r\n\r\n.pagination-ellipsis {\r\n  padding: 0 8px;\r\n  color: #6c757d;\r\n}\r\n\r\n@media (max-width: 768px) {\r\n  .completed-acbp-title {\r\n    font-size: 2.2rem;\r\n  }\r\n  \r\n  .table-pagination {\r\n    flex-direction: column;\r\n    gap: 12px;\r\n    padding: 12px 16px;\r\n  }\r\n  \r\n  .acbp-table {\r\n    font-size: 0.85rem;\r\n  }\r\n  \r\n  .acbp-table th,\r\n  .acbp-table td {\r\n    padding: 12px 8px;\r\n  }\r\n}\r\n</style>', '', 'full_html'),
