INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1165, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/cbc/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/cbc/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/cbc/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1166, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1167, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1168, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1170, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1171, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1172, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1181, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p><p class=\"karmayogi-feature-desc\">&nbsp;</p><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i></h2></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1182, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i></h2></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1185, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1193, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1209, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1211, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1213, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1214, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1215, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1216, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1217, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1219, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1220, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1223, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the Karmayogi Coaches (Master Trainers). They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over 9,50,000 Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1224, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1225, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1226, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1227, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1228, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Programme</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1229, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Programme</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1232, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Programme</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1238, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmayogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmayogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmayogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmayogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Programme</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1315, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Programme</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1392, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Program</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1415, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"sites/default/files/2026-01/Jan%20Seva%20Report%20%2831%29_0.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Program</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1416, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"sites/default/files/Jan Seva Report (31)_0.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Program</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1420, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/Jan Seva Report (31)_0.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Program</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 862, 1421, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmyogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this initiative is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmyogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmyogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i></h2><h2 class=\"karmayogi-section-title\">End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">24 Reinforcement Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units&nbsp;</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p><p class=\"karmayogi-text-large mt-4\">&nbsp;</p></div><h2 class=\"karmayogi-section-title\">Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - January 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January 2025 - May 2025 (Phase I)</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>April 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\">May 2025 - January 2026</div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers cascade the 3-day training to develop 15000–20000 Master Trainers. These trainers further train over 9,50,000 central government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 22.01.2026</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Over 16000 Karmyogi Coaches have been trained in Phase 2. These trainers have further cascaded the training to over 9.5 lakh civil servants.</div></div></div></div></div></div></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmyogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmyogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/Jan%20Seva%20Report%20%2831%29_0.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">17,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>86 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Jan - May 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>86</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmyogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">86 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>822 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainers Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>16,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmyogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>9.5 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries ) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmyogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmyogi Coaches</h4></div><p class=\"karmayogi-feature-desc\"><strong style=\"color:#0063ae;\">Lead Trainers</strong> were nominated from each Ministry, Department, and organisations under their administrative control to undergo an intensive <strong style=\"color:#0063ae;\">5-day Train-the-Trainer program.</strong> These Lead Trainers were then responsible for training <strong style=\"color:#28a745;\">Karmyogi Coaches</strong> (Master Trainers) through <strong style=\"color:#ffa500;\">3-day training sessions</strong> &nbsp;within their respective MDOs, more than <strong style=\"color:#28a745;\">16,500 Karmyogi Coaches</strong> have been trained in Phase II till <strong style=\"color:#dc3545;\">22.02.2026</strong>.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Karmyogi Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Training</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground-level delivery of the programme is managed by the <strong style=\"color:#28a745;\">Karmyogi Coaches (Master Trainers) </strong>. They conducted the 1-day training program for officials/officers within their respective MDOs, in batches of 30–35 participants. This comprehensive cascade framework enabled the program to reach over <strong style=\"color:#dc3545;\">9,50,000 </strong>Central Government employees across India, ensuring consistent delivery and widespread behavioural transformation.<br>&nbsp;</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02%20%281%29.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">9.5 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">&nbsp;Over <strong>9.5 lakh</strong> participants were trained under the<strong> Phase II One-Day Training Program</strong> by <strong>22nd January 2026</strong>.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1341, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Paanch Pran Sankalpas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Chaar Gunas</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1344, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1404, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM Model in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1405, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1406, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-6\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1407, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h4 class=\"karmayogi-principles-title\">Inspiration &amp; Core Principles</h4><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1408, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><p>Inspiration &amp; Core Principles<br>The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1409, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><p>Inspiration &amp; Core Principles<br>The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1410, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1487, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h4 class=\"karmayogi-framework-title\">The Competency Framework</h4><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1494, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h4>Global Benchmarking</h4></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1495, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1527, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1531, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1532, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The Karmayogi Competency Model signifies <strong style=\"color:#0063ae;\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul style=\"list-style:none;margin-top:20px;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\">The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p style=\"color:#002b5b;margin-bottom:15px;\">The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p style=\"color:#002b5b;margin-bottom:0;\">Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>October 19, 2024</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>10th March, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>18th July, 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 864, 1537, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3 text-primary-blue\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model signifies <strong class=\"karmayogi-highlight\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 text-dark-blue\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-feature-desc\"><p>The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p>The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p>Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3 text-primary-blue\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3 karmayogi-section-title-icon\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-timeline-wrapper\"><!-- Timeline Items --><div class=\"karmayogi-timeline-line\">&nbsp;</div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-blue\">&nbsp;</div><div class=\"karmayogi-timeline-date text-primary-blue\"><strong>October 19, 2024</strong></div><div class=\"karmayogi-timeline-content\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-green\">&nbsp;</div><div class=\"karmayogi-timeline-date text-green\"><strong>10th March, 2025</strong></div><div class=\"karmayogi-timeline-content\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-orange\">&nbsp;</div><div class=\"karmayogi-timeline-date text-orange\"><strong>18th July, 2025</strong></div><div class=\"karmayogi-timeline-content\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-yellow\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-red\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1685, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3 text-primary-blue\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model signifies <strong class=\"karmayogi-highlight\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 text-dark-blue\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-feature-desc\"><p>The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p>The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p>Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3 text-primary-blue\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3 karmayogi-section-title-icon\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-timeline-wrapper\"><!-- Timeline Items --><div class=\"karmayogi-timeline-line\">&nbsp;</div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-blue\">&nbsp;</div><div class=\"karmayogi-timeline-date text-primary-blue\"><strong>October 19, 2024</strong></div><div class=\"karmayogi-timeline-content\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-green\">&nbsp;</div><div class=\"karmayogi-timeline-date text-green\"><strong>10th March, 2025</strong></div><div class=\"karmayogi-timeline-content\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-orange\">&nbsp;</div><div class=\"karmayogi-timeline-date text-orange\"><strong>18th July, 2025</strong></div><div class=\"karmayogi-timeline-content\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-yellow\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-red\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html'),
('page', 0, 864, 1703, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3 text-primary-blue\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model signifies <strong class=\"karmayogi-highlight\">Atmanirbharta (self-reliance)</strong> in Competency-Based Capacity Building, reinforcing the commitment to develop a capable, accountable, and citizen-focused civil service. The model is inspired by Indic wisdom and advances the tenets of Mission Karmayogi.</p><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> The KCM will define the required competencies for capacity-building curricula.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Courses on the iGOT platform will be mapped to the competencies in the KCM framework.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will strive towards attaining the Sankalpas and Gunas ellucidiated in the KCM.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Officers will be shown courses based on the specific competencies they need to develop.</li></ul></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 text-dark-blue\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-feature-desc\"><p>The Karmayogi Competency Framework seeks to align roles with the competencies required to perform them effectively across all learning content within the Government of India. By embedding competencies directly into training and capacity-building exercises, the framework aims to shift Ministries, Departments, and Organisations (MDOs) from a rule-based approach to a more comprehensive, role-based way of thinking. This transition ensures that capacity-building initiatives are not viewed merely as compliance exercises but as structured pathways to strengthen the ability of civil servants to deliver on their responsibilities.</p><p>The integration of the KCM will help establish a common language for identifying, developing, managing, and deploying talent across the government ecosystem. It will enable MDOs to clearly define the competencies associated with each role, track workforce performance against those competencies, and set concrete targets for improvement. Such a system allows for better workforce planning, mobility, and succession management, ensuring that the right people are in the right roles at the right time.</p><p>Ultimately, the adoption of the KCM framework will not only enhance the efficiency and effectiveness of the government workforce but also improve role-fit, build accountability into learning and performance, and foster a culture of continuous development.</p></div></div></div></div></section><!-- Concept Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3 text-primary-blue\"></i>Conceptual Framework</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-quote\"></i></div><p class=\"karmayogi-quote-text\">The Karmayogi Competency Model (KCM) is India\'s first indigenous Public Sector Human Resource Management framework. Rooted in India\'s cultural and administrative context, it defines the values, skills, and behaviors required to build a capable, accountable, and citizen-centric civil service. Unlike one-size-fits-all global models, KCM is tailored to India\'s governance challenges, aligning with the aspirations of a Viksit Bharat (Developed India).</p></div><div class=\"karmayogi-feature-block\" data-subsection=\"benchmarking\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-globe2\"></i></p><h3>Global Benchmarking</h3></div><p class=\"karmayogi-feature-desc\">While uniquely Indian in design, KCM stands alongside internationally recognized frameworks such as:</p><div class=\"karmayogi-badges-wrapper\"><span class=\"karmayogi-badge\">UNDP Competency Model</span> <span class=\"karmayogi-badge\">Australian Competency Model</span> <span class=\"karmayogi-badge\">Singapore Competency Model</span> <span class=\"karmayogi-badge\">Korean Competency Model</span></div></div><div class=\"karmayogi-feature-block\" data-subsection=\"development\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-gear-fill\"></i></p><h4>Development Process</h4></div><p class=\"karmayogi-feature-desc\">The model was created through rigorous research and stakeholder engagement, involving:</p><div class=\"karmayogi-process-list\"><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Primary &amp; Secondary Research</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Global Benchmarking</span></div><div class=\"karmayogi-process-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Extensive Validation with public and private sector experts, academia, and Indian Knowledge Systems specialists</span></div></div></div><div class=\"karmayogi-principles-block\" data-subsection=\"principles\"><h2 class=\"karmayogi-section-title\">Inspiration &amp; Core Principles</h2><p class=\"karmayogi-feature-desc\">The Karmayogi Competency Model (KCM) draws its philosophical foundations from Indian Knowledge Systems (IKS) and is inspired by the Panch Pran vision articulated by the Hon’ble Prime Minister</p><div class=\"principles-groups-wrapper\"><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Sankalpas (Four Resolves)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Vikas</div><div class=\"karmayogi-principle-desc\">Commitment to a Developed India</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Garva</div><div class=\"karmayogi-principle-desc\">Pride in Indian ethos and identity</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Kartavya</div><div class=\"karmayogi-principle-desc\">Duty towards nation, people, and self</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Ekta</div><div class=\"karmayogi-principle-desc\">Unity in action</div></div></div></div><div class=\"karmayogi-principles-group\"><div class=\"karmayogi-principles-label\">Char Gunas (Four Foundational Virtues)</div><div class=\"karmayogi-principles-grid\"><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadhyaya</div><div class=\"karmayogi-principle-desc\">Knowing oneself</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Sahakaryata</div><div class=\"karmayogi-principle-desc\">Collaborative working</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Rajyakarma</div><div class=\"karmayogi-principle-desc\">Understanding governance systems</div></div><div class=\"karmayogi-principle-item\"><div class=\"karmayogi-principle-name\">Svadharma</div><div class=\"karmayogi-principle-desc\">Serving citizens with dedication</div></div></div></div></div></div><div class=\"karmayogi-framework-block\" data-subsection=\"framework\"><h3 class=\"karmayogi-framework-title\">The Competency Framework</h3><p class=\"karmayogi-framework-desc\">KCM categorizes competencies into two key domains:</p><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-domain-number\">13</div><div class=\"karmayogi-domain-title\">Behavioural Competencies</div><div class=\"karmayogi-domain-subtitle\">5 Leadership + 8 Core</div><div class=\"karmayogi-domain-examples\">Observable traits and actions that define effective public service. Including: Self-Awareness, Solution Orientation, Service Orientation, Creativity &amp; Innovation, Strategic &amp; Collaborative Leadership.</div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-domain-card\"><div class=\"karmayogi-domain-icon\"><i class=\"bi bi-tools\"></i></div><div class=\"karmayogi-domain-number\">21</div><div class=\"karmayogi-domain-title\">Functional Competencies</div><div class=\"karmayogi-domain-subtitle\">Skills &amp; Tools</div><div class=\"karmayogi-domain-examples\">Skills and tools essential for governance and service delivery. Including: Policy Architecture, Project Management, Financial Management, Digital Fluency &amp; Data Analytics, Grievance Redressal, Vigilance &amp; Change Management.</div></div></div></div></div></div></section><!-- Alignment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><div class=\"row g-4\"><div class=\"col-lg-6\" data-subsection=\"alignment\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">Alignment with Mission Karmayogi</h3><p class=\"karmayogi-alignment-desc\">The KCM directly supports the five objectives of Mission Karmayogi:</p><div class=\"karmayogi-objectives-list\"><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Enhancing performance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Citizen-centric governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Future readiness</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Accountability in service</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>Tech-enabled governance</span></div><div class=\"karmayogi-objective-list-item\"><i class=\"bi bi-check-circle-fill\"></i><span>It also ensures that courses on the iGOT platform are mapped to competencies, enabling targeted and personalized learning for civil servants.</span></div></div></div></div><div class=\"col-lg-6\" data-subsection=\"transformative\"><div class=\"karmayogi-alignment-block\"><h3 class=\"karmayogi-alignment-title\">A Transformative Shift</h3><p class=\"karmayogi-alignment-desc\">The Karmayogi Competency Model marks a paradigm shift in India\'s governance philosophy:</p><div class=\"karmayogi-transform-list\"><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From rule-based to role-based governance</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From Karmachari (employee) to Karmayogi (dedicated worker)</span></div><div class=\"karmayogi-transform-item\"><i class=\"bi bi-arrow-right-circle\"></i><span>From traditional administration to workplace transformation</span></div></div></div></div><div class=\"col-lg-12\"><div class=\"karmayogi-significance-box\" data-subsection=\"significance\"><p><i class=\"bi bi-star-fill\"></i></p><div><p><strong>Significance</strong></p><p>KCM embodies Atmanirbharta (self-reliance) in competency-based capacity building. By defining what public officials need to know, do, and embody, it strengthens India\'s commitment to building a future-ready, citizen-focused, and accountable civil service.</p></div></div></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3 karmayogi-section-title-icon\"></i>Chronology of Events (Pilots/Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-timeline-wrapper\"><!-- Timeline Items --><div class=\"karmayogi-timeline-line\">&nbsp;</div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-blue\">&nbsp;</div><div class=\"karmayogi-timeline-date text-primary-blue\"><strong>October 19, 2024</strong></div><div class=\"karmayogi-timeline-content\">Prime Minister Narendra Modi launched the Karmayogi Competency Model during the inaugural \'Karmayogi Saptah\'—or National Learning Week—on October 19, 2024.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-green\">&nbsp;</div><div class=\"karmayogi-timeline-date text-green\"><strong>10th March, 2025</strong></div><div class=\"karmayogi-timeline-content\">KCM Workshop conducted with CBC, KB, Training division of Department of Personnel &amp; Training (DoPT), CEGIS, and IDInsight.</div></div><div class=\"karmayogi-timeline-item\"><div class=\"karmayogi-timeline-dot dot-orange\">&nbsp;</div><div class=\"karmayogi-timeline-date text-orange\"><strong>18th July, 2025</strong></div><div class=\"karmayogi-timeline-content\">The KCM was copyrighted by CBC under the supervision of Dr R Balasubramaniam (Member-HR)</div></div></div></div></div></div></div></div></section><!-- Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\">Key Milestones</h2><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-laptop-fill\"></i></div><div class=\"karmayogi-milestone-title\">Integration of KCM with the iGOT Platform</div><div class=\"karmayogi-milestone-label\">The KCM has already been integrated within the iGOT platform for all courses, webinars, events, etc. This will enable a competency-based approach to learning.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">A course on KCM is available on the iGOT platform</div><div class=\"karmayogi-milestone-label\">Comprehensive course content on KCM is accessible to all civil servants through the iGOT platform.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-yellow\"><i class=\"bi bi-copyright\"></i></div><div class=\"karmayogi-milestone-title\">Copyright of the KCM</div><div class=\"karmayogi-milestone-label\">The KCM has been copyrighted by the CBC, making it a valuable resource for the India Civil Service Capacity Building Ecosystem.</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-red\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Alignment of Course Curriculum with the KCM in Training Ecosystem</div><div class=\"karmayogi-milestone-label\">Training curricula across the ecosystem are being aligned with the KCM framework to ensure consistency and competency-based learning.</div></div></div></div></div></section>', '', 'full_html');
