('page', 0, 907, 1593, 'en', 0, '<div class=\"impact-summit-posters\"><div class=\"impact-summit-posters__grid\"><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2011.29.17%20AM.jpeg\" alt=\"AI Impact Summit - AI for Viksit Bharat: The Capacity Building Imperative - Leadership Reflections by S Radha Chahuan\" width=\"1080\" height=\"1350\"></div><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2011.44.54%20AM.jpeg\" alt=\"AI Impact Summit - AI for Viksit Bharat: The Capacity Building Imperative - 20 February 2026 at Bharat Mandapam\" width=\"1080\" height=\"1350\"></div><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2012.23.49%20PM.jpeg\" alt=\"AI FOR EDUCATION\" width=\"1080\" height=\"1350\"></div></div></div>', '', 'full_html'),
('page', 0, 907, 1594, 'en', 0, '<div class=\"impact-summit-posters\"><div class=\"impact-summit-posters__grid\"><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2011.29.17%20AM.jpeg\" alt=\"AI Impact Summit - AI for Viksit Bharat: The Capacity Building Imperative - Leadership Reflections by S Radha Chahuan\" width=\"1080\" height=\"1350\"></div><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2011.44.54%20AM.jpeg\" alt=\"AI Impact Summit - AI for Viksit Bharat: The Capacity Building Imperative - 20 February 2026 at Bharat Mandapam\" width=\"1080\" height=\"1350\"></div><div class=\"impact-summit-posters__item\"><img src=\"/sites/default/files/2026-02/WhatsApp%20Image%202026-02-12%20at%2012.23.49%20PM.jpeg\" alt=\"AI FOR EDUCATION\" width=\"1080\" height=\"1346\"></div></div></div>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 950, 1736, 'en', 0, '<script>\r\n    (function () {\r\n        /* Find the base URL of the cbc theme by looking at any already-loaded\r\n           theme stylesheet (e.g. home.css loaded by Drupal globally). */\r\n        function getThemeBase() {\r\n            var links = document.querySelectorAll(\'link[rel=\"stylesheet\"]\');\r\n            for (var i = 0; i < links.length; i++) {\r\n                var href = links[i].href || \'\';\r\n                var idx = href.indexOf(\'/themes/cbc/\');\r\n                if (idx !== -1) { return href.substring(0, idx); }\r\n            }\r\n            /* Fallback: derive from current page URL up to the Drupal root.\r\n               Works if Drupal is at a subdirectory like /cbc/ or at / */\r\n            var base = window.location.origin;\r\n            var path = window.location.pathname;\r\n            var drupalRoot = path.split(\'/themes/\')[0];\r\n            return base + (drupalRoot || \'\');\r\n        }\r\n\r\n        var base = getThemeBase();\r\n        var theme = base + \'/themes/cbc\';\r\n\r\n        /* Inject CSS — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"sadhana-saptah.css\"]\')) {\r\n            var css = document.createElement(\'link\');\r\n            css.rel = \'stylesheet\';\r\n            css.type = \'text/css\';\r\n            css.href = theme + \'/css/sadhana-saptah.css\';\r\n            document.head.appendChild(css);\r\n        }\r\n\r\n        /* Inject Google Fonts — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"Outfit\"]\')) {\r\n            var gf = document.createElement(\'link\');\r\n            gf.rel = \'stylesheet\';\r\n            gf.href = \'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap\';\r\n            document.head.appendChild(gf);\r\n        }\r\n\r\n        /* Inject JS after DOM is ready — skip if already loaded */\r\n        function loadJS() {\r\n            if (document.querySelector(\'script[src*=\"sadhana-saptah.js\"]\')) return;\r\n            var scr = document.createElement(\'script\');\r\n            scr.src = theme + \'/js/sadhana-saptah.js\';\r\n            document.body.appendChild(scr);\r\n        }\r\n\r\n        if (document.readyState === \'loading\') {\r\n            document.addEventListener(\'DOMContentLoaded\', loadJS);\r\n        } else {\r\n            loadJS();\r\n        }\r\n    })();\r\n</script><div class=\"cbc-custom-landing\"><!-- ==================================================================\r\n         HERO SECTION: Poster/Banner\r\n         ================================================================== --><div class=\"cbc-hero-section\"><img class=\"cbc-hero-poster\" src=\"/sites/default/files/REPLACE-WITH-YOUR-BANNER.jpg\" alt=\"SĀDHANA Saptah Banner\"></div><div class=\"container\"><!-- ==================================================================\r\n     TOP ACTION BUTTONS: Registration & iGOT\r\n     ================================================================== --><div class=\"cbc-registration-bar\"><a class=\"cbc-reg-btn cbc-reg-primary\" href=\"#REPLACE-WITH-REGISTRATION-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">📋</span> Registration Link </a><a class=\"cbc-reg-btn cbc-reg-igot\" href=\"#REPLACE-WITH-IGOT-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">🏛️</span> iGOT Karmayogi&nbsp;</a></div><!-- ==================================================================\r\n     SECTION 1: ABOUT SADHANA SAPTAH + THREE SUTRAS\r\n     ================================================================== --><div class=\"cbc-about-section\"><h2>About <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah</h2><div class=\"section-about\"><p>India\'s governance landscape is being reshaped by rapid technological change, renewed attention to Indian Knowledge Systems, and an increasing focus on Citizen Centricity. <strong><img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah</strong> is conceived as a theme-focused, sector-anchored exercise (sector classification as per SGOS) to strengthen governance capability across Ministries, Departments, Organisations (MDO), and States. The structure of the week shall be focused on three themes or Sutras — <strong>Technology, Tradition &amp; Tangible Outcomes</strong>.</p><p>The week coincides with the Foundation Day of CBC and completion of five years of Mission Karmayogi, providing an opportunity to review progress while strengthening the national capacity-building ecosystem.</p><p>Through a blended delivery model—comprising Karmayogi Talks by domain experts, Samuhik Charchas within institutions, digital learning through the iGOT platform, inter-ministerial workshops, and training programmes conducted by civil services training institutions—the initiative will engage civil servants across the government ecosystem. Participation will extend across <strong>93 Central Ministries and Departments, 30 States and UTs</strong> implementing Mission Karmayogi, and more than <strong>200 civil services training institutions</strong>, supported through coordinated institutional mechanisms led by CBC.</p><p>Beyond a week of learning engagements, <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah aims to reinforce a culture of continuous learning in government, accelerate engagement with the digital learning ecosystem, strengthen knowledge exchange across institutions, and generate insights for strengthening the broader capacity-building architecture under Mission Karmayogi.</p></div><!-- Three Sutras --><div class=\"sutras-grid\"><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🤖</span></p><h3>Technology</h3><p>AI and emerging technologies transforming the sector</p><ul class=\"sutra-list\"><li>Sector-specific AI use cases</li><li>Regulatory readiness</li><li>Digital public infrastructure integration</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🏛️</span></p><h3>Tradition</h3><p>Indian Knowledge Systems and indigenous innovations</p><ul class=\"sutra-list\"><li>Civilizational practices with contemporary relevance</li><li>Community-led institutional models</li><li>Indigenous governance insights</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🎯</span></p><h3>Tangible Outcomes</h3><p>Outcome-oriented governance and public value creation</p><ul class=\"sutra-list\"><li>Citizen impact tracking</li><li>Clear articulation of priority sectoral outcomes</li><li>Dashboard-based monitoring</li></ul></div></div></div><!-- /cbc-about-section --></div><!-- ==================================================================\r\n     SECTION 2: EVENT SCHEDULE\r\n     ================================================================== --><!-- /container --><div class=\"cbc-schedule-section\"><p><span class=\"cbc-schedule-title\">Event Schedule</span> <span class=\"cbc-schedule-subtitle\">2nd April – 8th April 2026</span></p><div class=\"cbc-schedule-tabs\"><button class=\"cbc-schedule-tab active\" data-tab=\"week\">Throughout the Week</button> <button class=\"cbc-schedule-tab\" data-tab=\"day1\">Day 1 – Launch Day</button> <button class=\"cbc-schedule-tab\" data-tab=\"day2-7\">Day 2–7</button> <button class=\"cbc-schedule-tab\" data-tab=\"day8\">Day 8 – Valedictory</button> <button class=\"cbc-schedule-tab\" data-tab=\"courses\">Courses in Focus</button></div><div class=\"container\"><!-- TAB: Throughout the Week --><div class=\"cbc-schedule-content active\" id=\"tab-week\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Activities Available Throughout the Week</h3><p>Flexible, self-paced and group-based learning opportunities.</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session / Activity</th><th style=\"width:260px;\">Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>Karmayogi Talks</strong></td><td>National Webinars – Morning &amp; Evening sessions</td><td>2 webinars per day, each 1 hour, thematic and sector-aligned</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience</td><td>1–2 courses mandatory per MDO; AI &amp; Marketplace courses included</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led group discussions</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Domain &amp; sectoral capacity building sessions</td></tr></tbody></table></div></div></div><!-- TAB: Day 1 – Launch Day --><div class=\"cbc-schedule-content\" id=\"tab-day1\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Udghatan Samaroh – Launch Day</h3><p>📅 2nd April 2026 | New Delhi</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th>Session</th><th style=\"text-align:right;width:200px;\">Time</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1.</td><td><strong>Inaugural Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Guests of Honour / Chief Guest</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>10:00 AM – 11:30 AM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2.</td><td><strong>Master Class: \'Capacity Building Imperative for an Entrepreneurial State\'</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri V. Anantha Nageswaran, Chief Economic Advisor, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>11:30 AM – 12:00 Noon</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3.</td><td><strong>Thematic Session-I: National Workshop on Future Ready Training Institutions for Viksit Bharat</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>12:00 Noon – 1:30 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Lunch Break</strong></em></td></tr><tr><td class=\"cbc-schedule-sn\">4.</td><td><strong>Thematic Session-II: Karmayogi Quality Framework</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>2:30 PM – 3:30 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5.</td><td><strong>Special Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri T. V. Somanathan, Cabinet Secretary, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>3:30 PM – 4:00 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6.</td><td><strong>Closing Reflection and Vote of Thanks</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>4:00 PM – 4:15 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Tea &amp; Networking</strong></em></td></tr></tbody></table></div></div></div><!-- TAB: Day 2–7 --><div class=\"cbc-schedule-content\" id=\"tab-day2-7\"><div class=\"cbc-schedule-table-card\" style=\"background-color:transparent;border-style:none;box-shadow:none;padding:20px;\"><div class=\"cbc-schedule-card-header\" style=\"background-color:white;border-radius:16px;border:1px solid #f0f0f0;margin-bottom:20px;\"><h3>Daily Webinar Sessions</h3><p>📅 3rd April – 8th April 2026 | Virtual / Hybrid</p></div><div class=\"cbc-webinar-grid\"><div class=\"cbc-webinar-card\"><h4>Morning Session – Webinar 1</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Theme-aligned webinar session led by domain experts covering Technology, Tradition, or Tangible Outcomes.</p></div><div class=\"cbc-webinar-card\"><h4>Afternoon/Evening Session – Webinar 2</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Complementary session with sectoral deep-dives, case studies, and interactive discussions.</p></div></div><div class=\"cbc-date-pills\"><div class=\"cbc-date-pill\">🔵 3rd &amp; 4th April – Technology</div><div class=\"cbc-date-pill\" style=\"background-color:#fff3e0;color:#e67e22;\">🟠 5th &amp; 6th April – Tradition</div><div class=\"cbc-date-pill\" style=\"background-color:#e8f5e9;color:#2e7d32;\">🟢 7th &amp; 8th April – Tangible Outcomes</div></div><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session</th><th>Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience; AI &amp; Marketplace focus</td><td>1–2 courses mandatory per MDO</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led Samuhik Charcha</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Sectoral / domain capacity building sessions</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Thematic Days</strong></td><td>Technology (3–4 Apr), Traditions (5–6 Apr), Tangible Outcomes (7–8 Apr)</td><td>Samuhik Charchas, Karmayogi Talks, Webinars &amp; Panel Discussions</td></tr></tbody></table></div></div></div></div><!-- TAB: Day 8 – Valedictory --><div class=\"cbc-schedule-content\" id=\"tab-day8\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Samapan Samaroh – Valedictory Day</h3><p>📅 8th April 2026</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:140px;\">Duration</th><th>Session</th><th>Tentative Activities</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>120 minutes</td><td><strong>Felicitation Session</strong></td><td>Summary of the Week (Data) · Felicitation of Karmayogi Leaderboard Achievers · Address by Chief Guest (~20 min)</td></tr></tbody></table></div></div></div><!-- TAB: Courses in Focus --><div class=\"cbc-schedule-content\" id=\"tab-courses\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Curated Learning Pathways on iGOT Karmayogi</h3><p>AI Courses &amp; iGOT Marketplace Courses — available throughout the week</p></div><div style=\"padding:16px 16px 0;\"><div class=\"cbc-course-tabs\"><button class=\"cbc-course-tab active\" data-course=\"ai\">AI Courses</button> <button class=\"cbc-course-tab\" data-course=\"marketplace\">iGOT Marketplace Courses</button></div></div><!-- AI Courses --><div class=\"cbc-schedule-table-wrapper\" id=\"course-ai-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Artificial Intelligence for Public Governance</td><td>Wadhwani AI &amp; Data Security Council of India</td><td style=\"text-align:right;\">3h 10m</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Large Language Models: Concepts and Applications</td><td>IIT Hyderabad</td><td style=\"text-align:right;\">1h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Deep Tech and India</td><td>ORF</td><td style=\"text-align:right;\">55m</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>AI in Government: Transforming Public Service Delivery</td><td>IISc Bengaluru</td><td style=\"text-align:right;\">2h 20m</td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Artificial Intelligence for Smarter Governance</td><td>Karmayogi Bharat – NeGD</td><td style=\"text-align:right;\">1h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>IndiaAI for All</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Fundamentals of Generative Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">50m</td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Introduction to Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>AI Applications in Government</td><td>NIC</td><td style=\"text-align:right;\">1h 50m</td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>आर्टिफिशियल इंटेलिजेंस की मूल बातें: अवसर, अनुप्रयोग और नैतिकता</td><td>Microsoft</td><td style=\"text-align:right;\">1h 35m</td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>प्रशासन के लिए एआई: कार्यों का स्व-चालन</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">40m</td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>सुशासन के सन्दर्भ में एआई</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">1h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Artificial Intelligence in Finance</td><td>SUDI</td><td style=\"text-align:right;\">1h 40m</td></tr><tr><td class=\"cbc-schedule-sn\">14</td><td>Core Areas of Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">15</td><td>शून्य से एआई तक</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">16</td><td>Advanced Prompt Engineering for Everyone</td><td>Vanderbilt University</td><td style=\"text-align:right;\">2h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">17</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera</td><td style=\"text-align:right;\">3h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">18</td><td>AI for Educators [Intermediate]</td><td>Common Sense Education</td><td style=\"text-align:right;\">1h 25m</td></tr><tr><td class=\"cbc-schedule-sn\">19</td><td>AI for Energy and Biomedical Applications</td><td>University of Michigan</td><td style=\"text-align:right;\">2h 05m</td></tr></tbody></table></div><!-- Marketplace Courses --><div class=\"cbc-schedule-table-wrapper\" style=\"display:none;\" id=\"course-marketplace-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Strategy and Game Theory for Management</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>32h 42m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Leadership Skills</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>46h 11m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Law, Governance, and Public Policy</td><td>O. P. Jindal Global University</td><td style=\"color:#f39200;text-align:right;\"><strong>18h 37m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>Introduction to Quantum Information</td><td>KAIST</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 48m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Negotiation Fundamentals</td><td>ESSEC Business School</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 35m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>Analysis and Interpretation of Large-Scale Programs</td><td>Johns Hopkins University</td><td style=\"color:#f39200;text-align:right;\"><strong>21h 6m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera Instructor Network</td><td style=\"color:#f39200;text-align:right;\"><strong>5h 52m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Forest Carbon Credits and Initiatives</td><td>Michigan State University</td><td style=\"color:#f39200;text-align:right;\"><strong>6h</strong></td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>Design Thinking and Predictive Analytics for Data Products</td><td>UC San Diego</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 25m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>Effective Engagement of Civil Society in Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>13h 19m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>Blockchain Platforms</td><td>University at Buffalo, SUNY</td><td style=\"color:#f39200;text-align:right;\"><strong>16h 16m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>Trade and Investment: Evidence-based Policies for Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>17h 2m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Foundations of Cybersecurity</td><td>Google</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 10m</strong></td></tr></tbody></table></div></div></div></div><p><!-- /container -->&nbsp;</p></div><!-- ==================================================================\r\n     SECTION 3: EVENT GLIMPSES — 2-COLUMN GRID\r\n     (Leaders\' Voices on left | Testimonials on right)\r\n     ================================================================== --><!-- /cbc-schedule-section --><div class=\"cbc-glimpses-section\"><div class=\"container\"><div class=\"cbc-glimpses-header\"><h2>Event Glimpses</h2><p>Reliving the inspiring words and impactful moments from <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah.</p></div><div class=\"cbc-glimpses-grid\"><!-- ── LEFT COLUMN: Leaders\' Voices — VIDEO Carousel ── --><div class=\"cbc-column-box\"><div class=\"cbc-column-title\">Leadership message</div><!--\r\n                    ★ HOW TO ADD A LEADER VIDEO:\r\n                    1. Get the YouTube embed URL:\r\n                       https://www.youtube.com/embed/YOUR_VIDEO_ID\r\n                       OR upload to Drupal Media and use the direct file URL.\r\n                    2. Copy the <div class=\"swiper-slide\"> block below, paste it\r\n                       inside the swiper-wrapper, and replace the iframe src.\r\n                       No JS changes needed — JS auto-detects new slides.\r\n                    --><div class=\"swiper leadersSwiper\"><div class=\"swiper-wrapper\"><!-- Leader Video 1 (Direct Drupal .mp4 Example) --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                        <source src=\"/sites/default/files/2026-03/leader-video-1.mp4\" type=\"video/mp4\">\r\n                                        Your browser does not support the video tag.\r\n                                    </video></div></div><!-- ★ PASTE MORE LEADER VIDEOS BELOW THIS LINE ★\r\n                                 Copy the <div class=\"swiper-slide\"> block above, \r\n                                 paste it, and replace the <source src=\"...\"> with your Drupal media URL.\r\n                            --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /leadersSwiper --></div><!-- ── RIGHT COLUMN: Testimonials (Tabbed) ── --><!-- /left column --><div class=\"cbc-column-box\"><div style=\"align-items:center;display:flex;flex-wrap:wrap;gap:15px;justify-content:space-between;\"><div class=\"cbc-column-title\" style=\"margin-bottom:0;\">Our collaborative efforts matter</div><div class=\"cbc-testimonial-tabs\" style=\"justify-content:flex-end;margin-bottom:0;margin-top:0;\"><button class=\"cbc-testimonial-tab active\" data-test-tab=\"video\">Video</button> <button class=\"cbc-testimonial-tab\" data-test-tab=\"written\">Written</button></div></div><!-- Video Testimonials Tab --><div class=\"cbc-testimonial-content active\" id=\"test-video\"><!--\r\n                ★ HOW TO ADD A VIDEO TESTIMONIAL:\r\n                1. Upload video to Drupal Media.\r\n                2. Copy the <div class=\"swiper-slide\"> block below, paste it,\r\n                   and replace the source src.\r\n                --><div class=\"swiper testimonialVideoSwiper\"><div class=\"swiper-wrapper\"><!-- Video Testimonial 1 --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                            <source src=\"/sites/default/files/2026-03/testimonial-1.mp4\" type=\"video/mp4\">\r\n                                        </video></div></div><!-- Video Testimonial 2 --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                            <source src=\"/sites/default/files/2026-03/imgae%20%20%284%29.mp4\" type=\"video/mp4\">\r\n                                        </video></div></div><div class=\"swiper-slide\"><div class=\"video-container\"><iframe src=\"https://www.youtube.com/embed/r9pBy80zTws\" title=\"Video Testimonial 2\" allowfullscreen=\"\"></iframe></div></div><!-- ★ PASTE MORE VIDEO TESTIMONIAL SLIDES BELOW THIS LINE ★ --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /testimonialVideoSwiper --></div><!-- Written Testimonials Tab --><!-- /test-video --><div class=\"cbc-testimonial-content\" id=\"test-written\"><div class=\"testimonial-written-wrap\"><!--\r\n                    ★ HOW TO ADD A WRITTEN TESTIMONIAL:\r\n                    Copy the <div class=\"testimonial-card\"> block below, paste it,\r\n                    and change the quote and author text.\r\n                    --><div class=\"testimonial-track\"><div class=\"testimonial-card\"><p>\"The AI modules were eye-opening. It has completely changed how I think about data-driven decisions.\"</p><p><span class=\"author\">— Senior Administrative Officer</span></p></div><div class=\"testimonial-card\"><p>\"Samuhik Charcha sessions allowed us to bond as a team while solving real service bottlenecks.\"</p><p><span class=\"author\">— Deputy Secretary</span></p></div><div class=\"testimonial-card\"><p>\"A masterfully organized week. The focus on Indian Knowledge Systems was particularly inspiring.\"</p><p><span class=\"author\">— Project Director</span></p></div><div class=\"testimonial-card\"><p>\"The iGOT courses were highly relevant and helped me immediately apply learnings in my department.\"</p><p><span class=\"author\">— Under Secretary, Ministry of Finance</span></p></div><!-- ★ PASTE MORE WRITTEN TESTIMONIALS BELOW THIS LINE ★ --></div><!-- /testimonial-track --></div><!-- /testimonial-written-wrap --></div><!-- /test-written --></div><!-- /right column --></div><!-- /cbc-glimpses-grid --></div><!-- /container --></div><!-- ==================================================================\r\n     SECTION 4: PHOTO & VIDEO GALLERY (Side by Side)\r\n     ================================================================== --><!-- /cbc-glimpses-section --><div class=\"cbc-gallery-section\"><div class=\"container\"><div class=\"cbc-glimpses-header\"><h2>Event Gallery</h2><p>Capturing the moments and milestones of <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah.</p></div><div class=\"gallery-grid\"><!-- Photo Gallery --><div class=\"gallery-card\"><h3>📸 Glimpses</h3><!--\r\n            ★ HOW TO ADD A PHOTO:\r\n            1. Upload your photo to Drupal → Media → Add Media (Image).\r\n            2. Open the image and copy its URL from the browser address bar,\r\n               or right-click → \"Copy image address\".\r\n            3. Copy the <div class=\"swiper-slide\"> block below, paste it,\r\n               and replace the img src with your Drupal media URL.\r\n\r\n            Drupal media URLs typically look like:\r\n              /sites/default/files/2026-04/photo-name.jpg\r\n            --><div class=\"swiper photoSwiper\"><div class=\"swiper-wrapper\"><!-- ★ REPLACE WITH YOUR DRUPAL MEDIA URL ★ --><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-1.jpg\" alt=\"SĀDHANA Saptah Session\"></div><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-2.jpg\" alt=\"SĀDHANA Saptah Workshop\"></div><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-3.jpg\" alt=\"SĀDHANA Saptah Team\"></div><!-- ★ PASTE MORE PHOTO SLIDES BELOW THIS LINE ★ --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /photoSwiper --><p class=\"gallery-caption\"><strong>Moments of Interaction:</strong> Capturing the spirit of <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\"> Saptah.</p></div><!-- Video Gallery --><!-- /gallery-card Photo --><div class=\"gallery-card\"><h3>🎬 Videos</h3><!--\r\n            ★ HOW TO ADD A VIDEO:\r\n            Option A — YouTube: Use the YouTube embed URL:\r\n              https://www.youtube.com/embed/YOUR_VIDEO_ID\r\n\r\n            Option B — Drupal Media Upload:\r\n              1. Upload the video to Drupal → Media → Add Media (Video file).\r\n              2. Use the direct file URL as the iframe src is NOT needed for\r\n                 hosted videos. Instead use an HTML5 video tag:\r\n                 <video controls><source src=\"/sites/default/files/your-video.mp4\"></video>\r\n\r\n            Copy the <div class=\"swiper-slide\"> block below and paste it.\r\n            --><div class=\"swiper videoSwiper\"><div class=\"swiper-wrapper\"><!-- Video Highlight (Direct Drupal .mp4) --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                        <source src=\"/sites/default/files/2026-03/gallery-video-1.mp4\" type=\"video/mp4\">\r\n                                    </video></div></div><!-- ★ PASTE MORE VIDEO SLIDES BELOW THIS LINE ★\r\n                                 Copy the <div class=\"swiper-slide\"> block above and update the source src.\r\n                            --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /videoSwiper --><p class=\"gallery-caption\"><strong>Impact Stories:</strong> Watch the transformation in action.</p></div><!-- /gallery-card Video --></div><!-- /gallery-grid --></div><!-- /container --></div><!-- ==================================================================\r\n         SECTION 5: DoP&T SOCIAL MEDIA LINKS\r\n         ================================================================== --><!-- /cbc-gallery-section --><div class=\"cbc-social-section\" style=\"background-color:#000b1a;border-top:1px solid rgba(0,174,239,0.1);padding:40px 20px;position:relative;text-align:center;\"><div class=\"container\" style=\"position:relative;z-index:1;\"><h3 style=\"color:#ffffff;font-family:&apos;Outfit&apos;,sans-serif;font-size:20px;margin:0 0 5px;\"><strong>Connect with DoP&amp;T</strong></h3><p style=\"color:rgba(255,255,255,0.4);font-size:12px;letter-spacing:0.5px;margin:0 0 20px;\">Department of Personnel and Training</p><!-- Social icons row — Exact footer style: Tiny circular cyan stroke --><div style=\"align-items:center;display:flex;flex-wrap:wrap;gap:18px;justify-content:center;\"><!-- X (Twitter) --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://x.com/CBC_MK\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"14\" height=\"14\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z\"></path></svg></a><!-- LinkedIn --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"16\" height=\"16\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z\"></path></svg></a><!-- Instagram --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"18\" height=\"18\" viewbox=\"0 0 24 24\" fill=\"none\" stroke=\"#00adef\" stroke-width=\"2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"0.5\" fill=\"#00adef\"></circle></svg></a><!-- Facebook --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"18\" height=\"18\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M22.675 0h-21.35c-.732 0-1.325.593-1.325 1.325v21.351c0 .731.593 1.324 1.325 1.324h11.495v-9.294h-3.128v-3.622h3.128v-2.671c0-3.1 1.893-4.788 4.659-4.788 1.325 0 2.463.099 2.795.143v3.24l-1.918.001c-1.504 0-1.795.715-1.795 1.763v2.313h3.587l-.467 3.622h-3.12v9.293h6.116c.73 0 1.323-.593 1.323-1.325v-21.35c0-.732-.593-1.325-1.325-1.325z\"></path></svg></a></div></div></div><!-- ==================================================================\r\n         HIDDEN DATA BLOCK: CALENDAR EVENTS\r\n         Editable via Drupal Basic Page HTML — ZERO JS interaction needed.\r\n         ================================================================== --><div style=\"display:none;\" id=\"cbc-events-data\"><!-- Day 2: 2nd April --><div data-day=\"2\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Launch Event\" data-location=\"New Delhi\" data-date=\"2nd April, 2026\">&nbsp;</div><!-- Day 3: 3rd April --><div data-day=\"3\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Technology Sutra: AI in Governance\" data-location=\"Bengaluru\" data-date=\"3rd April, 2026\">&nbsp;</div><!-- Day 4: 4th April --><div data-day=\"4\" data-img=\"https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Tradition Sutra: Indian Knowledge Systems\" data-location=\"Varanasi\" data-date=\"4th April, 2026\">&nbsp;</div><!-- Day 5: 5th April --><div data-day=\"5\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Outcome Sutra: Citizen Centricity Workshop\" data-location=\"Hyderabad\" data-date=\"5th April, 2026\">&nbsp;</div><!-- Day 6: 6th April --><div data-day=\"6\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Mid-week Review and Samuhik Charcha\" data-location=\"Online\" data-date=\"6th April, 2026\">&nbsp;</div><!-- Day 7: 7th April --><div data-day=\"7\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Inter-ministerial Collaboration Session\" data-location=\"New Delhi\" data-date=\"7th April, 2026\">&nbsp;</div><!-- Day 8: 8th April --><div data-day=\"8\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Closing Ceremony\" data-location=\"New Delhi\" data-date=\"8th April, 2026\">&nbsp;</div></div></div><!-- /cbc-custom-landing -->', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 950, 1737, 'en', 0, '<script>\r\n    (function () {\r\n        /* Find the base URL of the cbc theme by looking at any already-loaded\r\n           theme stylesheet (e.g. home.css loaded by Drupal globally). */\r\n        function getThemeBase() {\r\n            var links = document.querySelectorAll(\'link[rel=\"stylesheet\"]\');\r\n            for (var i = 0; i < links.length; i++) {\r\n                var href = links[i].href || \'\';\r\n                var idx = href.indexOf(\'/themes/cbc/\');\r\n                if (idx !== -1) { return href.substring(0, idx); }\r\n            }\r\n            /* Fallback: derive from current page URL up to the Drupal root.\r\n               Works if Drupal is at a subdirectory like /cbc/ or at / */\r\n            var base = window.location.origin;\r\n            var path = window.location.pathname;\r\n            var drupalRoot = path.split(\'/themes/\')[0];\r\n            return base + (drupalRoot || \'\');\r\n        }\r\n\r\n        var base = getThemeBase();\r\n        var theme = base + \'/themes/cbc\';\r\n\r\n        /* Inject CSS — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"sadhana-saptah.css\"]\')) {\r\n            var css = document.createElement(\'link\');\r\n            css.rel = \'stylesheet\';\r\n            css.type = \'text/css\';\r\n            css.href = theme + \'/css/sadhana-saptah.css\';\r\n            document.head.appendChild(css);\r\n        }\r\n\r\n        /* Inject Google Fonts — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"Outfit\"]\')) {\r\n            var gf = document.createElement(\'link\');\r\n            gf.rel = \'stylesheet\';\r\n            gf.href = \'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap\';\r\n            document.head.appendChild(gf);\r\n        }\r\n\r\n        /* Inject JS after DOM is ready — skip if already loaded */\r\n        function loadJS() {\r\n            if (document.querySelector(\'script[src*=\"sadhana-saptah.js\"]\')) return;\r\n            var scr = document.createElement(\'script\');\r\n            scr.src = theme + \'/js/sadhana-saptah.js\';\r\n            document.body.appendChild(scr);\r\n        }\r\n\r\n        if (document.readyState === \'loading\') {\r\n            document.addEventListener(\'DOMContentLoaded\', loadJS);\r\n        } else {\r\n            loadJS();\r\n        }\r\n    })();\r\n</script><div class=\"cbc-custom-landing\"><!-- ==================================================================\r\n         HERO SECTION: Poster/Banner\r\n         ================================================================== --><div class=\"cbc-hero-section\"><img class=\"cbc-hero-poster\" src=\"/sites/default/files/REPLACE-WITH-YOUR-BANNER.jpg\" alt=\"SĀDHANA Saptah Banner\"></div><div class=\"container\"><!-- ==================================================================\r\n     TOP ACTION BUTTONS: Registration & iGOT\r\n     ================================================================== --><div class=\"cbc-registration-bar\"><a class=\"cbc-reg-btn cbc-reg-primary\" href=\"#REPLACE-WITH-REGISTRATION-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">📋</span> Registration Link </a><a class=\"cbc-reg-btn cbc-reg-igot\" href=\"#REPLACE-WITH-IGOT-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">🏛️</span> iGOT Karmayogi&nbsp;</a></div><!-- ==================================================================\r\n     SECTION 1: ABOUT SADHANA SAPTAH + THREE SUTRAS\r\n     ================================================================== --><div class=\"cbc-about-section\"><h2>About <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</h2><div class=\"section-about\"><p>India\'s governance landscape is being reshaped by rapid technological change, renewed attention to Indian Knowledge Systems, and an increasing focus on Citizen Centricity. <strong><img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</strong> is conceived as a theme-focused, sector-anchored exercise (sector classification as per SGOS) to strengthen governance capability across Ministries, Departments, Organisations (MDO), and States. The structure of the week shall be focused on three themes or Sutras — <strong>Technology, Tradition &amp; Tangible Outcomes</strong>.</p><p>The week coincides with the Foundation Day of CBC and completion of five years of Mission Karmayogi, providing an opportunity to review progress while strengthening the national capacity-building ecosystem.</p><p>Through a blended delivery model—comprising Karmayogi Talks by domain experts, Samuhik Charchas within institutions, digital learning through the iGOT platform, inter-ministerial workshops, and training programmes conducted by civil services training institutions—the initiative will engage civil servants across the government ecosystem. Participation will extend across <strong>93 Central Ministries and Departments, 30 States and UTs</strong> implementing Mission Karmayogi, and more than <strong>200 civil services training institutions</strong>, supported through coordinated institutional mechanisms led by CBC.</p><p>Beyond a week of learning engagements, <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah aims to reinforce a culture of continuous learning in government, accelerate engagement with the digital learning ecosystem, strengthen knowledge exchange across institutions, and generate insights for strengthening the broader capacity-building architecture under Mission Karmayogi.</p></div><!-- Three Sutras --><div class=\"sutras-grid\"><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🤖</span></p><h3>Technology</h3><p>AI and emerging technologies transforming the sector</p><ul class=\"sutra-list\"><li>Sector-specific AI use cases</li><li>Regulatory readiness</li><li>Digital public infrastructure integration</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🏛️</span></p><h3>Tradition</h3><p>Indian Knowledge Systems and indigenous innovations</p><ul class=\"sutra-list\"><li>Civilizational practices with contemporary relevance</li><li>Community-led institutional models</li><li>Indigenous governance insights</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🎯</span></p><h3>Tangible Outcomes</h3><p>Outcome-oriented governance and public value creation</p><ul class=\"sutra-list\"><li>Citizen impact tracking</li><li>Clear articulation of priority sectoral outcomes</li><li>Dashboard-based monitoring</li></ul></div></div></div><!-- /cbc-about-section --></div><!-- /container --><!-- ==================================================================\r\n     SECTION 2: EVENT SCHEDULE\r\n     ================================================================== --><div class=\"cbc-schedule-section\"><p><span class=\"cbc-schedule-title\">Event Schedule</span> <span class=\"cbc-schedule-subtitle\">2nd April – 8th April 2026</span></p><div class=\"cbc-schedule-tabs\"><button class=\"cbc-schedule-tab active\" data-tab=\"week\">Throughout the Week</button> <button class=\"cbc-schedule-tab\" data-tab=\"day1\">Day 1 – Launch Day</button> <button class=\"cbc-schedule-tab\" data-tab=\"day2-7\">Day 2–7</button> <button class=\"cbc-schedule-tab\" data-tab=\"day8\">Day 8 – Valedictory</button> <button class=\"cbc-schedule-tab\" data-tab=\"courses\">Courses in Focus</button></div><div class=\"container\"><!-- TAB: Throughout the Week --><div class=\"cbc-schedule-content active\" id=\"tab-week\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Activities Available Throughout the Week</h3><p>Flexible, self-paced and group-based learning opportunities.</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session / Activity</th><th style=\"width:260px;\">Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>Karmayogi Talks</strong></td><td>National Webinars – Morning &amp; Evening sessions</td><td>2 webinars per day, each 1 hour, thematic and sector-aligned</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience</td><td>1–2 courses mandatory per MDO; AI &amp; Marketplace courses included</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led group discussions</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Domain &amp; sectoral capacity building sessions</td></tr></tbody></table></div></div></div><!-- TAB: Day 1 – Launch Day --><div class=\"cbc-schedule-content\" id=\"tab-day1\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Udghatan Samaroh – Launch Day</h3><p>📅 2nd April 2026 | New Delhi</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th>Session</th><th style=\"text-align:right;width:200px;\">Time</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1.</td><td><strong>Inaugural Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Guests of Honour / Chief Guest</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>10:00 AM – 11:30 AM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2.</td><td><strong>Master Class: \'Capacity Building Imperative for an Entrepreneurial State\'</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri V. Anantha Nageswaran, Chief Economic Advisor, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>11:30 AM – 12:00 Noon</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3.</td><td><strong>Thematic Session-I: National Workshop on Future Ready Training Institutions for Viksit Bharat</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>12:00 Noon – 1:30 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Lunch Break</strong></em></td></tr><tr><td class=\"cbc-schedule-sn\">4.</td><td><strong>Thematic Session-II: Karmayogi Quality Framework</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>2:30 PM – 3:30 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5.</td><td><strong>Special Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri T. V. Somanathan, Cabinet Secretary, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>3:30 PM – 4:00 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6.</td><td><strong>Closing Reflection and Vote of Thanks</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>4:00 PM – 4:15 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Tea &amp; Networking</strong></em></td></tr></tbody></table></div></div></div><!-- TAB: Day 2–7 --><div class=\"cbc-schedule-content\" id=\"tab-day2-7\"><div class=\"cbc-schedule-table-card\" style=\"background-color:transparent;border-style:none;box-shadow:none;padding:20px;\"><div class=\"cbc-schedule-card-header\" style=\"background-color:white;border-radius:16px;border:1px solid #f0f0f0;margin-bottom:20px;\"><h3>Daily Webinar Sessions</h3><p>📅 3rd April – 8th April 2026 | Virtual / Hybrid</p></div><div class=\"cbc-webinar-grid\"><div class=\"cbc-webinar-card\"><h4>Morning Session – Webinar 1</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Theme-aligned webinar session led by domain experts covering Technology, Tradition, or Tangible Outcomes.</p></div><div class=\"cbc-webinar-card\"><h4>Afternoon/Evening Session – Webinar 2</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Complementary session with sectoral deep-dives, case studies, and interactive discussions.</p></div></div><div class=\"cbc-date-pills\"><div class=\"cbc-date-pill\">🔵 3rd &amp; 4th April – Technology</div><div class=\"cbc-date-pill\" style=\"background-color:#fff3e0;color:#e67e22;\">🟠 5th &amp; 6th April – Tradition</div><div class=\"cbc-date-pill\" style=\"background-color:#e8f5e9;color:#2e7d32;\">🟢 7th &amp; 8th April – Tangible Outcomes</div></div><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session</th><th>Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience; AI &amp; Marketplace focus</td><td>1–2 courses mandatory per MDO</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led Samuhik Charcha</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Sectoral / domain capacity building sessions</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Thematic Days</strong></td><td>Technology (3–4 Apr), Traditions (5–6 Apr), Tangible Outcomes (7–8 Apr)</td><td>Samuhik Charchas, Karmayogi Talks, Webinars &amp; Panel Discussions</td></tr></tbody></table></div></div></div></div><!-- TAB: Day 8 – Valedictory --><div class=\"cbc-schedule-content\" id=\"tab-day8\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Samapan Samaroh – Valedictory Day</h3><p>📅 8th April 2026</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:140px;\">Duration</th><th>Session</th><th>Tentative Activities</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>120 minutes</td><td><strong>Felicitation Session</strong></td><td>Summary of the Week (Data) · Felicitation of Karmayogi Leaderboard Achievers · Address by Chief Guest (~20 min)</td></tr></tbody></table></div></div></div><!-- TAB: Courses in Focus --><div class=\"cbc-schedule-content\" id=\"tab-courses\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Curated Learning Pathways on iGOT Karmayogi</h3><p>AI Courses &amp; iGOT Marketplace Courses — available throughout the week</p></div><div style=\"padding:16px 16px 0;\"><div class=\"cbc-course-tabs\"><button class=\"cbc-course-tab active\" data-course=\"ai\">AI Courses</button> <button class=\"cbc-course-tab\" data-course=\"marketplace\">iGOT Marketplace Courses</button></div></div><!-- AI Courses --><div class=\"cbc-schedule-table-wrapper\" id=\"course-ai-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Artificial Intelligence for Public Governance</td><td>Wadhwani AI &amp; Data Security Council of India</td><td style=\"text-align:right;\">3h 10m</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Large Language Models: Concepts and Applications</td><td>IIT Hyderabad</td><td style=\"text-align:right;\">1h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Deep Tech and India</td><td>ORF</td><td style=\"text-align:right;\">55m</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>AI in Government: Transforming Public Service Delivery</td><td>IISc Bengaluru</td><td style=\"text-align:right;\">2h 20m</td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Artificial Intelligence for Smarter Governance</td><td>Karmayogi Bharat – NeGD</td><td style=\"text-align:right;\">1h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>IndiaAI for All</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Fundamentals of Generative Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">50m</td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Introduction to Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>AI Applications in Government</td><td>NIC</td><td style=\"text-align:right;\">1h 50m</td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>आर्टिफिशियल इंटेलिजेंस की मूल बातें: अवसर, अनुप्रयोग और नैतिकता</td><td>Microsoft</td><td style=\"text-align:right;\">1h 35m</td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>प्रशासन के लिए एआई: कार्यों का स्व-चालन</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">40m</td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>सुशासन के सन्दर्भ में एआई</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">1h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Artificial Intelligence in Finance</td><td>SUDI</td><td style=\"text-align:right;\">1h 40m</td></tr><tr><td class=\"cbc-schedule-sn\">14</td><td>Core Areas of Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">15</td><td>शून्य से एआई तक</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">16</td><td>Advanced Prompt Engineering for Everyone</td><td>Vanderbilt University</td><td style=\"text-align:right;\">2h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">17</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera</td><td style=\"text-align:right;\">3h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">18</td><td>AI for Educators [Intermediate]</td><td>Common Sense Education</td><td style=\"text-align:right;\">1h 25m</td></tr><tr><td class=\"cbc-schedule-sn\">19</td><td>AI for Energy and Biomedical Applications</td><td>University of Michigan</td><td style=\"text-align:right;\">2h 05m</td></tr></tbody></table></div><!-- Marketplace Courses --><div class=\"cbc-schedule-table-wrapper\" style=\"display:none;\" id=\"course-marketplace-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Strategy and Game Theory for Management</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>32h 42m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Leadership Skills</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>46h 11m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Law, Governance, and Public Policy</td><td>O. P. Jindal Global University</td><td style=\"color:#f39200;text-align:right;\"><strong>18h 37m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>Introduction to Quantum Information</td><td>KAIST</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 48m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Negotiation Fundamentals</td><td>ESSEC Business School</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 35m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>Analysis and Interpretation of Large-Scale Programs</td><td>Johns Hopkins University</td><td style=\"color:#f39200;text-align:right;\"><strong>21h 6m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera Instructor Network</td><td style=\"color:#f39200;text-align:right;\"><strong>5h 52m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Forest Carbon Credits and Initiatives</td><td>Michigan State University</td><td style=\"color:#f39200;text-align:right;\"><strong>6h</strong></td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>Design Thinking and Predictive Analytics for Data Products</td><td>UC San Diego</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 25m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>Effective Engagement of Civil Society in Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>13h 19m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>Blockchain Platforms</td><td>University at Buffalo, SUNY</td><td style=\"color:#f39200;text-align:right;\"><strong>16h 16m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>Trade and Investment: Evidence-based Policies for Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>17h 2m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Foundations of Cybersecurity</td><td>Google</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 10m</strong></td></tr></tbody></table></div></div></div></div><p><!-- /container -->&nbsp;</p></div><!-- /cbc-schedule-section --><!-- ==================================================================\r\n     SECTION 3: EVENT GLIMPSES — 2-COLUMN GRID\r\n     (Leaders\' Voices on left | Testimonials on right)\r\n     ================================================================== --><div class=\"cbc-glimpses-section\"><div class=\"container\"><div class=\"cbc-glimpses-header\"><h2>Event Glimpses</h2><p>Reliving the inspiring words and impactful moments from <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah.</p></div><div class=\"cbc-glimpses-grid\"><!-- ── LEFT COLUMN: Leaders\' Voices — VIDEO Carousel ── --><div class=\"cbc-column-box\"><div class=\"cbc-column-title\">Leadership message</div><!--\r\n                    ★ HOW TO ADD A LEADER VIDEO:\r\n                    1. Get the YouTube embed URL:\r\n                       https://www.youtube.com/embed/YOUR_VIDEO_ID\r\n                       OR upload to Drupal Media and use the direct file URL.\r\n                    2. Copy the <div class=\"swiper-slide\"> block below, paste it\r\n                       inside the swiper-wrapper, and replace the iframe src.\r\n                       No JS changes needed — JS auto-detects new slides.\r\n                    --><div class=\"swiper leadersSwiper\"><div class=\"swiper-wrapper\"><!-- Leader Video 1 (Direct Drupal .mp4 Example) --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                        <source src=\"/sites/default/files/2026-03/leader-video-1.mp4\" type=\"video/mp4\">\r\n                                        Your browser does not support the video tag.\r\n                                    </video></div></div><!-- ★ PASTE MORE LEADER VIDEOS BELOW THIS LINE ★\r\n                                 Copy the <div class=\"swiper-slide\"> block above, \r\n                                 paste it, and replace the <source src=\"...\"> with your Drupal media URL.\r\n                            --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /leadersSwiper --></div><!-- /left column --><!-- ── RIGHT COLUMN: Testimonials (Tabbed) ── --><div class=\"cbc-column-box\"><div style=\"align-items:center;display:flex;flex-wrap:wrap;gap:15px;justify-content:space-between;\"><div class=\"cbc-column-title\" style=\"margin-bottom:0;\">Our collaborative efforts matter</div><div class=\"cbc-testimonial-tabs\" style=\"justify-content:flex-end;margin-bottom:0;margin-top:0;\"><button class=\"cbc-testimonial-tab active\" data-test-tab=\"video\">Video</button> <button class=\"cbc-testimonial-tab\" data-test-tab=\"written\">Written</button></div></div><!-- Video Testimonials Tab --><div class=\"cbc-testimonial-content active\" id=\"test-video\"><!--\r\n                ★ HOW TO ADD A VIDEO TESTIMONIAL:\r\n                1. Upload video to Drupal Media.\r\n                2. Copy the <div class=\"swiper-slide\"> block below, paste it,\r\n                   and replace the source src.\r\n                --><div class=\"swiper testimonialVideoSwiper\"><div class=\"swiper-wrapper\"><!-- Video Testimonial 1 --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                            <source src=\"/sites/default/files/2026-03/testimonial-1.mp4\" type=\"video/mp4\">\r\n                                        </video></div></div><!-- Video Testimonial 2 --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                            <source src=\"/sites/default/files/2026-03/imgae%20%20%284%29.mp4\" type=\"video/mp4\">\r\n                                        </video></div></div><div class=\"swiper-slide\"><div class=\"video-container\"><iframe src=\"https://www.youtube.com/embed/r9pBy80zTws\" title=\"Video Testimonial 2\" allowfullscreen=\"\"></iframe></div></div><!-- ★ PASTE MORE VIDEO TESTIMONIAL SLIDES BELOW THIS LINE ★ --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /testimonialVideoSwiper --></div><!-- /test-video --><!-- Written Testimonials Tab --><div class=\"cbc-testimonial-content\" id=\"test-written\"><div class=\"testimonial-written-wrap\"><!--\r\n                    ★ HOW TO ADD A WRITTEN TESTIMONIAL:\r\n                    Copy the <div class=\"testimonial-card\"> block below, paste it,\r\n                    and change the quote and author text.\r\n                    --><div class=\"testimonial-track\"><div class=\"testimonial-card\"><p>\"The AI modules were eye-opening. It has completely changed how I think about data-driven decisions.\"</p><p><span class=\"author\">— Senior Administrative Officer</span></p></div><div class=\"testimonial-card\"><p>\"Samuhik Charcha sessions allowed us to bond as a team while solving real service bottlenecks.\"</p><p><span class=\"author\">— Deputy Secretary</span></p></div><div class=\"testimonial-card\"><p>\"A masterfully organized week. The focus on Indian Knowledge Systems was particularly inspiring.\"</p><p><span class=\"author\">— Project Director</span></p></div><div class=\"testimonial-card\"><p>\"The iGOT courses were highly relevant and helped me immediately apply learnings in my department.\"</p><p><span class=\"author\">— Under Secretary, Ministry of Finance</span></p></div><!-- ★ PASTE MORE WRITTEN TESTIMONIALS BELOW THIS LINE ★ --></div><!-- /testimonial-track --></div><!-- /testimonial-written-wrap --></div><!-- /test-written --></div><!-- /right column --></div><!-- /cbc-glimpses-grid --></div><!-- /container --></div><!-- /cbc-glimpses-section --><!-- ==================================================================\r\n     SECTION 4: PHOTO & VIDEO GALLERY (Side by Side)\r\n     ================================================================== --><div class=\"cbc-gallery-section\"><div class=\"container\"><div class=\"cbc-glimpses-header\"><h2>Event Gallery</h2><p>Capturing the moments and milestones of <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah.</p></div><div class=\"gallery-grid\"><!-- Photo Gallery --><div class=\"gallery-card\"><h3>📸 Glimpses</h3><!--\r\n            ★ HOW TO ADD A PHOTO:\r\n            1. Upload your photo to Drupal → Media → Add Media (Image).\r\n            2. Open the image and copy its URL from the browser address bar,\r\n               or right-click → \"Copy image address\".\r\n            3. Copy the <div class=\"swiper-slide\"> block below, paste it,\r\n               and replace the img src with your Drupal media URL.\r\n\r\n            Drupal media URLs typically look like:\r\n              /sites/default/files/2026-04/photo-name.jpg\r\n            --><div class=\"swiper photoSwiper\"><div class=\"swiper-wrapper\"><!-- ★ REPLACE WITH YOUR DRUPAL MEDIA URL ★ --><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-1.jpg\" alt=\"SĀDHANA Saptah Session\"></div><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-2.jpg\" alt=\"SĀDHANA Saptah Workshop\"></div><div class=\"swiper-slide\"><img src=\"/sites/default/files/REPLACE-WITH-YOUR-PHOTO-3.jpg\" alt=\"SĀDHANA Saptah Team\"></div><!-- ★ PASTE MORE PHOTO SLIDES BELOW THIS LINE ★ --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /photoSwiper --><p class=\"gallery-caption\"><strong>Moments of Interaction:</strong> Capturing the spirit of <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah.</p></div><!-- /gallery-card Photo --><!-- Video Gallery --><div class=\"gallery-card\"><h3>🎬 Videos</h3><!--\r\n            ★ HOW TO ADD A VIDEO:\r\n            Option A — YouTube: Use the YouTube embed URL:\r\n              https://www.youtube.com/embed/YOUR_VIDEO_ID\r\n\r\n            Option B — Drupal Media Upload:\r\n              1. Upload the video to Drupal → Media → Add Media (Video file).\r\n              2. Use the direct file URL as the iframe src is NOT needed for\r\n                 hosted videos. Instead use an HTML5 video tag:\r\n                 <video controls><source src=\"/sites/default/files/your-video.mp4\"></video>\r\n\r\n            Copy the <div class=\"swiper-slide\"> block below and paste it.\r\n            --><div class=\"swiper videoSwiper\"><div class=\"swiper-wrapper\"><!-- Video Highlight (Direct Drupal .mp4) --><div class=\"swiper-slide\"><div class=\"video-container\"><video controls=\"\" playsinline=\"\">\r\n                                        <source src=\"/sites/default/files/2026-03/gallery-video-1.mp4\" type=\"video/mp4\">\r\n                                    </video></div></div><!-- ★ PASTE MORE VIDEO SLIDES BELOW THIS LINE ★\r\n                                 Copy the <div class=\"swiper-slide\"> block above and update the source src.\r\n                            --></div><!-- /swiper-wrapper --><div class=\"swiper-pagination\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-next-btn\">&nbsp;</div><div class=\"cbc-swiper-btn cbc-prev-btn\">&nbsp;</div></div><!-- /videoSwiper --><p class=\"gallery-caption\"><strong>Impact Stories:</strong> Watch the transformation in action.</p></div><!-- /gallery-card Video --></div><!-- /gallery-grid --></div><!-- /container --></div><!-- /cbc-gallery-section --><!-- ==================================================================\r\n         SECTION 5: DoP&T SOCIAL MEDIA LINKS\r\n         ================================================================== --><div class=\"cbc-social-section\" style=\"background-color:#000b1a;border-top:1px solid rgba(0,174,239,0.1);padding:40px 20px;position:relative;text-align:center;\"><div class=\"container\" style=\"position:relative;z-index:1;\"><h3 style=\"color:#ffffff;font-family:&apos;Outfit&apos;,sans-serif;font-size:20px;margin:0 0 5px;\"><strong>Connect with DoP&amp;T</strong></h3><p style=\"color:rgba(255,255,255,0.4);font-size:12px;letter-spacing:0.5px;margin:0 0 20px;\">Department of Personnel and Training</p><!-- Social icons row — Exact footer style: Tiny circular cyan stroke --><div style=\"align-items:center;display:flex;flex-wrap:wrap;gap:18px;justify-content:center;\"><!-- X (Twitter) --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://x.com/CBC_MK\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"14\" height=\"14\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z\"></path></svg></a><!-- LinkedIn --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"16\" height=\"16\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z\"></path></svg></a><!-- Instagram --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"18\" height=\"18\" viewbox=\"0 0 24 24\" fill=\"none\" stroke=\"#00adef\" stroke-width=\"2\"><rect x=\"2\" y=\"2\" width=\"20\" height=\"20\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"0.5\" fill=\"#00adef\"></circle></svg></a><!-- Facebook --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"18\" height=\"18\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M22.675 0h-21.35c-.732 0-1.325.593-1.325 1.325v21.351c0 .731.593 1.324 1.325 1.324h11.495v-9.294h-3.128v-3.622h3.128v-2.671c0-3.1 1.893-4.788 4.659-4.788 1.325 0 2.463.099 2.795.143v3.24l-1.918.001c-1.504 0-1.795.715-1.795 1.763v2.313h3.587l-.467 3.622h-3.12v9.293h6.116c.73 0 1.323-.593 1.323-1.325v-21.35c0-.732-.593-1.325-1.325-1.325z\"></path></svg></a></div></div></div><!-- ==================================================================\r\n         HIDDEN DATA BLOCK: CALENDAR EVENTS\r\n         Editable via Drupal Basic Page HTML — ZERO JS interaction needed.\r\n         ================================================================== --><div style=\"display:none;\" id=\"cbc-events-data\"><!-- Day 2: 2nd April --><div data-day=\"2\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Launch Event\" data-location=\"New Delhi\" data-date=\"2nd April, 2026\">&nbsp;</div><!-- Day 3: 3rd April --><div data-day=\"3\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Technology Sutra: AI in Governance\" data-location=\"Bengaluru\" data-date=\"3rd April, 2026\">&nbsp;</div><!-- Day 4: 4th April --><div data-day=\"4\" data-img=\"https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Tradition Sutra: Indian Knowledge Systems\" data-location=\"Varanasi\" data-date=\"4th April, 2026\">&nbsp;</div><!-- Day 5: 5th April --><div data-day=\"5\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Outcome Sutra: Citizen Centricity Workshop\" data-location=\"Hyderabad\" data-date=\"5th April, 2026\">&nbsp;</div><!-- Day 6: 6th April --><div data-day=\"6\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Mid-week Review and Samuhik Charcha\" data-location=\"Online\" data-date=\"6th April, 2026\">&nbsp;</div><!-- Day 7: 7th April --><div data-day=\"7\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Inter-ministerial Collaboration Session\" data-location=\"New Delhi\" data-date=\"7th April, 2026\">&nbsp;</div><!-- Day 8: 8th April --><div data-day=\"8\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Closing Ceremony\" data-location=\"New Delhi\" data-date=\"8th April, 2026\">&nbsp;</div></div></div><!-- /cbc-custom-landing -->', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 950, 1738, 'en', 0, '<script>\r\n    (function () {\r\n        /* Find the base URL of the cbc theme by looking at any already-loaded\r\n           theme stylesheet (e.g. home.css loaded by Drupal globally). */\r\n        function getThemeBase() {\r\n            var links = document.querySelectorAll(\'link[rel=\"stylesheet\"]\');\r\n            for (var i = 0; i < links.length; i++) {\r\n                var href = links[i].href || \'\';\r\n                var idx = href.indexOf(\'/themes/cbc/\');\r\n                if (idx !== -1) { return href.substring(0, idx); }\r\n            }\r\n            /* Fallback: derive from current page URL up to the Drupal root.\r\n               Works if Drupal is at a subdirectory like /cbc/ or at / */\r\n            var base = window.location.origin;\r\n            var path = window.location.pathname;\r\n            var drupalRoot = path.split(\'/themes/\')[0];\r\n            return base + (drupalRoot || \'\');\r\n        }\r\n        var base = getThemeBase();\r\n        var theme = base + \'/themes/cbc\';\r\n        /* Inject CSS — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"sadhana-saptah.css\"]\')) {\r\n            var css = document.createElement(\'link\');\r\n            css.rel = \'stylesheet\';\r\n            css.type = \'text/css\';\r\n            css.href = theme + \'/css/sadhana-saptah.css\';\r\n            document.head.appendChild(css);\r\n        }\r\n        /* Inject Google Fonts — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"Outfit\"]\')) {\r\n            var gf = document.createElement(\'link\');\r\n            gf.rel = \'stylesheet\';\r\n            gf.href = \'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap\';\r\n            document.head.appendChild(gf);\r\n        }\r\n        /* Inject JS after DOM is ready — skip if already loaded */\r\n        function loadJS() {\r\n            if (document.querySelector(\'script[src*=\"sadhana-saptah.js\"]\')) return;\r\n            var scr = document.createElement(\'script\');\r\n            scr.src = theme + \'/js/sadhana-saptah.js\';\r\n            document.body.appendChild(scr);\r\n        }\r\n        if (document.readyState === \'loading\') {\r\n            document.addEventListener(\'DOMContentLoaded\', loadJS);\r\n        } else {\r\n            loadJS();\r\n        }\r\n    })();\r\n</script><div class=\"cbc-custom-landing\"><!-- ==================================================================\r\n             HERO SECTION: Poster/Banner\r\n             ================================================================== --><div class=\"cbc-hero-section\"><img class=\"cbc-hero-poster\" src=\"/sites/default/files/2026-03/WhatsApp%20Image%202026-03-30%20at%203.27.47%20PM.jpeg\" alt=\"SĀDHANA Saptah Banner\"></div><div class=\"container\"><!-- ==================================================================\r\n             TOP ACTION BUTTONS: Registration & iGOT\r\n             ================================================================== --><div class=\"cbc-registration-bar\"><a class=\"cbc-reg-btn cbc-reg-primary\" href=\"#REPLACE-WITH-REGISTRATION-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">📋</span> Registration Link </a><a class=\"cbc-reg-btn cbc-reg-igot\" href=\"#REPLACE-WITH-IGOT-LINK\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">🏛️</span> iGOT Karmayogi&nbsp;</a></div><!-- ==================================================================\r\n             SECTION 1: ABOUT SADHANA SAPTAH + THREE SUTRAS\r\n             ================================================================== --><div class=\"cbc-about-section\"><h2>About <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</h2><div class=\"section-about\"><p>India\'s governance landscape is being reshaped by rapid technological change, renewed attention to Indian Knowledge Systems, and an increasing focus on Citizen Centricity. <strong><img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</strong> is conceived as a theme-focused, sector-anchored exercise (sector classification as per SGOS) to strengthen governance capability across Ministries, Departments, Organisations (MDO), and States. The structure of the week shall be focused on three themes or Sutras — <strong>Technology, Tradition &amp; Tangible Outcomes</strong>.</p><p>The week coincides with the Foundation Day of CBC and completion of five years of Mission Karmayogi, providing an opportunity to review progress while strengthening the national capacity-building ecosystem.</p><p>Through a blended delivery model—comprising Karmayogi Talks by domain experts, Samuhik Charchas within institutions, digital learning through the iGOT platform, inter-ministerial workshops, and training programmes conducted by civil services training institutions—the initiative will engage civil servants across the government ecosystem. Participation will extend across <strong>93 Central Ministries and Departments, 30 States and UTs</strong> implementing Mission Karmayogi, and more than <strong>200 civil services training institutions</strong>, supported through coordinated institutional mechanisms led by CBC.</p><p>Beyond a week of learning engagements, <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah aims to reinforce a culture of continuous learning in government, accelerate engagement with the digital learning ecosystem, strengthen knowledge exchange across institutions, and generate insights for strengthening the broader capacity-building architecture under Mission Karmayogi.</p></div><!-- Three Sutras --><div class=\"sutras-grid\"><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🤖</span></p><h3>Technology</h3><p>AI and emerging technologies transforming the sector</p><ul class=\"sutra-list\"><li>Sector-specific AI use cases</li><li>Regulatory readiness</li><li>Digital public infrastructure integration</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🏛️</span></p><h3>Tradition</h3><p>Indian Knowledge Systems and indigenous innovations</p><ul class=\"sutra-list\"><li>Civilizational practices with contemporary relevance</li><li>Community-led institutional models</li><li>Indigenous governance insights</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🎯</span></p><h3>Tangible Outcomes</h3><p>Outcome-oriented governance and public value creation</p><ul class=\"sutra-list\"><li>Citizen impact tracking</li><li>Clear articulation of priority sectoral outcomes</li><li>Dashboard-based monitoring</li></ul></div></div></div><!-- /cbc-about-section --></div><!-- /container --><!-- ==================================================================\r\n         SECTION 2: EVENT SCHEDULE\r\n         ================================================================== --><div class=\"cbc-schedule-section\"><p><span class=\"cbc-schedule-title\">Event Schedule</span> <span class=\"cbc-schedule-subtitle\">2nd April – 8th April 2026</span></p><div class=\"cbc-schedule-tabs\"><button class=\"cbc-schedule-tab active\" data-tab=\"week\">Throughout the Week</button> <button class=\"cbc-schedule-tab\" data-tab=\"day1\">Day 1 – Launch Day</button> <button class=\"cbc-schedule-tab\" data-tab=\"day2-7\">Day 2–7</button> <button class=\"cbc-schedule-tab\" data-tab=\"day8\">Day 8 – Valedictory</button> <button class=\"cbc-schedule-tab\" data-tab=\"courses\">Courses in Focus</button></div><div class=\"container\"><!-- TAB: Throughout the Week --><div class=\"cbc-schedule-content active\" id=\"tab-week\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Activities Available Throughout the Week</h3><p>Flexible, self-paced and group-based learning opportunities.</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session / Activity</th><th style=\"width:260px;\">Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>Karmayogi Talks</strong></td><td>National Webinars – Morning &amp; Evening sessions</td><td>2 webinars per day, each 1 hour, thematic and sector-aligned</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience</td><td>1–2 courses mandatory per MDO; AI &amp; Marketplace courses included</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led group discussions</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Domain &amp; sectoral capacity building sessions</td></tr></tbody></table></div></div></div><!-- TAB: Day 1 – Launch Day --><div class=\"cbc-schedule-content\" id=\"tab-day1\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Udghatan Samaroh – Launch Day</h3><p>📅 2nd April 2026 | New Delhi</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th>Session</th><th style=\"text-align:right;width:200px;\">Time</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1.</td><td><strong>Inaugural Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Guests of Honour / Chief Guest</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>10:00 AM – 11:30 AM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2.</td><td><strong>Master Class: \'Capacity Building Imperative for an Entrepreneurial State\'</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri V. Anantha Nageswaran, Chief Economic Advisor, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>11:30 AM – 12:00 Noon</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3.</td><td><strong>Thematic Session-I: National Workshop on Future Ready Training Institutions for Viksit Bharat</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>12:00 Noon – 1:30 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Lunch Break</strong></em></td></tr><tr><td class=\"cbc-schedule-sn\">4.</td><td><strong>Thematic Session-II: Karmayogi Quality Framework</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>2:30 PM – 3:30 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5.</td><td><strong>Special Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri T. V. Somanathan, Cabinet Secretary, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>3:30 PM – 4:00 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6.</td><td><strong>Closing Reflection and Vote of Thanks</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>4:00 PM – 4:15 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Tea &amp; Networking</strong></em></td></tr></tbody></table></div></div></div><!-- TAB: Day 2–7 --><div class=\"cbc-schedule-content\" id=\"tab-day2-7\"><div class=\"cbc-schedule-table-card\" style=\"background-color:transparent;border-style:none;box-shadow:none;padding:20px;\"><div class=\"cbc-schedule-card-header\" style=\"background-color:white;border-radius:16px;border:1px solid #f0f0f0;margin-bottom:20px;\"><h3>Daily Webinar Sessions</h3><p>📅 3rd April – 8th April 2026 | Virtual / Hybrid</p></div><div class=\"cbc-webinar-grid\"><div class=\"cbc-webinar-card\"><h4>Morning Session – Webinar 1</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Theme-aligned webinar session led by domain experts covering Technology, Tradition, or Tangible Outcomes.</p></div><div class=\"cbc-webinar-card\"><h4>Afternoon/Evening Session – Webinar 2</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Complementary session with sectoral deep-dives, case studies, and interactive discussions.</p></div></div><div class=\"cbc-date-pills\"><div class=\"cbc-date-pill\">🔵 3rd &amp; 4th April – Technology</div><div class=\"cbc-date-pill\" style=\"background-color:#fff3e0;color:#e67e22;\">🟠 5th &amp; 6th April – Tradition</div><div class=\"cbc-date-pill\" style=\"background-color:#e8f5e9;color:#2e7d32;\">🟢 7th &amp; 8th April – Tangible Outcomes</div></div><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session</th><th>Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience; AI &amp; Marketplace focus</td><td>1–2 courses mandatory per MDO</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led Samuhik Charcha</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Sectoral / domain capacity building sessions</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Thematic Days</strong></td><td>Technology (3–4 Apr), Traditions (5–6 Apr), Tangible Outcomes (7–8 Apr)</td><td>Samuhik Charchas, Karmayogi Talks, Webinars &amp; Panel Discussions</td></tr></tbody></table></div></div></div></div><!-- TAB: Day 8 – Valedictory --><div class=\"cbc-schedule-content\" id=\"tab-day8\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Samapan Samaroh – Valedictory Day</h3><p>📅 8th April 2026</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:140px;\">Duration</th><th>Session</th><th>Tentative Activities</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>120 minutes</td><td><strong>Felicitation Session</strong></td><td>Summary of the Week (Data) · Felicitation of Karmayogi Leaderboard Achievers · Address by Chief Guest (~20 min)</td></tr></tbody></table></div></div></div><!-- TAB: Courses in Focus --><div class=\"cbc-schedule-content\" id=\"tab-courses\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Curated Learning Pathways on iGOT Karmayogi</h3><p>AI Courses &amp; iGOT Marketplace Courses — available throughout the week</p></div><div style=\"padding:16px 16px 0;\"><div class=\"cbc-course-tabs\"><button class=\"cbc-course-tab active\" data-course=\"ai\">AI Courses</button> <button class=\"cbc-course-tab\" data-course=\"marketplace\">iGOT Marketplace Courses</button></div></div><!-- AI Courses --><div class=\"cbc-schedule-table-wrapper\" id=\"course-ai-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Artificial Intelligence for Public Governance</td><td>Wadhwani AI &amp; Data Security Council of India</td><td style=\"text-align:right;\">3h 10m</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Large Language Models: Concepts and Applications</td><td>IIT Hyderabad</td><td style=\"text-align:right;\">1h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Deep Tech and India</td><td>ORF</td><td style=\"text-align:right;\">55m</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>AI in Government: Transforming Public Service Delivery</td><td>IISc Bengaluru</td><td style=\"text-align:right;\">2h 20m</td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Artificial Intelligence for Smarter Governance</td><td>Karmayogi Bharat – NeGD</td><td style=\"text-align:right;\">1h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>IndiaAI for All</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Fundamentals of Generative Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">50m</td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Introduction to Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>AI Applications in Government</td><td>NIC</td><td style=\"text-align:right;\">1h 50m</td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>आर्टिफिशियल इंटेलिजेंस की मूल बातें: अवसर, अनुप्रयोग और नैतिकता</td><td>Microsoft</td><td style=\"text-align:right;\">1h 35m</td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>प्रशासन के लिए एआई: कार्यों का स्व-चालन</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">40m</td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>सुशासन के सन्दर्भ में एआई</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">1h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Artificial Intelligence in Finance</td><td>SUDI</td><td style=\"text-align:right;\">1h 40m</td></tr><tr><td class=\"cbc-schedule-sn\">14</td><td>Core Areas of Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">15</td><td>शून्य से एआई तक</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">16</td><td>Advanced Prompt Engineering for Everyone</td><td>Vanderbilt University</td><td style=\"text-align:right;\">2h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">17</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera</td><td style=\"text-align:right;\">3h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">18</td><td>AI for Educators [Intermediate]</td><td>Common Sense Education</td><td style=\"text-align:right;\">1h 25m</td></tr><tr><td class=\"cbc-schedule-sn\">19</td><td>AI for Energy and Biomedical Applications</td><td>University of Michigan</td><td style=\"text-align:right;\">2h 05m</td></tr></tbody></table></div><!-- Marketplace Courses --><div class=\"cbc-schedule-table-wrapper\" style=\"display:none;\" id=\"course-marketplace-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Strategy and Game Theory for Management</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>32h 42m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Leadership Skills</td><td>IIM, Ahmedabad</td><td style=\"color:#f39200;text-align:right;\"><strong>46h 11m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Law, Governance, and Public Policy</td><td>O. P. Jindal Global University</td><td style=\"color:#f39200;text-align:right;\"><strong>18h 37m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>Introduction to Quantum Information</td><td>KAIST</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 48m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Negotiation Fundamentals</td><td>ESSEC Business School</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 35m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>Analysis and Interpretation of Large-Scale Programs</td><td>Johns Hopkins University</td><td style=\"color:#f39200;text-align:right;\"><strong>21h 6m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Build and Execute an Organisational AI Strategy</td><td>Coursera Instructor Network</td><td style=\"color:#f39200;text-align:right;\"><strong>5h 52m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Forest Carbon Credits and Initiatives</td><td>Michigan State University</td><td style=\"color:#f39200;text-align:right;\"><strong>6h</strong></td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>Design Thinking and Predictive Analytics for Data Products</td><td>UC San Diego</td><td style=\"color:#f39200;text-align:right;\"><strong>8h 25m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>Effective Engagement of Civil Society in Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>13h 19m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>Blockchain Platforms</td><td>University at Buffalo, SUNY</td><td style=\"color:#f39200;text-align:right;\"><strong>16h 16m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>Trade and Investment: Evidence-based Policies for Development</td><td>Erasmus University Rotterdam</td><td style=\"color:#f39200;text-align:right;\"><strong>17h 2m</strong></td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Foundations of Cybersecurity</td><td>Google</td><td style=\"color:#f39200;text-align:right;\"><strong>10h 10m</strong></td></tr></tbody></table></div></div></div></div><p><!-- /container -->&nbsp;</p></div><!-- /cbc-schedule-section --><!-- ==================================================================\r\n         SE