"6.5\" r=\"0.5\" fill=\"#00adef\"></circle></svg></a><!-- Facebook --><a style=\"align-items:center;background-color:rgba(255,255,255,0.03);border-radius:50%;border:1px solid rgba(0,174,239,0.3);display:flex;height:38px;justify-content:center;text-decoration:none;transition:all 0.3s;width:38px;\" href=\"https://www.facebook.com/share/1AQvydowQ9/\" target=\"_blank\" rel=\"noopener\" onmouseover=\"this.style.borderColor=&apos;#00adef&apos;;this.style.background=&apos;rgba(0,174,239,0.1)&apos;\" onmouseout=\"this.style.borderColor=&apos;rgba(0,174,239,0.3)&apos;;this.style.background=&apos;rgba(255,255,255,0.03)&apos;\"><svg width=\"18\" height=\"18\" viewbox=\"0 0 24 24\" fill=\"#00adef\"><path d=\"M22.675 0h-21.35c-.732 0-1.325.593-1.325 1.325v21.351c0 .731.593 1.324 1.325 1.324h11.495v-9.294h-3.128v-3.622h3.128v-2.671c0-3.1 1.893-4.788 4.659-4.788 1.325 0 2.463.099 2.795.143v3.24l-1.918.001c-1.504 0-1.795.715-1.795 1.763v2.313h3.587l-.467 3.622h-3.12v9.293h6.116c.73 0 1.323-.593 1.323-1.325v-21.35c0-.732-.593-1.325-1.325-1.325z\"></path></svg></a></div></div></div><!-- ==================================================================\r\n                                         HIDDEN DATA BLOCK: CALENDAR EVENTS\r\n                                         Editable via Drupal Basic Page HTML — ZERO JS interaction needed.\r\n                                         ================================================================== --><div style=\"display:none;\" id=\"cbc-events-data\"><!-- Day 2: 2nd April --><div data-day=\"2\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Launch Event\" data-location=\"New Delhi\" data-date=\"2nd April, 2026\">&nbsp;</div><!-- Day 3: 3rd April --><div data-day=\"3\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Technology Sutra: AI in Governance\" data-location=\"Bengaluru\" data-date=\"3rd April, 2026\">&nbsp;</div><!-- Day 4: 4th April --><div data-day=\"4\" data-img=\"https://images.unsplash.com/photo-1517048676732-d65bc937f952?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Tradition Sutra: Indian Knowledge Systems\" data-location=\"Varanasi\" data-date=\"4th April, 2026\">&nbsp;</div><!-- Day 5: 5th April --><div data-day=\"5\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Outcome Sutra: Citizen Centricity Workshop\" data-location=\"Hyderabad\" data-date=\"5th April, 2026\">&nbsp;</div><!-- Day 6: 6th April --><div data-day=\"6\" data-img=\"https://images.unsplash.com/photo-1540575861501-7cf05a4b125a?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Mid-week Review and Samuhik Charcha\" data-location=\"Online\" data-date=\"6th April, 2026\">&nbsp;</div><!-- Day 7: 7th April --><div data-day=\"7\" data-img=\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"Inter-ministerial Collaboration Session\" data-location=\"New Delhi\" data-date=\"7th April, 2026\">&nbsp;</div><!-- Day 8: 8th April --><div data-day=\"8\" data-img=\"https://images.unsplash.com/photo-1531206715517-5c0ba140b2b8?auto=format&amp;fit=crop&amp;w=800&amp;q=80\" data-title=\"SĀDHANA Saptah Closing Ceremony\" data-location=\"New Delhi\" data-date=\"8th April, 2026\">&nbsp;</div></div></div><!-- /cbc-custom-landing -->', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 950, 1739, 'en', 0, '<script>\r\n    (function () {\r\n        /* Find the base URL of the cbc theme by looking at any already-loaded\r\n           theme stylesheet (e.g. home.css loaded by Drupal globally). */\r\n        function getThemeBase() {\r\n            var links = document.querySelectorAll(\'link[rel=\"stylesheet\"]\');\r\n            for (var i = 0; i < links.length; i++) {\r\n                var href = links[i].href || \'\';\r\n                var idx = href.indexOf(\'/themes/cbc/\');\r\n                if (idx !== -1) { return href.substring(0, idx); }\r\n            }\r\n            /* Fallback: derive from current page URL up to the Drupal root.\r\n               Works if Drupal is at a subdirectory like /cbc/ or at / */\r\n            var base = window.location.origin;\r\n            var path = window.location.pathname;\r\n            var drupalRoot = path.split(\'/themes/\')[0];\r\n            return base + (drupalRoot || \'\');\r\n        }\r\n        var base = getThemeBase();\r\n        var theme = base + \'/themes/cbc\';\r\n        /* Inject CSS — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"sadhana-saptah.css\"]\')) {\r\n            var css = document.createElement(\'link\');\r\n            css.rel = \'stylesheet\';\r\n            css.type = \'text/css\';\r\n            css.href = theme + \'/css/sadhana-saptah.css\';\r\n            document.head.appendChild(css);\r\n        }\r\n        /* Inject Google Fonts — skip if already loaded */\r\n        if (!document.querySelector(\'link[href*=\"Outfit\"]\')) {\r\n            var gf = document.createElement(\'link\');\r\n            gf.rel = \'stylesheet\';\r\n            gf.href = \'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap\';\r\n            document.head.appendChild(gf);\r\n        }\r\n        /* Inject JS after DOM is ready — skip if already loaded */\r\n        function loadJS() {\r\n            if (document.querySelector(\'script[src*=\"sadhana-saptah.js\"]\')) return;\r\n            var scr = document.createElement(\'script\');\r\n            scr.src = theme + \'/js/sadhana-saptah.js\';\r\n            document.body.appendChild(scr);\r\n        }\r\n        if (document.readyState === \'loading\') {\r\n            document.addEventListener(\'DOMContentLoaded\', loadJS);\r\n        } else {\r\n            loadJS();\r\n        }\r\n    })();\r\n</script><div class=\"cbc-custom-landing\"><!-- ==================================================================\r\n                 HERO SECTION: Poster/Banner\r\n                 ================================================================== --><div class=\"cbc-hero-section\"><img class=\"cbc-hero-poster\" src=\"/sites/default/files/2026-03/WhatsApp%20Image%202026-03-30%20at%203.27.47%20PM.jpeg\" alt=\"SĀDHANA Saptah Banner\"></div><div class=\"container\"><!-- ==================================================================\r\n                     TOP ACTION BUTTONS: Registration & iGOT\r\n                     ================================================================== --><div class=\"cbc-registration-bar\"><a class=\"cbc-reg-btn cbc-reg-primary\" href=\"https://cbc.negd.in/registration.aspx\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">📋</span> Registration Link </a><a class=\"cbc-reg-btn cbc-reg-igot\" href=\"https://igotkarmayogi.gov.in\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-icon\">🏛️</span> iGOT Karmayogi&nbsp;</a></div><!-- ==================================================================\r\n                     SECTION 1: ABOUT SADHANA SAPTAH + THREE SUTRAS\r\n                     ================================================================== --><div class=\"cbc-about-section\"><h2>About <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</h2><div class=\"section-about\"><p>India\'s governance landscape is being reshaped by rapid technological change, renewed attention to Indian Knowledge Systems, and an increasing focus on Citizen Centricity. <strong><img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah</strong> is conceived as a theme-focused, sector-anchored exercise (sector classification as per SGOS) to strengthen governance capability across Ministries, Departments, Organisations (MDO), and States. The structure of the week shall be focused on three themes or Sutras — <strong>Technology, Tradition &amp; Tangible Outcomes</strong>.</p><p>The week coincides with the Foundation Day of CBC and completion of five years of Mission Karmayogi, providing an opportunity to review progress while strengthening the national capacity-building ecosystem.</p><p>Through a blended delivery model—comprising Karmayogi Talks by domain experts, Samuhik Charchas within institutions, digital learning through the iGOT platform, inter-ministerial workshops, and training programmes conducted by civil services training institutions—the initiative will engage civil servants across the government ecosystem. Participation will extend across <strong>93 Central Ministries and Departments, 30 States and UTs</strong> implementing Mission Karmayogi, and more than <strong>200 civil services training institutions</strong>, supported through coordinated institutional mechanisms led by CBC.</p><p>Beyond a week of learning engagements, <img class=\"cbc-sadhana-logo\" src=\"https://cbc.gov.in/sites/default/files/2026-03/Sadhana_text.png\" alt=\"SĀDHANA\" width=\"4313\" height=\"1069\"> Saptah aims to reinforce a culture of continuous learning in government, accelerate engagement with the digital learning ecosystem, strengthen knowledge exchange across institutions, and generate insights for strengthening the broader capacity-building architecture under Mission Karmayogi.</p></div><!-- Three Sutras --><div class=\"sutras-grid\"><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🤖</span></p><h3>Technology</h3><p>AI and emerging technologies transforming the sector</p><ul class=\"sutra-list\"><li>Sector-specific AI use cases</li><li>Regulatory readiness</li><li>Digital public infrastructure integration</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🏛️</span></p><h3>Tradition</h3><p>Indian Knowledge Systems and indigenous innovations</p><ul class=\"sutra-list\"><li>Civilizational practices with contemporary relevance</li><li>Community-led institutional models</li><li>Indigenous governance insights</li></ul></div><div class=\"sutra-card\"><p><span class=\"sutra-icon\">🎯</span></p><h3>Tangible Outcomes</h3><p>Outcome-oriented governance and public value creation</p><ul class=\"sutra-list\"><li>Citizen impact tracking</li><li>Clear articulation of priority sectoral outcomes</li><li>Dashboard-based monitoring</li></ul></div></div></div><!-- /cbc-about-section --></div><!-- /container --><!-- ==================================================================\r\n             SECTION 2: EVENT SCHEDULE\r\n             ================================================================== --><div class=\"cbc-schedule-section\"><p><span class=\"cbc-schedule-title\">Event Schedule</span> <span class=\"cbc-schedule-subtitle\">2nd April – 8th April 2026</span></p><div class=\"cbc-schedule-tabs\"><button class=\"cbc-schedule-tab active\" data-tab=\"week\">Throughout the Week</button> <button class=\"cbc-schedule-tab\" data-tab=\"day1\">Day 1 – Launch Day</button> <button class=\"cbc-schedule-tab\" data-tab=\"day2-7\">Day 2–7</button> <button class=\"cbc-schedule-tab\" data-tab=\"day8\">Day 8 – Valedictory</button> <button class=\"cbc-schedule-tab\" data-tab=\"courses\">Courses in Focus</button></div><div class=\"container\"><!-- TAB: Throughout the Week --><div class=\"cbc-schedule-content active\" id=\"tab-week\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Activities Available Throughout the Week</h3><p>Flexible, self-paced and group-based learning opportunities.</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session / Activity</th><th style=\"width:260px;\">Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>Karmayogi Talks</strong></td><td>National Webinars – Morning &amp; Evening sessions</td><td>2 webinars per day, each 1 hour, thematic and sector-aligned</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience</td><td>1–2 courses mandatory per MDO; AI &amp; Marketplace courses included</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led group discussions</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Domain &amp; sectoral capacity building sessions</td></tr></tbody></table></div></div></div><!-- TAB: Day 1 – Launch Day --><div class=\"cbc-schedule-content\" id=\"tab-day1\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Udghatan Samaroh – Launch Day</h3><p>📅 2nd April 2026 | New Delhi</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th>Session</th><th style=\"text-align:right;width:200px;\">Time</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1.</td><td><strong>Inaugural Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Guests of Honour / Chief Guest</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>10:00 AM – 11:30 AM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">2.</td><td><strong>Master Class: \'Capacity Building Imperative for an Entrepreneurial State\'</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri V. Anantha Nageswaran, Chief Economic Advisor, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>11:30 AM – 12:00 Noon</strong></td></tr><tr><td class=\"cbc-schedule-sn\">3.</td><td><strong>Thematic Session-I: National Workshop on Future Ready Training Institutions for Viksit Bharat</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>12:00 Noon – 1:30 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Lunch Break</strong></em></td></tr><tr><td class=\"cbc-schedule-sn\">4.</td><td><strong>Thematic Session-II: Karmayogi Quality Framework</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>2:30 PM – 3:30 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">5.</td><td><strong>Special Address</strong><br><span style=\"color:#f39200;font-size:12px;\">Shri T. V. Somanathan, Cabinet Secretary, Govt. of India</span></td><td style=\"color:#0063ae;text-align:right;\"><strong>3:30 PM – 4:00 PM</strong></td></tr><tr><td class=\"cbc-schedule-sn\">6.</td><td><strong>Closing Reflection and Vote of Thanks</strong></td><td style=\"color:#0063ae;text-align:right;\"><strong>4:00 PM – 4:15 PM</strong></td></tr><tr style=\"background-color:#fff9f2;\"><td style=\"color:#f39200;font-size:13px;text-align:center;\" colspan=\"3\"><em><strong>Tea &amp; Networking</strong></em></td></tr></tbody></table></div></div></div><!-- TAB: Day 2–7 --><div class=\"cbc-schedule-content\" id=\"tab-day2-7\"><div class=\"cbc-schedule-table-card\" style=\"background-color:transparent;border-style:none;box-shadow:none;padding:20px;\"><div class=\"cbc-schedule-card-header\" style=\"background-color:white;border-radius:16px;border:1px solid #f0f0f0;margin-bottom:20px;\"><h3>Daily Webinar Sessions</h3><p>📅 3rd April – 8th April 2026 | Virtual / Hybrid</p></div><div class=\"cbc-webinar-grid\"><div class=\"cbc-webinar-card\"><h4>Morning Session – Webinar 1</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Theme-aligned webinar session led by domain experts covering Technology, Tradition, or Tangible Outcomes.</p></div><div class=\"cbc-webinar-card\"><h4>Afternoon/Evening Session – Webinar 2</h4><p><span class=\"cbc-duration-badge\">60 minutes</span></p><p class=\"cbc-webinar-desc\">Complementary session with sectoral deep-dives, case studies, and interactive discussions.</p></div></div><div class=\"cbc-date-pills\"><div class=\"cbc-date-pill\">🔵 3rd &amp; 4th April – Technology</div><div class=\"cbc-date-pill\" style=\"background-color:#fff3e0;color:#e67e22;\">🟠 5th &amp; 6th April – Tradition</div><div class=\"cbc-date-pill\" style=\"background-color:#e8f5e9;color:#2e7d32;\">🟢 7th &amp; 8th April – Tangible Outcomes</div></div><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:200px;\">Format</th><th>Session</th><th>Details</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td><strong>IGOT Modules</strong></td><td>Courses on IGOT – At learner\'s convenience; AI &amp; Marketplace focus</td><td>1–2 courses mandatory per MDO</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td><strong>Samuhik Charcha</strong></td><td>MDO/State-led Samuhik Charcha</td><td>Templatized format; 60–120 min; facilitated by CBC &amp; Karmayogi Bharat</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td><strong>Workshops / Onsite Courses</strong></td><td>MDO/CSTI/State-led workshops &amp; physical training</td><td>Sectoral / domain capacity building sessions</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td><strong>Thematic Days</strong></td><td>Technology (3–4 Apr), Traditions (5–6 Apr), Tangible Outcomes (7–8 Apr)</td><td>Samuhik Charchas, Karmayogi Talks, Webinars &amp; Panel Discussions</td></tr></tbody></table></div></div></div></div><!-- TAB: Day 8 – Valedictory --><div class=\"cbc-schedule-content\" id=\"tab-day8\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Samapan Samaroh – Valedictory Day</h3><p>📅 8th April 2026</p></div><div class=\"cbc-schedule-table-wrapper\"><table class=\"table cbc-schedule-table\"><thead><tr><th style=\"width:60px;\">S.N.</th><th style=\"width:140px;\">Duration</th><th>Session</th><th>Tentative Activities</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>120 minutes</td><td><strong>Felicitation Session</strong></td><td>Summary of the Week (Data) · Felicitation of Karmayogi Leaderboard Achievers · Address by Chief Guest (~20 min)</td></tr></tbody></table></div></div></div><!-- TAB: Courses in Focus --><div class=\"cbc-schedule-content\" id=\"tab-courses\"><div class=\"cbc-schedule-table-card\"><div class=\"cbc-schedule-card-header\"><h3>Curated Learning Pathways on iGOT Karmayogi</h3><p>AI Courses &amp; iGOT Marketplace Courses — available throughout the week</p></div><div style=\"padding:16px 16px 0;\"><div class=\"cbc-course-tabs\"><button class=\"cbc-course-tab active\" data-course=\"ai\">AI Courses</button> <button class=\"cbc-course-tab\" data-course=\"marketplace\">iGOT Marketplace Courses</button></div></div><!-- AI Courses --><div class=\"cbc-schedule-table-wrapper\" id=\"course-ai-table\"><table class=\"table cbc-schedule-table\"><thead><tr style=\"background-color:#f39200 !important;\"><th style=\"width:60px;\">S.N.</th><th>Course Name</th><th>Provider</th><th style=\"text-align:right;width:110px;\">Duration</th></tr></thead><tbody><tr><td class=\"cbc-schedule-sn\">1</td><td>Artificial Intelligence for Public Governance</td><td>Wadhwani AI &amp; Data Security Council of India</td><td style=\"text-align:right;\">3h 10m</td></tr><tr><td class=\"cbc-schedule-sn\">2</td><td>Large Language Models: Concepts and Applications</td><td>IIT Hyderabad</td><td style=\"text-align:right;\">1h 45m</td></tr><tr><td class=\"cbc-schedule-sn\">3</td><td>Deep Tech and India</td><td>ORF</td><td style=\"text-align:right;\">55m</td></tr><tr><td class=\"cbc-schedule-sn\">4</td><td>AI in Government: Transforming Public Service Delivery</td><td>IISc Bengaluru</td><td style=\"text-align:right;\">2h 20m</td></tr><tr><td class=\"cbc-schedule-sn\">5</td><td>Artificial Intelligence for Smarter Governance</td><td>Karmayogi Bharat – NeGD</td><td style=\"text-align:right;\">1h 30m</td></tr><tr><td class=\"cbc-schedule-sn\">6</td><td>IndiaAI for All</td><td>India AI Mission</td><td style=\"text-align:right;\">2h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">7</td><td>Fundamentals of Generative Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">50m</td></tr><tr><td class=\"cbc-schedule-sn\">8</td><td>Introduction to Artificial Intelligence</td><td>IIT Madras</td><td style=\"text-align:right;\">45m</td></tr><tr><td class=\"cbc-schedule-sn\">9</td><td>AI Applications in Government</td><td>NIC</td><td style=\"text-align:right;\">1h 50m</td></tr><tr><td class=\"cbc-schedule-sn\">10</td><td>आर्टिफिशियल इंटेलिजेंस की मूल बातें: अवसर, अनुप्रयोग और नैतिकता</td><td>Microsoft</td><td style=\"text-align:right;\">1h 35m</td></tr><tr><td class=\"cbc-schedule-sn\">11</td><td>प्रशासन के लिए एआई: कार्यों का स्व-चालन</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">40m</td></tr><tr><td class=\"cbc-schedule-sn\">12</td><td>सुशासन के सन्दर्भ में एआई</td><td>Wadhwani Foundation</td><td style=\"text-align:right;\">1h 15m</td></tr><tr><td class=\"cbc-schedule-sn\">13</td><td>Artificial Intelligence in Finance</td><td>SUDI</td><td style=\"text-align:right;\">1h 40m</td></tr><tr><td class=\"cbc-schedule-sn\"