INSERT INTO `node_revision__field_body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_body_value`, `field_body_summary`, `field_body_format`) VALUES
('news', 0, 17, 32, 'en', 0, '<p>National Programme for Civil Services Capacity Building(NPCSCB) - Mission Karmayogi aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonisation for effective and efficient public service delivery.</p>', '', 'full_html'),
('news', 0, 17, 33, 'en', 0, '<p>National Programme for Civil Services Capacity Building(NPCSCB) - Mission Karmayogi aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonisation for effective and efficient public service delivery.</p>', '', 'full_html'),
('news', 0, 17, 38, 'en', 0, '<p>National Programme for Civil Services Capacity Building(NPCSCB) - Mission Karmayogi aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonisation for effective and efficient public service delivery.</p>', '', 'full_html'),
('news', 0, 17, 112, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/cbc/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\">', '', 'full_html'),
('news', 0, 17, 249, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\">', '', 'full_html'),
('news', 0, 17, 575, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\"><p>&nbsp;function addMapIslands(container) { if (!container) return; // Find the map image to ensure we overlay correctly const img = container.querySelector(\'img\'); if (!img) return; // Use the image\'s parent for positioning to ensure dots stay with the map const parent = img.parentElement; // Check if islands already added if (parent.querySelector(\'.map-islands-container\')) return; if (window.getComputedStyle(parent).position === \'static\') { parent.style.position = \'relative\'; } const islandContainer = document.createElement(\'div\'); islandContainer.className = \'map-islands-container\'; islandContainer.style.position = \'absolute\'; islandContainer.style.top = \'0\'; islandContainer.style.left = \'0\'; islandContainer.style.width = \'100%\'; islandContainer.style.height = \'100%\'; islandContainer.style.pointerEvents = \'none\'; islandContainer.style.zIndex = \'1\'; // Coordinate percentages (Approximate for standard India map) // Lakshadweep (Bottom Left) // Adjusted for standard map aspect ratio const lakshadweepDots = [ { top: 82, left: 18, size: 3 }, { top: 84, left: 19, size: 2.5 }, { top: 83, left: 17, size: 3 }, { top: 85, left: 18, size: 2 }, { top: 86, left: 17, size: 2 }, { top: 81, left: 18, size: 2 }, { top: 79, left: 17, size: 1.5 }, ]; // Andaman &amp; Nicobar (Bottom Right) const andamanDots = [ // Andaman Group { top: 65, left: 88, size: 3 }, { top: 66, left: 88, size: 3 }, { top: 67, left: 88, size: 3.5 }, // North/Middle { top: 69, left: 88, size: 3 }, { top: 70, left: 88, size: 3 }, { top: 72, left: 88, size: 3.5 }, // Little Andaman // Nicobar Group { top: 76, left: 89, size: 3 }, // Car Nicobar { top: 78, left: 90, size: 2.5 }, { top: 79, left: 90, size: 3 }, { top: 81, left: 90, size: 4 }, // Great Nicobar ]; const mapColor = \'#9ecae1\'; // Standard map light blue, adjust if needed const createDot = (dot) =&gt; { const el = document.createElement(\'div\'); el.style.position = \'absolute\'; el.style.top = dot.top + \'%\'; el.style.left = dot.left + \'%\'; el.style.width = dot.size + \'px\'; el.style.height = dot.size + \'px\'; el.style.backgroundColor = mapColor; // Match map color el.style.borderRadius = \'50%\'; el.style.opacity = \'0.9\'; return el; }; lakshadweepDots.forEach(dot =&gt; islandContainer.appendChild(createDot(dot))); andamanDots.forEach(dot =&gt; islandContainer.appendChild(createDot(dot))); parent.appendChild(islandContainer); }</p>', '', 'full_html'),
('news', 0, 17, 576, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\"><p>&nbsp;</p>', '', 'full_html'),
('news', 0, 17, 577, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\"><p>&nbsp;</p><style>\r\n  .map-islands-container {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    pointer-events: none;\r\n    z-index: 1;\r\n  }\r\n\r\n  .map-dot {\r\n    position: absolute;\r\n    background-color: #9ecae1;\r\n    border-radius: 50%;\r\n    opacity: 0.9;\r\n    box-shadow: 0 0 4px rgba(158, 202, 225, 0.8);\r\n    animation: islandPulse 2s infinite ease-in-out;\r\n  }\r\n\r\n  @keyframes islandPulse {\r\n    0% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n    50% {\r\n      transform: scale(1.5);\r\n      opacity: 1;\r\n      box-shadow: 0 0 8px rgba(158, 202, 225, 1);\r\n    }\r\n    100% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n  }\r\n</style><script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n  const checkContainer = setInterval(function() {\r\n    // Target the specific In Focus map container\r\n    // You might need to adjust this selector based on your specific View structure\r\n    const container = document.querySelector(\'.infocus-container\');\r\n    \r\n    if (container) {\r\n      clearInterval(checkContainer);\r\n      addMapIslands(container);\r\n    }\r\n  }, 500);\r\n\r\n  function addMapIslands(container) {\r\n    if (!container) return;\r\n\r\n    // Find the map image to ensure we overlay correctly\r\n    const img = container.querySelector(\'img\');\r\n    if (!img) return;\r\n\r\n    // Use the image\'s parent for positioning to ensure dots stay with the map\r\n    const parent = img.parentElement;\r\n    \r\n    // Check if islands already added\r\n    if (parent.querySelector(\'.map-islands-container\')) return;\r\n\r\n    if (window.getComputedStyle(parent).position === \'static\') {\r\n      parent.style.position = \'relative\';\r\n    }\r\n\r\n    const islandContainer = document.createElement(\'div\');\r\n    islandContainer.className = \'map-islands-container\';\r\n\r\n    // Coordinate percentages (Approximate for standard India map)\r\n    const lakshadweepDots = [\r\n      { top: 82, left: 18, size: 3, delay: \'0s\' },\r\n      { top: 84, left: 19, size: 2.5, delay: \'0.2s\' },\r\n      { top: 83, left: 17, size: 3, delay: \'0.4s\' },\r\n      { top: 85, left: 18, size: 2, delay: \'0.1s\' },\r\n      { top: 86, left: 17, size: 2, delay: \'0.3s\' },\r\n      { top: 81, left: 18, size: 2, delay: \'0.5s\' },\r\n      { top: 79, left: 17, size: 1.5, delay: \'0.2s\' },\r\n    ];\r\n\r\n    const andamanDots = [\r\n      { top: 65, left: 88, size: 3, delay: \'0s\' },\r\n      { top: 66, left: 88, size: 3, delay: \'0.3s\' },\r\n      { top: 67, left: 88, size: 3.5, delay: \'0.1s\' },\r\n      { top: 69, left: 88, size: 3, delay: \'0.4s\' },\r\n      { top: 70, left: 88, size: 3, delay: \'0.2s\' },\r\n      { top: 72, left: 88, size: 3.5, delay: \'0.5s\' },\r\n      { top: 76, left: 89, size: 3, delay: \'0.1s\' },\r\n      { top: 78, left: 90, size: 2.5, delay: \'0.3s\' },\r\n      { top: 79, left: 90, size: 3, delay: \'0.2s\' },\r\n      { top: 81, left: 90, size: 4, delay: \'0.4s\' },\r\n    ];\r\n\r\n    const createDot = (dot) => {\r\n      const el = document.createElement(\'div\');\r\n      el.className = \'map-dot\';\r\n      el.style.top = dot.top + \'%\';\r\n      el.style.left = dot.left + \'%\';\r\n      el.style.width = dot.size + \'px\';\r\n      el.style.height = dot.size + \'px\';\r\n      el.style.animationDelay = dot.delay;\r\n      return el;\r\n    };\r\n\r\n    lakshadweepDots.forEach(dot => islandContainer.appendChild(createDot(dot)));\r\n    andamanDots.forEach(dot => islandContainer.appendChild(createDot(dot)));\r\n\r\n    parent.appendChild(islandContainer);\r\n  }\r\n});\r\n</script>', '', 'full_html'),
('news', 0, 17, 578, 'en', 0, '<img class=\"india-map-image map-fade-blink\" src=\"/sites/default/files/inline-images/indian_map_infocus.png\" alt=\"India Map showing States and Union Territories\" width=\"100%\" height=\"100%\" id=\"infocus-india-map\"><p>&nbsp;</p><style>\r\n  .map-islands-container {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    pointer-events: none;\r\n    z-index: 1;\r\n  }\r\n\r\n  .map-dot {\r\n    position: absolute;\r\n    background-color: #ff9933; /* Theme Orange */\r\n    border-radius: 50%;\r\n    opacity: 0.9;\r\n    box-shadow: 0 0 4px rgba(255, 153, 51, 0.8);\r\n    animation: islandPulse 2s infinite ease-in-out;\r\n  }\r\n\r\n  @keyframes islandPulse {\r\n    0% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n    50% {\r\n      transform: scale(1.5);\r\n      opacity: 1;\r\n      box-shadow: 0 0 8px rgba(255, 153, 51, 1);\r\n    }\r\n    100% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n  }\r\n</style><script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n  const checkContainer = setInterval(function() {\r\n    // Target the specific In Focus map container\r\n    const container = document.querySelector(\'.infocus-container\');\r\n    \r\n    if (container) {\r\n      clearInterval(checkContainer);\r\n      addMapIslands(container);\r\n    }\r\n  }, 500);\r\n\r\n  function addMapIslands(container) {\r\n    if (!container) return;\r\n\r\n    // Find the map image to ensure we overlay correctly\r\n    const img = container.querySelector(\'img\');\r\n    if (!img) return;\r\n\r\n    // Use the image\'s parent for positioning\r\n    const parent = img.parentElement;\r\n    \r\n    // Check if islands already added\r\n    if (parent.querySelector(\'.map-islands-container\')) return;\r\n\r\n    if (window.getComputedStyle(parent).position === \'static\') {\r\n      parent.style.position = \'relative\';\r\n    }\r\n\r\n    const islandContainer = document.createElement(\'div\');\r\n    islandContainer.className = \'map-islands-container\';\r\n\r\n    // Coordinate percentages (Approximate for standard India map)\r\n    const stateDots = [\r\n      // North\r\n      { top: 18, left: 32, size: 3, delay: \'0s\' },    // J&K\r\n      { top: 15, left: 40, size: 3, delay: \'0.2s\' },  // Ladakh\r\n      { top: 24, left: 35, size: 3, delay: \'0.1s\' },  // Himachal\r\n      { top: 26, left: 29, size: 3, delay: \'0.3s\' },  // Punjab\r\n      { top: 27, left: 40, size: 3, delay: \'0.2s\' },  // Uttarakhand\r\n      { top: 31, left: 33, size: 2.5, delay: \'0.4s\' },// Haryana\r\n      { top: 33, left: 36, size: 2.5, delay: \'0.1s\' },// Delhi\r\n      \r\n      // West\r\n      { top: 40, left: 25, size: 4, delay: \'0s\' },    // Rajasthan\r\n      { top: 50, left: 15, size: 4, delay: \'0.3s\' },  // Gujarat\r\n      { top: 62, left: 28, size: 4, delay: \'0.1s\' },  // Maharashtra\r\n      { top: 75, left: 25, size: 2, delay: \'0.2s\' },  // Goa\r\n\r\n      // Central\r\n      { top: 50, left: 42, size: 4, delay: \'0.4s\' },  // MP\r\n      { top: 38, left: 50, size: 4, delay: \'0.2s\' },  // UP\r\n      { top: 52, left: 55, size: 3.5, delay: \'0.1s\' },// Chhattisgarh\r\n\r\n      // East\r\n      { top: 40, left: 65, size: 3.5, delay: \'0.3s\' },// Bihar\r\n      { top: 48, left: 62, size: 3.5, delay: \'0s\' },  // Jharkhand\r\n      { top: 48, left: 70, size: 3.5, delay: \'0.2s\' },// West Bengal\r\n      { top: 58, left: 65, size: 3.5, delay: \'0.1s\' },// Odisha\r\n      { top: 32, left: 72, size: 2, delay: \'0.4s\' },  // Sikkim\r\n\r\n      // North East\r\n      { top: 38, left: 85, size: 3, delay: \'0.2s\' },  // Assam\r\n      { top: 30, left: 90, size: 3, delay: \'0.1s\' },  // Arunachal\r\n      { top: 36, left: 94, size: 3, delay: \'0.3s\' },  // Nagaland\r\n      { top: 42, left: 93, size: 3, delay: \'0s\' },    // Manipur\r\n      { top: 48, left: 91, size: 3, delay: \'0.4s\' },  // Mizoram\r\n      { top: 48, left: 86, size: 3, delay: \'0.2s\' },  // Tripura\r\n      { top: 40, left: 85, size: 3, delay: \'0.1s\' },  // Meghalaya\r\n\r\n      // South\r\n      { top: 78, left: 32, size: 4, delay: \'0.3s\' },  // Karnataka\r\n      { top: 65, left: 45, size: 3.5, delay: \'0s\' },  // Telangana\r\n      { top: 75, left: 48, size: 4, delay: \'0.2s\' },  // Andhra\r\n      { top: 88, left: 35, size: 3, delay: \'0.1s\' },  // Kerala\r\n      { top: 85, left: 42, size: 3.5, delay: \'0.4s\' },// Tamil Nadu\r\n\r\n      // Islands\r\n      { top: 82, left: 18, size: 3, delay: \'0s\' },    // Lakshadweep\r\n      { top: 65, left: 88, size: 3, delay: \'0s\' },    // Andaman\r\n      // ... (more island dots included in full code)\r\n    ];\r\n\r\n    const createDot = (dot) => {\r\n      const el = document.createElement(\'div\');\r\n      el.className = \'map-dot\';\r\n      el.style.top = dot.top + \'%\';\r\n      el.style.left = dot.left + \'%\';\r\n      el.style.width = dot.size + \'px\';\r\n      el.style.height = dot.size + \'px\';\r\n      el.style.animationDelay = dot.delay;\r\n      return el;\r\n    };\r\n\r\n    stateDots.forEach(dot => islandContainer.appendChild(createDot(dot)));\r\n    parent.appendChild(islandContainer);\r\n  }\r\n});\r\n</script>', '', 'full_html'),
