('news', 0, 17, 830, 'en', 0, '<!-- Copy this ENTIRE block into your Drupal View/Block --><style>\r\n  /* SVG Wrapper */\r\n  .map-wrapper {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    /* Height constraint to prevent clipping */\r\n    height: 190px;\r\n    width: 100%;\r\n    position: relative;\r\n    overflow: visible !important;\r\n    margin-bottom: 15px;\r\n    margin-top: 10px;\r\n  }\r\n  /* Force Map Colors - Darkish Theme Blue */\r\n  .map-wrapper svg path {\r\n    fill: #1a3c5e !important;\r\n    stroke: #ffffff;\r\n    stroke-width: 0.5px;\r\n    transition: fill 0.3s ease;\r\n  }\r\n  .map-wrapper svg path:hover {\r\n    fill: #2daae1 !important;\r\n  }\r\n  /* SVG Constraints */\r\n  .map-wrapper svg {\r\n    height: 100% !important;\r\n    width: auto !important;\r\n    max-width: 85%;\r\n    overflow: visible !important;\r\n    display: block;\r\n  }\r\n  /* SVG Dot Styles */\r\n  .map-dot-svg {\r\n    fill: #ff9933;\r\n    /* Theme Orange */\r\n    cursor: pointer;\r\n    /* Center transform origin on the dot itself for pulse */\r\n    transform-box: fill-box;\r\n    transform-origin: center;\r\n    opacity: 0.9;\r\n    animation: svgPulse 2s infinite ease-in-out;\r\n  }\r\n  @keyframes svgPulse {\r\n    0% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n    50% {\r\n      transform: scale(1.4);\r\n      opacity: 1;\r\n    }\r\n    100% {\r\n      transform: scale(1);\r\n      opacity: 0.9;\r\n    }\r\n  }\r\n</style><!-- IMAGE TAG --><img class=\"india-map-image map-fade-blink\" style=\"display:block;\" src=\"/sites/default/files/inline-images/indian_map_infocus.svg\" alt=\"India Map showing States and Union Territories\" width=\"80%\" height=\"80%\" id=\"infocus-india-map\"><script>\r\n  document.addEventListener(\'DOMContentLoaded\', function () {\r\n    console.log(\"CBC Map Script Loaded - Dots Enabled (Single Unique) v15\");\r\n    const checkContainer = setInterval(function () {\r\n      let img = document.getElementById(\'infocus-india-map\');\r\n      if (img && img.complete) {\r\n        clearInterval(checkContainer);\r\n        initDynamicMap(img);\r\n      }\r\n    }, 500);\r\n    function initDynamicMap(img) {\r\n      const svgUrl = img.getAttribute(\'src\');\r\n      if (!svgUrl) return;\r\n      fetch(svgUrl)\r\n        .then(response => {\r\n          if (!response.ok) throw new Error(\'Network response was not ok\');\r\n          return response.text();\r\n        })\r\n        .then(svgText => {\r\n          if (!svgText.trim().startsWith(\'<svg\') && !svgText.includes(\'<svg\')) {\r\n            console.warn(\'Fetched image is not an SVG\');\r\n            return;\r\n          }\r\n          const wrapper = document.createElement(\'div\');\r\n          wrapper.className = \'map-wrapper \' + (img.className || \'\');\r\n          wrapper.innerHTML = svgText;\r\n          const svg = wrapper.querySelector(\'svg\');\r\n          if (svg) {\r\n            if (!svg.hasAttribute(\'viewBox\')) {\r\n              const w = svg.getAttribute(\'width\') || 611;\r\n              const h = svg.getAttribute(\'height\') || 695;\r\n              svg.setAttribute(\'viewBox\', `0 0 ${parseFloat(w)} ${parseFloat(h)}`);\r\n            }\r\n            svg.style.width = \'auto\';\r\n            svg.style.height = \'100%\';\r\n            svg.style.display = \'block\';\r\n            svg.style.overflow = \'visible\';\r\n            img.parentNode.insertBefore(wrapper, img);\r\n            img.style.display = \'none\';\r\n            requestAnimationFrame(() => addDotsNative(svg));\r\n          }\r\n        })\r\n        .catch(error => console.error(\'Error loading map SVG:\', error));\r\n    }\r\n    function addDotsNative(svg) {\r\n      // User Provided List\r\n      const allowedStates = [\r\n        \"andaman and nicobar\",\r\n        \"andhra pradesh\",\r\n        \"arunachal pradesh\",\r\n        \"assam\",\r\n        \"bihar\",\r\n        \"chandigarh\",\r\n        \"chhattisgarh\", \"chattisgarh\",\r\n        \"delhi\",\r\n        \"goa\",\r\n        \"gujarat\",\r\n        \"haryana\",\r\n        \"jammu and kashmir\",\r\n        \"jharkhand\",\r\n        \"karnataka\",\r\n        \"ladakh\",\r\n        \"madhya pradesh\",\r\n        \"maharashtra\",\r\n        \"manipur\",\r\n        \"meghalaya\",\r\n        \"mizoram\",\r\n        \"nagaland\",\r\n        \"odisha\",\r\n        \"puducherry\",\r\n        \"punjab\",\r\n        \"rajasthan\",\r\n        \"tripura\",\r\n        \"uttar pradesh\",\r\n        \"uttarakhand\"\r\n      ];\r\n      const normalizeName = (name) => {\r\n        if (!name) return \'\';\r\n        return name.toLowerCase()\r\n          .replace(\'&\', \'and\')\r\n          .replace(\'islands\', \'\')\r\n          .replace(\'island\', \'\')\r\n          .trim();\r\n      };\r\n      const stateLargestPath = new Map();\r\n      const paths = svg.querySelectorAll(\'path\');\r\n      // 1. DEDUPLICATION: Find ONLY the largest path for each state\r\n      paths.forEach(path => {\r\n        if (path.closest(\'defs\')) return;\r\n        const id = path.id || \'\';\r\n        const rawTitle = path.getAttribute(\'title\') || \'\';\r\n        const normalizedTitle = normalizeName(rawTitle);\r\n        if (id.startsWith(\'IN-\')) {\r\n          const matchedState = allowedStates.find(state => normalizedTitle.includes(state));\r\n          if (matchedState) {\r\n            try {\r\n              const bbox = path.getBBox();\r\n              const area = bbox.width * bbox.height;\r\n              if (bbox.width <= 0 || bbox.height <= 0) return;\r\n              if (!stateLargestPath.has(matchedState) || area > stateLargestPath.get(matchedState).area) {\r\n                stateLargestPath.set(matchedState, {\r\n                  path: path,\r\n                  bbox: bbox,\r\n                  title: rawTitle\r\n                });\r\n              }\r\n            } catch (e) { }\r\n          }\r\n        }\r\n      });\r\n      // 2. RENDER: Add One Circle per State\r\n      stateLargestPath.forEach((data, stateName) => {\r\n        try {\r\n          const path = data.path;\r\n          const bbox = data.bbox;\r\n          const cx = bbox.x + bbox.width / 2;\r\n          const cy = bbox.y + bbox.height / 2;\r\n          const circle = document.createElementNS(\"http://www.w3.org/2000/svg\", \"circle\");\r\n          circle.setAttribute(\"cx\", cx);\r\n          circle.setAttribute(\"cy\", cy);\r\n          // Radius 4 for clean, visible dot\r\n          circle.setAttribute(\"r\", \"4\");\r\n          circle.setAttribute(\"class\", \"map-dot-svg\");\r\n          if (data.title) {\r\n            const titleEl = document.createElementNS(\"http://www.w3.org/2000/svg\", \"title\");\r\n            titleEl.textContent = data.title;\r\n            circle.appendChild(titleEl);\r\n          }\r\n          // Staggered animation\r\n          const safeH = svg.viewBox.baseVal.height || 700;\r\n          const normalizedY = cy / safeH;\r\n          const delay = (normalizedY * 1.5).toFixed(2) + \'s\';\r\n          circle.style.animationDelay = delay;\r\n          // Inject into path\'s parent to inherit transforms\r\n          path.parentNode.appendChild(circle);\r\n        } catch (e) {\r\n          console.error(\"Error creating SVG dot for \" + stateName, e);\r\n        }\r\n      });\r\n    }\r\n  });\r\n</script>', '', 'full_html'),
