INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 64, 1697, 'en', 0, '<!-- Vision Section --><!-- ========================================\r\n     NATIONAL TRAINING CONCLAVE 2023 PAGE\r\n     Refactored to use external CSS classes\r\n     ======================================== --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3 text-primary\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">The National Training Conclave (NTC) 2023, inaugurated by the Hon\'ble Prime Minister on <strong class=\"karmayogi-highlight\">11th June 2023</strong>, was envisioned by the Capacity Building Commission (CBC) as a landmark initiative to strengthen India\'s civil service training ecosystem. It aimed to bring together over <strong class=\"karmayogi-highlight\">1000+ Central and State Civil Service Training Institutions (CSTIs)</strong>, senior government officials, academicians, and knowledge partners onto a common platform for collaboration, knowledge exchange, and institutional strengthening.</p><p class=\"karmayogi-quote-text mt-3\">The core vision of the NTC was to create a <strong class=\"karmayogi-highlight\">future-ready civil service</strong> capable of driving India\'s transformation toward <strong class=\"karmayogi-highlight\">Viksit Bharat @2047</strong>. The Conclave emphasized the need to move from fragmented training approaches to a <strong class=\"karmayogi-highlight\">\"whole-of-government\"</strong> and <strong class=\"karmayogi-highlight\">\"whole-of-system\"</strong> learning ecosystem, where capacity building becomes continuous, competency-driven, and technology-enabled.</p><p class=\"karmayogi-quote-text mt-3\">Through its <strong class=\"karmayogi-highlight\">8 thematic breakout sessions</strong>, NTC focused on strengthening the foundations of training institutions in key areas—training needs assessment, knowledge sharing, impact evaluation, strategic resource planning, faculty development, phygital transformation, governance challenges, and competency-based capacity building. The discussions were designed to help CSTIs identify institution-level and policy-level interventions to enhance training quality and impact.</p><p class=\"karmayogi-quote-text mt-3\">Another major vision element was to standardize quality and institutional excellence across CSTIs through the <strong class=\"karmayogi-highlight\">National Standards for Civil Service Training Institutions (NSCSTI)</strong>, which were launched and awarded during the conclave. This framework aims to make India\'s training institutions globally benchmarked and capable of nurturing ethical, competent, and citizen-centric civil servants.</p><p class=\"karmayogi-quote-text mt-3\">NTC also sought to foster innovation and collaboration through technology lounges, including the <strong class=\"karmayogi-highlight\">iGOT Karmayogi Lounge</strong> and <strong class=\"karmayogi-highlight\">Emerging Tech Lounge</strong>, showcasing digital tools and immersive learning technologies.</p><p class=\"karmayogi-quote-text mt-3\">In essence, the National Training Conclave envisioned a transformed, interconnected, and adaptive training ecosystem—one that continuously upgrades the skills, mindset, and leadership of public servants, institutionalizes best practices, and ensures that training translates into tangible governance outcomes for citizens.</p></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 text-dark-blue\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue\"><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Facilitate collaboration and networking among CSTIs to share best practices and innovations.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Introduce and operationalize the National Standards for Civil Service Training Institutions (NSCSTI) for quality benchmarking.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Identify actionable strategies from the 8 breakout sessions to improve institutional and training performance.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Strengthen awareness and adoption of digital tools, especially the iGOT Karmayogi platform, for phygital learning.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Institutionalize the National Training Conclave as a recurring platform for knowledge exchange and reform.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Create a world-class training ecosystem aligned with the Mission Karmayogi vision of a future-ready civil service.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Promote competency-based, technology-driven, and citizen-centric training models across all government institutions.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Achieve nationwide NSCSTI accreditation and build CSTIs\' capacity on the eight pillars of excellence.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Drive continuous learning, collaboration, and behavioural transformation across government systems.</li></ul></div></div></div></div></section><!-- Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 text-primary\"></i>Concept Note</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill text-primary\"></i></p><h3>Concept Overview</h3></div><p class=\"karmayogi-feature-desc\">The National Training Conclave (NTC) 2023, organized by the Capacity Building Commission (CBC) under Mission Karmayogi, was conceptualized as a nationwide platform to strengthen collaboration among Central and State Training Institutions (CSTIs) and align capacity-building efforts with the vision of <strong class=\"karmayogi-highlight\">Viksit Bharat @2047</strong>. The Conclave aimed to transform the training ecosystem by fostering synergy, innovation, and standardization across institutions.</p><p class=\"karmayogi-feature-desc mt-3\">It brought together more than <strong class=\"karmayogi-highlight\">1000 training institutions</strong> and senior government officials to deliberate on improving training quality through competency-based design, technology integration, impact assessment, and governance reforms. A major focus was the launch and adoption of the <strong class=\"karmayogi-highlight\">National Standards for Civil Service Training Institutions (NSCSTI)</strong>—a framework to benchmark quality and institutional excellence across CSTIs.</p><p class=\"karmayogi-feature-desc mt-3\">The Conclave\'s eight thematic breakout sessions provided actionable pathways for reform, emphasizing digital transformation through iGOT Karmayogi, data-driven governance, and institutional collaboration.</p><p class=\"karmayogi-feature-desc mt-3\">In essence, the NTC was envisioned as a catalyst for professionalizing public service training, institutionalizing continuous learning, and building a future-ready, citizen-centric civil service through shared learning, technology, and capacity enhancement.</p></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3 text-primary\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"daksh-timeline\"><!-- Timeline Items --><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-blue\">&nbsp;</div><div class=\"daksh-timeline-date text-primary\"><strong>Pre-event</strong></div><div class=\"daksh-timeline-content\">Conceptualized by CBC; engagement with 1000+ CSTIs nationwide.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-green\">&nbsp;</div><div class=\"daksh-timeline-date text-success\"><strong>11 June 2023</strong></div><div class=\"daksh-timeline-content\">Launch by Hon\'ble Prime Minister; unveiling of NSCSTI Dashboard and accreditation to NADT, SVPNPA, and NICF.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-orange\">&nbsp;</div><div class=\"daksh-timeline-date text-orange\"><strong>Opening Session</strong></div><div class=\"daksh-timeline-content\">Address by Hon\'ble MoS Dr. Jitendra Singh; launch of NSCSTI Copyright Certificate; vision presented by CBC Chairperson.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-danger\">&nbsp;</div><div class=\"daksh-timeline-date text-danger\"><strong>Eight Breakout Sessions</strong></div><div class=\"daksh-timeline-content\">Discussions on training needs, knowledge sharing, impact assessment, resource planning, faculty capacity, phygital transformation, governance, and competencies.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-gray\">&nbsp;</div><div class=\"daksh-timeline-date text-muted\"><strong>Lounges</strong></div><div class=\"daksh-timeline-content\">NSCSTI, iGOT, Emerging Technologies, and Interview lounges established for engagement and demonstrations.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-blue\">&nbsp;</div><div class=\"daksh-timeline-date text-primary\"><strong>Closing Ceremony</strong></div><div class=\"daksh-timeline-content\">Addresses by Dr. P.K. Mishra and MoS Dr. Jitendra Singh; recommendations consolidated.</div></div><div class=\"daksh-timeline-item\"><div class=\"daksh-timeline-dot dot-green\">&nbsp;</div><div class=\"daksh-timeline-date text-success\"><strong>Post-event Strategy</strong></div><div class=\"daksh-timeline-content\">CBC to institutionalize NTC, implement panel recommendations, and expand NSCSTI accreditation.</div></div></div></div></div></div></div></div></section><!-- Key Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-flag-fill me-3 text-primary\"></i>Key Milestones</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-rocket-takeoff-fill text-primary\"></i></p><h3>Inauguration by Hon\'ble Prime Minister (11th June 2023)</h3></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Launch of the <strong class=\"karmayogi-highlight\">National Standards for Civil Service Training Institutions (NSCSTI)</strong> framework.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Unveiling of the <strong class=\"karmayogi-highlight\">PM Dashboard on NSCSTI</strong>.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Distribution of NSCSTI Accreditation Certificates to three Central Training Institutions — <strong class=\"karmayogi-highlight\">NADT, SVPNPA, and NICF</strong>.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> PM\'s address highlighting the vision of Future-Ready Civil Servants and <strong class=\"karmayogi-highlight\">Viksit Bharat @2047</strong>.</li></ul></div></div><div class=\"karmayogi-feature-block bg-alice-blue border-left-green mt-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-person-badge-fill text-success\"></i></p><h4>Opening Session (Led by Hon\'ble MoS Dr. Jitendra Singh)</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list karmayogi-list-green\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> Distribution of NSCSTI Accreditation Certificates to <strong class=\"text-success\">seven additional CSTIs</strong>.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> Presentation of CBC\'s vision for CSTIs by Chairperson, CBC.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> Launch of <strong class=\"text-success\">Copyright Certificate for NSCSTI</strong>.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> Presentations by CBC Members and CEO, Karmayogi Bharat, on Faculty Development, iGOT platform, and NSCSTI framework.</li></ul></div></div><div class=\"karmayogi-feature-block bg-alice-blue border-left-orange mt-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-chat-square-dots-fill text-orange\"></i></p><h4>Breakout Sessions (8 Thematic Panel Discussions)</h4></div><div class=\"karmayogi-feature-desc\"><p class=\"text-dark-blue mb-3\"><strong>Deliberations on key capacity-building themes:</strong></p><div class=\"row g-3\"><div class=\"col-md-6\"><ul class=\"karmayogi-list karmayogi-list-orange\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-1-circle-fill karmayogi-list-icon icon-orange\"></i> Training Needs &amp; Course Design</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-2-circle-fill karmayogi-list-icon icon-orange\"></i> Knowledge Sharing</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-3-circle-fill karmayogi-list-icon icon-orange\"></i> Training Impact Assessment</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-4-circle-fill karmayogi-list-icon icon-orange\"></i> Strategic Resource Planning</li></ul></div><div class=\"col-md-6\"><ul class=\"karmayogi-list karmayogi-list-orange\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-5-circle-fill karmayogi-list-icon icon-orange\"></i> Faculty Capacity Enhancement</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-6-circle-fill karmayogi-list-icon icon-orange\"></i> Phygital Transformation</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-7-circle-fill karmayogi-list-icon icon-orange\"></i> Overcoming Governance Challenges</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-8-circle-fill karmayogi-list-icon icon-orange\"></i> Competencies for Civil Service Officials</li></ul></div></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-danger\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building text-danger\"></i></p><h4>Lounge Installations</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list karmayogi-list-danger\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-danger\"></i> <strong class=\"text-danger\">NSCSTI Lounge</strong> – for accreditation guidance and process handholding.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-danger\"></i> <strong class=\"text-danger\">iGOT Lounge</strong> – for platform familiarization and digital course creation.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-danger\"></i> <strong class=\"text-danger\">Emerging Technology Lounge</strong> – showcasing AR/VR and AI-based learning tools.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-danger\"></i> <strong class=\"text-danger\">Interview Lounge</strong> – capturing stakeholder insights and experiences.</li></ul></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-gray\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clipboard-check-fill text-muted\"></i></p><h4>Closing Ceremony</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list karmayogi-list-gray\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-gray\"></i> Presentation of key recommendations from breakout sessions before Hon\'ble MoS and Principal Secretary to PM.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-gray\"></i> Address by <strong class=\"text-muted\">Dr. P.K. Mishra</strong> emphasizing holistic training and technological adaptability.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-gray\"></i> Closing remarks by <strong class=\"text-muted\">Dr. Jitendra Singh</strong> highlighting faculty development, behavioural training, and PPP models.</li></ul></div></div></div></div><div class=\"karmayogi-feature-block bg-light-blue border-left-blue mt-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-arrow-right-circle-fill text-primary\"></i></p><h4>Post-Conclave Strategy (Way Forward)</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Integration of panel recommendations into CBC\'s policy and institutional initiatives.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Expansion of NSCSTI accreditation and capacity-building programs.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> <strong class=\"karmayogi-highlight\">Institutionalisation of NTC</strong> as a recurring platform for collaboration, learning, and innovation in civil services training.</li></ul></div></div></div></div></section><!-- Impact Metrics Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3 text-success\"></i>Impact Metrics (Outcomes achieved, measurable indicators)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill text-primary\"></i></p><h3>Major Outcomes</h3></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> The Conclave brought together more than <strong class=\"karmayogi-highlight\">1,500–1,900 representatives</strong> from Civil Service Training Institutes (CSTIs), including central training institutes, state administrative training institutes, zonal/regional training institutes, and research institutes.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> <strong class=\"karmayogi-highlight\">Eight thematic panel discussions</strong> were organised covering key areas: training-needs identification, linking training to course design, faculty development, training-impact assessment, content digitisation, strategic resource planning, capacity enhancement, and evolving in a \"phygital\" (physical + digital) world of capacity building.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> A strong emphasis on breaking down vertical and horizontal silos, encouraging a <strong class=\"karmayogi-highlight\">\"whole of government\"</strong> mindset among civil servants, and promoting citizen-participation (\"Jan Bhagidari\").</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Recognition that training should no longer be seen as a \"punishment posting\" but as a key component of career development and governance effectiveness.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> The importance of digital platforms such as the <strong class=\"karmayogi-highlight\">iGOT Karmayogi platform</strong> – which had already crossed a registration of <strong class=\"text-success\">10 lakh (1 million) users</strong> – was highlighted as enabling \"anytime, anywhere, any device\" learning for government personnel.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Recommendations from the Conclave are compiled in a report which outlines actionable strategies for CSTIs, including improved training-needs assessment, linking course-design to competencies, and moving toward shared resources and standardisation of training institutions (National Standards for Civil Service Training Institutions – NSCSTI).</li></ul></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-green\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill text-success\"></i></p><h4>Broader Implications</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list karmayogi-list-green\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> <strong class=\"text-success\">Strengthening training infrastructure:</strong> The Conclave is a push towards modernising and upgrading training institutions for civil servants across India, aligning them with future-ready skills and governance needs.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> <strong class=\"text-success\">Institutionalising peer-learning and collaboration:</strong> With multiple training institutes, state/local government officials, and private-sector experts participating, the event sets up a platform for cross-learning and sharing best practices.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> <strong class=\"text-success\">Embedding a service-orientation mindset:</strong> By emphasising \"ownership\", \"service to the citizen\", and moving beyond hierarchy, the Conclave signals a shift in how government training is conceptualised — not just technical skills, but mindset, attitude, and governance culture.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon icon-green\"></i> <strong class=\"text-success\">Digital-first and competency-based training:</strong> The discussion around digitisation, online platforms, training-impact assessments, and linking-competencies indicate a shift from traditional classroom-centric training to blended, technology-enabled, outcomes-oriented capacity building.</li></ul></div></div></div></div></div></div></section><!-- Full Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-earmark-text-fill me-3 text-primary\"></i>Conceptual Framework</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-file-earmark-pdf-fill text-primary\"></i></p><h3>Document</h3></div><p class=\"karmayogi-feature-desc mb-4\">Complete concept note for National Training Conclave 2023 is available below.</p><div class=\"nlw-document-card nlw-document-card-blue\"><p><i class=\"bi bi-file-earmark-text-fill nlw-document-icon\"></i></p><div class=\"nlw-document-info\"><p class=\"nlw-document-title\"><strong>National Training Conclave 2023 - Full Concept Note</strong></p><p class=\"nlw-document-desc\">Complete concept document for NTC 2023</p></div><p><a class=\"nlw-document-link text-primary\" href=\"#\" title=\"View/Download Document\"><i class=\"bi bi-download\"></i></a></p></div></div></div></div></section><!-- Relevant Data Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-folder-fill me-3 text-primary\"></i>Relevant Data</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-file-earmark-pdf-fill text-danger\"></i></p><h3>Reports &amp; Documents</h3></div><div class=\"nlw-document-list\"><div class=\"nlw-document-card nlw-document-card-danger\"><p><i class=\"bi bi-file-earmark-pdf-fill nlw-document-icon text-danger\"></i></p><div class=\"nlw-document-info\"><p class=\"nlw-document-title\"><strong>NTC Report.pdf</strong></p><p class=\"nlw-document-desc\">National Training Conclave 2023 Report</p></div><p><a class=\"nlw-document-link text-danger\" href=\"/sites/default/files/2026-01/Report%20on%20NTC_Designed_19June23_1230PM%20%281%29_0.pdf\" title=\"View/Download Report\"><i class=\"bi bi-download\"></i></a></p></div></div></div></div></div></section><!-- Connection to NLW Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-link-45deg me-3 text-primary\"></i>Connection with National Learning Week</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block bg-light-blue border-left-blue\"><div class=\"karmayogi-quote-icon text-primary\"><i class=\"bi bi-diagram-3-fill\"></i></div><p class=\"karmayogi-quote-text\">The National Training Conclave (NTC) and National Learning Week (NLW) are <strong class=\"karmayogi-highlight\">complementary initiatives</strong> under Mission Karmayogi, both working toward the shared vision of transforming India\'s civil service training ecosystem. While the <strong class=\"karmayogi-highlight\">National Training Conclave 2023</strong> laid the foundation by bringing together training institutions and establishing standards (NSCSTI), the <strong class=\"karmayogi-highlight\">National Learning Week 2024</strong> operationalized these frameworks by engaging individual civil servants in competency-based learning.</p><p class=\"karmayogi-quote-text mt-3\">NTC focused on <strong class=\"karmayogi-highlight\">institutional strengthening</strong>—creating standards, building capacity of training institutions, and fostering collaboration among CSTIs. NLW, on the other hand, focuses on <strong class=\"karmayogi-highlight\">individual and organizational learning culture</strong>—encouraging civil servants to take ownership of their learning journeys and embedding continuous development as a professional norm.</p><p class=\"karmayogi-quote-text mt-3\">Together, these initiatives create a <strong class=\"karmayogi-highlight\">comprehensive ecosystem</strong> where training institutions are strengthened (NTC) and learners are motivated and enabled (NLW), ensuring that capacity building becomes both institutionalized and personalized, leading to a future-ready civil service aligned with Viksit Bharat 2047.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-milestone-card high-contrast-border nlw-link-card-blue\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">National Training Conclave</div><div class=\"karmayogi-milestone-label mb-3\">Institutional strengthening and standardization</div><p><span class=\"btn nlw-btn-primary nlw-btn-current\">Current Page</span></p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-milestone-card high-contrast-border nlw-link-card-green\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-mortarboard-fill\"></i></div><div class=\"karmayogi-milestone-title\">National Learning Week</div><div class=\"karmayogi-milestone-label mb-3\">Individual learning culture and continuous development</div><p><a class=\"btn nlw-btn-success\" href=\"/national-learning-week\">Learn More</a></p></div></div></div></div></div></section><!-- Media Assets Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-image-fill me-3 text-primary\"></i>Media Assets</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-folder-fill text-primary\"></i></p><h3>Resources</h3></div><p class=\"karmayogi-feature-desc\">All media assets and resources for the National Training Conclave 2023 are hosted on the dedicated microsite:</p><div class=\"ntc-microsite-link\"><p><a class=\"ntc-microsite-url\" href=\"https://cbc.gov.in/cbc-ntc2023/\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Visit NTC 2023 Microsite</strong></a></p><p class=\"ntc-microsite-hint\">https://cbc.gov.in/cbc-ntc2023/</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 1163, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"/sites/default/files/2026-01/train-the-trainer%20%20%281%29.png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"/sites/default/files/2026-01/cascade-model%20%281%29.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/sites/default/files/2026-01/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html'),
('page', 0, 67, 1698, 'en', 0, '<!-- Section 1: Programme Design (Orange Gradient) --><!-- ========================================\r\n     VIKSIT PANCHAYAT INITIATIVE SECTIONS\r\n     Refactored to use external CSS classes\r\n     ======================================== --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\"></i> Programme Design</h2><p class=\"karmayogi-text-large\">The Capacity Building for Viksit Panchayat initiative is a pilot programme of the Capacity Building Commission (CBC), conceptualised under the principles of Mission Karmayogi to strengthen Panchayati Raj Institutions (PRIs) as the foundation of decentralised governance. The programme is designed to build the capacities of both elected representatives and Panchayat-level officials to enable them to discharge their constitutional and statutory responsibilities more effectively.</p><p class=\"karmayogi-text-large\">While Panchayats have been constitutionally empowered through the 73rd Constitutional Amendment, capacity gaps at the grassroots level continue to constrain effective planning, financial management, service delivery, and citizen engagement. The Viksit Panchayat Initiative responds to this challenge by adopting a competency-based approach that focuses on what Panchayat functionaries are expected to do, the competencies required to perform these roles, and the systems needed to support them.</p><p class=\"karmayogi-text-large\">The programme has been designed as a pilot intervention, with implementation across four states—<strong>Assam, Odisha, Gujarat, and Andhra Pradesh</strong>—covering approximately <strong>60 Gram Panchayats</strong>. The pilot approach allows for contextual adaptation while maintaining a common design framework, enabling the Commission to generate evidence, refine methodologies, and develop models that are demonstrable and scalable. The long-term intent is to inform national-level capacity-building strategies for PRIs, in partnership with the Ministry of Panchayati Raj.</p></div></section><!-- Section 2: Objectives of the Programme (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-ideation-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\"></i> Objectives of the Programme</h2><p class=\"karmayogi-text-large\">The primary objective of the Viksit Panchayat Initiative is to bridge critical competency gaps at the Panchayat level and strengthen institutional functioning of PRIs. The programme seeks to enhance the ability of Panchayat representatives and officials to:</p><div class=\"karmayogi-feature-block mt-4\"><ul class=\"karmayogi-feature-list\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Plan and implement development interventions aligned with local needs</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Manage financial resources effectively and in compliance with established norms</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Deliver public services and entitlements efficiently</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Engage citizens in participatory decision-making processes</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Strengthen accountability and transparency mechanisms at the local level</span></li></ul></div><div class=\"karmayogi-requirements-card mt-4\"><h3 class=\"karmayogi-requirements-title\"><i class=\"bi bi-star-fill me-2\"></i> Evidence-Based Scalable Models</h3><p class=\"karmayogi-requirements-text\">An important objective of the initiative is also to develop evidence-based, scalable capacity-building models that can be adapted across states and institutional contexts. By documenting processes, outcomes, and implementation learnings, the programme aims to contribute to national discourse on Panchayat capacity building and inform future policy and programme design.</p></div></div></section><!-- Section 3: Methodology Adopted (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-intervention-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-gear-fill me-3\"></i> Methodology Adopted</h2><p class=\"karmayogi-text-large text-center mb-4\">The programme follows a competency-based and participatory methodology, combining research, stakeholder engagement, experiential learning, and technology-enabled support.</p><!-- 3.1 Competency-Based Framework --><div class=\"karmayogi-feature-block mt-4 bg-alice-blue border-left-blue\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-1-circle-fill me-2\"></i> Competency-Based Framework</h3><p class=\"karmayogi-text-large\">At the core of the programme is role-based competency mapping for key Panchayat functionaries, including elected representatives and officials. The Commission worked with subject matter experts, SIRDs, and practitioners to identify the functional, behavioural, and domain competencies required for effective Panchayat governance. This mapping provided the foundation for assessment, learning design, and monitoring.</p></div><!-- 3.2 Stakeholder Consultations --><div class=\"karmayogi-feature-block mt-4 bg-light-green border-left-green\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-2-circle-fill me-2\"></i> Stakeholder Consultations and Training Needs Analysis</h3><p class=\"karmayogi-text-large\">Extensive consultations were conducted at the state and Panchayat levels involving Commissionerates of Panchayati Raj, SIRDs, District Collectors of intervention districts, Sarpanches, Panchayat Secretaries, and other stakeholders. These consultations served two purposes: stakeholder onboarding and training needs analysis. Based on these discussions, priority themes for capacity building were identified, ensuring that the programme responds to real operational challenges faced by Panchayats.</p></div><!-- 3.3 Learning Design --><div class=\"karmayogi-feature-block mt-4 bg-light-orange border-left-orange\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-3-circle-fill me-2\"></i> Learning Design and Delivery Approach</h3><p class=\"karmayogi-text-large\">The programme adopts the <strong>70:20:10 model of learning</strong>, with emphasis on experiential learning (70%) and peer-based learning (20%), supported by structured self-learning (10%). This approach marks a shift away from traditional classroom-centric training towards learning that is embedded in day-to-day work contexts.</p><p class=\"karmayogi-text-large\">A learning design workshop was organised, bringing together experts in adult learning, academicians, civil society practitioners, state government officials, and representatives from the Ministry of Panchayati Raj. Based on the synthesis of inputs from this workshop, <strong>14 learning modules</strong> were developed, covering key competency areas relevant to Panchayat-level governance. These modules have been prepared in hardcopy and are being digitised for rollout.</p></div><!-- 3.4 Technology Enablement --><div class=\"karmayogi-feature-block mt-4 bg-light-cyan border-left-cyan\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-4-circle-fill me-2\"></i> Technology Enablement</h3><p class=\"karmayogi-text-large\">Technology forms a critical enabler of the programme. The learning content and training management are being integrated through the <strong>iGOT Karmayogi platform</strong>, ensuring alignment with Mission Karmayogi\'s digital learning ecosystem. iGOT will host the learning modules, track participation, and support training management functions.</p><p class=\"karmayogi-text-large\">In addition, an <strong>AI-enabled chatbot</strong> is being developed to provide on-demand, context-specific support to Panchayat functionaries. The chatbot is designed to address queries related to roles, governance processes, schemes, and entitlements, thereby reinforcing learning beyond formal training sessions. Beta testing of the chatbot has been completed, and the tool is currently in the advanced stages of development following multiple rounds of feedback.</p></div><!-- 3.5 Assessment and Monitoring --><div class=\"karmayogi-feature-block mt-4 bg-light-red border-left-red\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-5-circle-fill me-2\"></i> Assessment and Monitoring</h3><p class=\"karmayogi-text-large\">The programme incorporates a structured assessment framework, including baseline, midline, and endline assessments. A baseline survey was conducted across intervention Panchayats to assess current competency levels and capture indicators related to institutional knowledge, planning capacities, fund utilisation practices, and citizen perceptions. These data points will serve as reference benchmarks to measure progress and impact over the programme period.</p></div></div></section><!-- Section 4: Implementation Geography and Partnerships (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-learnings-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-geo-alt-fill me-3\"></i> Implementation Geography and Partnerships</h2><p class=\"karmayogi-text-large\">The pilot is being implemented across four states—<strong>Assam, Odisha, Gujarat, and Andhra Pradesh</strong>, covering approximately <strong>60 Gram Panchayats</strong>. State-specific implementation models have been adopted to reflect local institutional contexts while maintaining a common programme framework.</p><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-blue\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-learning-title\">National Anchor</h3><p class=\"karmayogi-learning-text\"><strong>Kaivalya Education Foundation (Piramal)</strong> - Programme anchoring at national level</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-teal\"><i class=\"bi bi-robot\"></i></div><h3 class=\"karmayogi-learning-title\">ChatBot Development</h3><p class=\"karmayogi-learning-text\"><strong>Tech4Dev</strong> - Developing WhatsApp-based AI Chatbot, currently undergoing field testing</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-yellow\"><i class=\"bi bi-graph-up-arrow\"></i></div><h3 class=\"karmayogi-learning-title\">Research Partners</h3><p class=\"karmayogi-learning-text\"><strong>Navagraam</strong> - Supporting baseline and impact assessments</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-learning-card\"><div class=\"karmayogi-learning-icon icon-pink\"><i class=\"bi bi-people-fill\"></i></div><h3 class=\"karmayogi-learning-title\">State-Level Partners</h3><p class=\"karmayogi-learning-text\">KEF has engaged experienced organisations with strong grassroots presence in each state in addition to SIRDs and Panchayat Commissionerate</p></div></div></div></div></section><!-- Section 5: Current Status and Progress (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-elements-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\"></i> Current Status and Progress to Date</h2><p class=\"karmayogi-text-large text-center mb-4\">Over the past year, the Commission has focused on programme design, preparatory activities, and readiness for rollout. Key milestones achieved include:</p><div class=\"row g-4 mt-3\"><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Completion of two national-level roundtables to finalise programme design and methodology</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Conduct of multiple state-level consultative workshops for stakeholder onboarding and training needs analysis</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Identification of priority capacity-building themes and development of 14 learning modules</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Completion of baseline surveys and competency assessments across intervention Panchayats</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Finalisation and onboarding of national and state-level implementation partners</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Beta testing of the AI-enabled chatbot and progression towards final deployment</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Integration of learning content and training management workflows with the iGOT platform</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-check-circle-fill\"></i> <span>Initiation of state-level launch workshops and early rollout activities</span></div></div></div><div class=\"karmayogi-requirements-card mt-5\"><p class=\"karmayogi-requirements-text m-0 text-center\">These activities have ensured that the programme enters the implementation phase with a strong evidence base, stakeholder ownership, and operational readiness.</p></div></div></section><!-- Section 6: Impact Metrics (White) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-ideation-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\"></i> Impact Metrics</h2><!-- Outputs --><div class=\"karmayogi-feature-block mt-4 bg-alice-blue border-left-blue\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-box-seam me-2\"></i> Outputs</h3><ul class=\"karmayogi-feature-list\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Number of PRI members trained and certified through blended learning modalities</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Number of customized training modules delivered and adopted</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Volume of user activity and feedback on the technology platforms (app, LMS, chatbot)</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>GPDP plans prepared with community inputs and evidence of best practices adoption</span></li></ul></div><!-- Outcomes --><div class=\"karmayogi-feature-block mt-4 bg-light-green border-left-green\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-trophy-fill me-2\"></i> Outcomes</h3><ul class=\"karmayogi-feature-list\"><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Improved governance capacity, leadership, and citizen-centric service delivery at Panchayat level</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Higher proportion of PRIs using digital tools for planning and public interface</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Increased citizen participation in local decision-making and planning processes</span></li><li><i class=\"bi bi-arrow-right-circle-fill\"></i> <span>Greater adoption of financial and resource management practices across Panchayats</span></li></ul></div><!-- Indicators --><div class=\"karmayogi-feature-block mt-4 bg-light-orange border-left-orange\"><h3 class=\"karmayogi-feature-title\"><i class=\"bi bi-speedometer2 me-2\"></i> Indicators</h3><div class=\"row g-3\"><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Percentage increase in governance capacity scores of PRI members measured through baseline, midline, and endline assessments</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Proportion of Panchayats regularly using digital tools (app, LMS, chatbot) for planning and citizen engagement</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Percentage increase in citizen participation in Gram Panchayat Development Plan (GPDP) consultations and Gram Sabha meetings</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Improvement in fund utilization rates and financial management efficiency at Panchayat level</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Percentage of PRI members demonstrating enhanced knowledge and skills in local governance, leadership, and planning</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Increase in successful resolution of citizen grievances and service requests through Panchayat mechanisms</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Level of community satisfaction with Panchayat services measured through periodic surveys</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Number of PRI members enrolled, trained, and certified across blended learning platforms</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Number of capacity-building modules and training sessions delivered and completed</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Volume and frequency of user interactions on technology platforms (app downloads, chatbot queries, LMS logins)</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Number of GPDP plans prepared with documented community inputs and evidence of good practices</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Number of workshops, roundtables, and learning circles conducted to facilitate peer learning</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Quantity and quality of knowledge products, toolkits, and best practice documentation produced for dissemination</span></div></div><div class=\"col-md-6\"><div class=\"karmayogi-topic-item\"><i class=\"bi bi-arrow-up-circle-fill\"></i> <span>Extent of technology adoption by Panchayats for governance and administrative functions</span></div></div></div></div></div></section><!-- Section 7: Way Forward (Orange Gradient) --><section class=\"karmayogi-section-fullwidth karmayogi-fdp-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-signpost-fill me-3\"></i> Way Forward</h2><p class=\"karmayogi-text-large\">The programme will now move into full-scale implementation across the selected Panchayats, with continued monitoring, midline assessments, and adaptive refinements based on field feedback. Documentation of processes and outcomes will be undertaken to inform future scale-up. The Commission will continue to engage with the Ministry of Panchayati Raj and state governments to ensure alignment with national and state priorities.</p><div class=\"karmayogi-requirements-card mt-4\"><p class=\"karmayogi-requirements-text font-12 m-0 text-center\"><strong>Through this pilot, the Capacity Building Commission aims to demonstrate how a structured, competency-based approach can strengthen Panchayats and contribute meaningfully to decentralised governance and local development.</strong></p></div></div></section>', '', 'full_html');
INSERT INTO `node__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 68, 1699, 'en', 0, '<!-- Vision Section --><!-- ========================================\r\n     ULB - Capacity Building of Urban Local Bodies\r\n     Refactored to use external CSS classes\r\n     ======================================== --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 align-items-start\"><!-- Vision Content --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title text-left mb-4\"><i class=\"bi bi-eye-fill me-3 text-primary\"></i>Vision</h2><div class=\"karmayogi-quote-block h-100\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">Cities in India occupy a central position for propelling India\'s vision of becoming <strong class=\"text-primary\">\"Viksit Bharat\" by 2047</strong> since they are contributing <strong class=\"text-primary\">65% to the overall GDP</strong>. Over the past two decades, urban development schemes have strengthened municipal capacities through infrastructure development and reforms. However, scheme-specific capacity-building efforts are often limited to aligned specific objectives with focused target group.</p><p class=\"karmayogi-quote-text mt-3\">Keeping in mind the important role of cities in nation development and learnings gained from legacy capacity building initiatives, the <strong class=\"text-primary\">Capacity Building Commission under Mission Karmyogi</strong> expanded its reach from central government ministries and departments to ULBs to develop a comprehensive capacity development ecosystem for all the <strong class=\"text-success\">4800+ Urban Local Bodies</strong>, which will eventually lead to improved local governance &amp; service delivery.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"ulb-overview-card h-100\"><!-- Blue Header Section --><div class=\"ulb-overview-header\"><h3><strong><i class=\"bi bi-info-circle-fill\"></i> Initiative Overview</strong></h3></div><!-- Info Section --><div class=\"ulb-overview-body\"><div><div class=\"ulb-overview-item\"><div class=\"ulb-overview-item-inner\"><p><i class=\"bi bi-building ulb-overview-icon\"></i></p><div class=\"flex-1\"><p><strong class=\"ulb-overview-label\">Target ULBs</strong></p><div class=\"ulb-overview-value\">4800+ Urban Local Bodies</div></div></div></div><div class=\"ulb-overview-item\"><div class=\"ulb-overview-item-inner\"><p><i class=\"bi bi-people-fill ulb-overview-icon\"></i></p><div class=\"flex-1\"><p><strong class=\"ulb-overview-label\">Municipal Functionaries</strong></p><div class=\"ulb-overview-value\">Over 15 lakh municipal functionaries</div></div></div></div><div class=\"ulb-overview-item\"><div class=\"ulb-overview-item-inner\"><p><i class=\"bi bi-graph-up-arrow ulb-overview-icon\"></i></p><div class=\"flex-1\"><p><strong class=\"ulb-overview-label\">GDP Contribution</strong></p><div class=\"ulb-overview-value\">65% of India\'s GDP</div></div></div></div><div class=\"ulb-overview-item\"><div class=\"ulb-overview-item-inner\"><p><i class=\"bi bi-bullseye ulb-overview-icon\"></i></p><div class=\"flex-1\"><p><strong class=\"ulb-overview-label\">Approach</strong></p><div class=\"ulb-overview-value\">Demand-driven, role-based capacity building</div></div></div></div></div></div></div></div></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 text-dark-blue\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill text-primary\"></i></p><h3>Strategic Approach</h3></div><p class=\"karmayogi-feature-desc\">This initiative presents a strategic opportunity to institutionalize a <strong class=\"text-primary\">demand-driven, role-based approach</strong> to capacity building across Urban Local Bodies (ULBs) in India. It seeks to move beyond traditional training paradigms by fostering a system responsive to the practical and evolving needs of ULBs, thereby supporting the development of a future-ready urban workforce.</p></div><!-- Short-Term Objectives --><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clock-fill text-primary\"></i></p><h4>Objectives</h4></div><div class=\"karmayogi-feature-desc\"><ul class=\"karmayogi-list\"><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Strengthen the overall capacity-building ecosystem by establishing institutional mechanisms, expanding access to high-quality e-learning resources, and ensuring seamless integration with digital platforms.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Create a network of Subject Matter Experts (SMEs) to deliver contextualized and role-specific training that aligns with the operational realities of ULBs.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Build the competencies of ULB officials to enhance last-mile service delivery, transparency, and citizen-centric governance.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Transition from rule-based to role-based management by identifying key roles within ULB structures and mapping them against domain, functional, and behavioural competencies.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Support the development of competency-aligned courses and structured learning pathways tailored to equip urban staff with the tools, knowledge, and skills required to deliver inclusive, efficient, and accountable services at the local level.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Design targeted interventions that empower personnel to perform their responsibilities effectively and accountably.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Address identified capacity gaps through systematic and scalable capacity building mechanisms.</li><li class=\"karmayogi-list-item\"><i class=\"bi bi-check-circle-fill karmayogi-list-icon\"></i> Transform ULBs from input-based entities into future-ready institutions that anchor India\'s vision of Viksit Bharat@2047.</li></ul></div></div></div></div></section><!-- Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3 text-primary\"></i>Conceptual Framework</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-quote\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill text-primary\"></i></p><h3>Concept Overview</h3></div><p class=\"karmayogi-feature-desc\">The Capacity Building of Urban Local Bodies initiative under Mission Karmayogi seeks to create a <strong class=\"text-primary\">robust, demand-driven, and role-based capacity development ecosystem</strong> for over <strong class=\"text-success\">4800 ULBs in India</strong>. Recognising the critical role of cities in driving economic growth and citizen welfare, this initiative moves beyond scheme-specific training to institutionalize structured and scalable mechanisms for enhancing municipal governance and service delivery.</p><p class=\"karmayogi-feature-desc mt-3\">It leverages the <strong class=\"text-primary\">iGOT Karmayogi platform</strong> to ensure speed, scale, and equitable access to high-quality courses, while simultaneously strengthening the fragmented training ecosystem through standardization, expert networks, and world-class pedagogy. The initiative ultimately aims to empower <strong class=\"text-success\">over 15 lakh municipal functionaries</strong> with the functional, domain, and behavioural competencies required to deliver inclusive, transparent, and citizen-centric services.</p><p class=\"karmayogi-feature-desc mt-3\">By integrating technology, performance-linked learning, and a focus on sustainability, the program envisions transforming ULBs from input-based entities into <strong class=\"text-primary\">future-ready institutions</strong> that anchor India\'s vision of <strong class=\"text-primary\">Viksit Bharat@2047</strong>.</p></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3 text-primary\"></i>Chronology of Events</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block bg-alice-blue\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill text-primary\"></i></p><h3>Pilot Phase Implementation</h3></div><p class=\"karmayogi-feature-desc mb-3\">CBC conducted a pilot for <strong class=\"text-primary\">7 (seven) selected ULBs</strong> (Pune, Ahmedabad, NDMC, Nagpur, Rajkot, Mysore and Bhubaneshwar), in collaboration with MOHUA, to tackle the crucial challenge of enhancing the capacity of these ULBs. A set of over <strong class=\"text-success\">120 areas of skilling</strong> in the areas of Administrative &amp; Governance, Technical &amp; Engineering, Technology, Finance, Project Management, Behavioral tracks were identified.</p><p class=\"karmayogi-feature-desc mb-3\">Based on this, the ULBs prepared their <strong class=\"text-primary\">Annual Capacity Building Plans (ACBPs)</strong> and with assistance prepared job descriptions, competency maps and linked trainings for each Municipal role. CBC is working closely with these ULBs for the time-bound implementation of the ACBPs, with officials leveraging iGOT to undergo training.</p><p class=\"karmayogi-feature-desc mb-3\">The findings suggest that a large number of behavioral, functional and domain competencies are common across all ULBs, so the development of digital courses and training programs can be started right away since they can be applied to all ULBs. The pilot suggests that a <strong class=\"text-primary\">demand-driven, bottom-up, role-based capacity building approach</strong> will have a sustainable impact on municipal performance.</p><!-- Challenges Identified --><div class=\"ulb-challenges-box mt-4\"><h3 class=\"text-dark-blue mb-3\"><strong><i class=\"bi bi-exclamation-triangle-fill text-primary me-2\"></i>Challenges Identified</strong></h3><div class=\"row g-3\"><div class=\"col-md-6\"><div class=\"ulb-challenge-item blue\"><i class=\"bi bi-speedometer2 text-primary me-2\"></i> <strong>Speed &amp; Scale:</strong> Capacity building must be done with speed and at scale for 4700+ ULBs (over 10+ lakh municipal functionaries in India, each with a varied level of resources and skills. iGOT offers the fastest way to train ULB staff.</div></div><div class=\"col-md-6\"><div class=\"ulb-challenge-item green\"><i class=\"bi bi-puzzle-fill text-success me-2\"></i> <strong>Fragmented Ecosystem:</strong> The training (supply) ecosystem in municipal domain is highly fragmented with varying degrees of faculty quality, pedagogy, scale, content and access.</div></div><div class=\"col-md-12\"><div class=\"ulb-challenge-item orange\"><i class=\"bi bi-diagram-3-fill text-orange me-2\"></i> <strong>Lack of Formal Structures:</strong> There is a lack of formal structures and Job Roles-to-Competency registries, which will prevent a consistent application of capacity building strategies. A formal competency framework with access to role-to-skill map, training linkage and performance assessment is being developed in concert with Karmayogi Competency Model.</div></div></div></div><!-- Outcomes Defined --><div class=\"mt-4\"><h3 class=\"text-dark-blue mb-3\"><strong><i class=\"bi bi-check-circle-fill text-success me-2\"></i>Outcomes Defined Based on Learnings</strong></h3><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip blue\"><i class=\"bi bi-arrow-left-right\"></i> Move urban capacity building from supply-driven to demand-driven approach by ULBs</div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip green\"><i class=\"bi bi-link-45deg\"></i> Linking job-roles to performance and continuous improvement</div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip orange\"><i class=\"bi bi-building-check\"></i> Strengthen the urban training (supply) ecosystem in India with world-class pedagogy and faculty</div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip red\"><i class=\"bi bi-laptop\"></i> Higher integration of technology in urban capacity building ecosystem for access, equity and quality of skilling</div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip gray\"><i class=\"bi bi-people\"></i> Move ULBs from inputs based to citizen oriented/service-oriented governance</div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-info-chip blue\"><i class=\"bi bi-handshake\"></i> These initiatives will be taken forward in collaboration with MoHUA and its affiliated training institutes</div></div></div></div></div></div></div></div></div></section><!-- Key Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-flag-fill me-3 text-primary\"></i>Key Milestones</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block bg-alice-blue mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clipboard-check-fill text-primary\"></i></p><h3>7 Annual Capacity Building Plans (ACBPs) Prepared and Approved</h3></div><p class=\"karmayogi-feature-desc mb-4\">The following Urban Local Bodies (ULBs) have finalised and received approval for their ACBPs:</p><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Ahmedabad Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Bhubaneswar Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-yellow\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Mysuru City Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-red\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Nagpur Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-gray\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">New Delhi Municipal Council (NDMC)</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-blue\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Pune Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon icon-teal\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Rajkot Municipal Corporation</div></div></div></div></div></div></div></section><!-- Key Achievements Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-trophy-fill me-3 text-primary\"></i>Key Achievements</h2><div class=\"karmayogi-content-wrapper\"><!-- Platform Onboarding --><div class=\"karmayogi-feature-block bg-alice-blue border-left-blue mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill text-primary\"></i></p><h3>Platform Onboarding</h3></div><p class=\"karmayogi-feature-desc\">Over <strong class=\"text-primary\">1,55,000+ ULB officials</strong> have been successfully onboarded onto the iGOT Karmayogi Bharat platform, with more in the process of joining.</p></div><!-- Course Development --><div class=\"karmayogi-feature-block bg-alice-blue border-left-green mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-book-half text-success\"></i></p><h3>Course Development</h3></div><p class=\"karmayogi-feature-desc mb-3\">A total of <strong class=\"text-success\">154 curated courses</strong> is currently available on iGOT for ULB officials, including:</p><div class=\"row g-3\"><div class=\"col-md-4\"><div class=\"ulb-stat-display blue\"><div class=\"ulb-stat-number\">60</div><div class=\"ulb-stat-label\">Functional Courses</div></div></div><div class=\"col-md-4\"><div class=\"ulb-stat-display green\"><div class=\"ulb-stat-number\">64</div><div class=\"ulb-stat-label\">Domain Courses</div></div></div><div class=\"col-md-4\"><div class=\"ulb-stat-display orange\"><div class=\"ulb-stat-number\">30</div><div class=\"ulb-stat-label\">Behavioural Courses</div></div></div></div><p class=\"karmayogi-feature-desc mt-4\"><strong class=\"text-success\">22 domain-specific courses</strong> have been launched on iGOT, and <strong class=\"text-success\">13 more high-impact courses</strong> are currently under development. The courses launched so far have received an <strong class=\"text-orange\">average user rating of 4.3 stars</strong>.</p></div><!-- State-Level Workshops --><div class=\"karmayogi-feature-block bg-alice-blue border-left-orange mb-4\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-calendar-event-fill text-orange\"></i></p><h4>State-Level Workshops</h4></div><p class=\"karmayogi-feature-desc mb-3\"><strong class=\"text-orange\">5 state-level workshops</strong> on \"Capacity Building of Urban Local Bodies under Mission Karmayogi\" were successfully organized:</p><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-workshop-card blue\"><div class=\"ulb-workshop-title text-primary\">Assam</div><div class=\"ulb-workshop-date\">December - 125+ ULB officials and State UDD representatives</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-workshop-card green\"><div class=\"ulb-workshop-title text-success\">Andhra Pradesh</div><div class=\"ulb-workshop-date\">June - 175+ ULB officials and State UDD representatives</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-workshop-card orange\"><div class=\"ulb-workshop-title text-orange\">Haryana</div><div class=\"ulb-workshop-date\">June - 90+ ULB officials</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-workshop-card red\"><div class=\"ulb-workshop-title text-danger\">Uttar Pradesh</div><div class=\"ulb-workshop-date\">24th &amp; 25th June - 750+ ULB officials</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"ulb-workshop-card gray\"><div class=\"ulb-workshop-title text-muted\">Odisha</div><div class=\"ulb-workshop-date\">23rd July - 100+ ULB officials</div></div></div></div><p class=\"karmayogi-feature-desc mt-4\">Representatives from <strong class=\"text-orange\">1200+ ULBs</strong> participated in the above workshops.</p></div><!-- Framework Development --><div class=\"karmayogi-feature-block bg-alice-blue border-left-red\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill text-danger\"></i></p><h4>Framework Development</h4></div><p class=\"karmayogi-feature-desc\">Identified and updated <strong class=\"text-danger\">125 unique designations</strong> across <strong class=\"text-danger\">25 departments</strong> in the developed Role Aligned Competency Enhancement (RACE) Framework. Comprehensive data mapping is underway to develop a dictionary of Profiles-Roles &amp; Responsibilities-competencies-Training needs for municipal staff that can be translated into an application to automate capacity building planning and implementation. A total of <strong class=\"text-danger\">65 competencies</strong>, across functional, domain and behavioural, have been defined for the ULBs capacity building.</p></div></div></div></section>', '', 'full_html'),
('page', 0, 74, 1690, 'en', 0, '<!-- ========================================\r\n     STATES AND UNION TERRITORIES PAGE\r\n     Updated with latest data as of 23rd Jan 2026\r\n     Theme Colors Only: Orange (#FF9800) and Blue (#0063ae)\r\n     ======================================== --><section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><h2 class=\"states-header-orange mb-5\"><a class=\"text-white text-decoration-none\" href=\"/sites/default/files/2026-02/SOP_Mission%20Karmayogi%20for%20ATIs%20%281%29.pdf\"><i class=\"fas fa-file-pdf me-2\"></i> Standard Operating Procedure (SOP) for States &amp; UTs</a></h2><!-- Overview Section --><div class=\"states-overview-box\"><h2 class=\"text-white mb-3\"><strong>Engagement with States/UTs</strong></h2><p class=\"mb-0 fs-5 lh-base\"><strong>Overview:</strong> The Capacity Building Commission engages closely with States and Union Territories to support implementation of capacity-building initiatives. Dedicated team under Mission Karmayogi have been assigned to facilitate coordination and implementation at the State/UT level.</p></div><!-- At-a-Glance Summary --><div class=\"mb-5\"><h2 class=\"states-header-orange\"><strong>At-a-Glance Summary</strong></h2><div class=\"table-responsive\"><table class=\"table states-table-summary\"><thead><tr><th>Total States/UTs engaged</th><th>Number of MoUs signed</th><th>No. of Workshops conducted in States/UTs (Online + Offline)</th></tr></thead><tbody><tr><td><strong class=\"states-summary-val-blue\">36</strong></td><td><strong class=\"states-summary-val-orange\">28</strong></td><td><h2 class=\"mb-0\"><strong class=\"states-summary-val-gray\">-</strong></h2></td></tr></tbody></table></div></div><!-- Important Documents Section --><div class=\"mb-5\"><h2 class=\"states-header-orange\"><strong>Important Documents</strong></h2><div class=\"table-responsive\"><table class=\"table mou-status-table states-ut-table important-docs-table\">