('page', 0, 830, 1110, 'en', 0, '<section class=\"container py-5\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><h1 class=\"completed-acbp-title\">Completed <span class=\"title-underline\">ACBP</span></h1><!-- Search Section --><div class=\"search-section mb-4\"><div class=\"row align-items-end\"><div class=\"col-md-8\"><label class=\"form-label\" style=\"color:#333;margin-bottom:8px;\" for=\"searchInput\"><strong>Search by Department Name or CBU Details </strong></label><input class=\"form-control\" style=\"border-radius:8px;border:1px solid #ddd;font-size:15px;padding:12px 16px;\" type=\"text\" id=\"searchInput\" placeholder=\"Enter department name or CBU details...\"></div><div class=\"col-md-4\"><strong><button class=\"btn btn-secondary w-100\" style=\"background-color:#6c757d;border-radius:8px;border-style:none;padding:12px;\" type=\"button\" id=\"searchBtn\">\r\n                                                                        Search\r\n                                                                      </button></strong></div></div></div><!-- Table Section --><div class=\"acbp-table-wrapper mt-4\"><div class=\"table-responsive\"><table class=\"table acbp-table\" id=\"acbpTable\"><thead><tr><th>S.No</th><th>Department Name</th><th>CBU Details</th><th>ACBP Plan Document</th><th>Download Document</th><th>Download Count</th></tr></thead><tbody id=\"acbpTableBody\"><tr data-row-index=\"0\"><td>1</td><td>Ministry of Parliamentary Affairs</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 5.31 MB, Language: English)</span></td><td>Download</td><td>155</td></tr><tr data-row-index=\"1\"><td>2</td><td>University Grants Commission</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 9.52 MB, Language: English)</span></td><td>Download</td><td>158</td></tr><tr data-row-index=\"2\"><td>3</td><td>Sashastra Seema Bal, Ministry of Home Affairs</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 1.55 MB, Language: English)</span></td><td>Download</td><td>236</td></tr><tr data-row-index=\"3\"><td>4</td><td>Department of Official Language</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 1.35 MB, Language: English)</span></td><td>Download</td><td>280</td></tr><tr data-row-index=\"4\"><td>5</td><td>Ministry of Tribal Affairs</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 3.93 MB, Language: English)</span></td><td>Download</td><td>140</td></tr><tr data-row-index=\"5\"><td>6</td><td>Ministry of Panchayati Raj</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 5.67 MB, Language: English)</span></td><td>Download</td><td>146</td></tr><tr data-row-index=\"6\"><td>7</td><td>Ministry of Development of North Eastern Region</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 2.72 MB, Language: English)</span></td><td>Download</td><td>143</td></tr><tr data-row-index=\"7\"><td>8</td><td>Ministry of Home Affairs</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 1.93 MB, Language: English)</span></td><td>Download</td><td>147</td></tr><tr data-row-index=\"8\"><td>9</td><td>Legislative Department</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 3.87 MB, Language: English)</span></td><td>Download</td><td>139</td></tr><tr data-row-index=\"9\"><td>10</td><td>Department of Youth Affairs</td><td>-</td><td>View Document <span class=\"document-info\">(Format: PDF, Size: 4.59 MB, Language: English)</span></td><td>Download</td><td>153</td></tr></tbody></table></div><!-- Pagination Controls --><div class=\"table-pagination\"><div class=\"pagination-info\"><span id=\"paginationInfo\">Showing 1 to 10 of 10 entries</span></div><div class=\"pagination-controls\"><p><button class=\"pagination-btn\" id=\"prevBtn\" onclick=\"changePage(-1)\">\r\n            