INSERT INTO `node__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('event', 0, 5, 1081, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani welcomed the USIBC - US India Business Council global board members for their annual meeting in Delhi this year. He explained the key tenets of Mission Karmayogi and its lasting impact on enhancing the state capacity.</p>', '', 'basic_html'),
('event', 0, 6, 1381, 'en', 0, '<p>Capacity Building Commission in collaboration with ISRO - Indian Space Research Organization launched the online phase of the ‘Building Science Leaders in India’ program today. The in-person phase will thereafter be held from 27th-30th September 2022.</p><p>&nbsp;</p><p>The ‘Building Science Leaders in India’ is a unique collaborative executive development program for scientists at our Public funded R&amp;D organizations. The first batch has a cohort of 32 scientists from 7 scientific departments.</p>', '', 'basic_html'),
('our_team', 0, 33, 69, 'en', 0, '<p>Dr. R. Balasubramaniam (Dr. Balu), Member HR at the Capacity Building Commission is a development scholar, public policy practitioner, author, and leadership educator with over four decades of deep grassroots engagement. He is the founder of the Swami Vivekananda Youth Movement (SVYM), a nationally recognised organisation working at the confluence of health, education, and community empowerment, and GRAAM, a pioneering public policy think tank.</p><p>A physician by training, Dr. Balu is a Harvard-educated public leader, a former faculty member at Cornell University and IIT Delhi. Dr Balu holds a doctorate in Indic Leadership. His work is distinguished by its rare ability to seamlessly blend lived experience with rigorous academic insight.</p><p>He has advised governments on governance reforms, institutional strengthening, and state capacity building. A prolific author, his books including&nbsp;i, the citizen;&nbsp;Voices from the Grassroots;&nbsp;Leadership Lessons for Daily Living;&nbsp;and&nbsp;Power Within: The Leadership Legacy of Narendra Modi&nbsp;reflects his distinctive voice at the intersection of public policy, leadership, and Indian thought.&nbsp;His current work explores leadership insights from the&nbsp;Bhagavad Gita.&nbsp;</p><p>He has also authored over 500 newspaper columns in Kannada and English. Dr. Balu also serves currently as the Chairperson of SEBI’s Social Stock Exchange Advisory Committee.</p>', '', 'full_html'),
('our_team', 0, 34, 70, 'en', 0, '<p>Ms. S. Radha Chauhan is a seasoned civil servant with 36+ years of leadership across public policy, fiscal governance, institutional reform, and digital transformation. She is a 1988 Batch IAS officer of UP Cadre (Retd.).</p>', '', 'full_html'),
('our_team', 0, 35, 71, 'en', 0, '<p>Dr. Alka Mittal is former CMD and Director (HR) of ONGC. She was also the Chairperson of ONGC Group of Companies viz. ONGC Videsh, MRPL, OPAL, OTPC, etc.</p>', '', 'full_html'),
('event', 0, 110, 1042, 'en', 0, '<p>CBC organized a learning Design workshop for teams involved in the design of the Combined Mid-Career Training Program for All India Service Officers to brainstorm and revisit the design of the program based on the principles of Adult learning</p>', '', 'basic_html'),
('event', 0, 113, 223, 'en', 0, '<p>IDinsight has entered into a partnership with the Capacity Building Commission of India. IDinsight will support the CBC in preparing the Annual State of Civil Services Report, along with several others.</p>', '', 'basic_html'),
('event', 0, 114, 224, 'en', 0, '<p>The First Roundtable of Central Training Institutions was organised by CBC to kickstart collaboration activities amongst CTIs and reinforce the importance of transition to an era of integrated and desiloed learning ecosystem.</p><p>The workshop was graced by the presence of Hon\'ble MoS, Dr Jitendra Singh</p>', '', 'basic_html'),
('event', 0, 115, 226, 'en', 0, '<p>CBC, and Director NAAA Mr. Sunil Dadhe, had a discussion with mid-service Indian Audit and Account Services Officers and discussed policies to contain possible 3rd wave of COVID and roles of Audit in ensuring result oriented administrators.</p>', '', 'basic_html'),
('event', 0, 116, 227, 'en', 0, '<p>Singapore-India Partnership Office from the Ministry of Trade and Industry (Singapore) visited the Capacity Building Commission. The interaction between SIPO and CBC was held to discuss areas of collaboration for capacity building, and to support CBC\'s initiatives.</p>', '', 'basic_html'),
('event', 0, 117, 1044, 'en', 0, '<p>Capacity Building Commission\'s team conducted a workshop at the National Institute of Communication Finance, a designated Central Training Institute for training of India Post and Telecommunications Accounts and Finance Service civil servants (IP&amp;TAFS).</p>', '', 'basic_html'),
('event', 0, 118, 1043, 'en', 0, '<p>The Capacity Building Commission visited the National Academy of Audit and Accounts, housed at the historic campus \"Yarrows\" (NAAA), the apex Central Training Institute for training of Indian Audit &amp; Accounts Department (IA&amp;AD).</p>', '', 'basic_html'),
('event', 0, 119, 1045, 'en', 0, '<p>The Capacity Building Commission visited the Army Training Command (ARTRAC), one of the seven commands of the Indian Army located at Shimla</p><p>&nbsp;</p>', '', 'full_html'),
('event', 0, 120, 231, 'en', 0, '<p>CBC organised a meeting with Secretaries of pilot departments to brainstorm on the CBP approach</p>', '', 'basic_html'),
('event', 0, 121, 232, 'en', 0, '<p>We are delighted to announce that the Nation First Policy Research Centre (www.nationfirstpolicy.org) has entered into an MoU with the Capacity Building Commission. Nation First will be supporting us with providing resources at multiple levels and other initiatives.</p>', '', 'basic_html'),
('event', 0, 122, 233, 'en', 0, '<p>A workshop on approach to creation of Annual Capacity Building Plan was conducted by CBC to apprise the officials at the Ministry of Skill Development and Employment</p>', '', 'basic_html'),
('event', 0, 123, 234, 'en', 0, '<p>CBC’s approach to creation of CBPs at ministries and departments was presented to the Hon’ble Cabinet Secretary</p>', '', 'basic_html'),
('event', 0, 124, 235, 'en', 0, '<p>We are delighted to announce that the Indian School of Business (www.isb.edu) has entered into an MoU with the Capacity Building Commission. The Indian School of Business will be supporting us with creating learning resources, sectoral needs and data-driven impact assessment, and training of trainers and content partners and other outreach initiatives.</p>', '', 'basic_html'),
('event', 0, 125, 236, 'en', 0, '<p>The Capacity Building Commission, with Shri Pankaj Kumar, Chief Secretary, Shri Amrendra Kumar Rakesh, Additional Chief Secretary (Personnel), Shri Dhananjay Dwivedi, Secretary (NRI &amp; ARTD), Government of Gujarat and Shri Ramesh Chand Meena (DG SPIPA) at the Sardar Patel Institute of Public Administration (spipa.gujarat.gov.in) at Ahmedabad.</p>', '', 'basic_html'),
('event', 0, 126, 1046, 'en', 0, '<p>Capacity Building Commission\'s team visited the National Institute of Defence Estates Management (NIDEM, nidem.dgde.gov.in), a Central Training Institute for training of Indian Defence Estates Service (IDES) Officers.</p><p>We conducted a workshop to test the draft CTI Functional Evaluation Framework, and learn from NIDEM\'s experience in operating a premier Civil Services Training Institute.</p>', '', 'basic_html'),
('event', 0, 127, 239, 'en', 0, '<p>Hon’ble Minister, Dr. Jitendra Singh chaired the first ever high-level Capacity Building Meeting of all the Science and Technology Ministries and Departments.<br>The meeting set the vision for capacity building of science ministries and departments under Government of India to achieve the Hon’ble Prime Minister’s vision of 5 trillion dollar economy and improving ease of living for all citizens.</p>', '', 'basic_html'),
('event', 0, 128, 240, 'en', 0, '<p>Shri Praveen Pardeshi a lecture on Wildlife crime detection and prevention to officers promoted into the IPS at the Sardar Vallabhai Patel National Police Academy Hyderabad. We discussed the application of DNA analysis of remnant of poached tigers to trace and link poachers to the crime.</p>', '', 'basic_html'),
('event', 0, 129, 1047, 'en', 0, '<p>Capacity Building Commission\'s team visited the National Academy of Customs, Indirect Taxes and Narcotics (NACIN, www.nacin.gov.in), one of the 16 Zonal Training Institute\'s for training of Indian Revenue Service (IRS) Officers.</p><p>We conducted a workshop to test the draft CTI Functional Evaluation Framework, and learn from NACIN\'s experience in functioning as a premier Civil Services Zonal Training Institute.</p>', '', 'basic_html'),
('event', 0, 130, 242, 'en', 0, '<p>We are delighted to open the “Innovations in Public Administration” portal; inaugurated by Hon\'ble MOS (PP) Dr. Jitendra Singh, inviting all Government employees in the civil services of the Central, State or Local Government for an opportunity to showcase their innovations, initiatives and work that goes beyond the bounds of existing managerial systems.</p>', '', 'basic_html'),
('event', 0, 131, 243, 'en', 0, '<p>We are delighted to announce that Wadhwani AI (www.wadhwaniai.org) has entered into an MoU with the Capacity Building Commission. Wadhwani AI will be supporting us with knowledge and technology support in the area of artificial intelligence, machine learning and integrating emerging technologies for governance with resources at multiple levels.</p>', '', 'basic_html'),
('event', 0, 132, 244, 'en', 0, '<p>Capacity Building Commission\'s team visited the Indian Institute of Public Administration (IIPA) (www.iipa.org.in), an autonomous academic institution of national eminence for training, research and information dissemination in streams related to the ethos of Public Administration.</p><p>We conducted a workshop to decide the future course of action of the sub-committee on “Promotion of Knowledge Sharing” and it’s recommendations on the collaboration pillar of CBC\'s accreditation framework - \"National Standards for Civil Service Training Institutes\".</p>', '', 'basic_html'),
('event', 0, 133, 245, 'en', 0, '<p>We are delighted to announce that the Indian Institute of Management, Calcutta (www.iimcal.ac.in) has entered into an MoU with the Capacity Building Commission.</p><p>The Indian Institute of Management, Calcutta will be supporting us as a knowledge partner, providing customised leadership training programs, reports through impact-studies and imparting knowledge in areas of infrastructure, project management and communication.</p>', '', 'basic_html'),
('event', 0, 134, 246, 'en', 0, '<p>We are pleased to announce that Foundation for Advancing Science and Technology - India (www.fast-india.org) has signed an MoU with Capacity Building Commission to support capacity building in science, technology and innovation.</p>', '', 'basic_html'),
('event', 0, 135, 247, 'en', 0, '<p>The Embedding Effective Assessment of Training group had its first meeting to decide the structure of the report and its recommendations on training at the&nbsp;Indira Gandhi National Forest Academy&nbsp;Central Training Institute.</p>', '', 'basic_html'),
('event', 0, 136, 248, 'en', 0, '<p>The Science Capacity Building Cell setup by collaboration between Office of the Principal Scientific Adviser to the Government of India and Capacity Building Commission hosted the kick-off meeting for capacity building of science, technology and innovation institutions in Government of India</p>', '', 'basic_html'),
('event', 0, 138, 252, 'en', 0, '<p>Shri Praveen Pardeshi inaugurated the CBI law officers training course at Rastriya Raksha University, Gujarat: the discussion was based on how the rate of conviction can be increased by legally compliant evidence collection and scientific application of forensics: Rastriya Raksha University</p>', '', 'basic_html'),
('event', 0, 139, 253, 'en', 0, '<p>CBC visited Council for Scientific and Industrial Research’s Human Resource Development Centre to kickstart capacity building of science and technology departments.</p>', '', 'basic_html'),
('event', 0, 140, 259, 'en', 0, '<p>Shri Praveen Pardeshi, at the invitation of Hon Minister for Commerce Textiles and Industries, Shri Piyush Goyal, presented the role of Capacity Building Commission: explainingthe need to create a demand for training by developing Annual Capacity Building Plans for role based training for eachGovernment of India department has the capacity to achieve national priorities; including to contribute to Hon’ble PM Narendra Modi’s vision of a 5 trillion economy and ease of living.</p>', '', 'basic_html'),
('event', 0, 141, 258, 'en', 0, '<p>Sardar Vallabhai Patel National Police Academy launched a co-generative capacity building program for UT police today focusing on being a Karmayogi Police. Energy &amp; creativity displayed by the police officers in discovering themselves and their motivation to serve society was impressive.</p>', '', 'basic_html'),
('photo_gallery', 0, 142, 659, 'en', 0, '<p>Knowledge Partnership</p>', '', 'basic_html'),
('event', 0, 143, 261, 'en', 0, '<p>Professor Deepa Mani, Deputy Dean - Executive Education and Digital Initiatives and Professor of Information Systems, Indian School of Business, is in conversation with Dr. R Balasubramaniam, Member - HR Capacity Building Commission, Government of India on \'Rethinking Leadership in the Public Sector.</p>', '', 'basic_html'),
('event', 0, 144, 262, 'en', 0, '<p>Sardar Vallabhai Patel National Police Academy and Capacity Building Commission have jointly organized a Master Trainers Training for over 34 police official representatives from Union Territories of Jammu &amp; Kashmir, Ladakh, Chandigarh, Puducherry, Dadra Nagar and Haveli, Daman &amp; Diu, Andaman Nicobar Islands: inspiring the motivation to serve citizens and solve problems proactively. Flashpoints which create friction between police and citizens are modeled, standardized and friendly responses are practiced ensuring that trust of citizens in police force improves.</p>', '', 'basic_html'),
('event', 0, 145, 263, 'en', 0, '<p>Capacity Building Commission held a session with the Ministry of Defence of India at the valedictory of the training program for ASOs and SOs. Dr. R Balasubramaniam interacted with the team, discussing their understanding of the constructs of capacity building. The team was appreciative of a program built around responding to their demands and their inputs reassured that capacity building can have a real impact, with feedback given on addressing work demands and being a consistent and constant process.</p>', '', 'basic_html'),
('photo_gallery', 0, 146, 264, 'en', 0, '<p>Knowledge Partnership</p>', '', 'basic_html'),
('photo_gallery', 0, 147, 265, 'en', 0, '<p>Partnership Extension</p>', '', 'basic_html'),
('photo_gallery', 0, 148, 266, 'en', 0, '<p>Knowledge Partnership</p>', '', 'basic_html'),
('photo_gallery', 0, 149, 370, 'en', 0, '<p>Amrit Gyan Kosh</p>', '', 'basic_html'),
('photo_gallery', 0, 150, 268, 'en', 0, '<p>Case Writing workshop</p>', '', 'basic_html'),
('photo_gallery', 0, 151, 371, 'en', 0, '<p>Cohort 3 - IRIFM</p>', '', 'basic_html'),
('photo_gallery', 0, 152, 296, 'en', 0, '<p>Addressing participants</p>', '', 'basic_html'),
('photo_gallery', 0, 153, 372, 'en', 0, '<p>During workshop</p>', '', 'basic_html'),
('photo_gallery', 0, 154, 373, 'en', 0, '<p>Workshop session</p>', '', 'basic_html'),
('photo_gallery', 0, 155, 374, 'en', 0, '<p>Addressing participants</p>', '', 'basic_html'),
('photo_gallery', 0, 156, 375, 'en', 0, '<p>Cohort 3 - IRIFM</p>', '', 'basic_html'),
('photo_gallery', 0, 157, 376, 'en', 0, '<p>Cohort 2 - Goa</p>', '', 'basic_html'),
('photo_gallery', 0, 158, 277, 'en', 0, '<p>05.08.25</p>', '', 'basic_html'),
('photo_gallery', 0, 159, 278, 'en', 0, '<p>24.02.25</p>', '', 'basic_html'),
('photo_gallery', 0, 160, 279, 'en', 0, '<p>With McKinsey and IIM Ahmedabad - 03.02.25</p>', '', 'basic_html'),
('photo_gallery', 0, 161, 280, 'en', 0, '<p>With McKinsey - 21.04.25</p>', '', 'basic_html'),
('photo_gallery', 0, 162, 377, 'en', 0, '<p>14th-19th July 2025</p>', '', 'basic_html'),
('photo_gallery', 0, 163, 378, 'en', 0, '<p>14th-19th July 2025</p>', '', 'basic_html'),
('event', 0, 164, 283, 'en', 0, '<p>Capacity Building Commission celebrated its 1st Anniversary on April 1st at the Indian Institute of Public Administration, with Praveen Pardeshi and R Balasubramaniam giving talks on lateral entrants.</p>', '', 'basic_html'),
('event', 0, 165, 285, 'en', 0, '<p>Capacity Building Commission commenced thedevelopment of 5 Annual Capacity Building Plans with Department for Promotion of Industry and Internal Trade (dpiit.gov.in), Ministry of Commerce and Industry, Government of India (commerce.gov.in), Department of Consumer Affairs (consumeraffairs.nic.in), Department of Food and Public Distribution (dfpd.gov.in) and Ministry of Textiles (texmin.nic.in).</p>', '', 'basic_html'),
('event', 0, 166, 287, 'en', 0, '<p>Capacity Building Commission\'s Chairman Shri Adil Zainulbhai and Secretary Shri Hemang Jani participated in the graduation ceremony of the foundation course for the second lateral entry batch of Civil Service Officers at Joint Secretary/Director/Deputy Secretary level. Cabinet Secretary Shri Rajiv Gauba graced the event as chief guest and shared a very warm welcome to the new batch of Civil Servants.</p>', '', 'basic_html'),
('event', 0, 167, 289, 'en', 0, '<p>Capacity Building Commission held a discussion session with Mr. Cyril Shroff and team of prominent lawyers from Cyril Amarchand Mangaldas on ideas, models, and collaborations on Capacity Building for Amrit Kaal.</p>', '', 'basic_html'),
('event', 0, 168, 291, 'en', 0, '<p>We are delighted to announce that the Indian School of Public Policy (ISPP) (www.ispp.org.in) has entered into an MoU with the Capacity Building Commission. The Indian School of Public Policy (ISPP) will be supporting us as a knowledge and advisory partner, providing training resource, impact assessment and research support.</p>', '', 'basic_html'),
('event', 0, 169, 292, 'en', 0, '<p>We are pleased to announce that FLAME University (www.flame.edu.in) has entered into an MoU with the Capacity Building Commission. FLAME University will be supporting us as a knowledge partner on collaborations in public policy and capacity building initiatives.</p>', '', 'basic_html'),
('event', 0, 170, 293, 'en', 0, '<p>Capacity Building Commission visited ISRO Headquarters to discuss about the Capacity Building Initiatives within Department of Space. CBC highlighted the importance of training, promoting citizen centric programmes and preparing sectoral roadmaps for identifying new technologies. STI-CB cell of Office of the Principal Scientific Adviser to the Government of India and Capacity Building Commission will interact with ISRO officials for preparing ISRO’s Annual Capacity Building Plan (ACBP).</p><p>&nbsp;</p><p>ISRO - Indian Space Research Organization: https://www.isro.gov.in/update/28-apr-2022/capacity-building-commission-visit-to-isro-headquarters</p>', '', 'basic_html'),
('event', 0, 171, 295, 'en', 0, '<p>Capacity Building Commission, with NACEN co-hosted a workshop on creating ‘Roadmap to Phygital learning’ for top Civil Service training institutions of the country.</p>', '', 'basic_html'),
('event', 0, 172, 297, 'en', 0, '<p>We were excited to host and have an insightful meeting with Harvard T.H. Chan School of Public Health\'s Design Laboratory (D-Lab) team! (<a href=\"http://www.hsph.harvard.edu/d-lab/\">www.hsph.harvard.edu/d-lab/</a>). Astute discussions were held on utilizing design knowledge methods and frameworks to understand competencies and build skills within the departments of our government.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 174, 300, 'en', 0, '<p>Capacity Building Commission gave a status update to Hon. Minister Bhupendra Yadav and held a meeting with the Ministry of Labour &amp; Employment, Government of India to discuss the Large-Scale Training Interventions.</p><p>&nbsp;</p><p>The tutelage resulting from the Training Needs Assessment exercise received unanimous positive feedback and the demand for conducting more such trainings was high.</p>', '', 'basic_html'),
('event', 0, 175, 301, 'en', 0, '<p>Villages in the CholaAdministration were known as Urs. Village administration was entrusted to the Gramsabha (village assembly) which was the lowest unit of Chola Administration. It took care of maintenance of roads, tanks, village ponds and village temples.</p><p>&nbsp;</p><p>In Arthasastra, the Fort\'s construction talks about the administrative reforms made to protect the kingdom and its people\'s distribution of natural resources. The reforms helped in the management of water, soil, and forest resources.</p><p>&nbsp;</p><p>Celebrating 75years of independence and tracing our roots back to 2500 BC as a civilizational state. Capacity Building Commission is collaborating with Nehru Yuva Kendra Sangathan (India), Ministry of Youth Affairs &amp; Sports, Government of India to document our rich, local administrative history and learn capacity building lessons.</p><p>&nbsp;</p><p>To help citizens learn more about such facts from history, we are producing an interactive timeline where India’s rich administrative histories will be featured on our website (www.cbc.gov.in) in partnership with FLAME University. Today, we interacted with more than 900 Yuva volunteers to join this historic effort.</p>', '', 'basic_html'),
('event', 0, 176, 1370, 'en', 0, '<p>The MSDE-ISB Capacity Building Program concluded at the ISB Mohali campus last week.</p><p>&nbsp;</p><p>Mr. Praveen Pardeshi, Member Administration at Capacity Building Commission, GoI, addressed the cohort, as part of a series of capacity building initiatives across diverse organizations under MSDE. The cohort brought together MSDE officials, DGT officers, senior officials from various sector skill councils and representatives from NSDC.</p><p>&nbsp;</p><p>The curriculum was designed to equip participants with leading-edge capabilities, and an agile mindset to embrace the dynamics of an increasingly complex world.</p>', '', 'basic_html'),
('event', 0, 177, 303, 'en', 0, '<p>Capacity Building Commission members met the Minister of Rural Development and Panchayati Raj Shri Shandilya Giriraj Singh, MoS Smt. Sadhvi Niranjan Jyoti &amp; Shri Faggan Singh Kulaste &amp; discussed the need for capacity building interventions for the ministry.</p><p>&nbsp;</p><p>National Institute of Rural Development and Panchayati Raj presented its update for the ministers and the Commission.</p>', '', 'basic_html'),
('event', 0, 178, 304, 'en', 0, '<p>R Balasubramaniam had a discussion with Ministry of Woman and Child Development, minister Smt. Smriti Irani on making National Institute of Public Cooperation and Child Development a world-class training and research institute in the domain of women and child development.</p>', '', 'basic_html'),
('event', 0, 179, 305, 'en', 0, '<p>Capacity Building Commission members met the Secretary of the Ministry of Ports, Shipping and Waterways Shri Sanjeev Ranjan to discuss the recommendations of implementing the Annual Capacity Building Plan. The Minister welcomed the report recommendations and stressed on effective and timebound implementation of the ACBP and pointed out that such Capacity Building would be critical for success of PM GATI SHAKTI.</p>', '', 'basic_html'),
('event', 0, 180, 306, 'en', 0, '<p>Capacity Building Commission team visited the National Academy of Direct Taxes, a designated Central Training Institute for training of India Revenue Services.</p><p>&nbsp;</p><p>We conducted a workshop to deliberate on administration challenges faced by the CTIs. The subcommittee will work on developing policy recommendations for improving governance.</p>', '', 'basic_html'),
('event', 0, 181, 307, 'en', 0, '<p>Disom - The Leadership School Foundation visited the Capacity Building Commission.Dr. R Balasubramaniam spoke to them about Youth leadership and what they can do for the nation. I also shared about the work that CBC is undertaking and how it is working to build capacities in public administrators to deliver citizen-centric governance.</p>', '', 'basic_html'),
('event', 0, 182, 308, 'en', 0, '<p>The next wave of Green Revolution for India would ride on emerging technologies. The third-largest agricultural producer in the world, India is gearing up to build capacity in its agriculture labs to produce world-class research.</p><p>&nbsp;</p><p>Capacity Building Commission held a meeting with the Ministry of Agriculture &amp; Farmers Welfare, Government of India for the commencement of the Annual Capacity Building Plan and the training and capacity building program \"Krishi Karmayogi\".</p>', '', 'basic_html'),
('event', 0, 183, 309, 'en', 0, '<p>Capacity Building Commission had a discussion on the 7 Stages of leadership development at the Larsen &amp; Toubro Leadership Development Academy.</p>', '', 'basic_html'),
('event', 0, 184, 310, 'en', 0, '<p>Capacity Building Commission was invited by the State Government of Goa to conduct a workshop on Transformational Development Process through Institutional Reforms.The workshop was graced by Hon. Chief Minister Dr. Pramod Sawant, chaired by Hon. Chief Secretary and Secretaries of various departments, Directors, Collectors, and other civil servants.</p>', '', 'basic_html'),
('event', 0, 185, 311, 'en', 0, '<p>Capacity Building Commission interacted with the Chairman of University Grants Commission of India, Mamidala Jagadesh Kumar along with the Vice Chancellors of Public Universities (Central &amp; State) across India. Dr. R Balasubramaniam spoke about building knowledge partnerships for Capacity Building of Public Administration in India.</p>', '', 'basic_html'),
('event', 0, 186, 312, 'en', 0, '<p>As part of Mission Karmayogi, Capacity Building Commission hosted Senior Officials, including the Additional Secretaries, and Joint Secretaries from various Ministries to discuss the timelines and process for the Annual Capacity Building Plans (ACBPS) for their Ministries.</p>', '', 'basic_html'),
('event', 0, 187, 313, 'en', 0, '<p>Capacity Building Commission, held a kick-off meeting in collaboration with the IFC - International Finance Corporation (IFC) will be developing an integrated approach for enhancing capacity at the Urban Local Body (ULB) level.</p><p>&nbsp;</p><p>Annual Capacity Building Plans (ACBPs) will be created in select ULBs to enhance capacity at an individual, institutional and an organizational level.</p>', '', 'basic_html'),
('event', 0, 188, 314, 'en', 0, '<p>CBC launched the online training module with the Ministry of Finance andthe Department of Public Expenditure &amp; Reform, by Hon. Minister of Finance Nirmala Sitharaman. The training module uses gaming techniques, audio visuals, quizzes to&nbsp;convert complex rules of procurement of goods, services and works and General and Supplementary rules into easy-to-understand nuggets of learning.</p>', '', 'basic_html'),
('event', 0, 189, 315, 'en', 0, '<p>Hon\'ble Minister Bhupender Yadav, Ministry of Environment, Forests &amp; Climate Change, GoI with Secretary, Ms. Leena Nandan, DG Forests and Sh. SP Yadav, Member Secretary, Tiger Conservation Authority to present on the approach to Capacity Building with the objective to address national priority of increasing forested area, conserving biodiversity, and mitigating man wildlife conflict through broad based training and non-training interventions. The Capacity Building exercise will leverage the existing network of Forest Training institutions like Indira Gandhi National Forest Academy, Wildlife Institute of India, and Bombay Natural History Society (BNHS) and experts like Bivash Pandav and Bilal Habib.</p>', '', 'basic_html'),
('event', 0, 190, 1257, 'en', 0, '<p>Praveen Pardeshi (Member Admin) participated in field police training organized the Chandigarh Police. The DGP Chandigarh Praveer Ranjan, SP Chandigarh Ketan Bansal and SP Training Jaswinder and master trainers conducted training with great enthusiasm.</p>', '', 'basic_html'),
('event', 0, 191, 1048, 'en', 0, '<p>Capacity Building Commission, in collaboration with IFC - International Finance Corporation held a kickoff meeting with the Ahmedabad Municipal Corporation to develop an integrated approach for enhancing capacity at the Urban Local Body (ULB) level.</p>', '', 'basic_html'),
('event', 0, 192, 318, 'en', 0, '<p>Capacity Building Commission held an interaction with officer trainees of Indian Information Services at the Indian Institute of Mass Communication, Delhi.</p><p>&nbsp;</p><p>CBC\'s team met with future officers of Press Information Bureau - India, All India News, DDNews and other major publication divisions of the Government of India.</p>', '', 'basic_html'),
('event', 0, 193, 319, 'en', 0, '<p>Capacity Building Commission\'s Member (HR) R Balasubramaniam interacted with consultants working on the Annual Capacity Building Plans (ACBP) for the Social Sector Ministries and guided them on conducting the process to achieve national priorities for the various Ministries/Departments/Organizations.</p>', '', 'basic_html'),
('event', 0, 194, 320, 'en', 0, '<p>Capacity Building Commission, in collaboration with IFC - International Finance Corporation held a kickoff meeting with the Rajkot Municipal Corporation to develop an integrated approach for enhancing capacity at the Urban Local Body (ULB) level.</p>', '', 'basic_html'),
('event', 0, 195, 321, 'en', 0, '<p>We are delighted to open the “Documenting Indian History of Public Administration” portal; in association with Nehru Yuva Kendra Sangathan (India) and FLAME University.</p><p>&nbsp;</p><p>Inaugurated by Hon\'ble MP (RS) and President ICCR Dr. Vinay Sahasrabuddhe, in the presence of Shri Sanjay Kumar, Secretary Youth Affairs, Hemang Jani, Secretary CBC, Dr. R Balasubramaniam, Member (HR), CBC, Professor Yugank Goyal, Dr Jigar Champaklal Inamdar and more than 400 DYOs and State Directors of NYKS.</p><p>&nbsp;</p><p>This portal will help documenting local administrative histories from Indian documented histories, oral traditions, and many un-documented sources.</p><p>&nbsp;</p><p>It will feature in the Annual Report of Capacity Building Commission and in the Timeline of Indian Administration (which will be launched in due course).</p><p>&nbsp;</p><p>All citizens, civil servants (all groups), NYKS volunteers and staff are requested to join in this initiative and be part of narrating India’s centuries old administrative systems for the world.</p>', '', 'basic_html'),
('event', 0, 196, 322, 'en', 0, '<p>Capacity Building Commission along with Central Board of Direct Taxes in presence of Chairperson Sangeeta Singh and member Anuja Sarangi and various officials from Indian Revenue Service (IRS) planned to analyze data of income tax related public grievances related to incometax return and develop a robust training intervention which will enable the Assessment and appellate officers to proactively resolve the grievances. Guided by Hon PM Narendra Modi ji motto of citizen centric civil services.</p>', '', 'basic_html'),
('event', 0, 197, 323, 'en', 0, '<p>Capacity Building Commission visited the Ashoka Puram Training Center at the Mysuru Sub-Division of Railways.</p><p>&nbsp;</p><p>CBC\'s Member (HR) R Balasubramaniam spoke about how MissionKarmayogi enables citizen-facing Railway employees to implement Hon. PM\'s mandate of Citizen Centricity, making each and every railway employee a part of teamindia and a partner in the progress of our nation.</p>', '', 'basic_html'),
('event', 0, 198, 1049, 'en', 0, '<p>Capacity Building Commission attended a conference of all Zonal Training Institutes of National Academy of Customs, Indirect Taxes and Narcotics (NACIN, nacin.gov.in) with their Additional Director Generals on E-learning content creation strategy for iGOT.</p>', '', 'basic_html'),
('event', 0, 199, 325, 'en', 0, '<p>As part of capacity building work for the state of Madhya Pradesh – Sensitization Workshop on Citizen Centric Behavior for State Administrative Services and Revenue Department Officers was conducted at RCVP Noronha Academy of Administration &amp; Management, Bhopal (academy.mp.gov.in). The event was chaired by Smt. Deepti Gaur Mukherjee, IAS, Principal Secretary (Personnel) General Administration Department, Government of Madhya Pradesh.</p><p>During the workshop, Dr. R Balasubramaniam shared his thoughts on significance, relevance, and impact of citizen-centric behavior. The workshop further comprised group discussion by the participating officers of State Administrative Services and Revenue Department on ways through which a civil servant can become citizen friendly, empathetic towards peers, superiors as well as subordinates and ways of lateral integration with other departments for healthy field relations.</p>', '', 'basic_html'),
('event', 0, 200, 326, 'en', 0, '<p>Ladakh Police facilitated by Capacity Building Commission have completed behavior training of 200 or the 250 frontline police personnel: the results are increased professional handing of investigation, recording of evidence scientifically as narrated by this Inspector Jamgiang Namgyal.</p>', '', 'basic_html'),
('event', 0, 201, 327, 'en', 0, '<p>Ladakh Police in partnership with Capacity Building Commission with support of Illumine Knowledge Resources are bringing about attitudinal transformation in all the police personnel who man ten police stations and traffic post to make them professionally skilled and citizen centric building transformation police</p>', '', 'basic_html'),
('event', 0, 202, 328, 'en', 0, '<p>R Balasubramaniam and Illumine Knowledge Resources played critical role in course design. Ladakh has no training institutions of its own he was keen to know how Ladakh could implement its capacity building plans for various departments; Capacity Building Commission could facilitate partnership with institutions like Indian Institute of Public Administration and nearby state ATI like Haryana Institute of Public Administration.</p>', '', 'basic_html'),
('event', 0, 203, 329, 'en', 0, '<p>Police inspector Fazil Abbas, station in-charge received Capacity Building Commission to facilitateKarmayogi training one month ago. PI Fazil Abbas narrated many cases which he solved with deep empathy and personally enjoys the policing with Karmayogi outlook.</p>', '', 'basic_html'),
('event', 0, 204, 330, 'en', 0, '<p>Capacity Building Commission co-organized a workshop on \"Enhancing Teaching Capacities of Central Training Institutes\" with Sushma Swaraj Institute of Foreign Services.</p><p>&nbsp;</p><p>The workshop is a first step towards institutionalization of structured, need-based, and contextual Faculty Development Programs at Central Training Institutes (CTIs).</p>', '', 'basic_html'),
('event', 0, 205, 331, 'en', 0, '<p>Capacity Building Commission, in collaboration with IFC - International Finance Corporation held a kickoff meeting with the Bhubaneswar Municipal Corporation to develop an integrated approach for enhancing capacity at the Urban Local Body (ULB) level.</p>', '', 'basic_html'),
('event', 0, 206, 332, 'en', 0, '<p>We were happy to host and have an insightful meeting with The World Bank\'s Governance Division, Hoon Soh.</p><p>&nbsp;</p><p>Discussions were held on the importance of having a forum for conversations on public sector capacity enhancement, collaborations, and exchange of learnings with other countries, and building meaningful partnerships.</p>', '', 'basic_html'),
('event', 0, 207, 333, 'en', 0, '<p>Technologies are the New Humanities\" - says Capacity Building Commission\'s Secretary Hemang Jani delivering a lecture on the role of technology and the process of propelling India\'s Economy 2.0 by leveraging emerging technology adoption to the new batch of Foreign Service Officers.</p>', '', 'basic_html'),
('event', 0, 208, 334, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani spoke at the India Stack Knowledge Exchange (ISKE) \"Technology Stack for Skilling\" session about transforming the civil service training landscape by leveraging iGOT (Integrated Government Online Training) - the government\'s bespoke civil service training technology platform.</p>', '', 'basic_html'),
('event', 0, 209, 335, 'en', 0, '<p>Capacity Building Commission hosted Temasek Foundation and had enriching discussions about the importance of having regional dialogues and the significance of ownership at a local level for public sector transformations.</p>', '', 'basic_html'),
('event', 0, 210, 336, 'en', 0, '<p>Capacity Building Commission held a meeting with the Ministry of Jal Shakti, the National Water Academy (NWA Pune, nwapune.gov.in), North-Eastern Regional Institute of Water and Land Management (NERIWALM Tezpur, neriwalm.gov.in) and Rajiv Gandhi Ground Water Training &amp; Research Institute (RGI Raipur, ngwtri.org).</p><p>&nbsp;</p><p>We are working with the Ministry of Jal Shakti, Department of Water Resources, RD &amp; GR, Govt. of India for creating synergies in capacity building of the three training institutes.</p>', '', 'basic_html'),
('event', 0, 211, 1398, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani delivered the valedictory address for Executive Development Programme for Assistant Director Generals and Directors/Joint Directors operating at various institutes of ICAR-National Academy of Agricultural Research Management (NAARM). Their efforts are a step forward in fulfilling the nation’s vision of integrating the farmers in the supply chain of farm-to-plate.</p>', '', 'basic_html'),
('event', 0, 212, 338, 'en', 0, '<p>Capacity Building Commission\'s Member (HR) R Balasubramaniam held an Annual Capacity Building Plan (ACBP) Orientation Workshop for the Department of Higher Education (www.education.gov.in), in the presence of Secretary Sh. K Sanjay Murthy.</p>', '', 'basic_html'),
('event', 0, 213, 339, 'en', 0, '<p>Capacity Building Commission held exploratory conversations with Nanyang Technological University Singapore for capacity building of science and technology departments.</p>', '', 'basic_html'),
('event', 0, 214, 340, 'en', 0, '<p>Union Home Secretary Shri Ajay Bhalla launched Mission Karmayogi in Delhi Police Department by training over 37,000 policemen who provide security and safety to Delhi’s citizens. The behavioral and professional training is facilitated by Capacity Building Commission and is pedagogically curated by Member (HR) R Balasubramaniam. Over 350 police master trainers carefully selected by Special CP Sundari Nanda are being intensively trained as Delhi Police training school.</p>', '', 'basic_html'),
('event', 0, 215, 341, 'en', 0, '<p>Capacity Building Commission welcomed two Assistant Secretaries (IAS) of 2020 batch posted in Department of Personnel and Training (DoPT, dopt.gov.in).CBC team and the young officers had detailed discussions on various aspects of the capacity building ecosystem, and they spoke about their own experiences as Officer Trainees (OTs).</p><p>&nbsp;</p><p>The Assistant Secretary (AS) program was the brainchild of Hon’ble PM Narendra Modi; started in 2015, with an objective to expose young IAS offices to the working of the Union Government before they are posted in their respective cadres\' districts.CBC Chairman, Members, Secretary, and team wished them luck for their new role in contributing towards making New India a reality.</p>', '', 'basic_html'),
('event', 0, 216, 342, 'en', 0, '<p>Capacity Building Commission\'s Member (HR) R Balasubramaniam visited the Chandigarh Police\'s Recruit Training Centre for the \"Karmayogi Police - Custodians of Society\" Large Scale Intervention.</p><p>He spoke about Hon\'ble PM Narendra Modi\'s vision of citizen centricity, focusing on addressing the immediate concerns of citizens i.e., cooperation, efficiency, stability, and continuity in the governance systems.</p>', '', 'basic_html'),
('video_gallery', 0, 217, 1190, 'en', 0, '<p>NLW 2024 Video-1</p>', '', 'full_html'),
('video_gallery', 0, 218, 344, 'en', 0, '<p>Dr. Balasubramaniam shares perspectives on National Learning Week and human resource development.</p>', '', 'full_html'),
('video_gallery', 0, 219, 1393, 'en', 0, '<p>Former CEO-KB, Secretary - CBC on National Learning Week Video</p>', '', 'full_html'),
('video_gallery', 0, 220, 1184, 'en', 0, '<p>Dr. Alka Mittal (Member Admin- Capacity Building Commission) on National Learning Week</p>', '', 'full_html'),
('video_gallery', 0, 221, 1183, 'en', 0, '<p>Adil Zainulbhai (Former Chairperson- Capacity Building Commission) on National Learning Week</p>', '', 'full_html'),
('opinions_do_matter', 0, 222, 348, 'en', 0, '<p class=\"opinion-card-designation\">NLC India Limited, Ministry of Coal</p><p class=\"opinion-card-description\">A participant from NLC India Limited shares their commitment to ensuring positive impact on citizens through their actions.</p>', '', 'full_html'),
('opinions_do_matter', 0, 223, 349, 'en', 0, '<p>This training gave me valuable new insights and made me feel excited about my role as a lead trainer under the National Karmayogi initiative. The most important learning for me was understanding that the spirit of service already exists within everyone. It is not something that is absent, it only needs to be awakened. I also feel more connected to how my work and my customers contribute to serving the nation through what they create. This realization has been the biggest takeaway for me.</p>', '', 'basic_html'),
('opinions_do_matter', 0, 224, 350, 'en', 0, '<p>This program helped me with self reflection and changed the way I view my work. Earlier, I saw it as a process driven activity, but now I understand it as purpose driven work. Through our daily activities, we are contributing towards nation building.</p>', '', 'basic_html'),
('opinions_do_matter', 0, 225, 351, 'en', 0, '<p>The National Karmayogi training program completely changed my perspective. Earlier, I saw my work as just a responsibility, but now I see my role as an opportunity to contribute to nation building through my daily duties. This training made me feel proud to be a part of the country\'s development, and I am committed to sharing this spirit with my colleagues.</p>', '', 'basic_html'),
('opinions_do_matter', 0, 226, 352, 'en', 0, '<p>Earning the prestigious 5-star \"Sarvotkrisht\" rating under CBC\'s National Standards for Accreditation has been nothing short of transformational for NCA-F. CBC\'s rigorous and comprehensive parameters compelled us to critically examine every dimension of our work—recognizing gaps, strengthening processes, and institutionalizing sustainable interventions and SOPs that have significantly elevated our operational excellence.</p><p>The QIP facilitated by CBC was equally invaluable, sharpening our focus and driving measurable improvements across the board. Our greatest takeaway from this journey has been a powerful one: the process itself is as meaningful as the achievement. While we are immensely proud to have earned the highest rating, the experience has also ignited within us a renewed commitment to strive higher, improve continually, and keep raising the bar for ourselves.</p><p><!-- Quote Box -->&nbsp;\"The process itself is as meaningful as the achievement. While we are immensely proud to have earned the highest rating, the experience has also ignited within us a renewed commitment to strive higher, improve continually, and keep raising the bar for ourselves.\"</p><p>CBC\'s rigorous and comprehensive parameters compelled us to critically examine every dimension of our work—recognizing gaps, strengthening processes, and institutionalizing sustainable interventions and SOPs that have significantly elevated our operational excellence. The QIP facilitated by CBC was equally invaluable, sharpening our focus and driving measurable improvements across the board.</p>', '', 'basic_html'),
('opinions_do_matter', 0, 227, 353, 'en', 0, '<p>When I first encountered the idea of Mission Karmayogi, it did not strike me as a reform. It felt more like a reminder — that governance is, at its heart, an act of seva. It is not about the pursuit of recognition or reward, but about the quiet satisfaction, the santushti, that comes from doing one\'s work with sincerity.</p><p>At the heart of this Mission lies a transformative truth: that the strength of our administrative system rests not in its rules, but in its people. For me, capacity building is not treated as a box to be ticked, but as a culture to be nurtured. I wanted to build a workplace where learning is as natural as conversation, and as inclusive as a shared lunch table. It is an act of curiosity that connects every role, every reform, to a larger purpose: Jan Seva and Viksit Bharat @ 2047.<!-- Quote Box --></p><p>\"We often seek reward before effort and ask, \'Mujhe kya milega?\' Yet the truth remains unchanged — kaam karoge, tab apne aap mil jaayega. The act of doing one\'s duty with sincerity brings its own reward. Real recognition is not given; it is earned in the quiet pride of contribution and the lasting satisfaction of service.\"</p><p>In my tenure as the Secretary of the Department of Legal Affairs, I successfully concluded Phases I and II of the Rashtriya Karmayogi Jan Seva Program, through 20 batches, marking a major milestone in its capacity-building journey, and achieving 100% saturation. Every officer, contractual employee, and even our MTS colleagues came together — because no one is too junior to learn, and no one is too senior to listen.</p><p>We have learned that progress doesn\'t always need paperwork and structure alone cannot change culture. At DLA, each week I used to host Chai Pe Charcha, an informal huddle with Group Heads to take stock of ongoing initiatives. It\'s simple, human, and astonishingly effective. Concerns are voiced openly; ideas are exchanged freely. Hierarchy pauses, and insight steps forward.</p><p>Another space that has redefined our internal culture is our monthly Tiffin Baithak, inspired by our Hon\'ble Prime Minister, Shri Narendra Modi. What began as an informal lunch gathering with the Law Secretary became a forum for cross-learning and collective problem-solving. Around shared meals, officers discuss challenges, exchange thoughts, and often end up finding solutions that meetings never could.</p><p><!-- Quote Box -->\"In our Department, we wanted learning to feel aspirational, not obligatory. We began recognising officers across all levels for their milestones on the iGOT platform — not through ceremonies, but through personal acknowledgment and conversation. The best part? When an officer, after completing a course, says, \'Madam, ab mujhe samajh mein aaya ki hum kya kar rahe hain\' — that sense of connection between their task and the larger purpose of governance — that is where Mission Karmayogi truly begins.\"</p><p>During my tenure, I also made small but meaningful structural changes within the Department premises. The Conference Room has been renamed \"Karmayogi Sabhagar\"; administrative sections have been renamed under the four Sankalp values of the Hon\'ble PM: Ekta, Vikas, Garv and Kartavya. These are not mere signboards, but daily reminders of who we are and why we serve.</p><p>I believe capacity building is not a program that begins and ends with a calendar, it is a relay. Each of us runs our lap, carries the baton for a while, and how sincerely we run our lap determines the strength of what we pass on. The baton we hold is not just of responsibility, but of seva bhav.</p><p>As we look ahead, our goal remains simple: to make our offices not just functional, but living classrooms of innovation, empathy, and excellence — where knowledge circulates freely, curiosity is encouraged, feedback is welcomed and where santushti defines success as a public servant.</p><p><!-- Final Quote Box -->That, to me, is the true meaning of reform:<br>Not loud change, but lasting change.<br>Not compliance, but conviction.<br>Not recognition, but santushti.</p>', '', 'basic_html');
INSERT INTO `node__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('opinions_do_matter', 0, 228, 354, 'en', 0, '<p>Rafi Ahmed Kidwai National Postal Academy (RAKNPA) is humbled and delighted at the same time on being accredited as the first Central Training Institute (CTI) to receive a prestigious 5-Star rating from the Capacity Building Commission (CBC).</p><p>This was the culmination of a transformative journey which began in June 2023 when the Academy received a 2-Star rating. Recognizing the need for improvement from that start, we aligned our efforts with the vision of Mission Karmayogi, with constant and patient guidance from the CBC team to refine our systems and training methodologies.</p><p>The accreditation process was itself a transformative journey for us, illuminating the path across all eight pillars of the National Standards for Civil Service Training Institutions (NSCSTI). We focused on critical areas such as Training Needs Assessment, faculty development, and digitization, which enabled us to standardize procedures and streamline our training processes.</p><p>By delegating key administrative and financial powers, we enhanced our institutional efficiency, fostering a more effective training environment. Significant upgrades, including digitally-enabled classrooms, a comprehensive Learning Management System, the Karmayogi Digital Learning Lab, and the Virtual Immersive Learning Lab, have enriched our content creation and training delivery.</p><p>Additionally, the integration of Indian Knowledge Systems has allowed us to infuse cultural and ethical perspectives, rooted in India\'s rich civilizational heritage, into our training environment. The CBC accreditation is not a mere assessment - it has been a journey of continuous improvement. RAKNPA remains steadfast in its commitment to nurturing capable, ethical, and future-ready civil servants for our nation.</p><p><!-- Karmayogi Digital Learning Lab Section --><strong>&nbsp;Karmayogi Digital Learning Lab</strong></p><p>Established on March 06, 2024, an innovative platform dedicated to revolutionizing e-content development.</p><p>State of the Art addition towards accomplishing the National Program for Civil Services Capacity Building (Mission Karmayogi)</p><p>Capability to record live videos, thereby converting them into eLearning content Designed to empower the Academy to produce high-quality, engaging training material efficiently and effectively.</p><p>Developed more than 100 quality courses in English and Hindi like: Post Office Act, 2023, Know Your Ministry - Department of Posts, Profit Centricity in Postal Services</p>', '', 'basic_html'),
('event', 0, 229, 355, 'en', 0, '<p>Capacity Building Commission\'s Member (HR) R Balasubramaniam and Secretary Hemang Jani spoke about capacity building, citizen centricity, overcoming challenges in the information and broadcasting sector and the future of communication technologies at the 3rd Annual Conference of Indian Information Services Officers.</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 230, 1550, 'en', 0, '<p>Valedictory of 100 Hrs to Mission Karmayogi for Lakshadweep Police</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 230, 1550, 'hi', 0, '<p>लक्षद्वीप पुलिस के लिए 100 घंटों के मिशन कर्मयोगी अभियान का समापन विदाई समारोह</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 231, 357, 'en', 0, '<p>The 𝗠𝗶𝗻𝗶𝘀𝘁𝗿𝘆 𝗼𝗳 𝗔𝘆𝘂𝘀𝗵 organized its first 𝐓𝐢𝐟𝐟𝐢𝐧 𝐁𝐚𝐢𝐭𝐡𝐚𝐤 under Mission Karmayogi. This informal interactive session was held under the Secretary, Ministry of Ayush, bringing together officers from different divisions.</p>', '', 'basic_html'),
('event', 0, 232, 358, 'en', 0, '<p>Hon’ble Prime Minister Narendra Modi has initiated a unique program of making the newly inducted IAS officers as Assistant Secretary in the Government of India before they go to their respective States.</p><p>&nbsp;</p><p>This is a unique opportunity for a young officer to experience the working of central government where many of them will reach after at least a decade of working at the ground level.</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 233, 1553, 'en', 0, '<p>The Capacity Building Commission (CBC) is proud to share that the Rashtriya Karmayogi Jan Seva Program has trained over 10,00,000 Government officials across the country cumulatively, in Phase I and Phase II of the program.</p><p>This milestone marks a significant advancement in embedding the spirit of Seva Bhav and the ethos of a Karmayogi across India’s administrative landscape. By strengthening purpose, intent, and service orientation at scale, the program continues to contribute meaningfully to the larger vision of citizen-centric governance.</p><p>CBC acknowledges the efforts of all Ministries, Departments, Organisations, and every participating official for their active engagement and support. Your dedication has transformed this initiative into a powerful movement for behavioural transformation in Government.</p><p>Together, we move closer to building a more responsive, empathetic, and service-oriented governance ecosystem.</p>', '', 'full_html'),
('our_collaboration_matters', 0, 233, 1553, 'hi', 0, '<p>क्षमता विकास आयोग को यह बताते हुए गर्व हो रहा है कि राष्ट्रीय कर्मयोगी जन सेवा कार्यक्रम ने देश भर में कुल मिला कर 10,00,000 से ज्यादा सरकारी कार्मिकों को प्रथम और द्वितीय चरण में प्रशिक्षण प्रदान किया है...&nbsp;</p>', '', 'full_html'),
('our_collaboration_matters', 0, 234, 1552, 'en', 0, '<p>Congratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 234, 1552, 'hi', 0, '<p>सीबीसी द्वारा किए गए क्यूआईपी कार्यान्वयन के बाद 5 स्टार रेटिंग के साथ पुनः प्रत्यायित होने पर रफी अहमद किदवई राष्ट्रीय पोस्टल अकादमी को बधाई। क्षमता विकास आयोग संस्थाओं को देखकर गौरवान्वित है...</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 235, 1551, 'en', 0, '<p>Congratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'basic_html'),
('our_collaboration_matters', 0, 235, 1551, 'hi', 0, '<p>सीबीसी द्वारा किए गए क्यूआईपी कार्यान्वयन के बाद 5 स्टार रेटिंग के साथ पुनः प्रत्यायित होने पर रफी अहमद किदवई राष्ट्रीय पोस्टल अकादमी को बधाई। क्षमता विकास आयोग संस्थाओं को देखकर गौरवान्वित है...</p>', '', 'basic_html'),
('event', 0, 242, 368, 'en', 0, '<p>MissionKarmayogi making an impact across India!</p><p>&nbsp;</p><p>Capacity Building Commission was invited by the State Government of Assam to conduct a one-day workshop on \'Transformational Development Process through Institutional Reform\'.</p><p>&nbsp;</p><p>The workshop was chaired by Hon. Chief Secretary of Assam Jishnu Barua and attended by all Secretaries, Commissioners and Department heads. This workshop included breakout sessions with police, industries, rural development, forest, and the Administrative Training Institute followed by a keynote speech by CBC Member (HR) R Balasubramaniam on leadership skills.</p><p>&nbsp;</p><p>Assam State Government is geared up to implement the capacitybuilding initiatives under MissionKarmayogi</p>', '', 'basic_html'),
('event', 0, 243, 369, 'en', 0, '<p>Capacity Building Commission\'s team visited ICAR-National Academy of Agricultural Research Management (NAARM) Hyderabad campus. Potential&nbsp;collaborations for capacity building of science and technology departments and civil services institutes were explored.</p>', '', 'basic_html'),
('event', 0, 244, 379, 'en', 0, '<p>Capacity Building Commission hosted nodal officers from 25 Central Training Institutions (CTIs) and 20+ Administrative Training Institutions (ATIs) at the National Institute of Communication Finance (NICF, nicf.gov.in) for a one-day workshop and training session of the National Standards for Civil Service Training Institutions portal (NSCSTI, cbc.gov.in).</p><p>&nbsp;</p><p>This workshop was inaugurated at the hands of Shri Devusinh Chauhan, Minister of State for Communications.</p><p>&nbsp;</p><p>This portal will help the Government of India to set common standards of excellence, promote organizational improvement through continuous self-assessment, enhance civil service capacity building with templates, institutionalize a forum to highlight best-practices and collaborative learning, and give direction for long-term strategic planning.</p>', '', 'basic_html'),
('event', 0, 245, 380, 'en', 0, '<p>IIT Bombay is delighted to complete capacity-building program entitled Highways for 21st Century India – Modern Technologies for Highways for Morth India in partnership with Indian Academy of Highway Engineering and NHAI INDIA. IIT Bombay feels humbled that the Hon’ble Minister Gadkari Nitin took time from his busy schedule to interact with the participants and encouraged them to adopt innovative technologies to enhance quality, improve sustainability, reduce cost, and increase speed of execution.</p><p>&nbsp;</p><p>The program was conducted in partnership with Capacity Building Commission under Mission Karmayogi. Among topics were Bridges for 21st Century, Accelerated Bridge Construction, Ultra High-Performance Concrete, Fiber Reinforced Bars, Perpetual Pavement, and Structural Health Monitoring. Secretary Giridhar Aramane extolled the participants to implement the lessons from the program.</p>', '', 'basic_html'),
('event', 0, 246, 381, 'en', 0, '<p>The Secretary, CBC participated in a panel discussion on future of MyGov alongside Shri Parameswaran Iyer, CEO Niti Aayog, Shri Amitabh Kant, G20 Sherpa and Shri Abhishek Singh, CEO MyGov.</p><p>&nbsp;</p><p>‘MyGov India has created a strong layer of trust between the citizen and government besides a strong technology layer for engagement’ said Secretary, CBC Hemang Jani</p><p>&nbsp;</p><p>MyGov is one of the most successful citizen engagementplatforms globally. The vision of Hon’ble PM to take every citizen service and information to the doorstep of people has been made possible by MyGov since last eight year.</p>', '', 'basic_html'),
('event', 0, 247, 382, 'en', 0, '<p>We are excited to announce that the Ministry of Skill Development and Entrepreneurship, India and Microsoft have entered an MoU with Capacity Building Commission.</p><p>&nbsp;</p><p>Microsoft for this initiative have developed self-paced learning courses on the Office 365 Suite, enabling CBC and MSDE to provide digital productivity skills to enhance functional computer literacy, and to provide efficient and effective citizen-centric services for nearly 3 million civil servants of the Government of India.</p>', '', 'basic_html'),
('event', 0, 248, 383, 'en', 0, '<p>Capacity Building Commission participated in the meeting at National Institute of Rural Development and Panchayati Raj (NIRDPR), Hyderabad on preparation of the National Capacity Building Framework (2022) and Training of PRIs functionaries by NIRDPR.</p>', '', 'basic_html'),
('event', 0, 249, 384, 'en', 0, '<p>Capacity Building Commission held a kickoff meeting with the Mysore City Corporation to develop an integrated approach for enhancing capacity at the Urban Local Body (ULB) level.</p>', '', 'basic_html'),
('event', 0, 250, 385, 'en', 0, '<p>Capacity Building Commission hosted a ‘Brainstorming Workshop on Capacity Building Plan for Ministry of Environment, Forests &amp; Climate Change, Government of India</p><p>&nbsp;</p><p>40+ participants from stakeholder organizations (Directorate of Forest Training Education (DFE), Indira Gandhi National Forest Academy (IFNFA), Central &amp; State Forest Training Intuitions) deliberated with domain experts from Wildlife Institute of India, Legal Initiative for Forest and Environment, Hiware Bazar on issues of enhancing capacity of Central and State Forest Services.</p><p>&nbsp;</p><p>Breakout sessions lead by Domain experts covered various topics such as</p><p>• Community participation in forest conservation,</p><p>• Forest and wildlife laws,</p><p>• Enhancing governance and faculty development,</p><p>• Field good practices in re-wilding natural forest</p><p>• Wildlife human conflict mitigation</p><p>&nbsp;</p><p>The workshop focused on building Integrated approach towards capacity building of forest services.</p>', '', 'basic_html'),
('event', 0, 251, 386, 'en', 0, '<p>Capacity Building Commission\'s Member (HR) R Balasubramaniam held interactions for institutional assessment with the faculty at Rajiv Gandhi National Institute of Youth Development at Sriperumbudur, Chennai.</p>', '', 'basic_html'),
('event', 0, 252, 387, 'en', 0, '<p>Secretary Capacity Building Commission and Director General Development Monitoring and Evaluation Office (DMEO) NITI Aayog at NITI Aayog signed an MoU for collaboration on various capacity building initiatives in data governance, monitoring and evaluation for the various departments of Government of India.</p>', '', 'basic_html'),
('event', 0, 253, 388, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani spoke about Mission Karmayogi, capacity building and reforms in governance at the \"Bringing Citizens and Government Closer through Administrative Reforms\" conference, held at Niti Vihar, Itanagar, Arunachal Pradesh.</p>', '', 'basic_html'),
('event', 0, 254, 389, 'en', 0, '<p>Shri Dr. P.K Mishra, Principal Secretary to Hon. PM Narendra Modi, visited and interacted with the team at Capacity Building Commission yesterday evening.</p><p>He addressed the CBC Team and shared Hon PM’s vision for Capacity Building Commission and Mission Karmayogi.</p><p>He provided valuable guidance and advice for capacity building of Ministries and States, following a citizen-centric training approach and for enabling Karmayogi Civil Servants.</p><p>The team also briefed him about its pilots of various types of training and capacity building activities and the recently launched National Standards for Civil Service Training Institutions to improve the quality of supply side of the capacity building eco-system in the country.</p>', '', 'basic_html'),
('event', 0, 276, 415, 'en', 0, '<p>We are delighted to announce that ISPP has signed an agreement with Capacity Building Commission to develop case studies on 30 success stories of innovations in public administration, to be featured in the Annual Health of Civil Service Report. This project would be housed at the ISPP Case Study Centre.</p>', '', 'basic_html'),
('event', 0, 277, 416, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani and Director General, IIPA (Official), Surendra Nath Tripathi called on to Hon. Governor of Arunachal Pradesh, Brigadier (Dr.) B. D. Mishra (Retd) on the sidelines of the \"Bringing Citizens and Government Closer through Administrative Reforms\" conference, at Niti Vihar, Itanagar, Arunachal Pradesh</p>', '', 'basic_html'),
('event', 0, 278, 418, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani participated in a panel discussion at the Nanyang Technological University Singapore - India Dialogue on Technology, Innovation and Entrepreneurship. The seminar was on the Singapore-India Technopreneurship Partnership.</p>', '', 'basic_html'),
('event', 0, 280, 421, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani welcomed the USIBC - US India Business Council global board members for their annual meeting in Delhi this year. He explained the key tenets of Mission Karmayogi and its lasting impact on enhancing the state capacity.</p>', '', 'basic_html'),
('event', 0, 378, 521, 'en', 0, '<p>A pre-workshop discussion was held in the presence of Smt. Chandralekha Mukherjee, Principal Advisor, Capacity Building Commission, and Shri Sachin Sinha, DG–RCVP Noronha Academy, Bhopal. Department HODs and senior officials presented their draft Capacity Building Plans, receiving key guidance for finalisation.</p>', '', 'basic_html'),
('event', 0, 379, 523, 'en', 0, '<p>Chairperson, CBC, Ms S. Radha Chauhan and Chief Secretary, Government of Madhya Pradesh, Shri Anurag Jain address the State‑Level Capacity‑Building Plan Development Workshop conducted at RCVP Noronha &nbsp;Academy of Administration and Management, Bhopal, Madhya Pradesh.</p><p>The Chairperson highlighted the paradigm shift towards role and demand-based training. She said that these departmental Capacity‑Building Plans will facilitate the training of cadres in their respective departments and aim to enhance the capacities of officials through role‑based, demand‑led training courses/programmes.</p><p>The Chief Secretary advised departmental heads to make modifications as required while finalising the capacity building plans. DG of ATI, Shri Sachin Sinha emphasised upon continuous learning, unlearning and re-learning. Shri Sanjay Shukla, ACS, General Administration Department, was also present at the workshop.</p><p>In the pre‑workshop exercises, around 29 key departments and their 60 sub‑departments/directorates /boards/authorities –89 in total – prepared Capacity‑Building Plans covering 1,089 unique designations.</p><p>This first‑of‑its‑kind workshop in the nation marks another milestone towards state‑level capacity building, bringing Madhya Pradesh to the forefront of capacity‑building initiatives under Mission Karmayogi.</p><p><strong>Event Venue</strong></p><p>RCVP Noronha Academy of Administration and Management, Bhopal, Madhya Pradesh.</p>', '', 'basic_html'),
('event', 0, 380, 1249, 'en', 0, '<p>The Pre-Workshop on Capacity Building Plan Development was conducted today in the presence of Ms. Rehana Batool, Director General, along with her team from the Jammu &amp; Kashmir Institute of Management, Public Administration and Rural Development (J&amp;K IMPARD) and Smt. Chandralekha Mukherjee, Principal Advisor, and her team from the Capacity Building Commission.</p><p>Looking forward to the collaborative efforts ahead and to translate these discussions into impactful outcomes for the region.</p>', '', 'basic_html'),
('event', 0, 381, 1278, 'en', 0, '<p>Rashtriya Karmyogi Jan Seva Program - 8,00,000 Government officials trained.</p><p>The Capacity Building Commission (CBC) is proud to share that the Rashtriya Karmyogi Jan Seva Program has trained over 8,00,000 Government officials across the country in one-day training, along with 16,000 Master Trainers and 822 Lead Trainers.</p><p>Phase II of the program, launched in May 2025, with an aim of training about 7,00,000 Government officials, has been completed, which is a testament to the enthusiasm and commitment of government employees nationwide.</p><p>This milestone marks a significant advancement in embedding the spirit of Seva Bhav and the ethos of a Karmyogi across India’s administrative landscape. By strengthening purpose, intent, and service orientation at scale, the program continues to contribute meaningfully to the larger vision of citizen-centric governance.</p><p>CBC acknowledges the efforts of all Ministries, Departments, Organisations, and every participating official for their active engagement and support. Your dedication has transformed this initiative into a powerful movement for behavioural transformation in Government.</p><p>Together, we move closer to building a more responsive, empathetic, and service-oriented governance ecosystem.</p>', '', 'basic_html'),
('event', 0, 382, 527, 'en', 0, '<p>Jammu &amp; Kashmir: One-Day Workshop on Developing Capacity Building Plans In collaboration with the CBC, the Institute of Management, Public Administration and Rural Development (IMPARD), Jammu &amp; Kashmir, organised a one-day workshop on the Development of CBPs.</p>', '', 'basic_html'),
('event', 0, 383, 529, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission visited Delhi Metro Rail Corporation (DMRC) Academy on 10.12.2025.</p><p>During her visit, she was given a brief presentation on the Academy and its facilities, providing her with an overview of its training capabilities and its centres of excellence. Following the presentation, the Chairperson visited the Academy’s state-of-the-art training infrastructure, which included Computer Based Training Lab, Model Rooms, Digital Library, Driving &amp; Maintenance Simulators etc.</p><p>Shri Ghansham Bansal, Director General, DMRC Academy was also present on the occasion.</p>', '', 'basic_html'),
('event', 0, 384, 530, 'en', 0, '<p>Dr. Alka Mittal, Member, Capacity Building Commission (CBC), delivered the address at the National Conference on the Role of Young Generation &amp; Women in a Strong and Vibrant Indian National Power Grid, held in New Delhi today. She highlighted the aspect of value-driven leadership grounded in integrity, empathy and fairness, and stressed upon the need for courage in decision-making by taking tough calls with accountability.</p><p>Emphasizing upon a people-centric approach, Dr Mittal highlighted the importance of listening and empathy in large organizations. She urged leaders to broaden their strategic outlook by moving from an operational to an organizational perspective and aligning personal vision with institutional goals.</p><p>For emerging leaders, she advised investing in continuous learning, building resilience by viewing failure as feedback, communicating with authenticity, and developing a personal leadership brand anchored in strong values, reminding everyone that “Leadership is not about titles; it’s about influence and impact.”</p><p>During her address, she also mentioned that the Capacity Building Commission is associating itself with the DPE, SCOPE and the PSE leadership to evolve a strategic HR ecosystem for aligning it with the National Development Goals.</p><p>She concluded with a call to action: “Lead with courage, compassion and conviction &amp; always walk the talk.”</p>', '', 'basic_html'),
('event', 0, 385, 531, 'en', 0, '<p>Capacity Building Commission organises National Workshop on “Future Readiness of Central Training Institutes”.</p><p>Training Institutes need to reimagine, revamp and re-define their roles in ever evolving training eco-system, says Ms S Radha Chauhan, Chairperson CBC at the inaugural session. She added that training needs to be dynamic focussing on learning, unlearning and re-learning. The Chairperson highlighted the significance of human element that needs to play its role in meeting the aim of citizen-centric governance for Viksit Bharat, within the overall technology-driven environment.</p><p>Ms Chandralekha Mukherjee, Principal Advisor, CBC made a detailed presentation on the future readiness of Central Training Institutes. She shared that now five (5) CTIs are rated 5-star as per the NSCSTI 2.O framework. She added that focus now moves beyond ratings towards Centres of Excellence, Competency-driven training and citizen-centric outcomes.</p><p>Former Chairman, CBC, Sh Adil Zainulbhai while addressing virtually said that going ahead, TIs need to aim for becoming five-star rated world-class training institutes; collaborate among themselves and with educational institutes &amp; think tanks; and become leaders in integrating physical &amp; digital training eco-system.</p><p>Mr. Rakesh Verma, COO, KB, introduced the AI-enabled CBP tool, highlighting its potential to support institutes in designing competency-driven training plans aligning with the dynamic needs of Training Institutes, MDOs.</p><p>Key feature of the workshop were three parallel breakout sessions, which enabled focused deliberations on critical aspects of future readiness on the topics Building Excellence through Roles, Responsibilities, and Technology-Enabled Training Quality, Strengthening the NSCSTI Framework &amp; Enabling Resource Pooling and Enhancing Courses on iGOT through AI tools &amp; Domain Course Identification. The sessions were moderated by the Principal Advisor, CBC, Ms Chandralekha Mukherjee and senior faculty from CTIs, including, Ms Madhavi Das, DG, NCA-F, Ms Shanmuga Priya Mishra, Deputy Director (Sr), LBSNAA, Ms Archana Gopinath, Joint Director, RAKNPA, Sh Rakesh Verma, COO, KB, Ms Uma S., Advisor, CBC &amp; other team members from CBC. The findings from breakout sessions were presented before the audience leading to convergence on actionable recommendations and implementation pathways.</p><p>Dr. Alka Mittal, Member (Admin), CBC complimented all groups for their active engagement during discussions. She said that the institutes should not only sustain standards, but should play the role of mentors. She appealed that we should ensure that all of us come together.</p><p>Sh S. P. Roy, Secretary, CBC, reaffirmed CBC’s commitment to supporting CTIs in becoming agile, tech-enabled &amp; future-ready institutions under MK</p>', '', 'basic_html'),
('event', 0, 386, 1362, 'en', 0, '<p>Chairperson CBC emphasizes upon de-siloization of governance and democratization of learning. She highlighted the importance of embedding competency-based governance, leadership development, and performance-linked learning within CPSEs as part of India’s broader civil services reform agenda. The ethos of Karmayogi should imbibe in every delivery of public service, she said.</p><p>Dr Alka Mittal, Member, CBC underscores strategic role of CPSEs as critical institutions for nation-building. While setting the context of the Conclave, Dr Mittal underscored the strategic role of CPSEs as critical institutions for nation-building beyond their commercial mandate. She highlighted that CPSEs are not only engines of economic growth, but also custodians of public values, governance standards, and long-term institutional capability.</p><p>The inaugural address was delivered by Shri K Moses Chalai, Secretary, DPE, who highlighted the fact that leadership is very important and we need visionary leaders. He later added that we should be open to change and adopt good changes.</p><p>Members of the PESB Shri Alkesh Kumar Sharma and Shri Roop Narayan Sunkar also shared their key observations.</p><p>A strategic keynote session was delivered by Dr. C. Jayakumar, Executive Vice President &amp; Head, Corporate Human Resources, Larsen &amp; Toubro (L&amp;T) Ltd on “HR Strategies for Purpose-Driven Leadership”, focusing on building resilient leadership pipelines and aligning organisational values with national priorities.</p><p>This was followed by a presentation on DAKSH by Shri Atul Sobti, DG, SCOPE, outlining a structured framework for leadership development, succession planning, and HR reforms in CPSEs.</p><p>Secretary, MNRE, Shri Santosh Kumar Sarangi, Dr R Balasubramaniam, Member (HR), CBC, CEO Karmayogi Bharat (KB) Ms Chhavi Bhardwaj, senior officials from DPE, Ministries &amp; CBC were also present during the inaugural session.</p><p>The conclave featured focused roundtable discussions on “Reimagining HR Systems for High-Impact CPSE Performance” and “Translating Vision into Action: CPSE HR Strategy” where participants emphasised the need for institutionalised collaboration, shared knowledge platforms, and integrated capacity-building efforts to enhance efficiency, innovation, and public value creation beyond financial returns.</p><p>The program concluded with closing reflections by Shri S. P. Roy, Secretary, CBC who said that CBC is always committed to support capacity building initiatives of CPSEs. The vote of thanks was delivered by Ms Navneet Kaur, Director, CBC.</p><p>The CBC will also bring the Training Institutes, PSUs and States on a common platform for collaboration aligned with Karmayogi capacity building efforts across governance space.</p>', '', 'basic_html'),
('event', 0, 391, 1280, 'en', 0, '<p>The Capacity Building Commission (CBC) organises National Consultative Workshop on Karmyogi Quality Framework</p><p>Aims to Strengthen Quality of Digital Learning for Civil Servants</p><p>Strong quality framework critical for building future-ready civil servants for Viksit Bharat: Ms S. Radha Chauhan<br><br>https://www.pib.gov.in/PressReleasePage.aspx?PRID=2206695&amp;reg=3&amp;lang=1</p>', '', 'basic_html'),
('event', 0, 392, 543, 'en', 0, '<p>Dr Alka Mittal, Member, Capacity Building Commission, addressed at the workshop on “Decoding Labour Codes – Understanding the New Era of Labour Reforms in India” at Mangaluru on December 20. The workshop was organised by Indian Institute of Skill Development and Research (IISDR), in collaboration with Confederation of Indian Industry (CII) Mangaluru, Mangalore Management Association (MMA), and Kanara Industries Association (KIA). The workshop brought together policymakers, industry leaders, labour administrators, HR professionals, academicians, and students to deliberate on India’s evolving labour regulatory framework.</p><p>Dr Mittal spoke on the importance of ethical leadership and strong governance in building people-centric organisations. She emphasised that effective governance frameworks guide employees through clear rules, fairness, and transparency, enabling organisations to function smoothly and sustainably.</p><p>Highlighting the role of labour laws, she noted that they support organizational stability by preventing exploitation, reducing disputes, and ensuring legal clarity through standardized labour practices. Stressing zero tolerance for discrimination in recruitment, wages, promotions, or training, she underlined the importance of protecting workers’ rights and promoting collective bargaining.</p><p>She highlighted the role of digital tools in enabling online registration, inspections, and compliance. She further stressed the importance of continuous reskilling and upskilling across technical and non-technical fields to prepare the workforce for technological change, advocating a holistic approach that balances worker welfare, employer flexibility, and digital transformation.</p>', '', 'basic_html'),
('event', 0, 393, 1247, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission (CBC), called on Shri Vishnu Deo Sai, Chief Minister, Chhattisgarh in Raipur.</p>', '', 'basic_html'),
('event', 0, 394, 546, 'en', 0, '<p>As a part of the Good Governance Week, the Capacity Building Commission organized a thought-provoking talk by Dr. Onkar Sharma, Former Chief Labour Commissioner, Government of India on “Labour Codes towards Governance Reforms” reaffirming its commitment to strengthening Good Governance. Dr Alka Mittal, Member (Admin), CBC highlighted the importance of the topic of the Samuhik Charcha.</p><p>Shri S.P Roy, Secretary, CBC welcomed the speaker. Dr Sharma shared strategic perspectives on India’s labour reforms and the transition towards a more facilitative and responsive governance model. Drawing from his rich experience, he traced the origins of labour laws in the Indian traditional roots. He highlighted how the Labour Codes address contemporary labour challenges through simplification, transparency, and administrative coherence.</p><p>The discussion underscored the role of stakeholder consultations, institutional preparedness, and sustained capacity-building in effective implementation.</p><p>Such knowledge-sharing engagements remain central to CBC’s mandate of building future-ready institutions and enabling transformative governance reforms.</p>', '', 'basic_html'),
('event', 0, 395, 547, 'en', 0, '<p>A one-day workshop on the Development of Capacity Building Plans (CBPs) was conducted jointly by the Capacity Building Commission (CBC) and the Chhattisgarh Academy of Administration (CAA) at IIIT, Naya Raipur.</p><p>The workshop was inaugurated by Ms. S. Radha Chauhan, Chairperson, CBC, along with Shri Vikas Sheel, Chief Secretary, Government of Chhattisgarh, in the presence of Additional Chief Secretary and other senior officers from various state departments.</p><p>Speaking on the occasion, Ms. S Radha Chauhan, Chairperson, CBC said that Training Institutes are critical to the success of Mission Karmayogi. She emphasised that Training Institutes need to stand out to meet the bigger challenges, adding that they need to reimagine, revamp and re-define their roles in the ever evolving training eco-system, where Artificial Intelligence is playing an important role.</p><p>Chairperson, CBC also added that in order to achieve the target of Viksit Bharat 2047, the public servants needs to be ‘Future Ready’ and for readying for the future we need to be ‘Present Ready’ and thus the iGOT Karmayogi plays an important part in making us ready for the future and thus in a way helps our country to achieve the growth and milestones.</p><p>The Chief Secretary of Chhattisgarh, Shri. Vikas Sheel highlighted how the State Government’s vision for \"Viksit Chhattisgarh @2047\" is reshaping the whole governance with the use of Information Technology. Shri. Vikas Sheel added that all the officers at the district level offices will start E-office from January, 2026 and also Aadhar based biometric attendance. He emphasized on Mid-Career level training and use of the AI-enabled Capacity Building Plan (CBP) tool to cater to the needs of the officers as per their duties and responsibilities.</p><p>Ms. Chandralekha Mukherjee, Principal Advisor, CBC, acknowledged the strong foundational work already undertaken by Chhattisgarh and highlighted the immense potential of the State to emerge as a leading example in the development and implementation of Capacity Building Plans, while guiding participants on strengthening CBPs through structured frameworks and strategic alignment.</p><p>The sessions also included inputs from Shri Abhishek Dubey, Nodal Officer, Mission Karmayogi, who outlined the implementation roadmap and priorities for Mission Karmayogi in Chhattisgarh.</p><p>The workshop witnessed active participation from 60+ officials across 8 departments, culminating in the development of department-wise Capacity Building Plans aligned with state and institutional priorities.</p><p>This workshop marks an important step towards building a future-ready civil services ecosystem and strengthening capacity building reforms in Chhattisgarh.</p>', '', 'basic_html'),
('event', 0, 396, 548, 'en', 0, '<p>Dr. R Balasubramaniam, Member (HR), Capacity Building Commission (CBC), delivered the keynote address at the Good Governance Day celebrations held in Jaipur</p>', '', 'basic_html'),
('event', 0, 402, 1373, 'en', 0, '<p>The Capacity Building Commission (CBC) has continued to play central role in strengthening India’s civil services architecture by driving the implementation of Mission Karmayogi.</p><p>During the year 2025, the Commission focused on reaching out to the states with a more structured approach, aiming at creating capacities through Capacity Building Plans (CBPs) for State Departments by using AI-tool. In addition, the Commission updated its accreditation framework for Training Institutes incorporating new dimensions. The behavioural training in Seva Bhav through ‘Rashtriya Karmayogi Jan Sewa Program’ was one of the important highlights of the year. In addition, the focus aimed at creating new courses in domain areas targeting domain competencies.</p><p>During 2025, the Commission took several key initiatives and achieved significant milestones.</p><p><a href=\"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2208111&amp;reg=3&amp;lang=2\">Read More&nbsp;</a></p>', '', 'basic_html'),
('event', 0, 409, 563, 'en', 0, '<p>A State-level meeting chaired by Chief Minister of Uttar Pradesh, Yogi Adityanath, was held with the Chief Secretary, Shri Shashi Prakash Goyal and Secretaries of key citizen-facing departments.</p>', '', 'basic_html'),
('event', 0, 413, 566, 'en', 0, '<p>Chairperson CBC, Ms S Radha Chauhan, visited @upacademyup &amp; held detailed discussions with institute leadership on the pivotal role state training institutions can play in developing a robust State CBP &amp; strengthening overall capacity-building ecosystem under Mission Karmayogi.</p>', '', 'basic_html'),
('event', 0, 496, 1067, 'en', 0, '<p>The Hon\'ble Minister of State for the Ministry of Science and Technology, Dr Jitendra Singh, inaugurated the phygital course on \'Building Science Leaders in India\' today.</p><p lang=\"en-US\">&nbsp;</p><p lang=\"en-US\">The course is implemented with support of Centre for Technology, Innovation and Economic Research (CTIER) and Ahmedabad University and marks a unique collaboration between Capacity Building Commission and ISRO - Indian Space Research Organization for executive development of scientists in Government of India.</p>', '', 'basic_html'),
('event', 0, 511, 673, 'en', 0, '<p>Capacity Building Commission and Administrative Staff College of India (ASCI) signed an MoU to enhance cooperation and collaboration in strengthening the capacity building ecosystem.</p><p lang=\"en-US\">We look forward to a fruitful and exciting partnership with ASCI.</p>', '', 'basic_html'),
('event', 0, 523, 1281, 'en', 0, '<p>“India is moving towards a “less government, more governance” approach. This requires a paradigmatic shift in the capacities, mindset, and actions of the civil servant.”</p><p lang=\"en-US\">Dr. R Balasubramaniam writes in The Indian Express where he talks about the evolution in governance and the role of Capacity Building Commission in building capacity and supporting the aspirations of a modern and future-ready civil service</p>', '', 'basic_html'),
('event', 0, 524, 686, 'en', 0, '<p>‘Science is the energy in development of India in 21st century, it has the power to accelerate the development of every region and state of the nation’ - PM Narendra Modi</p><p lang=\"en-US\">The Research and Information Systems for Developing Countries (RIS) and Office of the Principal Scientific Adviser to the Government of India hosted the Workshop on Science, Technology, and Innovation for Sustainable Development Goals.</p><p lang=\"en-US\">Speaking at the inauguration program of the workshop, Shri Hemang Jani, Secretary, Capacity Building Commission added that ‘Technologies are the new humanities’, and India is and will continue to play a key role in supporting development of Science, Technology, and Innovations. He added that India is emerging as one of the most innovative countries in the world and serves as test bed for innovations applicable for global south. India is steadfast to develop its own capacity to ensure its STI outputs are taking ‘Local to Global’.</p><p lang=\"en-US\">The program is part of the global pilot programme on STI for SDGs Roadmap hosted by United Nations (and endorsed by G20). The global STI for SDGs program is aimed towards enhancing global cooperation for global Technology Facilitation Mechanism (TFM). The program is being piloted in five countries, viz. Ethiopia, Ghana, Kenya, Serbia, and India.</p>', '', 'basic_html'),
('event', 0, 529, 691, 'en', 0, '<p>Capacity Building Commission and School of Planning and Architecture, New Delhi signed an MoU for collaboration on various capacity building initiatives in spatial planning, design, architecture, and management for the various departments of Government of India.</p>', '', 'basic_html'),
('event', 0, 534, 696, 'en', 0, '<p>\"We are committed to protecting IPR which is essential to fostering creativity\"</p><p lang=\"en-US\">- Hon\'ble PM Narendra Modi</p><p lang=\"en-US\">Hemang Jani, Secretary, Capacity Building Commission participated in the National IP Conference 2022, chaired by Hon\'ble CIM Shri Piyush Goyal. The conference was jointly organized by Capacity Building Commission and Office of The Controller General of Patents, Designs And Trademarks.</p><p lang=\"en-US\">The conference bought together policy makers, IP officers, creators, and practitioners on one platform to discuss futuristic IP challenges related to developmental issues.</p><p lang=\"en-US\">Speaking during the conference, Hon\'ble CIM Piyush Goyal said innovation is that one defining characteristic that has always pushed mankind forward and the key factor that would determine the fate of the country.</p><p lang=\"en-US\">He urged patent office to setup interactions of patent offices with applicants and stakeholders through video conferencing to take inputs from IP practitioners and public.</p><p lang=\"en-US\">Speaking at the conference, Secretary, CBC stressed on the need to streamline the IPR granting mechanism through capacity building of key functionaries, which would be a key to meet the needs of growing intellectual capital in the nation.</p>', '', 'basic_html'),
('event', 0, 538, 700, 'en', 0, '<p>Capacity Building Commission in collaboration with the Ministry of Textiles and Office of Textiles Commissioner organized a workshop to \"Strengthen collaboration between the industry and Ministry of Textiles\".</p><p lang=\"en-US\">The workshop saw representatives from various textiles industry associations and companies across the country. The workshop was aimed towards understanding priority capacity needs of the Ministry from their direct and indirect stakeholders.</p><p lang=\"en-US\">Post feedback from industry associations, the Annual Capacity Building Plan was presented to and launched by Shri U. P. Singh, Secretary, Ministry of Textiles.</p>', '', 'basic_html'),
('event', 0, 544, 706, 'en', 0, '<p>“Technology for us is a medium to empower the people of the country. For us, technology is the mainstay of making the country self-reliant”</p><p lang=\"en-US\">-PM Narendra Modi</p><p lang=\"en-US\">The Phygital course on ‘Emerging Technologies’ by Capacity Building Commission was launched today by Hon’ble MoS, Rajeev Chandrasekhar in presence of Adil Zainulbhai, Chairman CBC and Hemang Jani, Secretary CBC. The course is developed by CBC in partnership with Indian Institute of Public Administration (IIPA) and Wadhwani Institute of Technology and Policy.</p><p lang=\"en-US\">The course is designed as an introduction on key emerging technologies for civil servants, wherein the online part of the course is already available on iGOT and is now being followed by 2 days offline program at IIPA.</p><p lang=\"en-US\">While addressing the gathering, Hon’ble MoS said that countries around the world are in awe of India’s prowess in technology. Post the pandemic, digitization is the way of 21st century for world governments and markets, and India has emerged as a leader in this trend. A big credit for which goes to PM’s push for digital India since 2014.</p><p lang=\"en-US\">&nbsp;</p><p lang=\"en-US\">Adil Zainulbhai, Chairman CBC, added that the goal of the program is to use technology to leapfrog development. Hemang Jani, Secretary CBC, further added that technology is the solution for efficient governance, and the phygital course on emerging technology will enable civil servants to build skill set required for this transformation.</p>', '', 'basic_html'),
('event', 0, 549, 711, 'en', 0, '<p>Capacity Building Commission organized an experience sharing session for effective implementation of FRAC in Government of India in collaboration with iGOT Karmayogi team, Indian Oil Corporation Limited, and Department of Telecommunications (DOT).</p><p lang=\"en-US\">The discussion was focused on the future of competency mapping and e-learning for civil servants.</p>', '', 'basic_html'),
('event', 0, 555, 717, 'en', 0, '<p>\"I believe India\'s new National Education Policy is one of the major factors in the mahayagna of nation building. Therefore, the country has made this education policy modern and future ready\"</p><p lang=\"en-US\">-PM Narendra Modi</p><p lang=\"en-US\">Hemang Jani, Secretary Capacity Building Commission addressed the gathering Inaugural session of the ongoing 12th Education Summit by Confederation of Indian Industry (CII) on \"Improving Industry-Academia engagements in India\". The session was chaired by Dr Rajkumar Ranjan Singh, Minister of State, Ministry of Education &amp; Ministry of External Affairs, India.</p><p lang=\"en-US\">The summit brings together subject matters, experts, and policy to highlight the key points in the education sector and discuss the way forward,</p><p lang=\"en-US\">Addressing the gathering during the inaugural address, Secretary CBC spoke about the salient approach of National Education Policy (NEP) to enable practical learning and innovation in education. He highlighted on key areas where Academia-Industry can collaborate to improve curricula, pedagogy, and support translation of research of research into innovations.</p>', '', 'basic_html'),
('event', 0, 558, 722, 'en', 0, '<p>Capacity Building Commission held an interaction with The World Bank\'s India team, led by Country Director Auguste Tano Kouame.</p><p lang=\"en-US\">Capacity building initiatives within ministries and departments, National Standards of Civil Service Training Institutions, Innovations in public administration and the Annual Report of the commission was discussed.</p>', '', 'basic_html'),
('event', 0, 559, 723, 'en', 0, '<p>Capacity Building Commission held a workshop with all external partners working with ministries, departments, and organizations within the Government of India on Annual Capacity Building Plans.</p><p lang=\"en-US\">An Annual Capacity Building Plan (ACBP) of an MDO identifies capacity needs through three lenses of National Priorities, Emerging Technologies, and Citizen Centricity. Further, it details all training and non-training interventions required to develop the competencies of individuals and the organization as a whole.</p><p lang=\"en-US\">All our partners joined us at Vigyan Bhavan:</p><p lang=\"en-US\">Deloitte, Grant Thornton Bharat LLP, KPMG India, PwC India, EY, Sattva Consulting, National Institute for Smart Government, Asian Development Bank (ADB), Centre for Effective Governance of Indian States (CEGIS), Invest India, Primus Partners India, Foundation for Advancing Science and Technology - India and Centre for Good Governance (cgg.gov.in)</p>', '', 'basic_html'),
('event', 0, 585, 749, 'en', 0, '<p>Capacity Building Commission organised a three-day workshop to train Central Training Institutes (CTI) and State Training Institutes (ATI) faculty members on developing case studies. The workshop was facilitated by Harvard Business School India Research Center. The workshop was based on a combination of participant-centred learning as well as learning-by-doing approaches and involved case development through interviews with protagonists, who were Public Administrative Officials and had done exemplary work for the nation.</p>', '', 'basic_html'),
('event', 0, 600, 764, 'en', 0, '<p>In the roundtable, the various experts in the field of Bharatiya Civilisation gave their inputs on the first draft of the karmayogi competency model and made the discussion enriching and enlightening for the CBC team to guide the way forward.</p>', '', 'basic_html'),
('event', 0, 619, 1376, 'en', 0, '<p>Faculty Development Program in collaboration with the Indian School of Business was conducted at the Yashwantrao Chavan Academy of Development Administration (YASHADA), Pune. The 3-day-long event encompassed multiple sessions on the teaching methods of trainers, the importance of experiential learning and the usage of technology in teaching methods.</p>', '', 'basic_html'),
('event', 0, 620, 1378, 'en', 0, '<p>The officers trained for the Common Mid Career Training Program CMCTP came together to share and gather knowledge and inspire others in the regional event for the \"Community of Leaders\" from North India. Dr Madan Pillutla Dean and Professor at the Indian School of Business coached the participants on skills of Negotiation and Professor Aroon P Manoharan conducted a session on Strategic Communication, where the participants had simulating discussions about the art of policy communications.</p>', '', 'basic_html'),
('photo_gallery', 0, 622, 797, 'en', 0, '<p>01 January 2026</p>', '', 'basic_html'),
('event', 0, 623, 789, 'en', 0, '<p>The Capacity Building Commission&nbsp; hosted a&nbsp; workshop for the Civil Services training institutes at Sri Krishna Institute of Public Administration (SKIPA), Ranchi.</p><p>The workshop was targeted for training institutes in the East zone of India, intended to guide the institutes through the process of National Standards for Civil Services Training Institutes (NSCSTI).</p>', '', 'basic_html'),
('photo_gallery', 0, 624, 798, 'en', 0, '<p>07 January 2026</p>', '', 'basic_html'),
('photo_gallery', 0, 625, 799, 'en', 0, '<p>07 January 2026</p>', '', 'basic_html'),
('photo_gallery', 0, 626, 800, 'en', 0, '<p>08 January 2026</p>', '', 'basic_html'),
('event', 0, 627, 802, 'en', 0, '<p>The officers trained under the Common Mid Career Training Programme CMCTP came together to share &amp; gain knowledge in the regional event for the “Community of Practice” (COP) conducted for the southern region.</p><p>Several officers from across the cadres and services came together to be a part of the programme and strengthen their leadership skills via experiential session.</p><p>Dr R Balasubramaniam, Member HR delivered the inaugural address and lauded the efforts of the officers in keeping this learning and knowledge sharing journey active.</p><p>Shri Amit Garg, Director of Sardar Vallabhbhai Patel National Police Academy, also spoke to the participants and shared his experiences with them.</p><p>Raghu Ananthanarayanan, delivered an enriching session on “Leadership Journey through inner presence” which was appreciated by the participants of the programme.</p>', '', 'basic_html');
INSERT INTO `node__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('event', 0, 637, 812, 'en', 0, '<p>Capacity Building Commission and Department of Finance (DFS), Ministry of Finance, collaborated to host a one-day Fintech workshop held on October 04, 2023 at Vanijya Bhawan, New Delhi.&nbsp;</p><p>The workshop addressed digital technology\'s role in improving financial access and inclusion to address national priorities for involving ministries such as Ministry of Micro, Small and Medium Enterprises, Ministry of Commerce and Industry, Government of India &nbsp;Ministry of External Affairs, India, Ministry Of Corporate Affairs, Prime Ministers Office, NITI Aayog, Department for Promotion of Industry and Internal Trade, Ministry of Agriculture &amp; Farmers Welfare, Government of India and more. Chaired by DFS secretary, it brought together administrative, regulatory, and industry stakeholders. The morning sessions covered the fintech sector\'s sectoral scenario in India, in a global evolutionary context. Industry experts and thought leaders led discussions on Digital Public Infrastructure, Regulatory Issues, and India\'s fintech future. Afternoon sessions showcased impactful fintech stories, demos, and group activities.&nbsp;</p>', '', 'basic_html'),
('event', 0, 638, 813, 'en', 0, '<p>As part of ACBP for the Department of Defence Production, Capacity Building Commission facilitated an a 2-day immersion program for officials from Defence PSUs such as Hindustan Aeronautics Limited (HAL), Bharat Earth Movers Limited - India (BEML), and Bharat Dynamics Limited (BDL) at Walchandnagar Industries Limited (WIL). The immersion program was held on the topic \"Quality Control and Quality Assurance processes in Aerospace and Missile Manufacturing\".&nbsp;</p><p>During the program, WIL made an elaborate presentation on how it imparts Quality Assurance, Quality Control, and Quality Ethics in its processes. This was followed by a shop floor round where the visiting team had a hands-on experience with facilities and infrastructure, and also an understanding of mass and size, intricacies of product and manufacturing process, qualification and trials.&nbsp;</p><p>The feedback from the visiting officials was unanimously positive as they intend to use the learnings gained at WIL in their own organizations.</p>', '', 'basic_html'),
('event', 0, 639, 815, 'en', 0, '<p>Capacity Building Commission (CBC) facilitated an Industry Immersion program at Siemens on the topic \'Industry 4.0 with a defence lens\" for officials of Defence PSUs including shipyards such as Mazagon Docks Limited (MDL), Goa Shipyard Limited (GSL) and Bharat Electronics Limited (BEL), Bharat Dynamics Limited (BDL), Hindustan Aeronautics Limited (HAL), Advanced Weapons and Equipment India Limited (AWEIL).&nbsp;</p><p>Siemens demonstrated cutting-edge digital transformation interventions it has implemented in its brownfield factory to turn it around from a bleeding plant to a benchmark in \"Factory of the Future\". DPSU officials experienced the Global Data Monitoring &amp; Remote Analysis Center (GAVATAR) which tracks energy and carbon data coming from all site locations through KPIs. Participants also learned about leveraging Digital Twin technologies in processes, shop floor management, and Industrial Additive manufacturing technologies along with Robot integration</p><p>We thank Siemens for organizing the visit and showcasing their state-of-the-art manufacturing facilities.</p>', '', 'basic_html'),
('event', 0, 640, 816, 'en', 0, '<p>As part of State Level Capacity Building Initiatives, CBC was invited by Sardar Patel Institute of Public Administration (SPIPA), Gujarat to participate in a \'One day workshop of Departments and Training Institutes of Gujarat.\'&nbsp;</p><p>CBC team provided an overview of the learnings &amp; insights from Annual Capacity Building Planning Process. The workshop also intended to guide the institutes through the process of National Standards for Civil Services Training Institutes (NSCSTI). (www.nscsti.org)</p><p>Over 50 participants from various departments &amp; Training institutions like Gujarat Police Academy, Public Policy and Finance Institute of Gujarat, Gujarat, Jal Sewa Training Institute etc engaged in this Knowledge sharing workshop.&nbsp;</p><p>The Commission remains steadfast in its commitment to empowering the Karmayogi\'s and Enhancing State Capacity.</p>', '', 'basic_html'),
('event', 0, 641, 817, 'en', 0, '<p>Capacity Building Commission (CBC), Ministry of Skill Development and Entrepreneurship, India &amp; Microsoft India have teamed up again and entered into an MOU to develop and deploy digital learning resources for civil servants. &nbsp;This strategic partnership is a step towards empowering our civil servants with the knowledge and skills needed for navigating the dynamic landscape of emerging technologies.&nbsp;</p><p>The Microsoft modules onboarded on Karmayogi Bharat (IGOT) platform help enhance the knowledge on topics such as Cyber Security, Project Management, AI fluency skilling, Power BI as well as Functional Computer Literacy skills like MS word, Excell, PowerPoint etc. The first year of this collaboration resulted in over 3.1 Lakh course enrollments and 2.14 lakh course completions by civil servants across India.&nbsp;</p><p>Together, we are poised to create a future where technological advancements are seamlessly integrated into the governance framework by our Future Ready Civil Servants.&nbsp;</p>', '', 'basic_html'),
('event', 0, 642, 818, 'en', 0, '<p>Officers from the Ministry of Steel, Ministry of Environment, Forest and Climate Change, and NITI Aayog on an immersion visit to Bhilai Steel Plant, SAIL</p>', '', 'basic_html'),
('event', 0, 643, 820, 'en', 0, '<p>CBC, in collaboration with the Ministry of Statistics and Programme Implementation (MoSPI), organized a workshop focused on Enhancing Survey Quality by Dr. Brady West.</p><p>The sessions were well-received and attended by officers of the Indian Statistical Services, including the Chief Statistician of India and by field officers from several regional offices of MoSPI.</p><p>We extend our gratitude to Dr. Brady West from the University of Michigan.</p><p>Special thanks to Prof. Sonalde Desai and Dr. Sharan Sharma for moderating the discussions and for their invaluable support in conceptualizing the workshop.</p>', '', 'basic_html'),
('event', 0, 644, 823, 'en', 0, '<p>The Department of Commerce is pivotal in driving India\'s economic growth. As we aim to achieve USD 1 trillion in exports and move towards a USD 10 trillion economy by 2047, capacity building becomes essential.</p>', '', 'basic_html'),
('event', 0, 645, 824, 'en', 0, '<p>Secretary, Capacity Building Commission(CBC) gave a talk on Mission Karmayogi to the 1st Executive Batch on 16th February, 2024 at New Delhi .</p><p>Sri Lanka Institute of Development Administration (SLIDA), shared some of their learnings and appreciated the path taken under Mission Karmayogi.</p>', '', 'basic_html'),
('event', 0, 646, 826, 'en', 0, '<p>CBC, in collaboration with L&amp;T Defence IU organized a day-long immersion visit for Defence PSUs such as Hindustan Aeronautics Limited, Bharat Dynamics Limited, and Bharat Electronics Limited at Larsen &amp; Toubro\'s Hazira complex in Surat on the topic \" Supply Chain and Procurement Process Management\".</p><p>The visiting DPSU team deliberated, learned, and exchanged best practices on vendor development, material management, and mitigating supply chain risks. They also visited L&amp;T\'s state-of-the-art heavy manufacturing shops and armored systems complex.</p>', '', 'basic_html'),
('event', 0, 647, 1284, 'en', 0, '<p>Minister of State for Communications launched 25 new courses after the completion of the 2nd phase of the Dak Karmyogi Project and released a Special Cover commemorating the successful journey of the Dak Karmyogi Project.</p><p>The interactive session provided trainees and trainers with an opportunity to share their experiences and insights, emphasizing the practical benefits of the capacity-building programs.</p>', '', 'basic_html'),
('event', 0, 682, 870, 'en', 0, '<p>Member (HR), Capacity Building Commission, Dr. R Balasubramaniam visited All India Institute of Speech and Hearing (AIISH), Mysore and address the staff there on 4th December, 2025. He stressed on imbibing the spirit of continuous learning, bringing about the behavioural change, becoming future-ready and to encourage &amp; derive benefit by cross-pollination of ideas and collaboration.</p><p>His address also covered concepts of Vikas, Garv, Kartavya and Ekta, principles of Swadhyaya, Sahkaryata, RajyaKarma and Swadharma besides adoption of Indian Knowledge Systems and Quotes from Indic literature.</p><p>A brief presentation about the Institute was made by the Director, AIISH, covering governance aspects and the Institute’s work across four verticals-manpower development, clinical services, research, and public education in the area of communication (speech and hearing). This was followed by visits to the Departments of Special Education, Clinical services, Centre for Public Education in Communication Disorders (CPEC-D) and department of Prevention of Communication Disorders.</p><p>The Visit concluded with the Member (HR), CBC addressing the Officers of the Institute, followed by an interactive session. During the visit, the AIISHians of the Year 2025 were presented awards by Member (HR), CBC.</p><p>AIISH has achieved 98.4% staff coverage under the Rashtriya Karmayogi Jan Sewa (RKJS) program by CBC, and has developed 18 domain-specific courses for the KB in the domain of health.&nbsp;</p>', '', 'basic_html'),
('event', 0, 683, 1285, 'en', 0, '<p>The Capacity Building Commission (CBC), Karmyogi Bharat , and the Government of Mizoram signed a Memorandum of Understanding in Aizawl to strengthen capacity building initiatives in the state.</p><p>Mr. Khilli Ram Meena, Chief Secretary, Mizoram, acknowledged the need for systematic capacity building to meet the requirements of an evolving workforce. He welcomed the support of CBC and Karmyogi Bharat in enabling the state to ensure that officials are equipped with the right competencies and skills for effective governance. He emphasised on lifelong learning of officers in Mizoram.</p><p>Dr. R Balasubramaniam, Member (HR), CBC, emphasized the vital role of Administrative Training Institutes in shaping a future-ready civil service. He highlighted the importance of competency-based capacity building, integration of e-HRMS with the iGOT platform, and preparing officers today to deliver on the vision of Viksit Bharat 2047.</p><p>Shri. S P Roy, Secretary, CBC highlighted the role of Capacity Building Units in enabling the Capacity Building in the state. He explained the structural framework of overall coordination between the state and Capacity Building Commission. He also highlighted the importance of capacity building plan and the workshop to be planned for its development.</p><p>This partnership marks a significant step in advancing #MissionKarmyogi and building an agile, skilled, and citizen-centric workforce.</p>', '', 'basic_html'),
('event', 0, 686, 875, 'en', 0, '<p>Dr. R. Balasubramaniam, Member (HR), Capacity Building Commission, along with Shri S. P. Roy, Secretary, CBC, &amp; Ms. Soumi Banerjee, General Manager, Karmayogi Bharat visited the Administrative Training Institute (ATI), Mizoram. visited the campus and its facilities.</p>', '', 'basic_html'),
('event', 0, 687, 876, 'en', 0, '<p>Member (HR), Capacity Building Commission, Dr R Balasubramaniam addressed a session on “Leadership &amp; Management” at IIFM, Bhopal on 01.12.2025. The session was a part of the Management Module of the Mid-Career Training Phase-V for the in-service IFS Officers (1995 – 1999 batches).</p>', '', 'basic_html'),
('event', 0, 688, 877, 'en', 0, '<p>The Capacity Building Commission extends its heartfelt congratulations to the Lal Bahadur Shastri National Academy of Administration (LBSNAA) for achieving 5-star rating under the NSCSTI 2.0 Framework of Mission Karmayogi.</p><p>This milestone reflects LBSNAA’s commitment to strengthening public sector capacity and setting high standards in training, innovation, and governance excellence.</p><p>CBC remains steadfast in supporting and collaborating with institutions that are driving transformation across India’s civil services.</p>', '', 'basic_html'),
('event', 0, 689, 878, 'en', 0, '<p>The Capacity Building Commission (CBC) conducted a focused workshop on “Delivering Quality at Scale,” facilitated by Dr. R. Balasubramaniam, to strengthen quality standards in digital learning products and programmes across the public sector. The workshop saw the participation of Ms. S. Radha Chauhan (Chairperson, CBC), Dr. Alka Mittal (Member Administration, CBC), Shri S. P. Roy (Secretary, CBC), along with the Mission Karmayogi team.</p><p>The workshop encouraged participants to reflect deeply on what quality truly signifies in a learning environment—and how it shapes the overall user experience. Through practical illustrations, interactive exercises, and group discussions, the sessions helped participants examine how users perceive quality and how consistency can be intentionally designed across the learning lifecycle.</p><p>Aligned with the vision of Mission Karmayogi, CBC continues to foster an ecosystem where digital learning is not only accessible but also effective, reliable, future-ready, and designed to strengthen the competencies of India’s civil servants.</p>', '', 'basic_html'),
('event', 0, 690, 880, 'en', 0, '<p>Congratulations to the Institute of Secretariat Training &amp; Management (ISTM) on being re-accredited with a 5-Star rating following the successful Post-QIP implementation facilitated by the Capacity Building Commission (CBC).</p><p>The Capacity Building Commission is proud to support institutions in consistently raising the bar for excellence in civil service capacity building.</p><p>#CapacityBuilding #MissionKarmayogi #ISTM #Governance #PublicService #GoodGovernance #ViksitBharat2047 #InstitutionalExcellence</p>', '', 'basic_html'),
('event', 0, 691, 882, 'en', 0, '<p>Today, the Capacity Building Commission (CBC) observed the 76th Constitution Day (Samvidhan Diwas), reflecting on the values and vision that continue to guide India’s governance framework.</p><p>To mark the occasion, CBC organised a series of engaging and reflective activities for its officials and staff:</p><p>✅ Reading of the Preamble: Reaffirming our collective commitment to the Constitution’s foundational principles.</p><p>✅ Samuhik Charcha: Facilitating thoughtful dialogue on constitutional duties and their significance in public service.</p><p>✅ Digital Live Quiz: An interactive, real-time quiz designed to strengthen understanding of key constitutional concepts.</p><p>✅ Blog Writing Competition: Encouraging participants to articulate their perspectives on constitutional values, good governance, and public service ethics—fostering deeper reflection through creative expression.</p><p>These engagements provided a meaningful opportunity to revisit the core values that underpin effective governance and to reflect on how they translate into our day-to-day responsibilities as public servants.</p><p>As we work toward building a future-ready civil service under Mission Karmayogi, Constitution Day serves as a timely reminder to uphold a governance ecosystem grounded in integrity, accountability, and public service excellence.</p>', '', 'basic_html'),
('event', 0, 692, 884, 'en', 0, '<p>CBC in its commitment to strengthen the capacity building ecosystem by enhancing the capacity of Civil Service Training Institutions of the centre &amp; the states, launched its first Advanced Faculty Development Program at&nbsp;<br>@ISBedu with 34 carefully selected participants.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 693, 886, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission (CBC), visited the Yashwantrao Chavan Academy of Development Administration (YASHADA), Pune &nbsp;Maharashtra, to discuss the implementation of Mission Karmayogi initiatives undertaken by the academy.<br>During the visit, she met Shri N. K. Sudhanshu, Director General, YASHADA, along with senior officials and faculty members. The meeting focused on the ongoing efforts to establish State and Departmental Capacity Building Units (CBUs), as well as the development of Capacity Building Plans (CBPs).<br>She emphasised the importance of sustained inter-departmental collaboration and the creation of State-specific training content in partnership with various training institutions.&nbsp;<br>The Chairperson reaffirmed CBC’s commitment to supporting YASHADA in further strengthening the implementation of Mission Karmayogi across Maharashtra.</p>', '', 'basic_html'),
('event', 0, 694, 1287, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission (CBC), interacted with the Karmyogi Sarthis, outlining the key priorities and expectations for the forthcoming state-level capacity-building engagements under Mission Karmyogi</p><p>Mission Karmyogi is equipping State Departments to systematically develop structured CBPs aligned with assessed competency gaps, desired service delivery outcomes, and organisational priorities.</p><p>This initiative marks a significant step towards establishing a more efficient, robust, and future-ready civil service across&nbsp;the&nbsp;nation.</p>', '', 'basic_html'),
('event', 0, 695, 1288, 'en', 0, '<p>As a part of our collaborative effort towards development, a 3-day State Capacity Building workshop on creating State Capacity Building Plan was conducted at the RCVP Noronha Administrative Academy, Bhopal from 19–21 November, 2025, with participation from 30 departments and their sub-organisations.</p><p>The workshop opened with an address by Shri Sachin Sinha, IAS, Director General, who outlined the objectives and expected institutional outcomes of the workshop, followed by a detailed presentation by Shri Mujeebur Rehman Khan, IAS, Director-ATI, setting the operational and strategic context for departmental engagement.</p><p>Mission Karmyogi team facilitated the departments towards adopting state-wide standardisation of CBPs, ensuring data-driven capacity building and seamless integration with the iGOT Karmyogi platform.</p><p>The workshop marks a significant milestone in enabling the shift from creating rule-based to role-based Capacity Building Plans.</p>', '', 'basic_html'),
('event', 0, 697, 890, 'en', 0, '<p>“THE VOCABULARY OF GOVERNANCE IS EVOLVING FROM AUTHORITY TO EMPATHY, FROM SECRECY TO OPENNESS, FROM ‘DOING FOR’ TO ‘DOING WITH’.”</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 698, 1380, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission, addressed the Senior Civil Servants of the Republic of Mauritius during the 2nd Capacity Building Program for Senior Civil Servants from Mauritius at the National Centre for Good Governance (NCGG), New Delhi.</p><p>She shared insights on Mission Karmayogi and the iGOT Karmayogi platform, highlighting its transformative role in fostering continuous learning and capacity building among civil servants.</p>', '', 'basic_html'),
('event', 0, 699, 1289, 'en', 0, '<p>Today, the newly joined CBC officials and employees participated in the Rashtriya Karmyogi Large Scale Jan Seva Programme training — marking a major milestone: 7 lakh government officials trained with Seva Bhav from across India in Phase II.</p><p><br>Chairperson Ms. S. Radha Chauhan joined the team to mark this occasion. She talked about the values that shaped this journey — citizen-first governance and the belief that real change shows up in how we serve the citizens every day.</p><p>Dr. R. Balasubramaniam, Member (HR) reminded participants that the Karmyogi spirit must continue — the Seva Bhav nurtured through this programme should stay alive in their daily work.</p><p>We believe that the milestones mark progress, but it’s the intent we carry forward that transforms systems.</p>', '', 'basic_html'),
('event', 0, 700, 904, 'en', 0, '<p>Ms. S. Radha Chauhan, Chairperson, Capacity Building Commission, graced the Graduation Ceremony of the Advanced Management Programs (AMPs), Class of 2025, at the Indian School of Business (ISB), Mohali.</p><p>In her address, she highlighted that the world of management is evolving at an unprecedented pace — urging the graduating cohort to anticipate change, harness innovation, and build organisations and institutions that are resilient, ethical, and future-ready.</p><p>She encouraged them to situate their professional journeys within the larger national vision of Viksit Bharat@2047 — a vision of a developed, prosperous, inclusive, and globally influential India.</p>', '', 'basic_html'),
('event', 0, 701, 1246, 'en', 0, '<p>The Capacity Building Commission organised the mass singing of ‘Vande Mataram, joining the nationwide commemoration marking 150 years of India’s National Song.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 702, 906, 'en', 0, '<p>As part of the Vigilance Awareness Week 2025, being observed from 27th October to 2nd November, the Capacity Building Commission (CBC) organized a #SamuhikCharcha on the theme “Vigilance: Our Shared Responsibility.”</p><p>The discussion centered on the significance of collective responsibility in promoting integrity, transparency, and ethical governance. Participants reflected on the role of #vigilance as a continuous process that strengthens institutional credibility and fosters public trust.</p><p>The session reaffirmed CBC’s commitment to upholding the highest standards of accountability and public service in all its endeavors.</p>', '', 'basic_html'),
('event', 0, 703, 907, 'en', 0, '<p>On the occasion of #RashtriyaEktaDiwas 2025, officers and staff of the Capacity Building Commission, took the Integrity Pledge, reaffirming their commitment to uphold unity, integrity and security of the nation.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 704, 1290, 'en', 0, '<p>Capacity Building Commission (CBC), in collaboration with Lal Bahadur Shastri National Academy of Administration (LBSNAA) and Karmyogi Bharat, organized a workshop to strengthen the Mission Karmyogi team, preparing them to effectively facilitate the capacity building initiatives being implemented across States and Union Territories.</p><p>The workshop was graced by Shri Sriram Taranikanti, Director, LBSNAA; Smt Chandralekha Mukherjee, Former Director General, Haryana Institute of Public Administration (HIPA); Shri S P Roy, Secretary, CBC; Ms Shanmuga Priya Mishra, Deputy Director, LBSNAA and others.</p><p>Their participation and insights underscored the importance of collaboration and innovation in advancing the objectives of Mission Karmyogi.</p><p>This initiative marks another step towards realizing the shared vision of a #ViksitBharat, enabled by future-ready, and citizen-centric civil service.</p>', '', 'basic_html'),
('event', 0, 705, 911, 'en', 0, '<p>It is our privilege to announce the signing of a tripartite MoU between the Capacity Building Commission, the School of Ultimate Leadership, and the Government of Gujarat to roll out the 𝐃𝐢𝐬𝐭𝐫𝐢𝐜𝐭 𝐊𝐚𝐫𝐦𝐚𝐲𝐨𝐠𝐢 𝐏𝐫𝐨𝐠𝐫𝐚𝐦, an initiative to strengthen citizen-centric governance.</p><p>SOUL shall serve as the lead knowledge and leadership program implementation partner.</p><p>The MoU was signed by 𝐒 𝐏 𝐑𝐨𝐲, Secretary, CBC, 𝐒𝐚𝐮𝐫𝐚𝐛𝐡 𝐉𝐨𝐡𝐫𝐢, CEO, SOUL, and 𝐇𝐚𝐫𝐞𝐞𝐭 𝐒𝐡𝐮𝐤𝐥𝐚, IAS, Principal Secretary, ARTD, GoG, in the presence of 𝐃𝐫. 𝐇𝐚𝐬𝐦𝐮𝐤𝐡 𝐀𝐝𝐡𝐢𝐚, Principal Advisor to the H’ble Chief Minister of Gujarat, 𝐌𝐬. 𝐒 𝐑𝐚𝐝𝐡𝐚 𝐂𝐡𝐚𝐮𝐡𝐚𝐧, Chairperson, CBC and 𝐑. 𝐁𝐚𝐥𝐚𝐬𝐮𝐛𝐫𝐚𝐦𝐚𝐧𝐢𝐚𝐦, Member – HR, CBC.</p><p>SOUL shall design and implement behavioural transformation, functional excellence, and technological enablement programs for Grade 1 and Grade 2 officers, starting with the Narmada district as a pilot to create a scalable and replicable model for the state and the nation.</p>', '', 'basic_html'),
('event', 0, 706, 914, 'en', 0, '<p>Dr. R Balasubramaniam, Member HR, Capacity Building Commission, and the team visited AIIMS, Delhi.</p><p>The Capacity Building Commission (CBC) is conducting an extensive research study across Public Sector Hospitals to comprehend citizen-centric practices in healthcare delivery and propose templates for scaling those practices in other healthcare institutions.</p><p>Therefore, this visit aimed to gain firsthand insights into how processes, governance, and patient experience are interconnected.</p><p>The Director, Shri Srinivas, presented details about the initiatives in AIIMS, Delhi, that have improved patient experiences. The Heads of Departments, faculty members, discussed their experiences and how they contribute to these initiatives.</p><p>Dr. Balasubramaniam interacted with healthcare service providers, front desk officers, and some patients about these services.</p><p>This exercise is part of a larger effort to identify and document citizen-centric best practices. It also seeks to facilitate the exchange of ideas across public sector hospitals and develop models that can guide hospitals across India and globally.</p><p>The exceptional zeal and leadership capabilities of specific department staff, such as the NICU department, were insightful.</p><p>The cross-pollination of such practices will significantly enhance the citizen-centricity of healthcare services.</p><p>The insights gained from this visit will contribute to the development of healthcare systems that are accessible, transparent, and compassionate, with citizens firmly at the centre.</p>', '', 'basic_html'),
('event', 0, 707, 918, 'en', 0, '<p>ATIs to function as Catalysts in State-Level Capacity Building.&nbsp;</p><p>The 2-day workshop on \'Developing State-Level Capacity Building Plans\' brought ATIs as key stakeholders of capacity building in states. Through hands-on group exercises, ATI teams designed draft CBPs for key sectors. To begin with, six such key sectors were chosen: Education, Women &amp; Child Development, Agriculture, Rural Development, Health and Urban Development. These culminated in presentations that showcased their approach, key learnings, and next steps.</p><p>In the closing session, Smt. S. Radha Chauhan, Chairperson CBC, called ATIs a “pivotal pillar” in creating CBPs. She underlined that ATIs must act as mentors and catalysts, helping state governments own their CBPs and embed a whole-of-government approach. Importantly, she emphasized the shift from rule-based structures to role-based learning, focusing not just on designations, but on the competencies required for roles that officials actually perform.</p><p>Shri Sriram Taranikanti, Director, LBSNAA, reflected on the workshop presentations, stressing the importance of carrying forward the exercises into concrete state-level CBPs and highlighting the broader role ATIs must play in shaping this reform journey.</p><p>Smt. Chhavi Bhardwaj, CEO (Karmayogi Bharat) &amp; Joint Secretary (DoPT), underlined key priorities, from integrating training calendars to creating domain courses in regional languages, to make the ecosystem more relevant and impactful.</p><p>Member (Administration), CBC, Dr. Alka Mittal, officers and team members from Capacity Building Commission, Karmayogi Bharat and LBSNAA were also present during the conclusion of the workshop. The workshop brought together heads and senior faculty members from 17 State ATIs. Participants were introduced to the core principles of Mission Karmayogi, the Karmayogi Competency Model, and tools and templates for designing Capacity Building Plans (CBPs).</p><p>This workshop marked a significant step in deepening capacity building initiatives at the State level. With ATIs positioned as knowledge hubs and mentors, they will anchor CBPs across departments, ensuring that capacity building directly empowers every official to serve citizens better.</p>', '', 'basic_html'),
('event', 0, 708, 919, 'en', 0, '<p>The Workshop on \'Developing State-Level Capacity Building Plans\' was inaugurated by Hon’ble MoS (PP) Dr Jitendra Singh at CSOI, Vinay Marg today, who called for a future-ready, citizen-centric civil service built on continuous learning.</p><p>Smt. S. Radha Chauhan, Chairperson CBC, reflected on the journey of Mission Karmayogi-moving from rule-based to role-based competencies-and stressed that ATIs must become the fulcrum for driving State Capacity Building Plans.</p><p>Smt. Rachna Shah, Secretary, DoPT, highlighted that ATIs must become the nerve centres of reform by guiding states to embed capacity building into their departmental workflows.</p><p>Shri Sriram Taranikanti, Director, LBSNAA, highlighted the pivotal role of ATIs and assured sustained mentorship from LBSNAA to institutionalise Mission Karmayogi across states.</p><p>Dr. R Balasubramaniam, Member (HR), CBC, stressed that citizen-centricity and continuous learning must remain the guiding values of every CBP.</p><p>Dr. Alka Mittal, Member (Admin), CBC, spoke about strengthening institutional ecosystems to enable ATIs to lead this reform at the grassroots.</p><p>Shri S P Roy, Secretary, CBC, emphasised the commitment and teamwork required to make capacity building a lived practice in governance.</p><p>Smt. Chhavi Bhardwaj, CEO (Karmayogi Bharat) &amp; Joint Secretary (DoPT), along with COO (Karmayogi Bharat) Shri Rakesh Verma, oriented ATIs on designing effective Capacity Building Plans (CBPs) with the use of technology to anchor this transformation.</p><p>As the momentum amongst ATIs grows, the day ahead will focus on group activities and hands-on exercises, with the two-day workshop charting the way forward to build State-level Capacity Building Plans (CBPs).</p><p><a href=\"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2170806\">Press Release Link</a></p>', '', 'basic_html'),
('event', 0, 709, 1292, 'en', 0, '<p>In a significant step for strengthening public service in Manipur, a tripartite Memorandum of Understanding (MoU) was signed today (23 September 2025) between the Capacity Building Commission (CBC), Karmyogi Bharat, and the Government of Manipur.</p><p>Signed in the presence of Dr Puneet Kumar Goel, Chief Secretary, Government of Manipur, and Dr. R Balasubramaniam, Member (HR), CBC, the partnership will deepen the state’s engagement with hashtag#MissionKarmyogi.</p><p>The MoU marks the beginning of an institutional partnership to implement Mission Karmyogi’s vision of a competency-based, technology-driven, and continuous learning ecosystem for government officials in Manipur-enabling civil servants to serve citizens better, faster, and with empathy.</p>', '', 'basic_html'),
('event', 0, 710, 923, 'en', 0, '<p>To mark the launch of Swachhta Hi Seva (SHS) 2025, Swachhta Pledge was administered by Ms S Radha Chauhan, Chairperson, Capacity Building Commission and Shri S.P Roy, Joint Secretary, to all officers and staff of Capacity Building Commission.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 711, 1293, 'en', 0, '<p>Team CBC bid farewell to Ms. V. Lalithalakshmi, Secretary, Capacity Building Commission and CEO, Karmyogi Bharat. We wish her the very best in all her future endeavors.</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 712, 925, 'en', 0, '<p>Learning in action at the Second Edition of the Advanced Case Writing Workshop!</p><p>Today, Rajarshi Dey’s case study on \'Ordnance Factory Balangir\' was used for a live teaching demonstration. Rajarshi, an officer from National Academy of Defence Production, Nagpur (NADP), and participant of last year’s workshop, developed this case to highlight how procurement practices can be strengthened.</p><p>With participants stepping into role plays guided by the teaching note, the session came alive-showing how case teaching can turn policy dilemmas into real-time learning experiences.</p><p>📚 This case, along with its teaching note (faculty access only), is now part of the Amrit Gyaan Kosh on hashtag#iGOT.</p>', '', 'basic_html'),
('event', 0, 713, 927, 'en', 0, '<p>Advanced Case Writing Workshop at IRIFM, Secunderabad&nbsp;<br>Indian Railways Institute of Financial Management (IRIFM) is proud to host the Second Edition of the Advanced Case Writing Workshop in collaboration with the Capacity Building Commission (CBC), supported by the Asian Development Bank (ADB) and Asian Development Bank Institute (ADBI) and featuring Program Instructors like Blair Cameron (The World Bank) and Prof. Sanjay Dhir (Indian Institute of Technology, Delhi) in person and KE Seetha Ram, Dr. Eng. (Asian Development Bank Institute) virtually.&nbsp;<br><br>Dr. R Balasubramaniam, Member (HR), CBC, in his opening address emphasized that policies are not born in textbooks; they emerge from the experiences and partnership between government and citizens. He further highlighted the Hon’ble Prime Minister’s vision to adopt the case studies in Indian context for training purposes.&nbsp;<br><br>In her address, Aparna Garg, Director General, IRIFM, shared her perspective on the transformative role of case studies in officer training, as the learning outcome is proven to be most optimal. Equipped with right learning, the gap between government and governance gets minimized.&nbsp;<br><br>IRIFM is committed to contributing to this ecosystem of knowledge and to be a partner with CBC in this transformative mission.</p>', '', 'basic_html'),
('event', 0, 714, 1294, 'en', 0, '<p>The Rashtriya Karmyogi Large Scale Jan Seva program has commenced at one of India’s premier healthcare institutions, #AIIMS, New Delhi, which serves over 10,000 patients every day. Addressing the second batch of Master Trainers, Dr. R Balasubramaniam, Member (HR), Capacity Building Commission, applauded their commitment and highlighted the program’s vision of nurturing Seva Bhav (spirit of service) and Svadharma (sense of duty) among civil servants. Officials were encouraged to step away from their desks and recognize that every action—big or small—shapes the lives of citizens. This marks a fundamental shift from being process-driven to becoming purpose-driven and moving from Rule based to Role based governance.</p><p>A true #Karmyogi moment was witnessed when, six inspiring posters on “Who is a Karmyogi” and “Karmyogi Moments” were prepared by organisation and inaugurated by Member (HR) with Director, AIIMS New Delhi. This symbolic gesture underscored the spirit of agility, dedication, and collective ownership.</p><p>The session marked a shared Sankalp to strengthen India’s #healthcare system, with AIIMS New Delhi emerging as a model institution that will inspire and set benchmarks for others across the nation.</p>', '', 'basic_html'),
('event', 0, 715, 930, 'en', 0, '<p>The Capacity Building Commission (CBC) is pleased to announce the renewal of its Statement of Intent with IDinsight. This partnership reflects our shared vision of strengthening data-driven governance and fostering a culture of continuous improvement across the civil services.</p><p>Through this renewed collaboration, #CBC and #IDinsight will continue to work together to enhance the impact of #capacitybuilding initiatives by leveraging rigorous research, evidence-based strategies, and actionable insights.</p><p>We look forward to deepening this partnership to drive more informed, effective, and citizen-centric policies for a #ViksitBharat.</p>', '', 'basic_html'),
('event', 0, 716, 933, 'en', 0, '<p>After the resounding success of its first edition, the Advanced Case Writing Workshop returns this September with a bold mission-to build a practice-driven knowledge ecosystem for the public sector.</p><p>The Second Edition will bring together 75 Government Officials across three cohorts (Delhi/Goa/Secunderabad) for an intensive 3-day workshop designed to enhance their Case Writing Skills.</p><p>Pillars of the Workshop:</p><p>Atmanirbharta in Learning – Building a self-reliant Indian case-writing ecosystem.<br>Practice-Driven Knowledge – Converting governance experiences into learning resources.<br>Skill Building in Case Crafting – Developing impactful cases and teaching notes anchored in public sector challenges.<br>Policy Reflection &amp; Teaching Excellence – Advancing case pedagogy and policy insights.<br>Global–Local Collaboration – Featuring Program Instructors like Blair Cameron (World Bank) and Prof. Sanjay Dhir (IIT Delhi).</p><p>Supported by the Asian Development Bank (ADB) and Asian Development Bank Institute (ADBI), this workshop is shaping an India-centric case writing ecosystem with global reach under Mission Karmayogi.</p>', '', 'basic_html'),
('event', 0, 717, 1382, 'en', 0, '<p>Dr. R Balasubramaniam, Member (HR), Capacity Building Commission (CBC), visited the BEL Academy for Excellence, Bengaluru - a training institution that exemplifies sustainable design and capacity building.</p><p>The Academy is envisaged to serve not only BEL employees, but also its customers, vendors, and partners—especially MSMEs/SMEs. Its programs are structured around three core areas: Quality, Technology, and Leadership, designed in collaboration with experts from premier institutes such as IITs, IIMs, IISc, IETE, ISI, ASQ, and others.</p><p>It was inspiring to discuss the Academy’s vision and its immediate priority of launching the Quality Improvement Program (QIP). Together, we look forward to elevating training standards and fostering continuous excellence in public sector learning.&nbsp;</p>', '', 'basic_html'),
('event', 0, 718, 1295, 'en', 0, '<p>India’s single largest behavioural training program is entering its most powerful phase—scale with purpose.</p><p>Today marks the final Lead Trainer batch at CSOI, New Delhi under Phase II of the Rashtriya Karmyogi Large-Scale Jan Seva Program (RKLSJSP)—a transformative initiative reimagining how civil servants are trained to serve with Seva Bhav.</p><p>Phase II trained 740 Lead Trainers, 7,500 Master Trainers, who have already trained 1,57,806 civil servants across Bharat on iGOT.</p><p>As this pyramid of learning cascades further, 7,00,000+ government officials will be empowered through 1-day training sessions—ensuring that every citizen experiences responsive, empathetic, and effective governance.</p><p>RKLSJSP is a quiet revolution to realise Viksit Bharat—one that touches lives, villages, and cities through every act of improved public service.</p>', '', 'basic_html'),
('event', 0, 719, 1296, 'en', 0, '<p>The largest behavioural change program in India’s governance is shaping a new era of public service transformation.</p><p>A future-ready civil service begins with capacity building at scale. Under hashtag#MissionKarmyogi, the Rashtriya Karmyogi Large Scale Jan Seva Program has now crossed its first major milestone – 1,00,000 central government officials across Bharat trained to deliver governance with hashtag#SevaBhav at the core.</p><p>But this is only the beginning. The journey ahead envisions training 7,00,000 officials across the nation, building a civil service that is citizen-focused, technology-enabled, and rooted in continuous learning – where capacity building becomes second nature and public service keeps evolving to meet the aspirations of a Viksit Bharat.</p><p>This achievement stands as a testament to the collective effort of ministries, states, training institutions, who have worked in unison, shaping a system where knowledge spreads its wings and governance rises to serve better, every single day.</p><p>CBC remains committed to accelerating this journey – creating a culture where learning never stops, and service to the people stays at the heart of governance.</p><p>For in the service of people, the truest growth lies, As knowledge spreads its wings, a brighter Bharat shall rise.&nbsp;</p>', '', 'basic_html'),
('event', 0, 720, 938, 'en', 0, '<p>Mrs. S. Radha Chauhan assumed charge as the Chairperson of Capacity Building Commission, in New Delhi today. She is a retired IAS officer of UP Cadre (1988 batch). She has served in various capacities in the State and Centre Government. She is also the former Secretary of Department of Personnel and Training (DoPT). She took charge from Shri Adil Zainulbhai, who served as Chairman of the Capacity Building Commission since April, 2021.</p><p>Constituted on 1st April 2021, by the Government of India, the Capacity Building Commission has been mandated to drive standardisation and harmonisation across the Indian civil services landscape. As the custodian of civil services capacity building reforms, the Commission’s role is central to the overall institutional framework of Mission Karmayogi.</p>', '', 'basic_html'),
('event', 0, 721, 1297, 'en', 0, '<p>In a major stride towards strengthening the capacity-building framework for civil servants in Jammu &amp; Kashmir, the Government of Jammu &amp; Kashmir, the Capacity Building Commission (CBC), and Karmyogi Bharat signed a tripartite Memorandum of Understanding (MoU) on August 5, 2025, in Srinagar.</p><p>The MoU aims to institutionalize Mission Karmyogi across J&amp;K by facilitating structured, role-based, and continuous learning for government officials through the iGOT Karmyogi platform. The initiative will help build future-ready, and citizen-centric civil service ecosystem in the region.</p><p>Shri Atal Dulloo, Chief Secretary, Government of Jammu &amp; Kashmir, reiterated the government’s commitment to enhancing governance through capacity building. He emphasized the vital role of the General Administration Department (GAD) and the Institute of Management, Public Administration and Rural Development (IMPARD) in leading the implementation efforts and expediting the onboarding of officials across departments onto the iGOT Karmyogi platform.<br>The MoU signing was attended by senior dignitaries including Dr. Alka Mittal, Member (Administration), CBC; Shri M Raju, Secretary, General Administration Department, J&amp;K; Smt. Rehana Batul, Director General, IMPARD; Smt. V. Lalithalakshmi, CEO, Karmyogi Bharat; Shri S P Roy, Joint Secretary, CBC; Shri Rakesh Verma, Chief Executive Officer, Karmyogi Bharat.</p><p>As part of the engagement, an orientation session was attended by Additional Secretaries and Deputy Secretaries of various departments at IMPARD. The session was conducted by Smt. Navneet Kaur, Director, CBC, and Shri Rakesh Verma, COO, Karmyogi Bharat, who outlined the core objectives of Mission Karmyogi, with a focus on digital learning, need-based skilling, and the transition to a competency-driven public administration system.</p><p>Shri Rakesh Verma, COO of Karmyogi Bharat, delivered a live demonstration of the iGOT Karmyogi platform, highlighting its modular and self-paced learning design. He noted that over 1.26 crore learners across India have already benefited from the platform’s flexible and contextual learning modules.<br>A key outcome of the event was the Government of J&amp;K’s affirmation to begin onboarding officials from different departments and launch their curated learning journeys on iGOT Karmyogi. The administration also expressed interest in implementing customized blended learning programs tailored to their unique developmental priorities.</p><p>This MoU marks the beginning of a collaborative institutional effort to build a dynamic, digitally empowered, and continuously evolving public workforce aligned with the vision of Mission Karmyogi.</p>', '', 'full_html'),
('event', 0, 722, 1298, 'en', 0, '<p>Arunachal Pradesh takes a step towards citizen-first governance!</p><p>On 4th August 2025, the Rashtriya Karmyogi Large Scale Jan Seva Program was officially launched in Itanagar by Hon’ble Chief Minister Shri Pema Khandu, marking a key milestone in the state’s journey towards strengthening public service delivery under the vision of Mission Karmyogi.</p><p>The launch event was attended by several senior dignitaries, including Shri Manish Gupta, Chief Secretary, Government of Arunachal Pradesh; Dr. R Balasubramaniam, Member (Human Resources), Capacity Building Commission; Shri S P Roy, Joint Secretary, Capacity Building Commission; and Shri Vivek HP, Secretary, Health &amp; Family Welfare, Government of Arunachal Pradesh, along with Secretaries and Heads of Departments from across the state administration.</p><p>Speaking at the event, Dr. R Balasubramaniam shared the program’s vision to build a more empathetic, citizen-centric civil service by training over 7,00,000 government officials across the country. He also highlighted the relevance of key Mission Karmyogi initiatives such as Gyaan Kosh and Indian Knowledge Systems for the governance ecosystem of Arunachal Pradesh.</p><p>In his keynote address, the Hon’ble Chief Minister reaffirmed the state’s commitment to capacity building and formally launched the Jan Seva Program, underscoring its importance in empowering civil servants to deliver better outcomes for citizens.</p><p>This marks a significant step forward in advancing a responsive, accountable, and people-first civil service.</p>', '', 'basic_html'),
('event', 0, 723, 1300, 'en', 0, '<p>In a significant step towards transforming the capacity-building landscape of civil servants in #Chhattisgarh, the Capacity Building Commission (CBC), Karmyogi Bharat, and the Government of Chhattisgarh signed a Memorandum of Understanding (MoU) on 28th July 2025 in Raipur. The signing ceremony took place in the august presence of the Hon’ble Chief Minister of Chhattisgarh, Shri Vishnu Deo Sai.</p><p>In his address, the Hon’ble Chief Minister affirmed that the initiative will be pivotal in nurturing a culture of excellence in governance and public administration across Chhattisgarh.</p><p>The event was attended by senior dignitaries including Shri Amitabh Jain, Chief Secretary, Government of Chhattisgarh; Dr. Alka Mittal, Member (Administration), Capacity Building Commission; Shri Subrat Sahoo, Director General, Chhattisgarh Academy of Administration; Smt. V. Lalithalakshmi Secretary, Capacity Building Commission and Chief Executive Officer, Karmyogi Bharat; and Shri S P Roy, Joint Secretary, Capacity Building Commission.</p><p>As part of the engagement, an orientation session was conducted for Secretaries, Heads of Departments, and Departmental Nodal Officers. The session highlighted #MissionKarmyogi’s vision of creating a future-ready and citizen-centric civil service through digital learning, role-based training, and continuous professional development.</p><p>Shri Rakesh Verma, Chief Operating Officer of Karmyogi Bharat, provided a live demonstration of the #iGOT Karmyogi platform, showcasing its key features that enable modular, self-paced, and role-aligned learning. He also emphasized the platform’s growing impact, with over 1.26 crore learners across the country benefiting from flexible, need-based capacity-building opportunities.</p><p>A key outcome of the discussions was the Government of Chhattisgarh’s commitment to onboard officials from various departments onto the iGOT platform and initiate their structured learning journeys. The state also expressed interest in co-creating learning content tailored to its unique governance needs. &nbsp;</p><p>The MoU marks the beginning of an institutional partnership to implement Mission Karmyogi’s vision of a competency-based, technology-driven, and continuous learning ecosystem for government officials in Chhattisgarh.</p><p>The Capacity Building Commission extends its gratitude to the Government of Chhattisgarh for its steadfast commitment to advancing Mission Karmyogi in the state. This collaboration underscores our shared resolve to empower public servants and foster a more agile, accountable, and citizen-centric governance ecosystem.&nbsp;</p>', '', 'basic_html'),
('event', 0, 724, 1301, 'en', 0, '<p>S P Roy, Joint Secretary, Capacity Building Commission conducted an enlightening session on Mission Karmyogi for all faculties of Mahatma Gandhi State Institute of Public Administration, (MGSIPA) on 25th July 25.</p><p>He talked about the process of creating Capacity Building Plans, Jan Seva Trainings, Amrit Gyaan Kosh, Faculty Development Program and the NSCSTI framework.</p><p>MGSIPA is making strides in progress of Mission Karmyogi and also working towards creating culture and courses fostering Indian Knowledge Systems.</p>', '', 'basic_html');
INSERT INTO `node__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('event', 0, 725, 1302, 'en', 0, '<p>On 25th July 2025, a landmark MoU was signed between the Capacity Building Commission (CBC), Karmyogi Bharat, and the Union Territory of Chandigarh, in the presence of the Chief Secretary, UT Chandigarh. An MoU between MGSIPA and Chandigarh Administration was also formalized to further the goals of Mission Karmyogi in the region.</p><p>Ms. V. Lalithalakshmi, IAS, Secretary, CBC and CEO, Karmyogi Bharat, emphasized the importance of mandatory annual course completions on the iGOT Karmyogi platform and informed about its linkage with APARs, as directed by DoPT. She also highlighted the new scoring framework that assesses Ministries/Departments on their capacity building progress.</p><p>Sh. Shyama Prasad Roy, Joint Secretary, CBC, introduced the Rashtriya Karmyogi Jan Seva Program, a behavioural training initiative, and urged for early identification of Master Trainers in Chandigarh to enable its rollout before 15th August 2025.</p><p>Ms. Alka Mittal, Member (Admin), CBC, joined the event virtually and lauded Chandigarh Administration for onboarding over 25,000 officials, enrolling in 1,00,000+ courses, and completing 90,000+ learning modules on the iGOT Karmyogi platform.</p><p>Shri Rajeev Verma, Chief Secretary, Chandigarh, directed all departments to expedite onboarding and course completion and proposed a review meeting under his chairmanship to track progress.</p><p>This collaboration marks a significant step toward transforming governance through continuous learning and upskilling under Mission Karmyogi.</p>', '', 'basic_html'),
('event', 0, 726, 947, 'en', 0, '<p>Dr. R Balasubramaniam, Member–HR, Capacity Building Commission, visited the Delhi Metro Rail Corporation (DMRC) Academy today to engage with the institution and gain insights into its training approach and organizational development model.</p><p>The Academy has demonstrated consistent improvements in training quality, currently holding a Three-Star rating under the NSCSTI framework. Dr. Balu reviewed their ongoing practices and experienced the simulation-based training technology used in preparing metro pilots.</p><p>He encouraged the Academy to:</p><p>1. Share selected training modules on the iGOT platform,<br>2. Contribute case studies to the Amrit Gyaan Kosh, and<br>3. Pursue re-accreditation under NSCSTI for continued quality enhancement.</p><p>Member HR also urged the Academy to strive for higher benchmarks of excellence and actively share its practices and learnings across the broader capacity building ecosystem. CBC and DMRC Academy discussed potential avenues for future collaboration in training design and knowledge exchange.</p><p>The Commission expresses its sincere appreciation to Mr. Ghansham Bansal, Dean, DMRC Academy, and his team for their hospitality and commitment to strengthening public service training.</p>', '', 'full_html'),
('event', 0, 727, 950, 'en', 0, '<p>In alignment with our mission to empower Urban Local Body (ULB) officials to be citizen-centric, future-ready, and outcomes-driven, the Capacity Building Commission (CBC), in collaboration with the Housing &amp; Urban Development Department, Government of Odisha, conducted a capacity-building workshop on 23rd July 2025 at the Odisha Urban Academy (OUA), Bhubaneswar.</p><p>The workshop convened 100+ ULB officials from across the state and featured domain and functional sessions on key areas such as the principles of #MissionKarmayogi, public procurement, and budget planning for ULBs, among others—equipping officials with the tools to drive more effective and accountable urban governance.</p><p>A major highlight was the demonstration of the #iGOTKarmayogi platform, emphasizing its role-based digital learning capabilities. With over 3 lakh officials from Odisha already onboarded, the state stands at the forefront of India’s digital capacity-building transformation.</p><p>The workshop was graced by senior dignitaries from both the Centre and the State, including Dr. Alka Mittal (Member – Administration, CBC), Smt. Usha Padhee, IAS (Principal Secretary, H&amp;UD Department, Government of Odisha), Shri S P Roy (Joint Secretary, CBC), Shri Satrughna Kar (Additional Secretary, H&amp;UD Department, Government of Odisha), and Dr Santanu Rath (Director, Odisha Urban Academy). Their presence and insights reaffirmed the shared commitment to strengthening institutional and individual capacities.</p><p>This initiative marks a significant step toward scalable, inclusive, and sustained capacity building across Odisha’s ULB ecosystem.</p><p><br>&nbsp;</p>', '', 'full_html'),
('event', 0, 728, 1245, 'en', 0, '<p>The National Standards for Civil Services Training Institutions (NSCSTI) 2.0 was officially launched by the Hon’ble Minister of State for Personnel, Public Grievances and Pensions, Dr Jitendra Singh at CSOI, Vinay Marg, New Delhi.</p><p>Developed by the Capacity Building Commission (CBC) under Mission Karmayogi, NSCSTI 2.0 marks a significant upgrade to the world\'s first accreditation framework designed exclusively for civil services training institutions (CSTIs). The framework offers enhanced flexibility, addresses emerging tech needs, and promotes a holistic, future-ready and community-driven ecosystem for civil services training institutions.</p><p>In the keynote address by Hon’ble Minister, Dr Jitendra Singh emphasized the importance of creating future-ready civil servants through globally benchmarked, outcome-oriented training systems. He noted that NSCSTI 2.0 reflects India’s commitment to building a citizen-centric and performance-driven bureaucracy.</p><p>Setting the context for the new framework, Adil Zainulbhai, Chairman, CBC, highlighted the need for CSTIs to evolve in step with a rapidly changing governance landscape and underlined the importance of continuous institutional learning and improvement.</p><p>Dr. R Balasubramaniam, Member HR, CBC, outlined the new and unique features of the framework, including the Karmayogi Competency Model (KCM), the Amrit Gyaan Kosh digital knowledge repository, and the Indian Knowledge System (IKS).</p><p>Dr Alka Mittal, Member Admin, CBC, spoke about the importance of quality in public training and urged CSTIs to pursue reaccreditation under the upgraded framework. She highlighted that NSCSTI 2.0 is not just about compliance but about driving a culture of excellence, innovation and accountability in training.</p><p>The event featured dignitaries from DoPT, CBC, and Karmayogi Bharat who spoke about the importance of strengthening the training ecosystem of civil services and furthering the vision of Viksit Bharat 2047.</p><p>As part of the launch, a ceremonial distribution of certificates was also held for institutes which were accredited under NSCSTI 1.0, recognizing the efforts of the civil service training institutions that have met national standards of excellence.</p><p>NSCSTI 2.0 sets a new benchmark in public sector training globally and reflects India’s leadership in governance reform and digital transformation in capacity building.</p>', '', 'full_html'),
('event', 0, 729, 1303, 'en', 0, '<div class=\"clearfix text-formatted field field--name-body field--type-text-with-summary field--label-hidden field__item\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><p style=\"box-sizing:border-box;font-family:Poppins, sans-serif;letter-spacing:0em;margin:0px 0px 1rem;padding:0px;\">Lead Trainer Training under the Rashtriya Karmyogi Large-Scale Jan Seva Program of CBC was held from 14th to 18th July at HIPA, Gurgaon</p></div><div class=\"field field--name-field-event-venue field--type-string-long field--label-inline clearfix\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><br>&nbsp;</div>', '', 'full_html'),
('event', 0, 730, 1304, 'en', 0, '<p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Capacity Building Commission, along with Karmyogi Bharat, met the Hon’ble Chief Minister of Delhi, Smt. Rekha Gupta and Chief Secretary to discuss the way forward for implementing #MissionKarmyogi in the Government of NCT of Delhi.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Under the Hon’ble CM’s leadership, Delhi is set to onboard 80,000 officials onto the #iGOTKarmyogi platform-marking a significant step in building a future-ready civil service.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The discussion led to 3 key outcomes:<br>• 100% Onboarding: All Group A, B, and C officials of the Delhi Government will be onboarded on #iGOT portal to enable continuous, structured learning.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">• Departmental Participation: A directive will be issued mandating participation of all departments with a nodal officer designated to drive the effort.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">• Jan Seva Rollout: A large-scale citizen-first governance initiative will be launched across departments.<br>&nbsp;&nbsp;&nbsp;&nbsp;<br>Mission Karmyogi continues to expand across states and UTs empowering every civil servant with the competencies and tools to deliver better #governance and public service.</p>', '', 'full_html'),
('event', 0, 731, 956, 'en', 0, '<p>Under #MissionKarmayogi, states are stepping forward to build a culture of continuous learning and #Bihar joins the growing list, embracing it.</p><p>As envisioned by the Hon’ble Prime Minister Shri Narendra Modi Ji, every state is being encouraged to onboard onto #iGOTKarmayogi to make learning a core part of governance.</p><p>After successful Learning Weeks in Andaman &amp; Nicobar, Maharashtra and Rajasthan, it’s encouraging to see Bihar take this forward through the launch of #BiharLearningWeek (11–17 July 2025), a powerful step toward building a self-driven and future-ready government workforce.</p><p>As part of Mission Karmayogi, every official is encouraged to complete at least 4 hours of learning on #iGOT platform or curated webinars.</p><p>This growing momentum reflects a shared national commitment to make learning continuous, relevant, and rooted in-service delivery.</p><p>Congratulations to the Government of Bihar, Capacity Building Commission and Karmayogi Bharat team for taking this forward.</p>', '', 'basic_html'),
('event', 0, 732, 965, 'en', 0, '<p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Member-HR, Dr. R Balasubramaniam, Capacity Building Commission, led a workshop on 10th July 2025 for Capacity Building Units of MDOs, attended by CBU Heads and officials from 30 Ministries and Departments.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">It focused on:</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">🔹 Clarifying the roles of CBUs<br>🔹Understanding what competencies are needed for different roles<br>🔹 Improving implementation and monitoring of Capacity Building Plans (CBPs)<br>🔹 Planning for domain course development and the Rashtriya Karmayogi Large Scale Jan Seva Program rollout<br>🔹Facilitating cross-learning through the exchange of good practices across Ministries</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Dr. Anju Rathi Rana, ILS, Secretary, Department of Legal Affairs, shared impactful best practices for implementing Mission Karmayogi undertaken under her leadership—setting a strong example for peer Ministries. The workshop enabled CBUs to recalibrate their strategies for structured, demand-driven capacity building aligned with the Karmayogi Competency Model.</p>', '', 'full_html'),
('event', 0, 733, 1306, 'en', 0, '<p>Through deep partnerships with states, the Capacity Building Commission is building the foundation for a future-ready civil service, one that is skilled, responsive and aligned to the aspirations of a changing #India.</p><p>Today, a tripartite MoU was signed between the Capacity Building Commission (CBC), Karmyogi Bharat and the Government of Tripura, marking a key milestone in strengthening governance capabilities in the state.</p><p>The signing was followed by an orientation session led by Dr. R Balasubramaniam, Member (HR), CBC, introducing the framework and vision of #MissionKarmyogi. Ms. Shobhana Rana, Advisor on Content Development and Partnerships, Karmyogi Bharat, familiarised officials with the functionalities and usage of #iGOTKarmyogi Platform. Shri J.K. Sinha, Chief Secretary, Tripura, reaffirmed the state’s resolve to promote mindset change and strengthen a governance model that is both citizen-centric and digitally driven. S P Roy, Joint Secretary, CBC, outlined specific areas where #Tripura can collaborate with #CBC and #KarmyogiBharat, reinforcing the state’s intent to embed structured capacity-building in its governance approach.</p><p>The orientation witnessed active participation from Secretaries, Special Secretaries, Directors, and Heads of 51 departments of the Government of Tripura.</p><p>With this partnership, Tripura joins the national movement to build responsive, capable and future-ready civil service contributing to the vision of #ViksitBharat. The state is also experimenting with several transformational initiatives, offering valuable learnings for CBC and other states we collaborate with.</p>', '', 'basic_html'),
('event', 0, 734, 960, 'en', 0, '<p>Capacity Building Commission and Karmayogi Bharat jointly hosted ‘DigiManthan’ at Vigyan Bhawan on 16.04.24 to help Civil Services Training Institutions create more e-learning courses.</p><p>In a significant step towards embracing technology, Central Training Institutes are stepping up their game. Yesterday, 24 CTIs committed to launching a total of 78 digital courses by June 30th. This initiative will revolutionize the delivery of digital training for all central civil servants!</p>', '', 'basic_html'),
('event', 0, 735, 963, 'en', 0, '<p>Dr. R Balasubramaniam, Member-HR, Capacity Building Commission, participated as a panelist in the session on “IKS and Institutional Building” at the First Annual Academic Conference on Indian Knowledge Systems, held at Jawaharlal Nehru University.</p><p>The session focused on the relevance of Indian Knowledge Systems (IKS) in shaping institutional frameworks and building public leadership. Dr. Balasubramaniam spoke about how IKS and capacity building are closely linked, particularly in the context of lifelong learning as a continuous process for both individuals and institutions.</p><p>He also highlighted the need to integrate citizen-centric governance as a core outcome of capacity building efforts, drawing on indigenous knowledge and contextual understanding to make public systems more responsive and inclusive.</p><p>The conference brought together academics, practitioners, and policymakers to explore how IKS can inform contemporary governance and institutional development in India.</p>', '', 'full_html'),
('event', 0, 736, 966, 'en', 0, '<p>On 21st April 2025, the Capacity Building Commission, in partnership with #SCOPE (Standing Conference of Public Enterprises) launched #DAKSH (Development of Aspiration, Knowledge, Succession and Harmony)-a first-of-its-kind leadership program designed exclusively for senior executives of India’s Central Public Sector Enterprises (CPSEs). With McKinsey &amp; Company and Indian Institute of Management Ahmedabad as Knowledge Partners, DAKSH is a transformative initiative that aims to build a future-ready, value-driven leadership pipeline for the public sector.</p><p>The program was launched by Shri Arunish Chawla, Secretary, DIPAM, in the presence of Shri Adil Zainulbhai, Chairman, CBC; Smt. Soma Mondal, Member, Public Enterprises Selection Board (PESB); Shri K.P. Mahadevaswamy, Chairman, SCOPE; Shri Atul Sobti, DG, SCOPE; and Dr. Alka Mittal, Member (Administration), CBC. Their powerful insights set the tone for a future-ready, purpose-driven leadership agenda. The CMDs and Director(HR)s of #CPSEs also attended the launch program.</p><p>As CPSEs play a central role in India’s economic and social development, it is critical to develop competent, innovative and agile leaders. DAKSH is about preparing leaders to navigate complexity, scale impact, and steer India’s most strategic institutions towards inclusive, sustainable growth. It is a unique program built on world-class design principles, tailored to the Indian context.</p><p>As the DAKSH leadership journey began for the first cohort of over 70 senior officers of CPSEs, it is set to become a global benchmark in public leadership development.</p>', '', 'basic_html'),
('event', 0, 737, 967, 'en', 0, '<p>Capacity Building Commission (CBC) has signed a contract with the Kaivalya Education Foundation (KEF) to lead a transformative initiative focused on strengthening Panchayati Raj Institutions (PRIs).</p><p>As part of this partnership, 60 Gram Panchayats across Andhra Pradesh, Assam, Gujarat and Odisha will see implementation of a demonstrable, measurable, and scalable model of capacity building at the grassroots level.</p><p>Anchored in the vision of Mission Karmayogi, the initiative aims to enhance the capabilities of both elected representatives and government functionaries, fostering more effective, responsive, and citizen-centric governance.</p><p>Key Highlights:<br>🔹 Tech-enabled ecosystem for continuous capacity building<br>🔹 Custom-built e-learning platform, mobile app, and AI-powered chatbot<br>🔹 Personalized learning and on-demand support for PRI members<br>🔹 On-ground implementation anchored by KEF under the guidance of CBC</p><p>This partnership marks a major milestone as Mission Karmayogi expands to the last mile—empowering local institutions to become future-ready agents of change.</p><p>Together, we’re moving closer to a Viksit Bharat through stronger, more accountable Panchayats.</p>', '', 'full_html'),
('event', 0, 739, 1308, 'en', 0, '<p>Top leadership is in the room today because true transformation requires alignment at every level. Bottom-up change only succeeds when it is met with committed, value-driven leadership from the top. That is why Secretaries and Additional Secretaries from over 40 Ministries and Departments are undergoing an immersive orientation to lead Phase II of the Rashtriya Karmyogi – Large Scale Jan Seva Programme (RK-LSJSP)-India’s largest cognitive and behavioural transformation in governance.</p><p>This program is not about policy tweaks or procedural shifts-it’s about reimagining public service itself. Designed to reach over 7,00,000 government officials across Bharat,Rashtriya Karmyogi aims to instill hashtag#SevaBhaav, strengthen purpose, and embed citizen-first thinking across the system. As the architects of India’s governance machinery, Secretaries and Additional Secretaries are not just participants-they are the catalysts of this mission, anchoring the change within their ministries and setting the tone for cascading leadership across the country.</p>', '', 'basic_html'),
('event', 0, 740, 970, 'en', 0, '<p>At the heart of today’s Learning &amp; Development Workshop at National Academy of Agricultural Sciences -NAAS India, teams stepped into innovation labs-crafting the future of grassroots governance. As part of the Capacity Building program for #ViksitPanchayat, each breakout room became a hub of collaboration where real-world challenges were met with purpose-driven design.</p><p>The modules being shaped go beyond theory. They are anchored in field realities, focused on equipping Panchayat leaders with the skills, mindsets, and tools needed to lead transformation on the ground. With citizen-centricity at their core, these learning journeys aim to make local governance the driving force behind a truly #ViksitBharat.</p>', '', 'basic_html'),
('event', 0, 741, 971, 'en', 0, '<p><span style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);color:rgb(33, 37, 41);display:inline !important;float:none;font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The International Day of Yoga has been celebrated across the world annually on June 21 since 2015. This year 2025, the theme for International Day of Yoga is “Yoga for One Earth, One Health.” Yoga, a transformative practice, represents the harmony of mind and body, the balance between thought and action, and the unity of restraint and fulfillment. It integrates the body, mind, spirit, and soul, offering a holistic approach to health and well-being that brings peace to our hectic lives. Its power to transform is what we celebrate on this special day.</span></p>', '', 'full_html'),
('event', 0, 742, 972, 'en', 0, '<p>The Capacity Building Commission organised a two-day consultative workshop on the \"Capacity Building Needs of Civil Services of India\" at the Lal Bahadur Shastri National Academy Of Administration from 22nd to 23rd April 2024.</p><p>The workshop included the participation of leadership and senior faculties from the 25 Central Training Institutions (CTIs), the respective Cadre Controlling Authorities, and senior leadership from LBSNAA and the Department of Personnel and Training (DoPT).</p>', '', 'basic_html'),
('event', 0, 743, 1309, 'en', 0, '<p>With 6000 officials trained across 49 MDOs so far - the Rashtriya Karmyogi Large Scale Jan Seva Program - Phase 1 is helping government officials connect their work with service to citizens.</p><p>Today, Department of Administrative Reforms and Public Grievances, Government of India and Department of Pension &amp; Pensioners\' Welfare (DoPPW) hosted an event to share feedback and thank the Capacity Building Commission (CBC) for facilitating Phase 1 of the program for their departments. The training had a noticeable impact on officers-helping them reflect on their work with greater clarity, build stronger connections with citizens, and understand how their roles contribute to the broader goals of governance. Seeing this shift among their teams, the departments came together to acknowledge the value of the program and express their appreciation for the structured approach taken by #CBC.</p><p>Master Trainers and participants spoke about how the training helped them reflect on their role and connect daily tasks with a deeper purpose of public service.</p><p>Shri Srinivas Voruganti, Secretary, DARPG and DoPPW, appreciated the training effort and its relevance for improving public service delivery.</p><p>Dr. R Balasubramaniam, Member (HR), CBC, and Adil Zainulbhai, Chairman, CBC, shared their remarks and thanked officials for their honest reflections and participation.</p><p>We now look forward to Phase 2, which will train 7,00,000 officials across Bharat, further strengthening citizen-first governance.</p>', '', 'basic_html'),
('event', 0, 744, 974, 'en', 0, '<p>Under #MissionKarmayogi, the Capacity Building Commission (CBC), in collaboration with the Directorate of Urban Local Bodies (DULB), Government of Haryana, organized a one-day Capacity Building Workshop for Urban Local Bodies (ULBs) of the state at the Haryana Institute of Public Administration (HIPA), Gurugram.</p><p>The workshop witnessed the participation of over 100 senior officials, including Municipal Council Presidents, Commissioners, District Municipal Commissioners, Executive Officers, and representatives from #DULB and #HIPA. Participants were introduced to the #iGOTKarmayogi platform aimed at fostering a culture of anytime, anywhere, #ContinuousLearning for government officials. Deliberations throughout the day centered on embedding the principles of citizen-centric #governance and enhancing service delivery – key principles of Mission Karmayogi.</p><p>The event was graced by the presence of Smt. Rajrani Malhotra (Hon\'ble Mayor, Gurugram Municipal Corporation), Dr. Alka Mittal (Member – Administration, CBC), Shri Pankaj (Director General, DULB Haryana), Shri S P Roy (Joint Secretary, CBC), and Shri Pradeep Dahiya (Commissioner, Municipal Corporation Gurugram).</p><p>This workshop marks a pivotal step in equipping Haryana’s urban governance ecosystem with the skills and capacities needed to realize the vision of #ViksitBharat2047.</p>', '', 'full_html'),
('event', 0, 745, 977, 'en', 0, '<p>As part of #MissionKarmayogi, Capacity Building Commission (CBC) is committed to enhancing the competencies of all civil servants, including those in Central Public Sector Enterprises (CPSEs). In today’s dynamic and rapidly evolving landscape, CPSEs need agile and future-ready leaders capable of driving transformative growth.</p><p>To support this vision, CBC, in collaboration with the Standing Conference of Public Enterprises (#SCOPE), signed an MoU on 17th June 2025 to launch the second edition of the #DAKSH Program. This program under this initiative will be delivered with Egon Zehnder as the Knowledge Partner and the Indian Institute of Management, Indore as the Academic Partner.</p><p>Egon Zehnder and #IIM Indore will co-design and implement a cutting-edge leadership program focused on building strategic, functional and behavioral capabilities among senior #CPSE executives.</p><p>The program is tailored for high-potential leaders-GMs, CGMs, and EDs-who are poised to take on Board-level roles in the near future. Through this initiative, we aim to create a robust talent pipeline of visionary and competent public sector leaders.</p><p>We express our sincere gratitude to our esteemed committee members Mr. Ayush Gupta, Director (HR), GAIL (India) Limited, Mr. K K Singh, Director (Personnel), Steel Authority of India Limited, Dr. Vinay Ranjan, PhD, Director (HR), Coal India Limited for their continued support and guidance. Thanks to Dr. Alka Mittal, Member (Admin), CBC and Mr. Atul Sobti, Director General, #SCOPE, for their drive and leadership in making this happen.</p><p>This is a step forward in shaping a new generation of visionary public sector leaders-leaders who will help deliver a capable, competent and confident #ViksitBharat.</p>', '', 'full_html'),
('event', 0, 746, 1385, 'en', 0, '<p>The Capacity Building Commission (CBC) held a meeting with the Chandigarh Administration for implementation of #MissionKarmayogi in the Union Territory of Chandigarh.</p><p>The meeting was presided over by Shri Rajeev Verma, IAS, Chief Secretary- Union Territory of Chandigarh, and attended by all Heads of department and other senior officials of the Union Territory.</p><p>The CBC team, led by Dr. Alka Mittal, Member (Administration), and Smt. V Lalithalakshmi, Secretary, CBC and CEO, Karmayogi Bharat, provided an insightful overview of Mission Karmayogi — the National Program for Civil Services Capacity Building. The team highlighted the importance of capacity-building through Capacity Building Plans for all UT Chandigarh departments and the transition to role-based, competency-driven learning, while also providing a walkthrough of the iGOT platform in enhancing governance capabilities.</p><p>To drive the successful implementation of Mission Karmayogi in Chandigarh, the Chief Secretary directed the immediate formation of Capacity Building Unit (CBU), ensuring 100% onboarding of officials onto the #iGOT platform and completion of at least four courses by all officials within a month. A dedicated workshop will also be conducted by the #iGOTKarmayogi Bharat team, to guide nodal officers in effectively navigating the platform.</p>', '', 'basic_html'),
('event', 0, 747, 978, 'en', 0, '<p>Dr. R Balasubramaniam, Member (HR), Capacity Building Commission, visited the Matsushita Institute of Government and Management, Japan.</p><p>During his visit, he interacted with the Institute’s senior leadership and associates currently undergoing training to serve in public life. The discussions focused on understanding how the Institute nurtures young professionals to take on leadership roles in governance and public service.</p><p>Founded in 1979 by Konosuke Matsushita, the Institute was built on the belief that solving a nation\'s problems requires nurturing ethical, visionary leaders-not just bureaucrats. Its model combines intensive field experience, long-term mentoring, and a strong moral foundation. Over 50% of its alumni have gone on to hold elected office in Japan including Prime Ministers, Ministers, and Governors - a rare, measurable example of leadership development directly shaping national governance.</p><p>This aligns closely with CBC’s commitment to transforming India’s civil services into a citizen-centric, future-ready workforce-grounded in values and driven by purpose.</p>', '', 'basic_html'),
('event', 0, 748, 979, 'en', 0, '<p>Under #MissionKarmayogi, the Capacity Building Commission (CBC), in collaboration with the Department of Municipal Administration and Urban Development (MA&amp;UD), Government of Andhra Pradesh, and with the support of the Commissioner and Director of Municipal Administration (CDMA), organized a one-day #CapacityBuilding Workshop for Urban Local Bodies (ULBs) at the School of Planning &amp; Architecture Vijayawada.</p><p>The workshop brought together 175+ officials from 123 ULBs and key urban departments—including MEPMA, Public Health, and Town Planning.</p><p>Participants were introduced to the #iGOTKarmayogi platform to foster a culture of continuous learning for citizen-centric governance, and professional development. The discussions helped identify key training needs and priority areas for skilling ULB officials to drive better outcomes on the ground.</p><p>The workshop was graced by the presence of Shri Sureshkumar S Nair, I.A.S. (Principal Secretary, MA &amp; UD, Andhra Pradesh); Dr. Alka Mittal, Member (Admin), Capacity Building Commission; Smt. V. Lalithalakshmi, I.A.S. (Secretary, CBC and CEO, Karamayogi Bharat); and Dr. P. Sampath Kumar, I.A.S. (Commissioner &amp; Director of Municipal Administration).</p><p>This initiative is a step toward building a resilient, future-ready urban workforce, aligned with the vision of #SwarnaAndhra2047.</p>', '', 'full_html'),
('event', 0, 749, 1050, 'en', 0, '<p>The Capacity Building Commission carried out an on-site assessment at the Animal Training School, Indo-Tibetan Border Police, in Lohitpur, Arunachal Pradesh on 21st and 22nd March 2025.</p><p>We are delighted to announce that the institute has successfully achieved accreditation under the NSCSTI - National Standards for Civil Service Training Institutions | Capacity Building Commission. The assessment was efficiently facilitated by col (Dr) K Jagannathan and S P Roy, Joint Secretary, Capacity Building Commission, along with Jagan Sridhar and Susan Thomas.</p><p>A heartfelt thanks to the nodal officer, Mr. Pamei and his team for his support in ensuring a smooth process.</p>', '', 'basic_html'),
('event', 0, 750, 983, 'en', 0, '<p>Day 1 Highlights | Rise with Pride: Lead. Evolve. Transform 🌟<br>📍 Alleppey, Kerala<br>📅 11th June 2025<br>We are proud to kick off “Rise with Pride: Lead. Evolve. Transform”, a high-impact leadership development program set against the tranquil backdrop of Kerala.<br>With 50 senior professionals from both the Public Sector and Private Sector joining us, the energy, experience, and diversity in the room set the stage for powerful exchanges and meaningful learning.<br>✨ Day 1 Key Moments:<br>🔹 Welcome Address<br>By Dr. Alka Mittal, Member – Capacity Building Commission of India, Former CMD &amp; Director (HR), ONGC, and our esteemed Program Advisor. She highlighted the critical role of leadership evolution in building future-ready organizations.<br>🔹 Keynote Address<br>By Ms. Usha Singh, Director (HR), MOIL. Her address encouraged leaders to lead with authenticity, empathy, and strength.<br>🔹 Inaugural Address<br>By Dr. Dr. Ranjit Rath, Chairman &amp; Managing Director, Oil India Limited. His words inspired participants to embrace transformation and lead with vision.<br>🪔 Ceremonial Lighting of the Lamp</p><p>Dr. Alka Mittal, Ms. Usha Singh, and Dr. Dr. Ranjit Rath Rath came together to light the ceremonial lamp—an auspicious beginning to four days of growth, dialogue, and discovery.<br>This is only the beginning of an enriching journey. Stay tuned for more updates as we continue to lead, evolve, and transform together.</p><p>&nbsp;</p>', '', 'full_html'),
('event', 0, 752, 1311, 'en', 0, '<p>Rashtriya Karmyogi Large Scale Jan Seva Program – From Learning to Action.</p><p>The Rashtriya Karmyogi Program has trained another additional batch of officials from multiple ministries and departments over the past 3 days, continuing its mission of embedding #SewaBhaav in governance. Officials stepped away from their desks to rethink their role-not just as administrators, but as facilitators of citizen-centric service.</p><p>Understanding how every action-big or small-impacts citizens, this program is not just training but a shift in perspective rooted in Seva Bhaav and Svadharma. From the way policies are communicated to how challenges are approached, this program has encouraged participants to see governance through the lens of impact rather than process.</p><p>Now, as certified Master Trainers, they take on the responsibility of further training officials within their respective ministries, departments, and organizations-ensuring that service-oriented governance is not just discussed in a training room, but practiced at every level.</p><p>And this is just one step in a larger journey. With the next phase set to train 700000 government officials across Bharat, the movement is not far. The shift from process-driven to purpose-driven governance is taking shape.</p>', '', 'basic_html'),
('event', 0, 753, 1312, 'en', 0, '<p>A landmark moment for governance in the Capital</p><p>Government of NCT of Delhi Signs MoU with Capacity Building Commission and Karmyogi Bharat for Implementation of #MissionKarmyogi</p><p>In a major step towards strengthening governance and public service delivery, the Government of the National Capital Territory (NCT) of Delhi today signed a Memorandum of Understanding (MoU) with the Capacity Building Commission (CBC) and Karmyogi Bharat for the implementation of Mission Karmyogi.</p><p>The MoU was signed in the presence of the Hon’ble Chief Minister of Delhi, Smt. Rekha Gupta; the Chief Secretary of Delhi, Shri Dharmendra; Member (Administration), Capacity Building Commission, Dr. Alka Mittal and other senior officials from #CBC, Karmyogi Bharat and Delhi Government.</p><p>Under the visionary leadership of the Hon’ble Chief Minister, #Delhi is now poised to scale this effort significantly by onboarding all officials onto the #iGOT portal, marking one of the largest state-level initiatives under Mission Karmyogi.</p><p>Capacity Building Commission and Karmyogi Bharat commended the leadership of the Delhi Government and assured full support in enabling continuous learning and strengthening capacities of all the officials. This includes assistance in formulating Capacity Building Plans (CBPs) for departments, and strengthening the capacities of urban local body (ULB) officials to deliver citizen-centric services more effectively. And Large Scale Intervention for Delhi government officials for inculcating Sewa Bhav.</p><p>With this milestone, Mission Karmyogi continues to expand its footprint across states and Union Territories, creating a uniform and progressive ecosystem for capacity building.</p>', '', 'full_html'),
('event', 0, 754, 1386, 'en', 0, '<p>Reimagining Civil Service Training: Decolonizing Mindsets &amp; Institutions</p><p>For decades, India\'s CSTIs have operated within frameworks inherited from colonial rule-shaping administrative structures, policy-making approaches &amp; institutional cultures that often remain disconnected from realities of Bharat’s civilizational ethos. This calls for a necessary shift.</p><p>Today @IIT Delhi, Abhijnana-Workshop on Decolonizing CSTIs brings together thought leaders, policymakers &amp; academics to initiate this transformation. Organized by Capacity Building Commission,Training Division, DoPT, IKS Program @IIT Delhi &amp; INDICA, this workshop is designed to empower civil servants &amp; CSTIs with intellectual tools to draw from IKS-not as an abstract idea, but as a practical approach to governance &amp; administration.</p><p>Nomesh Bolia, Prof., IIT Delhi,remarked that civil services are deeply respected in India not just for their authority but for their role in nation-building,urging participants to explore how key concepts can be materialized into actionable steps for decolonization.</p><p>Prof. KE Seetha Ram,Senior Consulting Specialist, ADB Institute, highlighted that institutional transformation requires rethinking foundational frameworks &amp; that IKS offers a way to rebuild civil service training programs in alignment with India\'s unique governance needs.</p><p>S P Roy, Jt. Secretary, CBC,highlighted importance of building a mindset around Indian Knowledge System and its role in governance &amp; capacity building.</p><p>Dr. R Balasubramaniam, Member (HR), CBC, led key discussions today. His insights on how colonial constructs continue to shape public service &amp; need to realign governance with India’s cultural &amp; knowledge traditions will be instrumental in reshaping civil service training. Drawing from Panch Pran, he emphasized the need for capturing &amp; institutionalizing success stories to ensure governance becomes a structured, repeatable process that strengthens public institutions.</p><p>Shri Amit Khare (IAS), Advisor to the Hon’ble PM, the Chief Guest, reinforced that Viksit Bharat can only emerge when every state, village &amp; citizen progresses together.He emphasized a ‘saturation approach’ where every individual contributes to the nation’s growth story.He also commended CBC’s role in bringing IKS closer to civil servants, ensuring governance remains deeply connected to India’s knowledge traditions.He also made a poignant remark emphasizing the importance of sustaining their commitment to serving the nation, just as it is when they first embark on their journey in civil service.</p><p>The workshop will explore<br>🔸 Why we must decolonize our institutions<br>🔸 What elements of governance &amp; training need transformation<br>🔸 How to embed IKS into CSTI curricula, functional practices &amp; institutional culture</p><p>The workshop progresses to work towards redefining how civil servants are trained-so that they don’t just manage a system,but actively build one that is rooted in India’s knowledge traditions.</p>', '', 'basic_html'),
('event', 0, 755, 988, 'en', 0, '<p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The Capacity Building Commission conducted an on-site assessment of the National CPWD Academy, Ghaziabad (Delhi NCR) on 28th and 29th May 2025.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">We are pleased to share that the institute has successfully attained accreditation under the National Standards for Civil Service Training Institutes (#NSCSTI).</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The assessment process was effectively facilitated by Dr. Alka Mittal, Member (Administration), CBC, Shri Prasanta Kumar Mahapatra, Assessor along with Ritika Aggarwal, NABET and Susan Thomas, CBC.</p><p style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:Poppins, sans-serif;font-size:17.136px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin:0px 0px 1rem;orphans:2;padding:0px;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Our sincere appreciation goes to Shri Ujjwal Mitra, ADG (T&amp;R) and his dedicated team for their exemplary support in ensuring a seamless and well-coordinated assessment process.</p>', '', 'full_html'),
('event', 0, 756, 990, 'en', 0, '<p>While iGOT has come a long way-</p><p>With 8 million users and 1,900 courses-there’s still a massive opportunity ahead. Today, learners engage for just 3 hours a year. Imagine if we could shift that to 25 hours per user today, not as an obligation, but as a habit, a mindset, a way of life, and make doing that “cool”!</p><p>That’s exactly why #CBC and #iGOT brought together some of India’s sharpest minds in marketing, branding, and digital engagement at ‘KarmaConnect: Increasing Learner Engagement’ workshop. They didn’t just discuss ideas; they challenged the way we think about #learning.</p><p>Leaders and changemakers like Suhel Seth (Founder &amp; Managing Partner, Counselage India), Ajay Gahlaut (Independent Creative &amp; Former CCO, Dentsu Creative Service), Sahibjeet Singh Sawhney (Marketing Head, Zomato), Pankaj Bansal (पंकज बंसल) (Board Member, KB, &amp; Co-founder, Peoplestrong), Gayatri Yadav (Group CMO &amp; EVP, Strategic Initiatives, Reliance Industries), Hari Krishnan (Managing Director, Publicis Content &amp; GroupéMarcomm), Biju Dominic (Chief Evangelist, Fractal Analytics), Prashasti Rastogi (Senior Director, Education and Government, Coursera), Sumit Harjani (Managing Director, India, Harvard Business Publishing), Swati Agarwal (Partner, Deloitte), Abhishek Singh (Additional Secretary, Ministry of Electronics and IT, and CEO, India AI Mission) didn’t hold back. They broke down engagement into its raw elements - behavior, motivation, habit-building.</p><p>💡 Why do people binge-watch content but struggle with courses?&nbsp;<br>💡 What makes a message stick?&nbsp;<br>💡 How do we make learning irresistible?</p><p>Discussions went beyond theory. Behavioral nudges, branding that inspires action, and celebrating learners like influencers-all of this was put on the table. 15 pages of brilliant ideas that we now have the responsibility to bring to life.</p><p>Thank you to all our participants for helping us drive #iGOT and #MissionKarmayogi to new heights!</p>', '', 'basic_html');
INSERT INTO `node__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('event', 0, 757, 994, 'en', 0, '<p>Building towards a future-ready civil service, the Capacity Building Commission is cultivating deep partnerships with states, fostering skilled and responsive governance aligned with India\'s evolving needs.</p><p>Today marks a significant milestone as the Capacity Building Commission (CBC), Karmayogi Bharat, and the Government of Arunachal Pradesh signed a tripartite MoU. This agreement signifies a pivotal step in enhancing governance capabilities within the state.</p><p>The signing ceremony was followed by an insightful orientation session led by Dr. R Balasubramaniam, Member (HR) at CBC, focusing on #MissionKarmayogi and the Karmayogi Competency Model (#KCM). Ms. Soumi Banerjee, GM – Strategic Alliance and Partnership from Karmayogi Bharat, provided an overview of the functionalities and usage of the iGOT platform.</p><p>Shri Manish Kumar Gupta, Chief Secretary of Arunachal Pradesh, emphasized the critical importance of #CapacityBuilding for government officials and highlighted the need for a transformative mindset among civil servants. He also commended Mission Karmayogi for its structured approach to competency development.</p><p>Shri S P Roy, Joint Secretary, CBC, outlined specific areas for collaboration between the state and #CBC, while Shri Yashpal Garg, Commissioner of the Department of Personnel, underscored the necessity of tailored training programs based on identified needs.</p><p>The orientation session saw active participation from Secretaries, Special Secretaries, Commissioners, Additional Secretaries, Joint Secretaries, Directors, and Heads of departments from across the Government of Arunachal Pradesh.</p>', '', 'full_html'),
('event', 0, 758, 1394, 'en', 0, '<p>The Department of Social Justice and Empowerment (DoSJE) inaugurated the first batch of the Rashtriya Karmayogi Jan Seva Program on 5th March 2025—a transformative training initiative launched by the Capacity Building Commission to foster Seva Bhav (spirit of service) among government officials.<br><br>Hon’ble Shri Amit Yadav, Secretary, DoSJE, in his inaugural address, reinforced the essence of public service: “Every action taken by public servants contributes to the nation’s progress. This program serves as a reminder of why we serve—to bring meaningful change in people’s lives.”<br><br>The training is being led by Ms. Kajal Singh (Director, DoSJE), Shri Puspendra Singh (Deputy Secretary, DoSJE), and supported by Ms. Shipra Singh (Capacity Building Commission).</p><p>Held at Dr. Ambedkar International Centre, New Delhi, the ongoing training program is witnessing active participation from officials as they gain deeper insights into their roles in nation-building, policy formulation, grievance redressal, and citizen-centric governance. This initiative continues to strengthen efforts toward a more efficient, impactful, and service-driven public administration.</p>', '', 'basic_html'),
('event', 0, 759, 998, 'en', 0, '<p>Capacity Building Commission is pleased to support the dynamic efforts led by Smt. Tilotama Varma, DG, UP Police Training; to train 60,000 newly recruited #police constables in #UttarPradesh. Together with Karmayogi Bharat, CBC will enable curated learning on the #iGOTKarmayogi platform and #JanSeva training - building a new generation of police personnel committed to citizen-first governance.</p><p>&nbsp;</p>', '', 'full_html'),
('event', 0, 760, 999, 'en', 0, '<p>Dr. R Balasubramaniam, Member (HR), Capacity Building Commission met with the faculty of Kautilya School of Public Policy, Hyderabad, to discuss ways to enhance the effectiveness of Knowledge Partners (KPs) in civil services #CapacityBuilding.&nbsp;</p><p>The conversation focused on strengthening collaboration between CBC and academic institutions to develop high-quality, competency-based training for civil servants. Dr. Balasubramaniam emphasized the role of KPs in shaping structured learning programs, designing relevant courses on #iGOT, and contributing research-driven insights to improve governance and public service delivery. The discussion also explored opportunities for the institution to contribute to Amrit Gyaan Kosh through case writing and to engage students as interns, fostering a deeper connection between academic research and real-world policymaking.</p>', '', 'basic_html'),
('event', 0, 761, 1000, 'en', 0, '<p>Tech WARI – Maharashtra Tech Learning Week was inaugurated today at the Mantralaya, Mumbai by Hon’ble Deputy Chief Minister Shri Ajit Pawar and Hon’ble Cabinet Minister for IT &amp; Cultural Affairs (Maharashtra) Shri Ashish Shelar.</p><p>An initiative of the Government of Maharashtra, in partnership with Karmayogi Bharat and the Capacity Building Commission, #TechWARI brings together learners, leaders, and innovators to celebrate digital empowerment in governance.</p><p>As part of the in-person sessions today, Distinguished Fellow, NITI Aayog, Ms Debjani Ghosh spoke on ‘Frontier Tech for Viksit Maharashtra’, and CEO, IndiaAI Mission &amp; DG, NIC, Shri Abhishek Singh addressed the gathering on ‘Artificial Intelligence’.</p><p>Visit the iGOT Karmayogi stall over the next 4 days to explore how Maharashtra’s officials are upskilling for the future!</p><p>With nearly 5 lakh learners enrolled in over 15 lakh courses and more than 10 lakh completions on the iGOT platform, Maharashtra now ranks among the top 3 performing States in the country.</p>', '', 'full_html'),
('event', 0, 763, 1002, 'en', 0, '<p>Adil Zainulbhai, Chairman of the Capacity Building Commission (CBC), held insightful discussions with the Secretary, Department of Commerce to explore the ways to enhance learning and development within the department.</p><p>The discussions focused on:<br>Utilizing the iGOT platform<br>Development of courses aligned with the department’s priorities<br>Conducting workshops to equip officials with cutting-edge knowledge<br>Charting a future roadmap</p><p>With a strong commitment to upskilling, these initiatives will play a crucial role in enhancing the capabilities of officials, fostering efficiency, and driving excellence in #trade and #commerce.&nbsp;</p>', '', 'full_html'),
('event', 0, 764, 1003, 'en', 0, '<p>Today marks a defining moment as we launch Phase II of the Rashtriya Karmayogi Large Scale Jan Seva Programme at Indian Institute of Corporate Affairs , IMT Manesar (Lead Trainer Training Workshop). What began by impacting over 11,000 civil servants in Phase I is now set to scale to reach 700,000 government officials across Bharat, guided by a shared purpose and strengthened by Illumine Knowledge Resources, our knowledge partner in this transformative journey.</p><p>This is not a training rollout but a national movement, led by 300 Lead Trainers and 20,000 Karmayogi Coaches, designed to spark deep shifts in mindset, motivation and method across every office, from the grassroots to the highest corridors of administration.</p><p>We are not just building skills but building a citizen-first civil service, powered by purpose and anchored in Seva Bhaav.</p><p>The scale is historic. The intent is urgent. And the outcome will shape how #Bharat is served in the years to come.</p><p>Ms. Ankita Singh, Director, Capacity Building Commission, set the tone for the workshop with her opening remarks, welcoming participants and urging them to engage wholeheartedly in this transformative national mission.</p>', '', 'full_html'),
('event', 0, 765, 1004, 'en', 0, '<p>On Feb 10, 2025, the National Standards for Civil Service Training Institutes (NSCSTI)Workshop was conducted as part of the consultative process to update the #NSCSTI accreditation framework. The workshop aimed to gather comprehensive feedback from all stakeholders, including training institutes, onsite assessors, &amp; desktop assessors, to refine the framework’s 8 pillars. A total of 40 training institutes participated, including 6 Administrative Training Institutes(ATIs) &amp; 15 Central Civil Service Training Institutes(CTIs).</p><p>The event was chaired by Adil Zainulbhai, Chairman, CBC who emphasized importance of this reiterative process in developing a framework that is both accessible for training institutes &amp; aspirational in driving continuous improvement.</p><p>Dr. R Balasubramaniam, Member (HR), Capacity Building Commission, spoke to the institutes about the various initiatives under the Commission aimed @ strengthening &amp; facilitating the capacity building of civil service training institutes across the country.</p><p>To facilitate in-depth discussions, institutes were divided into 3 breakout groups, each focusing on specific pillars of framework.</p><p>Group 1 was led by Sh. Adil Zainulbhai, Group 2 by Smt. V. Lalithalakshmi (CEO, Karmayogi Bharat), &amp; Group 3 by Dr. Alka Mittal (Member Admin, CBC). Participants deliberated on which aspects of the framework should be retained &amp; proposed modifications to enhance its effectiveness.Each group then presented their insights to larger gathering, exchanging notes &amp; identifying key problem areas.</p><p>The valuable feedback gathered from workshop will be incorporated into revised framework,which is set to be rolled out in May 2025,ensuring it remains both relevant &amp; progressive for training institutes across the country.</p>', '', 'basic_html'),
('event', 0, 766, 1005, 'en', 0, '<p>On January 31 and February 1, 2025, the Office Of The Controller General Of Patents, Designs And Trade Marks (CGPDTM), organized simultaneous sessions in #Nagpur and #Hyderabad for newly appointed officials, focusing on #MissionKarmayogi. S P Roy, Joint Secretary, Capacity Building Commission, delivered an insightful lecture on the mission\'s significance and its pivotal role in transforming civil services.</p><p>Mission Karmayogi, officially known as the National Programme for Civil Services Capacity Building (NPCSCB), was approved by the Government of India on September 2, 2020. It aims to transition civil services from a \'rule-based\' to a \'role-based\' system, emphasizing competency development and fostering a culture of #ContinuousLearning among government officials.</p><p>The sessions underscored the mission\'s objective to equip civil servants with the necessary skills and knowledge to meet the evolving challenges of governance. By leveraging #digitallearning platforms and structured training modules, Mission Karmayogi aspires to create a future-ready civil service dedicated to serving the nation effectively.</p><p>The participation of the newly appointed CGPDTM officials in these sessions marks a significant step towards enhancing their capabilities and aligning them with the mission\'s vision. Such initiatives are crucial in building a proficient and responsive civil service committed to the nation\'s progress.</p>', '', 'basic_html'),
('event', 0, 767, 1363, 'en', 0, '<p>Capacity Building Commission (CBC) and Karmayogi Bharat, in collaboration with the India AI Mission organised an event on “AI for Capacity Building: Transforming Governance”, in New Delhi.</p><p>At the inaugural session, MoS Dr Jitendra Singh said that Mission Karmayogi and iGOT platform are built on Prime Minister Narendra Modi’s vision to shift governance from rule-based to role-based functioning. The Minister said that a hybrid model combining Artificial Intelligence with human intelligence will be critical to building a future-ready, responsive and effective public administration. He further mentioned that the iGOT platform has adopted AI-driven tools such as AI Saarthi, AI Tutor and AI-based Capacity Building Plans. These tools, he said, are enabling personalised learning pathways, faster planning and improved delivery across ministries and departments.</p><p>The event was attended by senior dignitaries including Smt. Rachna Shah, Secretary, Department of Personnel &amp; Training; Smt. S. Radha Chauhan, Chairperson, Capacity Building Commission; and Shri Subramanian Ramadorai, Chairperson, Karmayogi Bharat, along with senior officers from the Centre and States, representatives from academia, industry, training institutions and capacity building units across ministries.</p><p>Smt. Rachna Shah, Secretary, DoPT, emphasised that AI can significantly strengthen transparent, responsive and citizen-centric governance by improving relevance, timeliness and personalisation in capacity building, while underscoring the importance of ethical safeguards and inclusive access.</p><p>Smt. Chhavi Bhardwaj, CEO, KB, highlighted that iGOT has emerged as the foundational digital infrastructure for public sector capacity building, with over 1.5 crore learners and more than 6.7 crore course completions.</p><p>A key highlight of the event was the launch of “Karmayogi Classroom”, a new AI-enabled feature on the iGOT Karmayogi platform designed to enhance contextual, interactive and personalised learning for civil servants.</p><p>The program also featured live demonstrations and thought leadership sessions by leading AI ecosystem partners, showcasing AI tutors, AI-driven capacity building plans, competency mapping tools and indigenous AI solutions tailored for public administration.</p><p><a href=\"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2212462&amp;reg=3&amp;lang=1\" target=\"_blank\">Press Release</a></p>', '', 'full_html'),
('event', 0, 768, 1051, 'en', 0, '<p>Honored to have Dr. Jitendra Singh, Union Minister of State for Personnel, Public Grievances, and Pensions, inaugurate the Advanced Case Writing and Teaching Workshop and officially launch the Amrit Gyaan Kosh Portal at the Sushma Swaraj Institute of Foreign Service (SSIFS), New Delhi today.</p><p>This initiative by the Capacity Building Commission in collaboration with Asian Development Bank Institute (ADBI) and the Stanford Leadership Academy for Development (LAD) marks the beginning of a transformative journey to institutionalize case-based learning in governance.&nbsp;</p><p>The Amrit Gyaan Kosh Portal is now live, offering complete access to Atmanirbhar case studies and supporting materials on iGOT. It is more than a repository-it’s a national knowledge treasure designed to:</p><p>?Empower faculty and practitioners to create contextual, impactful governance models.<br>?Facilitate experiential learning by capturing real-world challenges and solutions.<br>?Foster collaboration and innovation across academies and sectors.</p><p>This initiative is aligned with the vision of making “learning just a click away,” ensuring accessible, high-quality, indigenous resources for governance professionals and academies.</p><p>Together, let’s embark on this transformative journey to empower public service delivery and inspire future generations!</p>', '', 'basic_html'),
('event', 0, 769, 1052, 'en', 0, '<p>Chairman (NHAI) and Member (Admin) &nbsp;Capacity Building Commission held a pivotal meeting to strengthen NHAI\'s workforce for &nbsp;dealing with the complexities of modern infrastructure development. Key note address &nbsp;was given by Member CBC) emphasizing the need for &nbsp;technical leadership, and problem-solving skills; and stressing on the importance of continuous learning and creating a culture of excellence . The Chairman stressed on the NHAI team to focus on behavioral, domain and functional competencies . S P Roy, Joint secretary (CBC) &nbsp;laid down the steps involved in the creation of the capacity building plan , and &nbsp;assured full support &nbsp;of CBC and PwC in developing the Capacity Building Program for NHAI. The Kick off meeting ended with &nbsp;Member (Admin) CBC highlighting the scope for continuous improvement, hoping that NHAI, as an apex institution, will set a benchmark for others in the infrastructure sector.</p>', '', 'basic_html'),
('event', 0, 770, 1053, 'en', 0, '<p>Constitution Day is celebrated in our country on 26th November every year to commemorate the adoption of the Constitution of India. On 26th November 1949, the Constituent Assembly of India adopted the Constitution of India, which came into effect from 26th January 1950.&nbsp;</p>', '', 'basic_html'),
('event', 0, 771, 1017, 'en', 0, '<p>Mission Karmayogi team led by Dr Alka Mittal, Member, Capacity Building Commission called on the Hon\'ble Governor of Himachal Pradesh Shri Shiv Pratap Shukla on 21st November, 2024, in Raj Bhawan, Shimla.</p><p>Team consisting of officials from CBC and Karmayogi Bharat discussed various initiatives and interventions related to capacity building of the officials of Himachal Pradesh.</p><p><br>The team had brief interaction with the Chief Secretary, Shri Prabodh Saxena and Secretary, Urban Development, Shri Devesh Kumar, to discuss the way forward for Capacity Building in the State of Himachal Pradesh.</p>', '', 'basic_html'),
('event', 0, 772, 1018, 'en', 0, '<p>A tripartite MoU was signed between the Capacity Building Commission (CBC), Karmayogi Bharat, and the Government &nbsp;Of Assam , India, marking an important step in the mission to strengthen governance capabilities. The signing ceremony was attended by the Chief Secretary of Assam, Dr. Ravi Kota, IAS ; Dr. R Balasubramaniam, Member HR, CBC; Dr. Alka Mittal, Member Admin, CBC; Smt. V. Lalithalakshmi, Secretary, CBC &amp; CEO of Karmayogi Bharat, and Shri S P Roy, Secretary, CBC.</p><p>Following the signing, a workshop outlined key achievements of #MissionKarmayogi over the past three years, including CBC and Karmayogi Bharat’s work with Central and State Governments. Discussions covered promising areas of collaboration, such as:</p><p>* CBC’s Viksit Panchayat Initiative<br>* Interventions with Urban Local Bodies<br>* Development of a Centre of Excellence for Urban Planning and Development for Assam<br>* District-Level Leadership Program</p><p>Principal Secretaries and department heads from Assam’s Secretariat participated in the workshop. Chief Secretary Dr. Ravi Kota Ji expressed the state’s commitment to effective governance through #CapacityBuilding and ongoing collaboration with #CBC and #KarmayogiBharat.</p><p>Together, CBC, Karmayogi Bharat, and the Government of Assam are excited to enhance the capacity in public administration, paving the way for a brighter and more empowered future, and contributing to #ViksitBharat.</p>', '', 'basic_html'),
('event', 0, 773, 1054, 'en', 0, '<p>We are delighted to announce the #KarmayogiSaptah - National Learning Week (#NLW) will be launched by our Hon’ble Prime Minister, Shri Narendra Modi, at 10 am.</p><p>The #NLW, from 19th-25th October, is aimed to inspire civil servants to embrace a culture of continuous learning, crucial for driving India towards #ViksitBharat.</p><p>We invite you to join us: https://lnkd.in/gzN-gf28</p><p>Also, as part of your commitment to professional excellence, we encourage all civil servants to dedicate at least 4 hours to completing iGOT courses, this week. iGOT certificates and Karma Points will be awarded to recognize your efforts.</p><p>Let’s come together to make the Karmayogi Saptah a grand success!</p>', '', 'basic_html'),
('event', 0, 774, 1021, 'en', 0, '<p>The Department Of Personnel &amp; Training hosted the \"Workshop on Mission Karmayogi for Capacity Building Units of Ministries/Departments\" on October 3, 2024, in New Delhi. The workshop underscored the evolving role of Ministries and Departments in capacity building, reinforcing CBC’s efforts to equip civil servants with the competencies needed to achieve Viksit Bharat.</p><p>The Capacity Building Commission (CBC) presented key highlights of the upcoming National Learning Week, aimed at fostering SevaBhaav and aligning civil servants with the vision of ViksitBharat through continuous learning.</p><p>CBC also shared updates on the Karmayogi Seva Bhaav program, a large-scale behavioral intervention set to engage 700,000 Central Government employees. This initiative, designed to develop 20,000 Karmayogi Coaches, seeks to instill a spirit of public service, enhancing the delivery of citizen-centric governance. Mission Karmayogi is in full momentum as National Learning Week approaches.</p>', '', 'basic_html'),
('event', 0, 775, 1022, 'en', 0, '<p>Capacity Building Commission met Mr. Koosiram Conhye, Secretary for Public Service (Mauritius), to discuss proposed capacity-building programs by CBC and iGOT. The 3- member delegation showed keen interest in the large-scale interventions undertaken by the Capacity Building Commission (CBC), along with the iGOT online platform, which provides competency-based courses for civil servants. They were excited to try out some courses themselves. The collaboration aims to strengthen international partnerships and enhance global best practices in civil service governance.</p><p>They were very complimentary of the speed and scale of the efforts in India on capacity building.</p>', '', 'basic_html'),
('event', 0, 776, 1023, 'en', 0, '<p>Pledge taking ceremony on Swachh Bharat Campaign at CBC</p>', '', 'basic_html'),
('event', 0, 777, 1251, 'en', 0, '<p>The Capacity Building Commission team, led by Dr. Alka Mittal, Member (Administration), along with Ms V. Lalithalakshmi, Secretary,Ms &nbsp; Anuradha Mukharjee (Retd IRS Official and QIP Mentor) and Ms Navneet Kaur, Director, conducted onsite meetings at the Institute of Secretariat Training and Management (ISTM), Delhi, focusing on the Quality Improvement Plan (QIP) based on the NSCSTI framework.&nbsp;</p><p>This initiative is driving significant progress in enhancing training quality. The institute remains committed to contributing to the nation’s capacity-building efforts.</p>', '', 'basic_html'),
('event', 0, 778, 1025, 'en', 0, '<p>Signing of MoU with Piramal Foundation for Education Leadership<br>&nbsp;</p>', '', 'full_html'),
('event', 0, 779, 1026, 'en', 0, '<p>CBC was delighted to welcome the team of National Informatics Centre, MeitY (NIC) lead by DG NIC &amp; CEO Unique Identification Authority of India (UIDAI) Sh Amit Agrawal.</p><p>The brainstorming session focused around Capacity Building, HR Transformation, Knowledge Management, Change management &amp; Technology Integration. &nbsp;NIC is the key enabler of technology driven solutions for Central and State Governments. CBC is glad to support NIC in this journey.</p>', '', 'full_html'),
('event', 0, 780, 1027, 'en', 0, '<p>Capacity Building Commission today launched the “National Karmayogi Seva Bhaav&nbsp;program” with participation from more than 15 Ministries/Departments of the Government of India.&nbsp;</p><p>Phase 1 of this program will build the capacity of officers of the entire Secretariat of the Government of India in the next 3 months covering all 93 Ministries and Departments.&nbsp;</p><p>The impact of governance should be felt by the citizens of the last mile. With the focus on changing mindsets, this program will ensure that all officers go through 1 day of training on building karmayogi competencies and mindsets and operating like a karmayogi.&nbsp;</p><p>Supported by the knowledge partner, the trainers will be created from the nominated DSs/Directors of the MDO who will bring the right context and experience to the training.</p><p>CBC aims to ensure that the National Karmayogi Seva Bhaav program will catalyse and rekindle the spirit of Janbhagidari to help India achieve the goal of Viksit Bharat, as envisioned by the Hon\'ble Prime Minister Shri Narendra Modi.</p>', '', 'basic_html'),
('event', 0, 781, 1028, 'en', 0, '<p>We just ended the communication workshop for CPSE finance executives which was attended by 30 executives from 15 CPSEs, 15 analysts and investors , DIPAM officers. Each executive got a chance to get one on one coaching on their analyst presentation and had to do the presentation 3 times in front of a panel of communications coaches, analysts, investors, &amp; &nbsp;dipam officers.</p><p>The 2 days were intense but the workshop went off very well. Kudos to the cbc team , E&amp;Y, Initium and DIPAM for making this happen.</p><p>Every participant thought it was &nbsp;a very good training workshop.</p>', '', 'full_html'),
('event', 0, 782, 1384, 'en', 0, '<p>Secretary (CBC) addressed the group of civil servants from Gamibia, at National Centre for Good Governance , who are in India as part of their mid career &nbsp;training program. The &nbsp;group was informed about the achievements under &nbsp;Mission Karmayogi focussing on building Competencies to enable the shift &nbsp;from Rule to Role based performance, citizen centric and groomed to be tech enabled and future ready.</p>', '', 'full_html'),
('event', 0, 783, 1031, 'en', 0, '<p>“गुरु ब्रह्मा गुरु विष्णु, गुरु देवो महेश्वरा, गुरु साक्षात परब्रह्म, तस्मै श्री गुरुवे नमः”</p><p>At the core of Mission Karmayogi is continuous learning and competency-driven capacity building. It envisions a future-ready civil service rooted in Indian ethos, with a global perspective. Key teachers in the civil service capacity building ecosystem in India, are our Civil Service Training Institutions (CSTIs), and the IGOT Karmayogi platform, shouldering the responsibility of teaching and training ~31 lakh Karmayogis.</p><p>On this Teachers\' Day, the Commission extends its heartfelt thanks and celebrates the dedicated faculty of all 800+ CSTIs who play a pivotal role in shaping the future of our nation\'s governance. Your commitment to excellence and passion for imparting knowledge and empowering our civil servants with the skills and insights necessary for effective public service is commendable.</p><p>As we reflect on these invaluable contributions, we also acknowledge the pivotal role of the IGOT Karmayogi platform in facilitating anytime-anywhere learning, ensuring that every civil servant has access to essential resources and guidance for their professional development. The platform boasts over 4.3 million registered civil servants, 1100+ digital courses, and 11 million courses completed. The teachings on IGOT not only impart knowledge but also instill the values that make a true public servant.</p><p>Together, these efforts cultivate a culture of lifelong learning and excellence in public administration. The contributions of CSTIs and the IGOT platform have been instrumental in advancing the competency-driven capacity-building goals of Mission Karmayogi. Taking inspiration from Dr. Radhakrishnan’s teachings , the end of all education should be the betterment of the individual and society. This spirit embodies the mission of shaping future leaders who will work towards citizen-centric, effective, and efficient public service delivery.</p>', '', 'basic_html'),
('event', 0, 784, 1033, 'en', 0, '<p>As part of working with States, the Capacity Building Commission team had discussions with officials from the State of Odisha, to spearhead Mission Karmayogi in the state and onboard officials for the Capacity Building process at the State and Local levels.&nbsp;</p><p>The meeting was attended by the Chief Secretary of Odisha, Shri Manoj Ahuja, IAS, Shri Surendra Kumar, IAS Additional Chief Secretary, Smt. Anu Garg, IAS, Development Commissioner, G Mathi Vathanan, IAS, DG Gopabandhu Academy of Administration, Shri Manish Agarwal, IAS Additional DG and other senior officials.&nbsp;</p><p>Very fruitful discussions took place leading to concrete action plans.&nbsp;</p><p><br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 785, 1034, 'en', 0, '<p>Capacity Building Commission, along with Karmayogi Bharat, has been enhancing capacity building for central civil servants for the last two years. Recently, CBC met with Andhra Pradesh CM Nara Chandrababu Naidu and his team in Amravati to extend the benefits of capacity building to all 4.5 lakh civil servants across all levels.</p><p>The CM\'s vision for Andhra Pradesh necessitates every civil servant’s contribution to the state\'s GDP and citizens’ ease of living.&nbsp;</p><p>R Balasubramaniam, Rakesh Verma, and S P Roy led the discussions with Andhra Pradesh CM Chandrababu Naidu and his team in Amravati, aiming to establish a model for capacity building that could benefit all states. Capacity Building Commission and Karmayogi Bharat are committed to supporting Andhra in this mission and pioneering the measurement of the impact of these efforts alongside capacity building.</p>', '', 'basic_html'),
('event', 0, 786, 1035, 'en', 0, '<p>The Capacity Building Commission successfully organized the CSTI Convention 2024 at Vigyan Bhawan on 12th August 2024, bringing together all Civil Service Training Institutions (CSTIs) accredited under the National Standards for Civil Service Training Institutions (NSCSTI).</p><p>At this convention, 144 accredited CSTIs were awarded certificates in the presence of the Chief Guest, Hon’ble MoS Dr. Jitendra Singh, recognizing their collective commitment to excellence in civil service capacity building. Addressing the gathering, Hon’ble MoS remarked, “We have accredited over 140 training institutes, and each accreditation represents a step towards a more competent, efficient, and responsive civil service.” The Commission extends its heartfelt congratulations to all accredited CSTIs and our esteemed partners.</p><p>During the convention, Hon. MoS also launched three significant initiatives: the Faculty Development Program, Amrit Gyaan Kosh, and Quality Improvement Program—all dedicated to fostering continuous learning and competency-driven capacity building among CSTIs.</p><p>Digimanthan 2.0 resulted in institutions committing to digitalising 300+ courses for the IGOT Karmayogi platform.&nbsp;</p><p>The Commission expresses its deep gratitude to Hon. MoS PP Dr. Jitendra Singh, all participants, and our distinguished speakers for making this event a resounding success.</p>', '', 'basic_html'),
('event', 0, 787, 1036, 'en', 0, '<p>Capacity Building Commission (CBC) and Centre for Effective Governance of Indian States signed an MoU for collaboration on various capacity-building initiatives for the various departments of the Government of India.</p>', '', 'basic_html'),
('event', 0, 788, 1037, 'en', 0, '<p>The International Day of Yoga has been celebrated across the world annually on June 21 since 2015. This year the theme for International Day of Yoga is “Yoga for Self and Society.” Yoga, a transformative practice, represents the harmony of mind and body, the balance between thought and action, and the unity of restraint and fulfillment. It integrates the body, mind, spirit, and soul, offering a holistic approach to health and well-being that brings peace to our hectic lives. Its power to transform is what we celebrate on this special day.</p>', '', 'basic_html'),
('event', 0, 789, 1038, 'en', 0, '<p>Today, CBC leadership called on Shri Jitendra Singh, Union MoS(Ind. Charge)Science &amp; Technology; Earth Sciences; MoS PMO, PP/ DoPT, Atomic Energy, Space.&nbsp;</p><p>They also presented a draft copy of the #KarmayogiCompetencyModel (KCM), which is the first indigenous Public HR Management Model developed in the country and will be of global standards at par with other competency models across the world.&nbsp;</p><p>It\'s always a pleasure to get inspiration for #MissionKarmayogi from him.&nbsp;</p>', '', 'basic_html'),
('event', 0, 790, 1055, 'en', 0, '<p>In another milestone, CBC hosted the induction session for 11 Program Coordinators (Karmayogi Sarthis) in New Delhi on June 11, 2024. Piramal Foundation members, especially CEO Aditya Natraj and Director Saurabh Johri, along with representatives from various Ministries, Departments, and Organizations (MDOs), graced the occasion.</p><p>CBC leadership, including Chairman Mr. Adil Zainulbhai, members - Dr. Alka Mittal, Dr. R Balasubramaniam, and secretary Mr. S P Roy were delighted to interact with the Karmayogi Sarthis along with the MDO’s to bring them up to speed on various activities of CBC and expectation of the MDO’s.</p><p>These young, dynamic, and dedicated Program Coordinators will play a pivotal role in enhancing #capacitybuilding and fostering #collaboration within various MDOs as part of #MissionKarmayogi. They will assist the Capacity Building Unit (CBU) team in implementing the Annual Capacity Plan, enforcing Karmayogi Guidelines, and supporting the Central Civil Service Training Institutions in onboarding the Accreditation framework.</p>', '', 'basic_html'),
('event', 0, 795, 1060, 'en', 0, '<p>Mr. Hemang Jani, Secretary, Capacity Building Commission (CBC), addressed the AMP Participants today at the Bella Vista Campus of Administrative Staff College of India (ASCI) and had a discussion withSri Padmanabhaiah Kantipudi, Chairman-ASCI, Dr.Nirmalya Bagchi, DG(I/c), Dr. Valli Manickam, Dean, Bose S.K &amp; Dr O P Singh, Registrar (I/c)</p><p>&nbsp;</p>', '', 'full_html'),
('event', 0, 799, 1064, 'en', 0, '<p>In partnership with Korn Ferry, the SHRMExecutiveNetwork held a Knowledge and Networking Breakfast with SHRM India to welcome 13 new members as well as discuss the challenges and trends in workforce management. Sharing their insights and connecting with attendees were Secretary of Capacity Building Commission, Hemang Jani, Country Manager - India UKG, Sumeet Doshi, and Director of Tata Management Training Center (TMTC) and Senior Vice President Group HR at Tata Group, Anand Shankar</p>', '', 'basic_html'),
('event', 0, 817, 1086, 'en', 0, '<p>Celebrating 75 Years of Independence</p>', '', 'basic_html'),
('event', 0, 847, 1240, 'en', 0, '<p>Joint Secretary, Shri Jagdeep Gupta, IPoS (2004) joins Capacity Building Commission (CBC) today.&nbsp;</p>', '', 'basic_html'),
('event', 0, 855, 1252, 'en', 0, '<p>Joint Secretary, Shri Jagdeep Gupta, IPoS (2004) joins Capacity Building Commission (CBC).&nbsp;</p>', '', 'basic_html'),
('event', 0, 895, 1477, 'en', 0, '<p>AI-Enabled Capacity Building Plans:\r\n\r\nCapacity Building Commission, in coordination with Mahatma Gandhi State Institute of Public Administration (MGSIPA), conducted the AI-enabled Capacity Building Plan (CBP) Workshop (15–16 January 2026) under Mission Karmayogi.\r\n\r\nOver two days, departments moved from planning to implementation:\r\n•	48 departments participated\r\n•	10 departments developed CBPs\r\n•	5 departments successfully made their CBPs live on the iGOT Karmayogi platform\r\n•	33 departments were oriented to complete their CBPs at the earliest \r\n\r\nThe sessions were guided by senior leadership whose insights set both direction and momentum:\r\n\r\nSmt. Chandralekha Mukherjee highlighted the transformative potential of Mission Karmayogi in shifting civil services from a rule-based to a role-based approach. She emphasized that clearly defined roles, supported by targeted competency development, would enable officials to become more effective, productive, and responsive in addressing citizens’ needs.\r\n\r\nMr. Gulshan, Executive Director, MGSIPA shared the simplicity and usability of the AI-enabled CBP tool, noting that it not only supports structured training planning but also helps departments strategically utilize their existing resources for competency development.\r\n\r\nCol. Dalbir Singh, Training Director, MGSIPA, provided sustained operational leadership, reinforcing the importance of systematic and executable training plans.\r\n\r\nThe workshop was facilitated by Ms. Zainab Naaz and Ms. Akanksha Mahapatro, Programme Coordinators, who led hands-on demonstrations and ensured seamless support for departments transitioning their CBPs to the iGOT platform.\r\n\r\nThis milestone marks a significant step in institutionalising technology-enabled, role-specific, and future-ready capacity building at the state level strengthening the foundations of Mission Karmayogi through action, ownership, and implementation.\r\n<br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 896, 1478, 'en', 0, '<p>Smt. S. Radha Chauhan, Chairperson, <a href=\"https://in.linkedin.com/company/capacity-building-commission?trk=public_post-text\"><strong>Capacity Building Commission</strong></a> urged graduates to align their professional efforts with the National Vision of \"Viksit Bharat\" and highlighted the disruptive yet transformative power of Artificial Intelligence. She emphasized that AI must be managed with a focus on ethics, equity, and inclusion to prevent widening the digital divide.\r\n\r\nShe was addressing the Convocation Ceremony at <a href=\"https://in.linkedin.com/company/administrative-staff-college-of-india-asci?trk=public_post-text\"><strong>Administrative Staff College of India (ASCI)</strong></a>, Hyderabad.</p>', '', 'basic_html'),
('event', 0, 897, 1480, 'en', 0, '<p>Smt. S. Radha Chauhan, Chairperson - Capacity Building Commission (CBC) and Smt. Santhi Kumari, Vice Chairperson &amp; Director General - Dr. Marri Channa Reddy Human Resource Development Institute of Telangana (MCRHRDIT) held an interaction focusing on Capacity Building of State at Hyderabad today.\r\n\r\nDuring the deliberations, the ATI highlighted multiple areas reflecting innovative progress, wherein domain expertise has been identified for curating digital content and converting the same into structured digital courses.\r\n\r\nChairperson, CBC underscored the critical importance of formulation and implementation of Capacity Building Plans (CBPs) by all State Departments, reiterating the emphasis laid during the meeting of Chief Secretaries that every State Department must have a CBP in place.\r\n\r\nThe Chairperson, CBC further highlighted the need for integration of training data with HRMS systems, enabling effective personalisation of learning pathways for officials. She urged the ATI to supplement the competency gaps identified through CBPs by aligning and delivering appropriate training programmes, including blended learning, thereby facilitating a transition from a supply-driven to a demand-driven training ecosystem.\r\n\r\nSmt. S Radha Chauhan also assured continued guidance and support to the ATI in strengthening its capabilities in emerging technology domains, as part of ongoing capacity-building efforts.\r\n\r\nThe interaction concluded with a campus tour, during which the Chairperson, CBC was apprised of the Institute’s infrastructure, including training halls, labs, sports facilities, and the Women SHG-run canteen operating within the campus.</p>', '', 'basic_html'),
('event', 0, 917, 1610, 'en', 0, '<p>The Inaugural Session of the second batch of DAKSH (Development of Aspiration, Knowledge, Succession and Harmony), a flagship leadership development programme for senior executives of Central Public Sector Enterprises (CPSEs), was held at the SCOPE Convention Centre, New Delhi. The programme is jointly organised by the Capacity Building Commission (CBC) and the Standing Conference of Public Enterprises (SCOPE) under Mission Karmayogi.<br><br>The event was attended by senior leadership from the Government of India and the public sector, including Dr. P. K. Mishra, Principal Secretary to the Prime Minister; Shri K. Moses Chalai, Secretary, Department of Public Enterprises; Smt. Rachna Shah, Secretary, Department of Personnel and Training; Smt. S. Radha Chauhan, Chairperson, Capacity Building Commission; Shri K. P. Mahadevaswamy, Chairman, SCOPE; Shri Atul Sobti, Director General, SCOPE; and Smt. Alka Mittal, Member (Administration), Capacity Building Commission.<br><br>Welcoming participants, Shri Atul Sobti said DAKSH will help leaders reflect, prepare and transform themselves, while enabling leadership emergence, strategic development and international exposure.<br><br>Setting the context, Smt. Alka Mittal described DAKSH as a 12-month leadership programme integrating digital learning, classroom engagement, executive coaching, action learning and international exposure. She noted that 73 senior CPSE officials were trained in the first batch &amp; 72 participants from diverse sectors form the second. Highlighting Mission Karmayogi initiatives such as iGOT onboarding, Karmayogi Saptah, the Competency Model, accreditation of institutions and Amrit Gyaan Kosh, she emphasised leadership development, competency-based growth and technology-enabled learning for CPSE reforms.<br><br>Delivering the address, Dr. P. K. Mishra highlighted the evolving role of CPSEs and their foundational contribution to India’s industrial and infrastructure base. He said globalisation and reforms have shifted focus to competitiveness, efficiency and innovation, requiring greater agility while serving national priorities and competing globally. Referring to the Public Sector Enterprise Policy of 2021, he noted that despite an expanding role for private enterprises, CPSEs remain vital in strategic sectors such as energy, defence, infrastructure and finance, and in balancing markets involving public goods and national security. He stressed innovation, continuous learning and strategic thinking through initiatives like DAKSH.<br><br>Earlier, Shri K. Moses Chalai highlighted the economic contribution of CPSEs to GDP &amp; the Central Exchequer, stressing the need for future-ready leadership and describing DAKSH as timely.&nbsp;<br><br>Shri Jagdeep Gupta, Secretary, Capacity Building Commission gave the vote of thanks. He reiterated the commitment of the Commission to take forward the vision of Mission Karmayogi.&nbsp;<br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 918, 1611, 'en', 0, '<p>Chairperson, Capacity Building Commission, Ms S. Radha Chauhan, visited Sardar Patel Institute of Public Administration (SPIPA), Ahmedabad, Gujarat today. \r\n\r\nShe chaired a meeting with the Deputy Director General, SPIPA, Shri Chandresh Kotak, Joint Secretary &amp; Knowledge Manager, Ms Ruta Bhatt and others. During the meeting, various matters related to the implementation of Mission Karmayogi in the state of Gujarat were discussed.</p>', '', 'basic_html'),
('event', 0, 919, 1612, 'en', 0, '<p>Capacity Building Commission’s Rashtriya Karmayogi Large Scale Jan Seva Programme (Phase-II) concludes\r\n\r\nDr. R. Balasubramaniam, Member (HR), Capacity Building Commission chaired the Closing Session of Phase-II of the Rashtriya Karmayogi Large Scale Jan Seva Program today. Around 10.5 lakh government servants have been trained under this interactive behavioural training program across the country. The closing session was attended virtually by around 300 participants from various Ministries and Departments. A key outcome of the program has been the creation of a nationwide cohort of 822 Lead Trainers and over 16,500 Master Trainers, equipped with facilitation skills grounded in adult-learning principles and activity-based learning methodologies.&nbsp;\r\nDr. R. Balasubramaniam lauded all participating MDOs for their enthusiastic involvement in the entire program. He emphasized that the initiative\'s core aim was to realign inner purpose with outward service, fostering empathetic, efficient, and citizen-centric service delivery, with \"Seva Bhav\" as the driving force. Dr. Balasubramaniam stressed that this is merely the beginning of a long-term transformation, urging the institutionalization of these efforts to cultivate a responsive, resilient, and future-ready administrative culture for a \"Viksit Bharat.\" \r\n\r\nShri Jagdeep Gupta, Secretary of CBC extended gratitude to the MDOs, highlighting the unprecedented scale of over 500 organizations participating and the overwhelmingly positive feedback.\r\n<br>&nbsp;</p>', '', 'basic_html'),
('event', 0, 923, 1618, 'en', 0, '<p>Capacity Building Commission’s Rashtriya Karmayogi Large Scale Jan Seva Programme (Phase-II) concludes Dr. R. Balasubramaniam, Member (HR), Capacity Building Commission chaired the Closing Session of Phase-II of the Rashtriya Karmayogi Large Scale Jan Seva Program today. Around 10.5 lakh government servants have been trained under this interactive behavioural training program across the country. The closing session was attended virtually by around 300 participants from various Ministries and Departments. A key outcome of the program has been the creation of a nationwide cohort of 822 Lead Trainers and over 16,500 Master Trainers, equipped with facilitation skills grounded in adult-learning principles and activity-based learning methodologies.&nbsp; Dr. R. Balasubramaniam lauded all participating MDOs for their enthusiastic involvement in the entire program. He emphasized that the initiative\'s core aim was to realign</p>', '', 'basic_html'),
('event', 0, 943, 1660, 'en', 0, '<p>For Testing event</p>', '', 'basic_html');
